    private final ExecutorService executor = Executors.newCachedThreadPool();
    /** One screenshot or recording at a time (the Terminal's Screenshot and Record buttons); both run on the executor, which onDestroy shuts down. */
    private final java.util.concurrent.atomic.AtomicBoolean screenBusy = new java.util.concurrent.atomic.AtomicBoolean(false);
    private final java.util.concurrent.atomic.AtomicBoolean screenRecording = new java.util.concurrent.atomic.AtomicBoolean(false);

    /**
     * Hands a job to the executor. False when it refuses (shut down with the Activity): the caller then clears the
     * process-wide "busy" mark it set before submitting, so a re-created page isn't told "busy" for the rest of the process.
     */
    // ---------------------------------------------------------------------------------------------
    // Trackers: the known tracker libraries (Exodus Privacy list, assets/trackers.json) found in an app's dex class names. Results are kept in files/trackers_cache.json
    // per package, valid while the app's version, update time, split count and the list are the same.
    // ---------------------------------------------------------------------------------------------
    private volatile Trackers trackersLib;
    private final Object trackerLock = new Object();
    private final ExecutorService trackerExecutor = Executors.newSingleThreadExecutor();
    private volatile boolean trackerBusy, trackerCancel;
    // one switch of an app's tracker parts at a time (trackerPartsSet): a second tap while a run is going is told "busy"
    private final Object trackerPartsLock = new Object();
    private boolean trackerPartsBusy;

    private Trackers trackers() throws Exception {
        Trackers t = trackersLib;
        if (t != null) return t;
        synchronized (trackerLock) {
            if (trackersLib == null) {
                // a list fetched with "Update the tracker list" wins over the one in the app, as long as it can be read
                File fresh = new File(getFilesDir(), "trackers_user.json");
                if (fresh.isFile()) {
                    try {
                        trackersLib = Trackers.load(new String(java.nio.file.Files.readAllBytes(fresh.toPath()), "UTF-8"));
                        return trackersLib;
                    } catch (Throwable broken) { fresh.delete(); }
                }
                InputStream in = getAssets().open("trackers.json");
                try {
                    java.io.ByteArrayOutputStream bo = new java.io.ByteArrayOutputStream();
                    byte[] buf = new byte[16384];
                    for (int n; (n = in.read(buf)) > 0; ) bo.write(buf, 0, n);
                    trackersLib = Trackers.load(new String(bo.toByteArray(), "UTF-8"));
                } finally {
                    in.close();
                }
            }
            return trackersLib;
        }
    }

    private File trackerCacheFile() { return new File(getFilesDir(), "trackers_cache.json"); }

    private JSONObject trackerCacheRead(Trackers t) {
        try {
            JSONObject o = new JSONObject(new String(java.nio.file.Files.readAllBytes(trackerCacheFile().toPath()), "UTF-8"));
            if (t.dbVersion().equals(o.optString("db")) && o.optJSONObject("apps") != null) return o;
        } catch (Throwable ignored) { }
        try { return new JSONObject().put("db", t.dbVersion()).put("apps", new JSONObject()); } catch (Exception e) { return new JSONObject(); }
    }

    private void trackerCacheWrite(JSONObject cache) {
        try {
            File tmp = new File(getFilesDir(), "trackers_cache.json.tmp");
            java.nio.file.Files.write(tmp.toPath(), cache.toString().getBytes("UTF-8"));
            if (!tmp.renameTo(trackerCacheFile())) tmp.delete();
        } catch (Throwable ignored) { }
    }

    /** Version, update time and number of splits of an installed package, "" when it is not installed. */
    private String trackerStamp(PackageInfo pi) {
        long vc = Build.VERSION.SDK_INT >= 28 ? pi.getLongVersionCode() : pi.versionCode;
        int splits = pi.applicationInfo != null && pi.applicationInfo.splitSourceDirs != null ? pi.applicationInfo.splitSourceDirs.length : 0;
        return vc + ":" + pi.lastUpdateTime + ":" + splits;
    }

    private List<File> trackerApks(PackageInfo pi) {
        List<File> files = new ArrayList<File>();
        if (pi.applicationInfo == null) return files;
        if (pi.applicationInfo.sourceDir != null) files.add(new File(pi.applicationInfo.sourceDir));
        if (pi.applicationInfo.splitSourceDirs != null) for (String d : pi.applicationInfo.splitSourceDirs) files.add(new File(d));
        return files;
    }

    private boolean submitJob(Runnable job) {
        try {
            executor.submit(job);
            return true;
        } catch (java.util.concurrent.RejectedExecutionException refused) {
            return false;
        }
    }

    /** One thread for the Hidden Settings tab (and the Overlays tab): a toggle tapped twice quickly must reach the phone in that order, and reads must not overtake writes. */
    private final ExecutorService settingsExecutor = Executors.newSingleThreadExecutor();

    private boolean submitSettingsJob(Runnable job) {
        try {
            settingsExecutor.submit(job);
            return true;
        } catch (java.util.concurrent.RejectedExecutionException refused) {
            return false;
        }
    }

    // Working modes: "auto", "adb_tcp", "adb_wireless", "shizuku", "root", "unprivileged".
    // The configured mode is only ever changed by an explicit user action (selecting a mode,
    // connecting, authorizing Shizuku). Status checks never change it.
    private static final java.util.List<String> WORKING_MODES = java.util.Arrays.asList("auto", "adb_tcp", "adb_wireless", "shizuku", "root", "unprivileged");
    /** The mode as one of the known names; anything else (a made-up or stale value) is "auto", so no unknown string ever passes a privileged check. */
    private static String knownWorkingMode(String mode) {
        String m = mode == null ? "" : mode.trim();
        return WORKING_MODES.contains(m) ? m : "auto";
    }
    private volatile String activeWorkingMode = "auto";
    private volatile String adbTcpHost = "127.0.0.1";
    private volatile int adbTcpPort = 5555;
    private volatile String adbWirelessHost = "127.0.0.1";
    private volatile int adbWirelessPort = 0;

    // Short-lived cache of the backend used by "auto" mode so batch actions don't re-probe every command
    private volatile String cachedAutoMode = null;
    private volatile long cachedAutoModeAt = 0;

    private final Shizuku.OnRequestPermissionResultListener shizukuPermissionListener = new Shizuku.OnRequestPermissionResultListener() {
        @Override
        public void onRequestPermissionResult(int requestCode, int grantResult) {
            invalidateModeCache();
            if (requestCode != SHIZUKU_REQUEST_CODE) return;
            boolean granted = grantResult == PackageManager.PERMISSION_GRANTED;
            if (granted) {
                setConfiguredMode("shizuku");
            }
            notifyJs("window.onShizukuPermissionResult && window.onShizukuPermissionResult(" + granted + ")");
        }
    };

    private final Shizuku.OnBinderReceivedListener shizukuBinderListener = new Shizuku.OnBinderReceivedListener() {
        @Override
        public void onBinderReceived() {
            invalidateModeCache();                  // Shizuku just came up: the page's next look must not read a probe from before it did
            notifyJs("window.checkAllWorkingModes && window.checkAllWorkingModes(false)");
        }
    };

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);

        // One UI dark system bar integration
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            getWindow().setNavigationBarColor(0xFF080A0F);
            getWindow().setStatusBarColor(0xFF080A0F);
        }

        vibrator = (Vibrator) getSystemService(Context.VIBRATOR_SERVICE);
        prefs = getSharedPreferences("adb_app_manager_prefs", Context.MODE_PRIVATE);

        // Load saved working mode settings
        activeWorkingMode = knownWorkingMode(prefs.getString("working_mode", "auto"));
        adbTcpHost = prefs.getString("adb_tcp_host", "127.0.0.1");
        adbTcpPort = prefs.getInt("adb_tcp_port", 5555);
        adbWirelessHost = prefs.getString("adb_wireless_host", "127.0.0.1");
        adbWirelessPort = prefs.getInt("adb_wireless_port", 0);

        try {
            Shizuku.addRequestPermissionResultListener(shizukuPermissionListener);
            Shizuku.addBinderReceivedListenerSticky(shizukuBinderListener);
        } catch (Throwable t) {
            Log.w(TAG, "Shizuku listener registration failed: " + t.getMessage());
        }

        // A changed build fingerprint means the system was updated since the app last ran
        // (a tile or widget tap runs headless and must not use up the flag before the user opens the app)
        if (!isHeadless()) {
            String fingerprint = Build.FINGERPRINT == null ? "" : Build.FINGERPRINT;
            String seenFingerprint = prefs.getString("app_fp", null);
            buildChangedThisLaunch = seenFingerprint != null && !seenFingerprint.equals(fingerprint);
            prefs.edit().putString("app_fp", fingerprint).apply();
        }

        // Extract binaries and ADB keys in background
        setupBinariesAndKeys();

        // a copy of the Morphe signing key staged for the share sheet is short-lived; whatever a dead process left behind is removed here, however young
        // (only the first onCreate of the process: a later one, the window opened again, may have a share sheet still reading the live copy)
        try { KeyShare.sweepAtStart(getCacheDir()); } catch (Throwable ignored) {}

        if (isHeadless()) {
            runQuickAction(getIntent());
            return;
        }

        webView = new WebView(this);
        setContentView(webView);
        // the newest window is the one a Morphe patch that is going asks for the installer, also before this page makes a Morphe call (MOR-1)
        try { MorpheBridge.windowOpened(morpheHost()); } catch (Throwable t) { Log.w(TAG, "Morphe window registration failed: " + t.getMessage()); }

        webView.setVerticalScrollBarEnabled(true);
        webView.setHorizontalScrollBarEnabled(false);
        webView.setOverScrollMode(android.view.View.OVER_SCROLL_IF_CONTENT_SCROLLS);

        WebSettings settings = webView.getSettings();
        settings.setJavaScriptEnabled(true);
        settings.setDomStorageEnabled(true);
        settings.setAllowFileAccess(true);
        settings.setAllowContentAccess(true);
        settings.setAllowFileAccessFromFileURLs(false);
        settings.setAllowUniversalAccessFromFileURLs(false);
        settings.setDatabaseEnabled(true);
        settings.setLoadWithOverviewMode(false);
        settings.setUseWideViewPort(false);

        // alert(), confirm() and prompt() of the page as dialogs in the app's look, with a real title (PageDialogs); every one is answered exactly once
        webView.setWebChromeClient(pageDialogs.client());
        webView.setWebViewClient(new WebViewClient() {
            @Override
            public void onPageFinished(WebView view, String url) {
                pageReady = true;
                deliverPendingInstall();
                deliverPendingQuickOpen();
            }

            // The page holds a powerful bridge (shell, files, installs), so it never navigates away from the
            // bundled UI: a web link opens in the browser instead of loading inside this WebView.
            @Override
            public boolean shouldOverrideUrlLoading(WebView view, android.webkit.WebResourceRequest request) {
                Uri u = request.getUrl();
                if (u.toString().startsWith("file:///android_asset/")) return false;
                String scheme = u.getScheme();
                if ("http".equalsIgnoreCase(scheme) || "https".equalsIgnoreCase(scheme)) {
                    try {
                        startActivity(new Intent(Intent.ACTION_VIEW, u).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
                    } catch (Exception ignored) {}
                }
                return true;
            }

            // If the WebView's renderer is killed (low memory), start over instead of crashing the app: the dead WebView
            // is destroyed and the Activity re-created. A renderer that dies again and again (three times within a minute)
            // is not retried for ever.
            @Override
            public boolean onRenderProcessGone(final WebView view, android.webkit.RenderProcessGoneDetail detail) {
                Log.w(TAG, "WebView renderer gone (crashed=" + detail.didCrash() + ")");
                long now = android.os.SystemClock.elapsedRealtime();
                if (now - renderGoneAt > 60000) renderGoneCount = 0;
                renderGoneAt = now;
                final boolean giveUp = ++renderGoneCount >= 3;
                runOnUiThread(new Runnable() {
                    @Override
                    public void run() {
                        try {
                            android.view.ViewParent parent = view.getParent();
                            if (parent instanceof android.view.ViewGroup) ((android.view.ViewGroup) parent).removeView(view);
                            view.destroy();
                        } catch (Throwable ignored) {}
                        if (giveUp) {
                            Toast.makeText(MainActivity.this, "The web view keeps crashing, so the app is closing. Restart the phone or update Android System WebView, then open it again.", Toast.LENGTH_LONG).show();
                            finish();
                        } else {
                            recreate();
                        }
                    }
                });
                return true;
            }
        });
        webView.setBackgroundColor(0xFF080A0F);

        // Remote WebView debugging only for a debuggable build (the release build is not).
        WebView.setWebContentsDebuggingEnabled((getApplicationInfo().flags & ApplicationInfo.FLAG_DEBUGGABLE) != 0);

        webView.addJavascriptInterface(new AndroidBridge(), "AndroidBridge");
        webView.loadUrl("file:///android_asset/index.html");
        // Leftovers of archive browsing (nested archives, files staged for install) from a previous run
        executor.submit(new Runnable() {
            @Override
            public void run() {
                synchronized (archiveLock) {
                    if (archiveBusy) return;          // this process (re-created Activity) still has a job using them
                    deleteContents(archiveNestedDir());
                    deleteContents(archiveStageDirLocal());
                    // working files of a signing / edit job that a killed process never got to remove
                    new File(getCacheDir(), "archive_sign_prep.apk").delete();
                    new File(getCacheDir(), "archive_sign_out.apk").delete();
                    new File(getCacheDir(), "archive_edit.tmp").delete();
                }
            }
        });
        registerWallpaperListener();
        // A package opened from outside is handed over once: recreate(), a restore and Recents bring the same old intent back.
        if (savedInstanceState != null) {
            String kept = savedInstanceState.getString(STATE_PENDING_INSTALL);
            if (kept != null) pendingInstallRef = kept;                // arrived, but the page was not ready to take it yet
            // a font package's "save as" that was open when Android ended the process: its answer comes to this window
            String export = savedInstanceState.getString(STATE_FMK_EXPORT);
            if (FontLibrary.isId(export)) {
                synchronized (fmkLock) {
                    fmkExportId = export;
                }
            }
        }
        Intent launch = getIntent();
        if (launch != null && IncomingInstall.handOverAtCreate(launch.getAction(), launch.getFlags(), savedInstanceState != null)) handleIncomingIntent(launch);
        // a tap on the Stop apps notification that starts the window: handed over once, not again by a recreate or a start from Recents
        if (launch != null && QuickStopRun.openAtCreate(savedInstanceState != null, launch.getFlags())) takeQuickOpen(launch);
        maybeRequestFirstLaunchPermissions();
        // A package file deleted with an Undo whose few seconds ran out while the app was closed: it is deleted for good now
        if (prefs != null && prefs.getBoolean("apk_trash_pending", false)) {
            executor.submit(new Runnable() {
                @Override
                public void run() {
                    try { purgeApkTrash(); } catch (Exception ignored) {}
                }
            });
        }
    }

    private static final int REQ_STORAGE_PERM = 9301;
    /** A runtime permission asked for from the permissions sheet (Bluetooth Connect, Notifications): a refusal for good sends the person to the app's settings page too */
    private static final int REQ_SHEET_RUNTIME_PERM = 9304;
    /** The sheet's last request as it stood before Android's dialog (for PermRefusal): the permission, its rationale, and whether the sheet had asked for it before. UI thread only. */
    private String sheetAskPerm = "";
    private boolean sheetRationaleBefore, sheetAskedBefore;

    /** The system's permission dialog was answered: tell the page, and after a refusal for good send the user to the app's settings page, where the switch is. */
    @Override
    public void onRequestPermissionsResult(int requestCode, String[] permissions, int[] grantResults) {
        super.onRequestPermissionsResult(requestCode, permissions, grantResults);
        try {
            if (requestCode == REQ_STORAGE_PERM || requestCode == REQ_SHEET_RUNTIME_PERM) {
                boolean never = false;
                for (String p : permissions) {
                    boolean granted = checkSelfPermission(p) == PackageManager.PERMISSION_GRANTED, rationale = shouldShowRequestPermissionRationale(p);
                    if (requestCode == REQ_SHEET_RUNTIME_PERM) {
                        // a dialog dismissed on a first ask (Back, a tap outside) leaves no rationale either: only an earlier answer makes it a refusal for good
                        boolean same = p.equals(sheetAskPerm);
                        if (PermRefusal.forGood(granted, same && sheetRationaleBefore, rationale, same && sheetAskedBefore)) never = true;
                    } else if (!granted && !rationale) never = true;
                }
                if (never) {
                    Intent i = new Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS, Uri.parse("package:" + getPackageName()));
                    i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
                    startActivity(i);
                }
            }
        } catch (Exception ignored) {}
        if (requestCode == REQ_TERMUX_PERM) {
            boolean granted = checkSelfPermission(TermuxBridge.PERMISSION) == PackageManager.PERMISSION_GRANTED;
            boolean canAsk = !granted && shouldShowRequestPermissionRationale(TermuxBridge.PERMISSION);
            notifyJs("window.onTermuxPermission && window.onTermuxPermission(" + granted + "," + canAsk + ")");
            return;
        }
        notifyJs("window.onPermissionsChanged && window.onPermissionsChanged()");
    }

    /**
     * On the very first launch, check and request the standard runtime permissions the app uses
     * (notifications, and legacy storage on pre-Android 11). The special accesses - All-files access,
     * usage access and display over other apps - have no dialog of their own: the page offers them in its
     * first-launch sheet (and asks for All-files access again whenever an action needs it).
     */
    private void maybeRequestFirstLaunchPermissions() {
        try {
            if (prefs == null || prefs.getBoolean("first_launch_perms_done", false)) return;
            prefs.edit().putBoolean("first_launch_perms_done", true).apply();
            java.util.List<String> req = new java.util.ArrayList<String>();
            if (Build.VERSION.SDK_INT >= 33
                    && checkSelfPermission("android.permission.POST_NOTIFICATIONS") != PackageManager.PERMISSION_GRANTED) {
                req.add("android.permission.POST_NOTIFICATIONS");
            }
            // Android 11+ browses storage through All-files access (a special-access grant), not these.
            if (Build.VERSION.SDK_INT < 30) {
                if (checkSelfPermission(android.Manifest.permission.READ_EXTERNAL_STORAGE) != PackageManager.PERMISSION_GRANTED)
                    req.add(android.Manifest.permission.READ_EXTERNAL_STORAGE);
                if (checkSelfPermission(android.Manifest.permission.WRITE_EXTERNAL_STORAGE) != PackageManager.PERMISSION_GRANTED)
                    req.add(android.Manifest.permission.WRITE_EXTERNAL_STORAGE);
            }
            if (!req.isEmpty()) requestPermissions(req.toArray(new String[0]), 9100);
        } catch (Exception ignored) {}
    }

    private static final String STATE_PENDING_INSTALL = "pending_install_ref";

    @Override
    protected void onSaveInstanceState(Bundle outState) {
        super.onSaveInstanceState(outState);
        if (pendingInstallRef != null) outState.putString(STATE_PENDING_INSTALL, pendingInstallRef);
        synchronized (fmkLock) {
            if (fmkExportId != null) outState.putString(STATE_FMK_EXPORT, fmkExportId);
        }
    }

    @Override
    protected void onNewIntent(Intent intent) {
        super.onNewIntent(intent);
        setIntent(intent);
        handleIncomingIntent(intent);
        takeQuickOpen(intent);
    }

    /**
     * The Stop apps notification was tapped (QuickStopNotice): remembers which quick list's sheet to show. The extra is taken out of the intent, so a
     * window that is created again from it does not open the sheet a second time.
     */
    private void takeQuickOpen(Intent intent) {
        if (intent == null || isHeadless()) return;
        String id = intent.getStringExtra(QuickActions.EXTRA_OPEN_QUICK_LIST);
        if (id == null) return;
        intent.removeExtra(QuickActions.EXTRA_OPEN_QUICK_LIST);
        pendingQuickOpen = id;
        deliverPendingQuickOpen();
    }

    /** Hands the tap on the Stop apps notification to the page once it is ready: Saved Applications, with the quick list's sheet. */
    private void deliverPendingQuickOpen() {
        if (!pageReady || pendingQuickOpen == null) return;
        final String id = pendingQuickOpen;
        pendingQuickOpen = null;
        notifyJs("window.onQuickStopOpen && window.onQuickStopOpen(" + JSONObject.quote(id) + ")");
    }

    /** Picks up an APK opened from outside (the default-installer intent-filter) and remembers it. */
    private void handleIncomingIntent(Intent intent) {
        if (intent == null) return;
        if (!IncomingInstall.handOverAtNewIntent(intent.getAction())) return;
        Uri data = intent.getData();
        if (data == null) return;
        pendingInstallRef = "file".equals(data.getScheme()) ? data.getPath() : data.toString();
        deliverPendingInstall();
    }

    /** Hands a pending opened-APK to the Installer tab once the WebView is ready. */
    private void deliverPendingInstall() {
        if (!pageReady || pendingInstallRef == null) return;
        final String ref = pendingInstallRef;
        pendingInstallRef = null;
        notifyJs("window.onInstallIntent && window.onInstallIntent(" + JSONObject.quote(ref) + ")");
    }

    private void setupBinariesAndKeys() {
        try {
            File filesDir = getFilesDir();

            // 1. Shizuku rish setup (fallback executor when the Shizuku API binder is unavailable)
            rishFile = new File(filesDir, "rish");
            rishDexFile = new File(filesDir, "rish_shizuku.dex");
            extractAsset("rish", rishFile);
            rishFile.setExecutable(true, false);
            rishFile.setReadable(true, false);
            extractAsset("rish_shizuku.dex", rishDexFile);
            rishDexFile.setReadable(true, false);
            if (Build.VERSION.SDK_INT >= 34) {
                rishDexFile.setWritable(false, false);
            }

            // 2. ADB Native Library setup
            // Prefer extracted native library in nativeLibraryDir (standard for Android APKs)
            // (on a 32-bit phone the adb is a dynamic build: its libraries are unpacked first and found through LD_LIBRARY_PATH)
            AdbRuntime.prepare(this);
            File nativeAdb = new File(getApplicationInfo().nativeLibraryDir, "libadb.so");
            if (nativeAdb.exists() && nativeAdb.canExecute()) {
                adbBinFile = nativeAdb;
            } else {
                String fallback = AdbRuntime.assetName(Build.SUPPORTED_ABIS);
                adbBinFile = new File(filesDir, fallback);
                extractAsset(fallback, adbBinFile);
                adbBinFile.setExecutable(true, false);
                adbBinFile.setReadable(true, false);
            }

            // 3. ADB Keys setup (.android/adbkey & .android/adbkey.pub)
            adbHomeDir = new File(filesDir, "adb_home");
            File dotAndroid = new File(adbHomeDir, ".android");
            if (!dotAndroid.exists()) dotAndroid.mkdirs();

            ensurePrivateAdbKey();

            // An adb server of an older version (or one started on the fallback port by an earlier run) may still hold the loopback port
            // that any app on the phone can reach: when this run uses the private socket, stop whatever listens there. Checked at every
            // start (a closed port costs one connect attempt), not once for ever, since a later run may have fallen back to the port.
            if (AdbRuntime.usesPrivateSocket(this)) {
                executor.submit(new Runnable() {
                    @Override public void run() {
                        try {
                            if (isPortOpen("127.0.0.1", AdbServerSpec.LEGACY_PORT, 400)) {
                                runProcessWithTimeout(buildAdbProcess(AdbServerSpec.args(null), "kill-server"), 3000);
                            }
                        } catch (Throwable ignored) {}
                    }
                });
            }

            // Reconnect the saved ADB TCP target on launch, but only when ADB TCP is (or may be) the
            // chosen mode. This never changes the configured mode, so other modes stay selectable.
            executor.submit(new Runnable() {
                @Override
                public void run() {
                    try {
                        String mode = activeWorkingMode;
                        if (("auto".equals(mode) || "adb_tcp".equals(mode)) && isPortOpen(adbTcpHost, adbTcpPort, 400)) {
                            performConnect(adbTcpHost, adbTcpPort, null);
                        } else if ("adb_wireless".equals(mode) && adbWirelessPort > 0) {
                            performConnect(adbWirelessHost, adbWirelessPort, null);
                        }
                    } catch (Exception e) {
                        Log.w(TAG, "Auto-connect background failed: " + e.getMessage());
                    }
                }
            });

            // The assistant method (Activity Manager launches) changes a secure setting for a moment: if the app was killed in that
            // moment, put the user's own values back
            if (prefs.contains("assistant_restore_pending")) {
                executor.submit(new Runnable() {
                    @Override public void run() {
                        try { Thread.sleep(4000); } catch (InterruptedException ignored) {}
                        recoverPendingAssistant();
                    }
                });
            }

        } catch (Exception e) {
            Log.e(TAG, "setupBinariesAndKeys error", e);
        }
    }

    // Fingerprint of the key pair that versions up to 3.5 shipped inside every APK (public in the repo history)
    private static final String LEGACY_SHARED_KEY_FINGERPRINT = "36:62:EE:8B:CA:29:5D:B6:B1:5C:DA:4E:ED:59:1D:01";

    private File adbKeyFile() {
        return new File(new File(adbHomeDir, ".android"), "adbkey");
    }

    private File adbPubKeyFile() {
        return new File(new File(adbHomeDir, ".android"), "adbkey.pub");
    }

    private String adbKeyName() {
        String model = Build.MODEL == null ? "android" : Build.MODEL.replaceAll("[^A-Za-z0-9._-]", "_");
        return "adbmanager@" + model;
    }

    /**
     * Every install gets its own ADB key. Missing keys are generated; the old shared key from v3.0–v3.5
     * is replaced (the phone will ask "Allow debugging?" once for the new key).
     */
    private void ensurePrivateAdbKey() {
        File key = adbKeyFile();
        File pub = adbPubKeyFile();
        try {
            if (key.exists() && key.length() > 0) {
                if (!pub.exists() || pub.length() == 0) {
                    AdbKeyManager.generate(key, pub, adbKeyName()); // unreadable pub: start fresh
                    onAdbKeyReplaced(false);
                    return;
                }
                if (!LEGACY_SHARED_KEY_FINGERPRINT.equals(AdbKeyManager.fingerprint(pub))) {
                    key.setReadable(false, false);
                    key.setReadable(true, true);
                    return; // already a private per-install key
                }
                AdbKeyManager.generate(key, pub, adbKeyName());
                onAdbKeyReplaced(true);
            } else {
                AdbKeyManager.generate(key, pub, adbKeyName());
                prefs.edit().putLong("adb_key_created_at", System.currentTimeMillis()).apply();
            }
        } catch (Exception e) {
            Log.e(TAG, "ADB key generation failed", e);
        }
    }

    private void onAdbKeyReplaced(boolean fromSharedKey) {
        prefs.edit()
                .putLong("adb_key_created_at", System.currentTimeMillis())
                .putBoolean("adb_key_notice_pending", fromSharedKey)
                .apply();
        // A running adb server still holds the old key in memory
        runProcessWithTimeout(buildAdbProcess("kill-server"), 3000);
        cachedAutoMode = null;
    }

    private JSONObject adbKeyInfo() {
        JSONObject o = new JSONObject();
        try {
            o.put("fingerprint", AdbKeyManager.fingerprint(adbPubKeyFile()));
            o.put("name", adbKeyName());
            o.put("createdAt", prefs.getLong("adb_key_created_at", 0));
            o.put("noticePending", prefs.getBoolean("adb_key_notice_pending", false));
        } catch (Exception ignored) {}
        return o;
    }

    /** Copies an asset into the app's files once per app version, whole or not at all (a copy cut short is not kept; see AssetCopy). */
    private void extractAsset(final String assetName, File destFile) {
        String stamp;
        try {
            stamp = String.valueOf(versionCodeOf(getPackageManager().getPackageInfo(getPackageName(), 0)));
        } catch (Exception e) {
            stamp = "0";
        }
        AssetCopy.copy(new AssetCopy.Source() {
            @Override
            public InputStream open() throws IOException {
                return getAssets().open(assetName);
            }
        }, destFile, stamp);
    }

    /** Whether the terminal a queued script is for is still the current one when the script is about to run. */
    private interface Live { boolean now(); }

    /** Like {@link #notifyJs}, but the script is dropped if {@code live} no longer holds on the UI thread (a restart may have happened while it waited). */
    private void notifyJsIf(final String script, final Live live) {
        runOnUiThread(new Runnable() {
            @Override
            public void run() {
                if (!activityDestroyed && webView != null && live.now()) {      // checked here, on the UI thread: onDestroy may have run since the script was queued
                    webView.evaluateJavascript(script, null);
                }
            }
        });
    }

    private void notifyJs(final String script) {
        runOnUiThread(new Runnable() {
            @Override
            public void run() {
                if (!activityDestroyed && webView != null) {      // checked here, on the UI thread: onDestroy may have run since the script was queued
                    webView.evaluateJavascript(script, null);
                }
            }
        });
    }

    // The mode probe is a few process spawns and a socket check, and the page asks for it on most view changes.
    private static final Object modeCacheLock = new Object();
    private static String modeCacheJson;
    private static long modeCacheAt;
    private static long modeCacheGen;          // bumped by every invalidation: a probe that was running meanwhile must not store its (older) answer
    private static final long MODE_CACHE_MS = 2500;
    private static boolean rootChecked;
    private static boolean rootCached;
    private static long rootCheckedAt;
    // Whether root was actually GRANTED to this app (su answers uid=0), not only that an su file exists. null: not asked yet. Asked only while Root is the chosen
    // mode (a root manager shows a prompt for it), kept until the person checks again (the mode buttons) or switches to Root.
    private static Boolean rootGrant;

    private static void invalidateModeCache() {
        synchronized (modeCacheLock) {
            modeCacheJson = null;
            modeCacheGen++;
        }
    }

    private void setConfiguredMode(String mode) {
        invalidateModeCache();
        activeWorkingMode = knownWorkingMode(mode);
        cachedAutoMode = null;
        prefs.edit().putString("working_mode", activeWorkingMode).apply();
    }


    // ---------------------------------------------------------------------------------------------
    // Quick actions (Quick Settings tiles and the home-screen widget run these through QuickActionActivity)
    // ---------------------------------------------------------------------------------------------

    private void runQuickAction(Intent intent) {
        final String action = intent == null ? null : intent.getStringExtra(QuickActions.EXTRA_ACTION);
        executor.submit(new Runnable() {
            @Override
            public void run() {
                String message;
                try {
                    if (QuickActions.ACTION_CYCLE_MODE.equals(action)) {
                        message = quickCycleMode();
                        // the mode just changed and the page may not be open to probe it: probe here (the cache was invalidated), so the
                        // light the probe publishes (publishModeTileLight) follows the new mode; the passive tile reads it the next time the
                        // panel opens. This window asks no su (see probeWorkingMode), so its answer is not kept: the app's next look probes,
                        // and asks su, by itself.
                        try { new AndroidBridge().getWorkingMode(); } catch (Throwable ignored) {}
                        invalidateModeCache();
                    }
                    else if (QuickActions.ACTION_STOP_LIST.equals(action)) message = quickStopList();
                    else message = "Unknown quick action";
                } catch (Exception e) {
                    message = "Failed: " + (e.getMessage() != null ? e.getMessage() : e.getClass().getSimpleName());
                }
                finishQuickAction(message);
            }
        });
    }

    private void finishQuickAction(final String message) {
        runOnUiThread(new Runnable() {
            @Override
            public void run() {
                Toast.makeText(MainActivity.this, message, Toast.LENGTH_LONG).show();
                QuickWidgetProvider.refreshAll(MainActivity.this);
                // No tile refresh: both tiles are passive (no ACTIVE_TILE meta-data) and Android ignores requestListeningState for a passive
                // tile. Each tile reads its state in onStartListening the next time the panel opens (the tap's startActivityAndCollapse closed it).
                finish();
            }
        });
    }

    /**
     * Keeps the Working mode tile's light in step with the probe. The tile runs without this activity, so the probe's resolved mode and
     * whether it was available go to the preferences the tile reads (ModeTileLight.PREF_MODE / PREF_AVAILABLE); they are written only
     * when they changed. The tile is a passive one (no ACTIVE_TILE meta-data): Android calls its onStartListening, where it reads the keys
     * again, every time the Quick Settings panel opens, and a panel already open keeps the light it showed until it is opened again.
     * requestListeningState is not called here: Android ignores it for a passive tile.
     */
    private void publishModeTileLight(String resolved, boolean available) {
        try {
            String mode = resolved == null ? "" : resolved;
            android.content.SharedPreferences p = QuickActions.prefs(this);
            String oldMode = p.getString(ModeTileLight.PREF_MODE, "");
            boolean oldAvailable = p.getBoolean(ModeTileLight.PREF_AVAILABLE, false);
            if (mode.equals(oldMode) && available == oldAvailable) return;
            p.edit().putString(ModeTileLight.PREF_MODE, mode).putBoolean(ModeTileLight.PREF_AVAILABLE, available).apply();
        } catch (Throwable ignored) {}
    }

    /**
     * Samsung's One UI version as people write it ("9.0", "6.1.1"), or "" on a phone that is not a Samsung. It comes from ro.build.version.oneui
     * (60101 = 6.1.1, 90000 = 9.0) and, on older One UI, from Build.VERSION.SEM_PLATFORM_INT (150000 = 6.0: take away 90000).
     */
    private String oneUiVersion() {
        return oneUiVersion(null);
    }

    /** Build.MANUFACTURER or Build.BRAND says samsung. */
    private static boolean isSamsung() {
        return "samsung".equalsIgnoreCase(Build.MANUFACTURER) || "samsung".equalsIgnoreCase(Build.BRAND);
    }

    /**
     * oneUiVersion(), and in propertyUnset[0] (when given) whether getprop ro.build.version.oneui ran and printed nothing, that is the
     * property is not set (false when getprop failed, timed out or printed anything else): MonetProfile.oneUi tells "not One UI" from "could
     * not be read" with it (monetOneUi, the root theme card's note).
     */
    private String oneUiVersion(boolean[] propertyUnset) {
        try {
            if (!isSamsung()) return "";
            int v = 0;
            try {
                String line = runProcessWithTimeout(new ProcessBuilder("getprop", "ro.build.version.oneui"), 2000).trim();
                if (propertyUnset != null) propertyUnset[0] = line.isEmpty();
                if (line.matches("\\d{4,7}")) v = Integer.parseInt(line);
            } catch (Throwable ignored) {}
            if (v <= 0) {
                try {
                    int sem = Build.VERSION.class.getField("SEM_PLATFORM_INT").getInt(null);
                    if (sem >= 100000) v = sem - 90000;
                } catch (Throwable ignored) {}
            }
            return AppExtras.oneUi(v);
        } catch (Throwable t) {
            return "";
        }
    }

    /** The theme-colour profile, worked out once: the build and the colour names it has do not change while the app runs. */
    private volatile MonetProfile.Result monetProfileCache;

    /**
     * Which Android build family builds this phone's theme colours (MonetProfile): the SDK level, which of MonetProfile.PROBES the
     * framework has (getIdentifier(name, "color", "android") != 0) and which of MonetProfile.BOOL_PROBES (getIdentifier(name, "bool",
     * "android") != 0; no root, no shell). One UI is decided the same way (PR 13). A lookup that throws leaves the answer locked (fail
     * closed) and is not kept, so the next call looks again.
     */
    private MonetProfile.Result monetProfile() {
        MonetProfile.Result r = monetProfileCache;
        if (r != null) return r;
        Set<String> present = new HashSet<String>();
        try {
            Resources res = getResources();
            for (String name : MonetProfile.PROBES) if (res.getIdentifier(name, "color", "android") != 0) present.add(name);
            for (String name : MonetProfile.BOOL_PROBES) if (res.getIdentifier(name, "bool", "android") != 0) present.add(name);
        } catch (Throwable t) {
            return MonetProfile.of(Build.VERSION.SDK_INT, null);
        }
        r = MonetProfile.of(Build.VERSION.SDK_INT, present);
        monetProfileCache = r;
        return r;
    }

    /** The One UI value for the root theme card's note, worked out once it could be read (One UI does not change while the app runs). */
    private volatile String monetOneUiCache;

    /**
     * The One UI value getSystemPalette reports as "oneUi" (MonetProfile.oneUi: "" on a phone that is not One UI, the version on one,
     * MonetProfile.ONE_UI_UNREAD on a Samsung phone whose version could not be read, which is not kept so the next call reads again). It only
     * shows the page's note on the root theme card; it does not lock anything.
     */
    private String monetOneUi() {
        String v = monetOneUiCache;
        if (v != null) return v;
        boolean[] unset = {false};
        String version = oneUiVersion(unset);
        String oneUi = MonetProfile.oneUi(isSamsung(), version, unset[0]);
        if (!MonetProfile.ONE_UI_UNREAD.equals(oneUi)) monetOneUiCache = oneUi;
        return oneUi;
    }

    /**
     * The phone's contrast setting, the value SystemUI builds the theme colours at (UiModeManager.getContrast, Android 14 and newer),
     * through MonetProfile.contrast; 0 before Android 14 or when it cannot be read. Read on every call: it changes in Settings.
     */
    private double systemContrast() {
        if (Build.VERSION.SDK_INT < 34) return 0;
        try {
            android.app.UiModeManager um = (android.app.UiModeManager) getSystemService(Context.UI_MODE_SERVICE);
            return um == null ? 0 : MonetProfile.contrast(um.getContrast());
        } catch (Throwable t) {
            return 0;
        }
    }

    /** Is this backend usable right now, without showing any prompt? */
    private boolean modeReadyQuiet(String mode) {
        if ("adb_tcp".equals(mode)) return isAdbTargetConnected(tcpTarget());
        if ("adb_wireless".equals(mode)) return adbWirelessPort > 0 && isAdbTargetConnected(wirelessTarget());
        if ("shizuku".equals(mode)) return isShizukuAuthorized();
        if ("root".equals(mode)) {
            Boolean g;
            synchronized (modeCacheLock) { g = rootGrant; }
            return isRootAvailable() && (g == null || g);                 // no prompt here: not asked yet counts as possible, a known refusal does not
        }
        return false;
    }

    /** Switches to the next working mode that is ready (ADB TCP, Wireless, Shizuku, Root), else back to Automatic. */
    private String quickCycleMode() {
        String[] order = {"adb_tcp", "adb_wireless", "shizuku", "root"};
        int start = -1;
        for (int i = 0; i < order.length; i++) if (order[i].equals(activeWorkingMode)) start = i;
        // Starting from an explicit mode, only look at the OTHER backends (exclude step == order.length,
        // which would wrap back to the current one and "switch" to the mode already selected).
        int steps = start == -1 ? order.length : order.length - 1;
        for (int step = 1; step <= steps; step++) {
            String candidate = order[(start + step) % order.length];
            if (modeReadyQuiet(candidate)) {
                setConfiguredMode(candidate);
                return "Working mode: " + QuickActions.modeLabel(candidate);
            }
        }
        setConfiguredMode("auto");
        return "No other mode is ready. Using Automatic.";
    }

    // ---- SD Maid SE tab: the host of the four tools (see SdmHost) ----
    private final java.util.concurrent.ExecutorService sdmCalls = java.util.concurrent.Executors.newFixedThreadPool(3);
    private SdmHost sdmHostInstance;
    private boolean sdmClosed;      // set in onDestroy: a call that was already running must not build a new host (and engine threads) afterwards

    private synchronized SdmHost sdmHost() {
        if (sdmClosed) throw new IllegalStateException("the app is closing");
        if (sdmHostInstance == null) {
            sdmHostInstance = new SdmHost(this, new SdmHost.Hooks() {
                @Override public String mode() { return resolveExecMode(); }

                @Override
                public Process open(String script) throws IOException {
                    String mode = resolveExecMode();
                    try {
                        if ("adb_tcp".equals(mode) || "adb_wireless".equals(mode)) {
                            boolean tcp = "adb_tcp".equals(mode);
                            String target = tcp ? tcpTarget() : wirelessTarget();
                            if (!isAdbTargetConnected(target)) performConnect(tcp ? adbTcpHost : adbWirelessHost, tcp ? adbTcpPort : adbWirelessPort, null);
                            ProcessBuilder pb = buildAdbProcess("-s", target, "shell", script);
                            pb.redirectErrorStream(true);
                            return pb.start();
                        }
                        if ("shizuku".equals(mode)) return rishSpawn(new String[]{"sh", "-c", "exec 2>&1; " + script});
                        if ("root".equals(mode)) {
                            ProcessBuilder pb = new ProcessBuilder("su", "-c", script);
                            pb.redirectErrorStream(true);
                            return pb.start();
                        }
                    } catch (IOException e) {
                        throw e;
                    } catch (Exception e) {
                        throw new IOException(String.valueOf(e.getMessage()), e);
                    }
                    throw new IOException("Needs ADB, Shizuku or Root");
                }

                @Override public void js(String code) { notifyJs(code); }
                @Override public boolean storage() { return new AndroidBridge().hasAllFilesAccess(); }
                @Override public boolean usage() { return hasUsageAccess(); }
            });
        }
        return sdmHostInstance;
    }

    /**
     * Force-stops every app in the quick list, except this app, the WebView provider and Media Picker (QuickStopRun.protectedPackages): stopping those
     * would end this run or the window it is shown in. A notification shows how far it is and has Cancel (QuickStopNotice); it goes when the run ends.
     */
    private String quickStopList() throws Exception {
        JSONObject list = QuickActions.quickList(this);
        if (list == null) return "No quick list set. Open Saved Applications in the app and tap Quick list.";
        if ("standard".equals(resolveExecMode())) return "Needs ADB, Shizuku or Root. Set up a working mode first.";
        List<String> listed = new ArrayList<String>();
        org.json.JSONArray pkgs = list.optJSONArray("packages");
        for (int i = 0; pkgs != null && i < pkgs.length(); i++) listed.add(pkgs.optString(i));
        final Context app = getApplicationContext();                 // the notification does not depend on this (headless) window staying
        QuickStopRun run = new QuickStopRun(list.optString("id"), list.optString("name"), listed, QuickStopRun.protectedPackages(getPackageName(), webViewPackageName()));
        if (!QuickStopRun.begin(run, android.os.SystemClock.elapsedRealtime())) return "Kill Apps is already running. Tap Cancel in its notification to stop it.";
        // No tile refresh here or in finishQuickAction: the Kill Apps tile is passive (no ACTIVE_TILE meta-data), and
        // TileService.requestListeningState does nothing for a passive tile. Android reads QuickStopRun.tileActive() in the tile's
        // onStartListening each time the panel opens, so the tile is lit when the panel is opened while a run is going. Making the tile
        // active instead would change when Android redraws it (also its "list (N apps)" subtitle), which only a phone can show; not done.
        try {
            AndroidBridge bridge = new AndroidBridge();
            for (String pkg : run.targets()) {
                if (run.cancelled()) break;                          // Cancel: the apps not reached yet are left as they are
                run.starting(appLabel(pkg));
                if (run.shouldPost(android.os.SystemClock.elapsedRealtime())) QuickStopNotice.show(app, run);
                String out = bridge.executeAppAction("force_stop", pkg);
                // force_stop is flagged by its own real exit status (see AndroidBridge.runShellAction) - read that
                // rather than guessing from the text, same reasoning as the rest of executeAppAction's callers.
                boolean stopped;
                if (out != null && out.length() >= 2 && out.charAt(0) == '\u0001') stopped = out.charAt(1) == '1';
                else stopped = !launchOutputFailed(out);
                run.finished(stopped);
            }
        } finally {
            QuickStopRun.end(run);
            QuickStopNotice.clear(app, run);
        }
        return run.summary();
    }

    /** The package of the WebView this phone uses (Android System WebView, or Chrome on a phone that uses it), or "" when the phone does not say. */
    private static String webViewPackageName() {
        try {
            PackageInfo pi = WebView.getCurrentWebViewPackage();
            return pi == null || pi.packageName == null ? "" : pi.packageName;
        } catch (Throwable t) {
            return "";
        }
    }

    /** The name people know an app by, or its package name when the phone has none to give. */
    private String appLabel(String pkg) {
        try {
            PackageManager pm = getPackageManager();
            CharSequence label = pm.getApplicationLabel(pm.getApplicationInfo(pkg, PackageManager.MATCH_UNINSTALLED_PACKAGES));
            if (label != null && label.length() > 0) return label.toString();
        } catch (Exception ignored) {}
        return pkg;
    }

    // ---------------------------------------------------------------------------------------------
    // Process helpers
    // ---------------------------------------------------------------------------------------------

    private boolean isDebuggableBuild() {
        return (getApplicationInfo().flags & ApplicationInfo.FLAG_DEBUGGABLE) != 0;
    }

    private ProcessBuilder buildAdbProcess(String... args) {
        return buildAdbProcess(AdbRuntime.serverArgs(this), args);
    }

    /** {@code serverArgs} say where adb's server listens: a private unix socket, or (fallback and the old server) loopback port 5042. */
    private ProcessBuilder buildAdbProcess(List<String> serverArgs, String... args) {
        List<String> cmd = new ArrayList<String>();
        cmd.add(adbBinFile != null && adbBinFile.exists() ? adbBinFile.getAbsolutePath() : "adb");
        cmd.addAll(serverArgs);
        Collections.addAll(cmd, args);
        ProcessBuilder pb = new ProcessBuilder(cmd);
        Map<String, String> env = pb.environment();
        if (adbHomeDir != null) {
            env.put("HOME", adbHomeDir.getAbsolutePath());
            env.put("ANDROID_USER_HOME", adbHomeDir.getAbsolutePath());
            File dotKey = new File(new File(adbHomeDir, ".android"), "adbkey");
            if (dotKey.exists()) {
                env.put("ADB_VENDOR_KEYS", dotKey.getAbsolutePath());
            }
        }
        env.put("TMPDIR", getCacheDir().getAbsolutePath());
        AdbRuntime.applyEnv(this, env);
        pb.redirectErrorStream(true);
        return pb;
    }

    // ---------------------------------------------------------------------------------------------
    // Wi-Fi pairing notification (inline reply runs `adb pair` straight from the shade)
    // ---------------------------------------------------------------------------------------------

    private void toastUi(final String msg) {
        runOnUiThread(new Runnable() {
            @Override
            public void run() {
                Toast.makeText(MainActivity.this, msg, Toast.LENGTH_LONG).show();
            }
        });
    }

    /** Posts the inline-reply pairing notification. Ensures notification permission, discovers the
     *  current `_adb-tls-pairing` endpoint via mDNS off the UI thread, then builds the notification. */
    private void postPairingNotification() {
        if (Build.VERSION.SDK_INT >= 33) {
            if (checkSelfPermission("android.permission.POST_NOTIFICATIONS")
                    != PackageManager.PERMISSION_GRANTED) {
                try {
                    requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"}, 9201);
                } catch (Exception ignored) {}
                toastUi("Allow notifications, then tap “Pair via notification” again.");
                return;
            }
        }
        toastUi("Preparing pairing notification…");
        new Thread(new Runnable() {
            public void run() {
                String endpoint = "";
                try {
                    String raw = runProcessWithTimeout(buildAdbProcess("mdns", "services"), 4000);
                    if (raw != null) {
                        for (String line : raw.split("\n")) {
                            if (line.contains("_adb-tls-pairing")) {
                                String[] parts = line.trim().split("\\s+");
                                String ep = parts.length > 0 ? parts[parts.length - 1] : "";
                                if (ep.contains(":")) { endpoint = ep; break; }
                            }
                        }
                    }
                } catch (Exception ignored) {}
                final String ep = endpoint;
                runOnUiThread(new Runnable() {
                    public void run() { buildAndPostPairingNotification(ep); }
                });
            }
        }).start();
    }

    /** Builds and shows the pairing notification with a RemoteInput "Pair" action. Replying runs
     *  `adb pair` in {@link PairReceiver} without the app needing to be open. */
    private void buildAndPostPairingNotification(String endpoint) {
        try {
            android.app.NotificationManager nm =
                    (android.app.NotificationManager) getSystemService(NOTIFICATION_SERVICE);
            if (nm == null) return;
            nm.createNotificationChannel(new android.app.NotificationChannel(
                    PairReceiver.CHANNEL, "Wi-Fi pairing", android.app.NotificationManager.IMPORTANCE_HIGH));

            boolean haveEndpoint = endpoint != null && !endpoint.isEmpty();
            String hint = haveEndpoint
                    ? "6-digit pairing code"
                    : "port code  (e.g. 37123 123456)";

            android.app.RemoteInput remoteInput = new android.app.RemoteInput.Builder(PairReceiver.KEY_CODE)
                    .setLabel(hint)
                    .build();

            Intent replyIntent = new Intent(this, PairReceiver.class).setAction(PairReceiver.ACTION);
            if (haveEndpoint) replyIntent.putExtra(PairReceiver.EXTRA_ENDPOINT, endpoint);
            int replyFlags = android.app.PendingIntent.FLAG_UPDATE_CURRENT;
            if (Build.VERSION.SDK_INT >= 31) replyFlags |= android.app.PendingIntent.FLAG_MUTABLE;
            android.app.PendingIntent replyPending = android.app.PendingIntent.getBroadcast(
                    this, 71, replyIntent, replyFlags);

            android.app.Notification.Action action = new android.app.Notification.Action.Builder(
                    android.graphics.drawable.Icon.createWithResource(this, R.drawable.ic_stat),
                    "Pair", replyPending)
                    .addRemoteInput(remoteInput)
                    .build();

            String body = haveEndpoint
                    ? ("Found pairing service at " + endpoint + ".\nTap Pair and type the 6-digit code shown on your device.")
                    : "On your device: Wireless debugging ▸ Pair device with pairing code.\nTap Pair and reply with: port code  (e.g. 37123 123456).";

            Intent openIntent = new Intent(this, MainActivity.class);
            int openFlags = android.app.PendingIntent.FLAG_UPDATE_CURRENT;
            if (Build.VERSION.SDK_INT >= 31) openFlags |= android.app.PendingIntent.FLAG_IMMUTABLE;
            android.app.PendingIntent openPending =
                    android.app.PendingIntent.getActivity(this, 72, openIntent, openFlags);

            android.app.Notification n = new android.app.Notification.Builder(this, PairReceiver.CHANNEL)
                    .setSmallIcon(R.drawable.ic_stat)
                    .setContentTitle("Pair over Wi-Fi")
                    .setContentText(haveEndpoint
                            ? ("Tap Pair, then enter the code for " + endpoint)
                            : "Tap Pair, then enter: port code")
                    .setStyle(new android.app.Notification.BigTextStyle().bigText(body))
                    .addAction(action)
                    .setContentIntent(openPending)
                    .setAutoCancel(false)
                    .build();
            nm.notify(PairReceiver.NOTIF_ID, n);
            Toast.makeText(this, "Pairing notification posted — open your shade to enter the code.",
                    Toast.LENGTH_LONG).show();
        } catch (Exception e) {
            Toast.makeText(this, "Couldn't post pairing notification: " + e.getMessage(),
                    Toast.LENGTH_LONG).show();
        }
    }

    private String runProcessWithTimeout(ProcessBuilder pb, int timeoutMs) {
        try {
            return readProcessWithTimeout(pb.start(), timeoutMs);
        } catch (Exception e) {
            return "Error: " + e.getMessage();
        }
    }

    private String readProcessWithTimeout(final Process p, int timeoutMs) {
        final StringBuilder sb = new StringBuilder();
        FutureTask<String> future = new FutureTask<String>(new Callable<String>() {
            @Override
            public String call() throws Exception {
                BufferedReader reader = new BufferedReader(new InputStreamReader(p.getInputStream()));
                String line;
                while ((line = reader.readLine()) != null) {
                    synchronized (sb) {
                        sb.append(line).append("\n");
                    }
                }
                reader.close();
                p.waitFor();
                return "";
            }
        });
        try {
            executor.execute(future);
        } catch (RejectedExecutionException closing) {
            // the activity is being destroyed (a theme change restarts it): the command is already running, so read it out on a thread of its own
            Thread reader = new Thread(future, "proc-read");
            reader.setDaemon(true);
            reader.start();
        }

        try {
            future.get(timeoutMs, TimeUnit.MILLISECONDS);
        } catch (Exception timeoutEx) {
            future.cancel(true);
            try { p.destroy(); } catch (Exception ignored) {}
            try { p.getInputStream().close(); } catch (Exception ignored) {}     // ends the reader even when a child keeps the pipe open
            synchronized (sb) {
                sb.append("\n[Process timed out after ").append(timeoutMs).append("ms]");
            }
        }
        synchronized (sb) {
            return sb.toString().trim();
        }
    }

    private boolean isPortOpen(String host, int port, int timeoutMs) {
        Socket socket = null;
        try {
            socket = new Socket();
            socket.connect(new InetSocketAddress(host, port), timeoutMs);
            return true;
        } catch (Exception e) {
            return false;
        } finally {
            if (socket != null) {
                try { socket.close(); } catch (Exception ignored) {}
            }
        }
    }

    // ---------------------------------------------------------------------------------------------
    // ADB backends
    // ---------------------------------------------------------------------------------------------

    private String adbDevicesOutput() {
        return runProcessWithTimeout(buildAdbProcess("devices"), 2500);
    }

    /** True when `adb devices` lists the target in the ready "device" state (not offline/unauthorized). */
    private static boolean isTargetReady(String devicesOutput, String target) {
        if (devicesOutput == null) return false;
        for (String line : devicesOutput.split("\n")) {
            String[] parts = line.trim().split("\\s+");
            if (parts.length >= 2 && parts[0].equals(target) && "device".equals(parts[1])) {
                return true;
            }
        }
        return false;
    }

    private boolean isAdbTargetConnected(String target) {
        return isTargetReady(adbDevicesOutput(), target);
    }

    private String tcpTarget() {
        return adbTcpHost + ":" + adbTcpPort;
    }

    private String wirelessTarget() {
        return adbWirelessHost + ":" + adbWirelessPort;
    }

    /**
     * Runs `adb connect host:port`. When selectMode is non-null and the target ends up ready,
     * that mode becomes the configured mode (explicit user action). Otherwise the mode is untouched.
     */
    private String performConnect(String host, int port, String selectMode) {
        invalidateModeCache();
        if (host == null || host.trim().isEmpty()) host = "127.0.0.1";
        host = host.trim();
        String target = host + ":" + port;

        String output = runProcessWithTimeout(buildAdbProcess("connect", target), 6000);
        Log.d(TAG, "adb connect " + target + " -> " + output);

        boolean ready = isAdbTargetConnected(target);
        String moved = null;
        if (!ready && selectMode == null && port == adbWirelessPort && host.equals(adbWirelessHost) && !target.equals(tcpTarget())) {
            moved = reconnectWirelessViaMdns(host, port);   // the saved Wireless Debugging port went stale: find the current one
            ready = moved != null;
        }
        if (ready && selectMode != null) {
            setConfiguredMode(selectMode);
        }
        cachedAutoMode = null;
        invalidateModeCache();                      // connected (or not) now: a probe that overlapped the connect must not keep the old picture
        if (output == null) output = "";
        if (moved != null) return moved;
        if (!ready && !output.toLowerCase().contains("fail") && !output.toLowerCase().contains("error")) {
            output = output + (output.isEmpty() ? "" : "\n") + "Target " + target + " is not ready (check the authorization prompt on the device).";
        }
        return output;
    }

    /**
     * Wireless Debugging takes a new random port each time it is switched on, so the saved one goes stale. Asks adb's mDNS for the phone's
     * current connect endpoint (same host only, see {@link WirelessReconnect}), connects to it and, once it is ready, saves it. Returns a
     * sentence for the person, or null when no endpoint was found or none would connect (the saved port is then left as it was).
     */
    private String reconnectWirelessViaMdns(String host, int stalePort) {
        String raw = runProcessWithTimeout(buildAdbProcess("mdns", "services"), 4000);
        List<String> tries = WirelessReconnect.candidates(WirelessReconnect.connectEndpoints(raw), host, stalePort, deviceWifiIp());
        for (int i = 0; i < tries.size() && i < 2; i++) {
            String ep = tries.get(i);
            String out = runProcessWithTimeout(buildAdbProcess("connect", ep), 6000);
            Log.d(TAG, "adb connect " + ep + " (mDNS) -> " + out);
            if (!isAdbTargetConnected(ep)) continue;
            adbWirelessHost = WirelessReconnect.hostOf(ep);
            adbWirelessPort = WirelessReconnect.splitPort(ep);
            prefs.edit().putString("adb_wireless_host", adbWirelessHost).putInt("adb_wireless_port", adbWirelessPort).apply();
            return "Wireless Debugging moved from port " + stalePort + " to " + adbWirelessPort + "; connected to " + ep + " and saved the new port.";
        }
        return null;
    }

    private final java.util.concurrent.atomic.AtomicBoolean shizukuStarting = new java.util.concurrent.atomic.AtomicBoolean();

    private static JSONObject shizukuStartResult(String status, String pkg, ShizukuStart.Result r) {
        JSONObject o = new JSONObject();
        try {
            o.put("status", status);
            o.put("pkg", pkg == null ? "" : pkg);
            if (r != null) {
                o.put("script", r.script);
                o.put("exit", r.exit);
                o.put("text", r.text);
            }
        } catch (Exception ignored) {}
        return o;
    }

    /**
     * Runs the start script the installed Shizuku app wrote (see {@link ShizukuStart}) through a ready ADB TCP or Wireless Debugging connection,
     * then reads the binder back: "started" only when Shizuku answers afterwards, whatever the script printed. Usually a few seconds; the bound is
     * about 36 seconds (adb devices 2.5 s, a reconnect of 5 s when the link had dropped, the script up to ShizukuStart.SCRIPT_TIMEOUT_MS = 20 s,
     * then the binder poll of 16 x 500 ms), so it runs on the executor.
     */
    private JSONObject startShizukuNow() {
        if (isShizukuBinderAlive()) return shizukuStartResult("already_running", installedShizukuPackage(), null);
        String pkg = installedShizukuPackage();
        if (pkg == null) return shizukuStartResult("not_installed", "", null);
        String devices = adbDevicesOutput();
        String target = isTargetReady(devices, tcpTarget()) ? tcpTarget()
                : (adbWirelessPort > 0 && isTargetReady(devices, wirelessTarget())) ? wirelessTarget() : null;
        if (target == null) return shizukuStartResult("no_adb", pkg, null);
        String cmd = ShizukuStart.command(pkg);
        if (cmd == null) return shizukuStartResult("failed", pkg, null);
        ShizukuStart.Result r = ShizukuStart.parse(runAdbShell(target, cmd, ShizukuStart.SCRIPT_TIMEOUT_MS));     // not the 8 s of a plain command: a slow start is not cut off
        if (r.noScript) return shizukuStartResult("no_script", pkg, r);
        boolean alive = false;
        for (int i = 0; i < 16 && !activityDestroyed; i++) {
            if (isShizukuBinderAlive()) { alive = true; break; }
            try { Thread.sleep(500); } catch (InterruptedException e) { Thread.currentThread().interrupt(); break; }
        }
        invalidateModeCache();
        return shizukuStartResult(alive ? "started" : "failed", pkg, r);
    }

    private String connectTcp(String host, int port, boolean select) {
        if (host == null || host.trim().isEmpty()) host = "127.0.0.1";
        if (port <= 0) port = 5555;
        adbTcpHost = host.trim();
        adbTcpPort = port;
        prefs.edit().putString("adb_tcp_host", adbTcpHost).putInt("adb_tcp_port", adbTcpPort).apply();
        return performConnect(adbTcpHost, adbTcpPort, select ? "adb_tcp" : null);
    }

    private String connectWireless(String host, int port, boolean select) {
        if (port <= 0) return "Error: Invalid wireless debugging port";
        if (host == null || host.trim().isEmpty()) host = "127.0.0.1";
        adbWirelessHost = host.trim();
        adbWirelessPort = port;
        prefs.edit().putString("adb_wireless_host", adbWirelessHost).putInt("adb_wireless_port", adbWirelessPort).apply();
        return performConnect(adbWirelessHost, adbWirelessPort, select ? "adb_wireless" : null);
    }

    private String runAdbShell(String target, String cmd) {
        return runAdbShell(target, cmd, 8000);
    }

    private String runAdbShell(String target, String cmd, int timeoutMs) {
        String output = runProcessWithTimeout(buildAdbProcess("-s", target, "shell", cmd), timeoutMs);
        if (output != null && output.contains("device '") && output.contains("' not found")) {
            // The connection dropped (e.g. adbd restarted). Reconnect once without changing the mode.
            runProcessWithTimeout(buildAdbProcess("connect", target), 5000);
            output = runProcessWithTimeout(buildAdbProcess("-s", target, "shell", cmd), timeoutMs);
        }
        return output != null ? output : "";
    }

    // ---------------------------------------------------------------------------------------------
    // Shizuku backend
    // ---------------------------------------------------------------------------------------------

    private boolean isPackageInstalled(String pkg) {
        try {
            getPackageManager().getPackageInfo(pkg, 0);
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    private String installedShizukuPackage() {
        if (isPackageInstalled(SHIZUKU_PKG)) return SHIZUKU_PKG;
        if (isPackageInstalled(SHIZUKU_PLUS_PKG)) return SHIZUKU_PLUS_PKG;
        return null;
    }

    private static boolean isShizukuBinderAlive() {
        try {
            return Shizuku.pingBinder();
        } catch (Throwable t) {
            return false;
        }
    }

    private static boolean isShizukuAuthorized() {
        try {
            return Shizuku.pingBinder() && !Shizuku.isPreV11()
                    && Shizuku.checkSelfPermission() == PackageManager.PERMISSION_GRANTED;
        } catch (Throwable t) {
            return false;
        }
    }

    private JSONObject shizukuStatus() {
        JSONObject obj = new JSONObject();
        try {
            String pkg = installedShizukuPackage();
            boolean running = isShizukuBinderAlive();
            boolean authorized = isShizukuAuthorized();
            boolean preV11 = false;
            int version = 0;
            int uid = -1;
            if (running) {
                try {
                    preV11 = Shizuku.isPreV11();
                    version = Shizuku.getVersion();
                    uid = Shizuku.getUid();                 // 0 root, 1000 system, 2000 ADB shell; the gate (RootGate) reads it
                } catch (Throwable ignored) {}
            }
            obj.put("installed", pkg != null || running);
            obj.put("manager", pkg != null ? pkg : "");
            obj.put("running", running);
            obj.put("authorized", authorized);
            obj.put("preV11", preV11);
            obj.put("version", version);
            obj.put("uid", uid);
        } catch (Exception ignored) {}
        return obj;
    }

    /** The uid the Shizuku server runs as (0 root, 1000 system, 2000 ADB shell), or -1 when the binder is down or it cannot be read. */
    private int shizukuServerUid() {
        try {
            if (!isShizukuBinderAlive()) return -1;
            return Shizuku.getUid();
        } catch (Throwable t) {
            return -1;
        }
    }

    private static Method shizukuNewProcessMethod;

    private String runShizukuShell(String cmd) {
        // Preferred path: Shizuku API remote process (fast, no app_process start-up cost)
        if (isShizukuAuthorized()) {
            try {
                if (shizukuNewProcessMethod == null) {
                    Method m = Shizuku.class.getDeclaredMethod("newProcess", String[].class, String[].class, String.class);
                    m.setAccessible(true);
                    shizukuNewProcessMethod = m;
                }
                Process p = (Process) shizukuNewProcessMethod.invoke(null,
                        new String[]{"sh", "-c", "exec 2>&1; " + cmd}, null, null);
                return readProcessWithTimeout(p, 10000);
            } catch (Throwable t) {
                Log.w(TAG, "Shizuku newProcess failed, falling back to rish: " + t.getMessage());
            }
        }

        // Fallback: rish shell bundled in assets
        if (rishFile != null && rishFile.exists()) {
            ProcessBuilder pb = new ProcessBuilder("/system/bin/sh", rishFile.getAbsolutePath(), "-c", cmd);
            pb.environment().put("RISH_APPLICATION_ID", getPackageName());
            pb.redirectErrorStream(true);
            return runProcessWithTimeout(pb, 10000);
        }
        return "Error: Shizuku is not authorized for this app";
    }

    // ---------------------------------------------------------------------------------------------
    // Rish shell: the Terminal tab's persistent shell (see RishShell). It runs as the Shizuku shell
    // user, so cd / export / variables persist between commands. Output is streamed to the page.
    // ---------------------------------------------------------------------------------------------

    private static final long RISH_COMMAND_TIMEOUT_MS = 10 * 60 * 1000;
    private static final int RISH_OUTPUT_CAP = 1500000;    // characters shown per command
    private static final int RISH_FLUSH_CHARS = 24000;
    private static final long RISH_FLUSH_MS = 40;

    private static final int RISH_IDLE_CHARS_PER_SEC = 200000;     // background-job output the page is sent per second at most

    private final Object rishGate = new Object();
    private static volatile String rishLastCwd = "";       // where the shell was last, so the next one opens there (read and written from different threads)
    private long rishIdleWindowAt;
    private int rishIdleChars;
    private boolean rishIdleDropped;
    private RishShell rishShell;           // guarded by rishGate
    private boolean rishStarting;          // guarded by rishGate
    private boolean rishRunning;           // guarded by rishGate
    private final StringBuilder rishOut = new StringBuilder();   // guarded by itself
    private String rishOutRunId = "";
    private boolean rishFlushScheduled;
    private final android.os.Handler rishHandler = new android.os.Handler(android.os.Looper.getMainLooper());
    private final Runnable rishFlusher = new Runnable() {
        @Override
        public void run() {
            rishFlush();
        }
    };

    /** Starts a process through the Shizuku API, or through the bundled rish when that call fails. */
    private Process rishSpawn(String[] argv) throws Exception {
        if (isShizukuAuthorized()) {
            try {
                if (shizukuNewProcessMethod == null) {
                    Method m = Shizuku.class.getDeclaredMethod("newProcess", String[].class, String[].class, String.class);
                    m.setAccessible(true);
                    shizukuNewProcessMethod = m;
                }
                return (Process) shizukuNewProcessMethod.invoke(null, argv, null, null);
            } catch (Throwable t) {
                Log.w(TAG, "Shizuku newProcess failed for the Rish shell, trying the bundled rish: " + t.getMessage());
            }
        }
        if (rishFile != null && rishFile.exists()) {
            List<String> cmd = new ArrayList<String>();
            cmd.add("/system/bin/sh");
            cmd.add(rishFile.getAbsolutePath());
            if (argv.length > 1) {
                cmd.add("-c");
                StringBuilder script = new StringBuilder();
                for (int i = 2; i < argv.length; i++) script.append(i > 2 ? " " : "").append(argv[i]);
                cmd.add(script.toString());
            }
            ProcessBuilder pb = new ProcessBuilder(cmd);
            pb.environment().put("RISH_APPLICATION_ID", getPackageName());
            return pb.start();
        }
        throw new IOException("Shizuku is not authorized for this app");
    }

    /**
     * Output that arrives while no command is running (a background job). A runaway one (`yes &`) can produce tens of
     * megabytes a second, so the page gets a bounded share and one note that the rest was dropped.
     */
    private void rishEmitIdle(String text) {
        boolean notice = false;
        synchronized (rishOut) {
            long now = System.nanoTime() / 1000000L;
            if (now - rishIdleWindowAt >= 1000) {
                rishIdleWindowAt = now;
                rishIdleChars = 0;
                rishIdleDropped = false;
            }
            if (rishIdleChars >= RISH_IDLE_CHARS_PER_SEC) {
                if (!rishIdleDropped) {
                    rishIdleDropped = true;
                    notice = true;
                } else {
                    return;
                }
            } else {
                rishIdleChars += text.length();
            }
        }
        rishEmit("", notice ? "\n[a background job is printing faster than this screen can show: output is being dropped]\n" : text);
    }

    /** Buffers shell output and sends it to the page a few times a second instead of once per read. */
    private void rishEmit(String runId, String text) {
        synchronized (rishOut) {
            if (rishOut.length() > 0 && !runId.equals(rishOutRunId)) rishFlushLocked();
            rishOutRunId = runId;
            rishOut.append(text);
            if (rishOut.length() >= RISH_FLUSH_CHARS) {
                rishFlushLocked();
            } else if (!rishFlushScheduled) {
                rishFlushScheduled = true;
                rishHandler.postDelayed(rishFlusher, RISH_FLUSH_MS);
            }
        }
    }

    private void rishFlush() {
        synchronized (rishOut) {
            rishFlushLocked();
        }
    }

    /** Posts the buffered output to the UI thread in order (post order == buffer order). */
    private void rishFlushLocked() {
        rishFlushScheduled = false;
        rishHandler.removeCallbacks(rishFlusher);
        if (rishOut.length() == 0) return;
        final String runId = rishOutRunId;
        final String text = rishOut.toString();
        rishOut.setLength(0);
        rishHandler.post(new Runnable() {
            @Override
            public void run() {
                if (activityDestroyed || webView == null) return;     // onDestroy may have run since this was queued
                int i = 0;
                while (i < text.length()) {
                    int end = Math.min(text.length(), i + 32000);
                    if (end < text.length() && Character.isHighSurrogate(text.charAt(end - 1))) end++;
                    webView.evaluateJavascript("window.onRishOutput && window.onRishOutput(" + JSONObject.quote(runId)
                            + "," + JSONObject.quote(text.substring(i, end)) + ")", null);
                    i = end;
                }
            }
        });
    }

    private void closeRishShell() {
        final RishShell sh;
        synchronized (rishGate) {
            sh = rishShell;
            rishShell = null;
        }
        if (sh != null) {
            executor.submit(new Runnable() {
                @Override
                public void run() {
                    sh.close();
                }
            });
        }
    }

    // ---------------------------------------------------------------------------------------------
    // Terminal tab (v7.8): the Terminal sub-tab's persistent shells, one per backend, and the coding agents'
    // HTTPS calls. Backends: "app" (this app's own sandbox, always there), "priv" (the working mode: Shizuku,
    // Root or ADB) and "termux" (the user's own Termux: bash and everything installed with pkg, through
    // TermuxBridge + TermuxLink). Each one is a RishShell, so cd and exports persist between commands.
    // ---------------------------------------------------------------------------------------------

    private static final long TERM_COMMAND_TIMEOUT_MS = 30 * 60 * 1000;      // a package install or a build can take a while
    private static final int TERM_OUTPUT_CAP = 2000000;                        // characters shown per command
    private static final int TERM_QUIET_CAP = 4 * 1024 * 1024;                // what a quiet command (the agents' file reads) may return
    private static final int TERM_IDLE_CHARS_PER_SEC = 200000;
    private static final int REQ_TERMUX_PERM = 9302;

    /** Batches text for one page callback, window.fn(args..., text): a few calls a second instead of one per read, in order. */
    private final class JsStream {
        private final String fn;
        private final StringBuilder buf = new StringBuilder();
        private String args = "";
        private boolean scheduled;
        private final Runnable flusher = new Runnable() {
            @Override
            public void run() {
                flush();
            }
        };

        JsStream(String fn) {
            this.fn = fn;
        }

        /** {@code argsJs}: the callback's leading arguments as JavaScript (already quoted). Text for different arguments never mixes. */
        void add(String argsJs, String text) {
            if (text == null || text.isEmpty()) return;
            synchronized (buf) {
                if (buf.length() > 0 && !argsJs.equals(args)) flushLocked();
                args = argsJs;
                buf.append(text);
                if (buf.length() >= 24000) {
                    flushLocked();
                } else if (!scheduled) {
                    scheduled = true;
                    rishHandler.postDelayed(flusher, 40);
                }
            }
        }

        void flush() {
            synchronized (buf) {
                flushLocked();
            }
        }

        private void flushLocked() {
            scheduled = false;
            rishHandler.removeCallbacks(flusher);
            if (buf.length() == 0) return;
            final String a = args;
            final String text = buf.toString();
            buf.setLength(0);
            rishHandler.post(new Runnable() {
                @Override
                public void run() {
                    if (activityDestroyed || webView == null) return;     // onDestroy may have run since this was queued
                    int i = 0;
                    while (i < text.length()) {
                        int end = Math.min(text.length(), i + 32000);
                        if (end < text.length() && Character.isHighSurrogate(text.charAt(end - 1))) end++;
                        webView.evaluateJavascript("window." + fn + " && window." + fn + "(" + a + "," + JSONObject.quote(text.substring(i, end)) + ")", null);
                        i = end;
                    }
                }
            });
        }
    }

    private final class TermSlot {
        final String backend;
        RishShell shell;
        String kind = "";            // what it runs on: app, shizuku, root, adb, termux
        boolean starting;
        boolean running;
        long idleWindowAt;
        int idleChars;
        boolean idleDropped;
        final JsStream out = new JsStream("onTermOutput");

        TermSlot(String backend) {
            this.backend = backend;
        }

        /** Output while no command runs (a background job). A runaway one gets a bounded share and one note. */
        void idle(String text) {
            boolean notice = false;
            synchronized (this) {
                long now = System.nanoTime() / 1000000L;
                if (now - idleWindowAt >= 1000) {
                    idleWindowAt = now;
                    idleChars = 0;
                    idleDropped = false;
                }
                if (idleChars >= TERM_IDLE_CHARS_PER_SEC) {
                    if (idleDropped) return;
                    idleDropped = true;
                    notice = true;
                } else {
                    idleChars += text.length();
                }
            }
            out.add(JSONObject.quote(backend) + ",\"\"", notice ? "\n[a background job is printing faster than this screen can show: output is being dropped]\n" : text);
        }
    }

    private final Object termGate = new Object();
    private final Map<String, TermSlot> termSlots = new java.util.HashMap<String, TermSlot>();     // guarded by termGate

    /** What the "priv" backend runs on right now: shizuku, root, adb, or null with no privileged working mode. */
    private String termPrivKind() {
        String mode = resolveExecMode();
        if ("shizuku".equals(mode)) return isShizukuAuthorized() ? "shizuku" : null;
        if ("root".equals(mode)) return "root";
        if ("adb_tcp".equals(mode) || "adb_wireless".equals(mode)) return "adb";
        return null;
    }

    private RishShell.Spawner termSpawner(String kind, JSONObject opts) {
        if ("shizuku".equals(kind)) {
            return new RishShell.Spawner() {
                @Override
                public Process spawn(String[] argv) throws Exception {
                    return rishSpawn(argv);
                }
            };
        }
        if ("root".equals(kind)) {
            return new RishShell.Spawner() {
                @Override
                public Process spawn(String[] argv) throws Exception {
                    return (argv.length >= 3 && "-c".equals(argv[1]) ? new ProcessBuilder("su", "-c", argv[2]) : new ProcessBuilder("su")).start();
                }
            };
        }
        if ("adb".equals(kind)) {
            final boolean tcp = !"adb_wireless".equals(resolveExecMode());
            final String target = tcp ? tcpTarget() : wirelessTarget();
            final String host = tcp ? adbTcpHost : adbWirelessHost;
            final int port = tcp ? adbTcpPort : adbWirelessPort;
            return new RishShell.Spawner() {
                @Override
                public Process spawn(String[] argv) throws Exception {
                    if (argv.length >= 3 && "-c".equals(argv[1])) return buildAdbProcess("-s", target, "shell", argv[2]).start();   // a helper (Stop, ps) next to a shell that is up
                    // the shell itself: a link that dropped (adbd restarted) is connected again first, as every other adb command does
                    if (!isAdbTargetConnected(target)) performConnect(host, port, null);
                    // -T: no terminal on the phone's side; the shell reads the commands this app writes
                    return buildAdbProcess("-s", target, "shell", "-T").start();
                }
            };
        }
        if ("termux".equals(kind)) {
            boolean login = opts == null || opts.optBoolean("profile", true);
            String cwd = opts == null ? "" : opts.optString("cwd", "");
            return TermuxLink.spawner(TermuxBridge.launcher(this), TermuxBridge.BASH, cwd, login, 25000);
        }
        // this app's own sandbox: always there, no privileges (toybox, and files under the app's home folder)
        final File home = new File(getFilesDir(), "home");
        if (!home.isDirectory()) home.mkdirs();
        return new RishShell.Spawner() {
            @Override
            public Process spawn(String[] argv) throws Exception {
                ProcessBuilder pb = argv.length >= 3 && "-c".equals(argv[1]) ? new ProcessBuilder("/system/bin/sh", "-c", argv[2])
                        : new ProcessBuilder("/system/bin/sh");
                pb.directory(home);
                Map<String, String> env = pb.environment();
                env.put("HOME", home.getAbsolutePath());
                env.put("TMPDIR", getCacheDir().getAbsolutePath());
                return pb.start();
            }
        };
    }

    /** Set up once per new shell: no pagers or terminal tricks (there is no keyboard input to running programs). */
    private static String termInitScript(String kind, boolean matchEnv) {
        StringBuilder s = new StringBuilder("export PAGER=cat GIT_PAGER=cat MANPAGER=cat TERM=dumb GIT_TERMINAL_PROMPT=0 2>/dev/null; ");
        if ("termux".equals(kind)) {
            s.append("export DEBIAN_FRONTEND=noninteractive PATH=\"$HOME/.local/bin:$HOME/bin:$PATH\"; ")
                    // pkg / apt would stop at "Do you want to continue? [Y/n]" with no way to answer: they answer yes here
                    .append("pkg() { case \"$1\" in install|reinstall|upgrade|update|uninstall|remove|autoremove|full-upgrade) ")
                    .append("local c=\"$1\"; shift; command pkg \"$c\" -y \"$@\";; *) command pkg \"$@\";; esac; }; ")
                    .append("apt() { case \"$1\" in install|reinstall|upgrade|remove|purge|autoremove|full-upgrade|dist-upgrade) ")
                    .append("local c=\"$1\"; shift; command apt \"$c\" -y \"$@\";; *) command apt \"$@\";; esac; }; ");
            // "profile" (login shell) already reads ~/.bash_profile or ~/.profile; neither of those pulls in ~/.bashrc
            // unless the user's own profile chains to it, so without this, aliases/functions/exports a Termux user
            // keeps in .bashrc would silently be missing here even with the login profile on. Two things stop a plain
            // "source ~/.bashrc" in this (non-interactive) shell: aliases are not expanded unless asked for, and the usual
            // first lines of a .bashrc ("[[ $- != *i* ]] && return", "case $- in *i*) ;; *) return;; esac") end the file at once.
            // So aliases are switched on and those guard lines are left out of the copy that is read.
            if (matchEnv) {
                s.append("if [ -f \"$HOME/.bashrc\" ]; then shopt -s expand_aliases 2>/dev/null; ")
                        .append(". <(sed -e '/^[[:space:]]*\\[\\[ *\\$- *!= *\\*i\\* *\\]\\] *&& *return/d' -e '/^[[:space:]]*\\[ *-z *\"\\$PS1\" *\\] *&& *return/d' ")
                        .append("-e '/^[[:space:]]*case *\\$- *in/,/^[[:space:]]*esac/d' \"$HOME/.bashrc\") >/dev/null 2>&1; fi; ");
            }
            // what "Sync with Termux" shows once the shell is up: the proof that this shell is Termux's, and what it took over
            s.append("adbmgr_sync_report() { local a=0 f=0 n; while read -r _; do a=$((a+1)); done < <(alias 2>/dev/null); ")
                    .append("while read -r _ _ n; do case \"$n\" in _*|pkg|apt|adbmgr_*) ;; *) f=$((f+1));; esac; done < <(declare -F 2>/dev/null); ")
                    .append("printf 'Synced with Termux\\n  bash %s, home %s\\n  packages in %s\\n  taken from ~/.bashrc: %s aliases, %s functions\\n  phone storage: %s\\n' ")
                    .append("\"$BASH_VERSION\" \"$HOME\" \"${PREFIX:-unknown}\" \"$a\" \"$f\" ")
                    .append("\"$([ -d \"$HOME/storage/shared\" ] && echo 'set up' || echo 'not set up yet: Settings > Set up storage in Termux')\"; }; ");
        }
        s.append("true");
        return s.toString();
    }

    // ---- The real terminal (a pseudo-terminal through libptyexec.so, see PtyShell): the full-screen Terminal's sessions ----
    private final SessionMap<PtyShell> ptySessions = new SessionMap<PtyShell>();

    private File ptyHelper() {
        return new File(getApplicationInfo().nativeLibraryDir, "libptyexec.so");
    }

    /** The process that runs a shell on a pty for {@code backend}: app (this app's sandbox), priv (the working mode: Shizuku, Root or ADB) or termux. */
    private Process ptyProcess(String backend, int rows, int cols) throws Exception {
        File helper = ptyHelper();
        if (!helper.isFile()) throw new IOException("this build of the app has no terminal helper for this phone's processor");
        String h = helper.getAbsolutePath();
        if ("termux".equals(backend)) {
            checkTermuxReady();
            return TermuxLink.openPtySession(TermuxBridge.launcher(this), h, rows, cols, TermuxBridge.BASH, "", 25000);
        }
        String kind = "app".equals(backend) ? "app" : termPrivKind();
        if (kind == null) throw new IOException("There is no working mode that can open a terminal: set up ADB, Shizuku or Root first");
        if ("app".equals(kind)) {
            File home = new File(getFilesDir(), "home");
            if (!home.isDirectory()) home.mkdirs();
            ProcessBuilder pb = new ProcessBuilder(PtyShell.command(h, rows, cols, java.util.Collections.singletonList("/system/bin/sh")));
            pb.directory(home);
            Map<String, String> env = pb.environment();
            env.put("HOME", home.getAbsolutePath());
            env.put("TMPDIR", getCacheDir().getAbsolutePath());
            env.put("TERM", "xterm-256color");
            env.put("COLORTERM", "truecolor");
            env.put("LANG", "en_US.UTF-8");
            pb.redirectErrorStream(true);
            return pb.start();
        }
        if ("adb".equals(kind)) {
            // adb's own client gets the terminal: it then asks the phone for a terminal of the same size and follows resizes
            boolean tcp = !"adb_wireless".equals(resolveExecMode());
            String target = tcp ? tcpTarget() : wirelessTarget();
            if (!isAdbTargetConnected(target)) performConnect(tcp ? adbTcpHost : adbWirelessHost, tcp ? adbTcpPort : adbWirelessPort, null);   // a link that dropped is connected again first
            ProcessBuilder adb = buildAdbProcess("-s", target, "shell");
            ProcessBuilder pb = new ProcessBuilder(PtyShell.command(h, rows, cols, adb.command()));
            pb.environment().putAll(adb.environment());
            pb.environment().put("TERM", "xterm-256color");
            pb.redirectErrorStream(true);
            return pb.start();
        }
        // Shizuku and Root run the helper as the phone's shell user / root: a shell on a pty there
        String script = "export TERM=xterm-256color COLORTERM=truecolor LANG=en_US.UTF-8 HOME=/data/local/tmp\ncd /data/local/tmp 2>/dev/null\n"
                + PtyShell.launchScript(h, "/data/local/tmp/.adbmgr-ptyexec", rows, cols, "/system/bin/sh");
        if ("root".equals(kind)) {
            ProcessBuilder pb = new ProcessBuilder("su", "-c", script);
            pb.redirectErrorStream(true);
            return pb.start();
        }
        return rishSpawn(new String[]{"sh", "-c", script});
    }

    /** A terminal session ended: drop it (unless the id already belongs to a newer one) and tell the page when it still waits for this end. */
    private void ptyEnded(final String key, PtyShell sh, int code, final long token) {
        final long gen = ptySessions.endedAt(key, sh);
        if (gen >= 0) {
            // told on the UI thread only while no newer session has been stored under the id since this decision
            notifyJsIf("window.onPtyExit&&window.onPtyExit(" + JSONObject.quote(key) + "," + code + "," + token + ")", new Live() { public boolean now() { return ptySessions.generation(key) == gen; } });
        }
    }

    private void closePtySessions() {
        for (PtyShell p : ptySessions.drain()) p.close();
    }

    private void closeTermSessions() {
        final List<RishShell> shells = new ArrayList<RishShell>();
        synchronized (termGate) {
            for (TermSlot s : termSlots.values()) {
                if (s.shell != null) shells.add(s.shell);
                s.shell = null;
            }
            termSlots.clear();
        }
        if (shells.isEmpty()) return;
        Thread closer = new Thread(new Runnable() {
            @Override
            public void run() {
                for (RishShell sh : shells) {
                    try {
                        sh.close();
                    } catch (Throwable ignored) {
                    }
                }
            }
        }, "term-close");
        closer.setDaemon(true);
        closer.start();
    }

    /** Termux is there and this app may run commands in it; otherwise an error whose prefix tells the page what to show. */
    private void checkTermuxReady() throws IOException {
        JSONObject st = TermuxBridge.status(this);
        if (!st.optBoolean("installed", false)) throw new IOException("termux_missing: Termux is not installed");
        if (!st.optBoolean("permission", false)) throw new IOException("termux_permission: this app may not run commands in Termux yet");
    }

    /** export lines for an official command-line tool: each provider's own variable only, filled from the vault. */
    private String termSecretEnv(String envJson) {
        if (envJson == null || envJson.trim().isEmpty()) return "";
        StringBuilder sb = new StringBuilder();
        try {
            JSONObject o = new JSONObject(envJson);
            java.util.Iterator<String> it = o.keys();
            while (it.hasNext()) {
                String name = it.next();
                AgentRules.Provider p = AgentRules.find(o.optString(name, ""));
                if (p == null || p.env == null || !p.env.equals(name)) continue;
                String key = vault().get(p.id);
                if (key == null || key.isEmpty()) continue;
                sb.append("export ").append(name).append('=').append(RishShell.quote(key)).append('\n');
            }
        } catch (Exception ignored) {
        }
        return sb.toString();
    }

    // ---- coding agents: keys and HTTPS ----

    private AgentVault agentVault;
    private final ExecutorService aiExecutor = Executors.newCachedThreadPool();
    private final Map<String, AiHttp> aiCalls = new java.util.concurrent.ConcurrentHashMap<String, AiHttp>();

    private SecretSettings secretSettings;

    /** The GitHub token and the VirusTotal key: sealed in the Keystore vault, old plain copies moved there on first read. */
    private synchronized SecretSettings secrets() {
        if (secretSettings == null) {
            final AgentVault v = vault();
            secretSettings = new SecretSettings(new SecretSettings.Vault() {
                public String get(String id) { return v.get(id); }
                public void put(String id, String secret) throws Exception { v.put(id, secret); }
                public void remove(String id) { v.remove(id); }
            }, new SecretSettings.Plain() {
                public String get(String name) { return prefs.getString(name, ""); }
                public void remove(String name) { if (prefs.contains(name)) prefs.edit().remove(name).apply(); }
            });
        }
        return secretSettings;
    }

    private synchronized AgentVault vault() {
        if (agentVault == null) agentVault = new AgentVault(this);
        return agentVault;
    }

    /** Adds provider {@code auth}'s key to a request, but only if the request goes to that provider's own address. */
    private String aiAuthorize(AiHttp.Request req, String auth) {
        if (auth == null || auth.isEmpty()) return null;
        AgentRules.Provider p = AgentRules.find(auth);
        if (p == null) return "unknown provider " + auth;
        String base = vault().base(auth);
        if (!AgentRules.allowed(p, base, req.url)) {
            return p.ownServer() ? "blocked: that address is not the " + auth + " server saved in Terminal settings"
                    : "blocked: " + auth + " keys are only sent to " + p.host;
        }
        for (String[] h : p.extra) if (!req.headers.containsKey(h[0])) req.headers.put(h[0], h[1]);
        String key = vault().get(auth);
        if (key != null && !key.isEmpty()) { req.headers.put(p.header, p.prefix + key); req.secret = key; }
        else if (!p.ownServer()) return "no " + auth + " key is saved: add it in Terminal settings";
        return null;
    }

    private void aiFinish(String reqId, AiHttp.Response r, String secret) {
        JSONObject o = new JSONObject();
        try {
            o.put("status", r.status);
            o.put("body", r.body == null ? "" : r.body);
            o.put("error", AgentRules.scrub(r.error, secret));          // an exception may quote a header: the key never goes back to the page
            o.put("cancelled", r.cancelled);
            JSONObject h = new JSONObject();
            for (Map.Entry<String, String> e : r.headers.entrySet()) h.put(e.getKey(), e.getValue());
            o.put("headers", h);
        } catch (Exception ignored) {
        }
        notifyJs("window.onAiDone && window.onAiDone(" + JSONObject.quote(reqId) + "," + o.toString() + ")");
    }

    // ---------------------------------------------------------------------------------------------
    // Root backend
    // ---------------------------------------------------------------------------------------------

    private static final String[] SU_PATHS = {
            "/system/bin/su", "/system/xbin/su", "/sbin/su", "/su/bin/su",
            "/debug_ramdisk/su", "/data/adb/ksu/bin/su", "/data/adb/ap/bin/su", "/vendor/bin/su"
    };

    /** Does su answer uid=0 for this app? Asked once (the root manager may show its prompt, so it waits a few seconds for an answer) and remembered. */
    private boolean isRootGranted() {
        synchronized (modeCacheLock) {
            if (rootGrant != null) return rootGrant;
        }
        boolean ok;
        try {
            ProcessBuilder pb = new ProcessBuilder("su", "-c", "id");
            pb.redirectErrorStream(true);
            String out = runProcessWithTimeout(pb, 8000);
            ok = out != null && out.contains("uid=0");
        } catch (Exception e) {
            ok = false;
        }
        synchronized (modeCacheLock) {
            rootGrant = ok;
        }
        return ok;
    }

    /** The su verdict as already known, without asking (no prompt): not asked yet counts as not granted. */
    private boolean rootGrantedKnown() {
        synchronized (modeCacheLock) {
            return Boolean.TRUE.equals(rootGrant);
        }
    }

    private boolean isRootAvailable() {
        for (String path : SU_PATHS) {
            if (new File(path).exists()) return true;
        }
        // "no su" rarely changes (Magisk can be installed while the app runs): ask the shell once a minute, not on every probe
        synchronized (modeCacheLock) {
            if (rootChecked && System.nanoTime() / 1000000L - rootCheckedAt < 60000) return rootCached;
        }
        boolean found;
        try {
            Process p = Runtime.getRuntime().exec(new String[]{"sh", "-c", "command -v su"});
            found = p.waitFor() == 0;
        } catch (Exception e) {
            found = false;
        }
        synchronized (modeCacheLock) {
            rootChecked = true;
            rootCached = found;
            rootCheckedAt = System.nanoTime() / 1000000L;
        }
        return found;
    }

    // ---------------------------------------------------------------------------------------------
    // Mode resolution
    // ---------------------------------------------------------------------------------------------

    /** Backend used to execute commands right now: adb_tcp, adb_wireless, shizuku, root or standard. */
    private String resolveExecMode() {
        String mode = activeWorkingMode;
        if (!"auto".equals(mode)) {
            return "unprivileged".equals(mode) ? "standard" : mode;
        }
        long now = System.currentTimeMillis();
        String cached = cachedAutoMode;
        if (cached != null && now - cachedAutoModeAt < 4000) {
            return cached;
        }
        String devices = adbDevicesOutput();
        String resolved;
        if (isTargetReady(devices, tcpTarget())) {
            resolved = "adb_tcp";
        } else if (adbWirelessPort > 0 && isTargetReady(devices, wirelessTarget())) {
            resolved = "adb_wireless";
        } else if (isShizukuAuthorized()) {
            resolved = "shizuku";
        } else if (isPortOpen(adbTcpHost, adbTcpPort, 200)) {
            // Port is open but not connected yet: connect quietly without changing the configured mode
            performConnect(adbTcpHost, adbTcpPort, null);
            resolved = isAdbTargetConnected(tcpTarget()) ? "adb_tcp" : "standard";
        } else {
            resolved = "standard";
        }
        cachedAutoMode = resolved;
        cachedAutoModeAt = now;
        return resolved;
    }

    private static String deviceWifiIp() {
        String fallback = "";
        try {
            for (NetworkInterface nif : Collections.list(NetworkInterface.getNetworkInterfaces())) {
                if (!nif.isUp() || nif.isLoopback()) continue;
                for (InetAddress addr : Collections.list(nif.getInetAddresses())) {
                    if (!(addr instanceof Inet4Address) || addr.isLoopbackAddress()) continue;
                    String ip = addr.getHostAddress();
                    String name = nif.getName() != null ? nif.getName() : "";
                    if (name.startsWith("wlan") || name.startsWith("swlan") || name.startsWith("ap")) {
                        return ip;
                    }
                    if (fallback.isEmpty() && addr.isSiteLocalAddress()) {
                        fallback = ip;
                    }
                }
            }
        } catch (Exception ignored) {}
        return fallback;
    }

    private static String colorHex(int color) {
        return String.format("#%06X", 0xFFFFFF & color);
    }

    private static int mixColor(int a, int b, float ratio) {
        float inv = 1f - ratio;
        int r = (int) (Color.red(a) * inv + Color.red(b) * ratio);
        int g = (int) (Color.green(a) * inv + Color.green(b) * ratio);
        int bl = (int) (Color.blue(a) * inv + Color.blue(b) * ratio);
        return Color.rgb(r, g, bl);
    }

    /**
     * Adds protection details so the UI knows which permissions `pm grant/revoke` can change:
     * runtime (dangerous) and development permissions are changeable, the rest are install-time.
     */
    private static void describePermission(PackageManager pm, String permName, JSONObject out) throws Exception {
        String protection = "unknown";
        boolean changeable = false;
        boolean appOp = false;
        String label = "";
        String description = "";
        String group = "";
        try {
            android.content.pm.PermissionInfo pi = pm.getPermissionInfo(permName, 0);
            try {
                CharSequence ds = pi.loadDescription(pm);
                if (ds != null) description = ds.toString();
            } catch (Throwable ignored) {}
            if (pi.group != null) group = pi.group;
            int level = pi.protectionLevel;
            int base = level & android.content.pm.PermissionInfo.PROTECTION_MASK_BASE;
            boolean development = (level & android.content.pm.PermissionInfo.PROTECTION_FLAG_DEVELOPMENT) != 0;
            appOp = (level & android.content.pm.PermissionInfo.PROTECTION_FLAG_APPOP) != 0;
            switch (base) {
                case android.content.pm.PermissionInfo.PROTECTION_NORMAL: protection = "normal"; break;
                case android.content.pm.PermissionInfo.PROTECTION_DANGEROUS: protection = "runtime"; break;
                case android.content.pm.PermissionInfo.PROTECTION_SIGNATURE: protection = "signature"; break;
                default: protection = "privileged"; break;
            }
            changeable = base == android.content.pm.PermissionInfo.PROTECTION_DANGEROUS || development;
            if (development && !"runtime".equals(protection)) protection = "development";
            CharSequence l = pi.loadLabel(pm);
            if (l != null && !permName.equals(l.toString())) label = l.toString();
        } catch (PackageManager.NameNotFoundException e) {
            protection = "undefined";
        }
        out.put("protection", protection);
        out.put("changeable", changeable);
        out.put("appOp", appOp);
        out.put("label", label);
        out.put("description", description);
        out.put("group", group);
    }

    /** Maps Android 12+ system tonal palettes to the app's color roles (Material 3 dark / light). */
    private JSONObject materialYouScheme(boolean dark) throws Exception {
        JSONObject o = new JSONObject();
        if (dark) {
            int n900 = systemColor("system_neutral1_900");
            int n800 = systemColor("system_neutral1_800");
            o.put("accent", colorHex(systemColor("system_accent1_200")));
            o.put("bg", colorHex(mixColor(n900, 0xFF000000, 0.35f)));
            o.put("surface", colorHex(n800));
            o.put("card", colorHex(mixColor(n900, n800, 0.45f)));
            o.put("sheet", colorHex(n900));
            o.put("running", colorHex(systemColor("system_accent3_200")));
            o.put("frozen", colorHex(systemColor("system_accent1_200")));
            o.put("system", colorHex(systemColor("system_accent2_200")));
            o.put("secondary", colorHex(systemColor("system_accent2_200")));
            o.put("bloat", "#F2B8B5");
            o.put("text", colorHex(systemColor("system_neutral1_100")));
            o.put("muted", colorHex(systemColor("system_neutral2_200")));
        } else {
            int n10 = systemColor("system_neutral1_10");
            int n50 = systemColor("system_neutral1_50");
            int n100 = systemColor("system_neutral1_100");
            o.put("accent", colorHex(systemColor("system_accent1_600")));
            o.put("bg", colorHex(n10));
            o.put("surface", colorHex(n100));
            o.put("card", colorHex(n50));
            o.put("sheet", colorHex(mixColor(n10, n50, 0.5f)));
            o.put("running", colorHex(systemColor("system_accent3_600")));
            o.put("frozen", colorHex(systemColor("system_accent1_600")));
            o.put("system", colorHex(systemColor("system_accent2_600")));
            o.put("secondary", colorHex(systemColor("system_accent2_600")));
            o.put("bloat", "#B3261E");
            o.put("text", colorHex(systemColor("system_neutral1_900")));
            o.put("muted", colorHex(systemColor("system_neutral2_700")));
        }
        return o;
    }

    // ---------------------------------------------------------------------------------------------
    // Debloater: Universal Android Debloater Next Generation (UAD-NG) community package list.
    // Downloaded at runtime (GPL-3.0 data, not bundled) and cached in app storage.
    // ---------------------------------------------------------------------------------------------

    private static final String UAD_LIST_URL =
            "https://raw.githubusercontent.com/Universal-Debloater-Alliance/universal-android-debloater-next-generation/main/resources/assets/uad_lists.json";
    private static final long UAD_MAX_AGE_MS = 7L * 24 * 60 * 60 * 1000;
    private volatile boolean uadDownloading = false;

    private File uadCacheFile() {
        return new File(getFilesDir(), "uad_lists.json");
    }

    private JSONObject uadStatus() {
        JSONObject o = new JSONObject();
        try {
            File f = uadCacheFile();
            long updatedAt = prefs.getLong("uad_updated_at", 0);
            o.put("cached", f.exists() && f.length() > 0);
            o.put("updatedAt", updatedAt);
            o.put("count", prefs.getInt("uad_count", 0));
            o.put("stale", updatedAt == 0 || System.currentTimeMillis() - updatedAt > UAD_MAX_AGE_MS);
            o.put("downloading", uadDownloading);
            o.put("source", UAD_LIST_URL);
        } catch (Exception ignored) {}
        return o;
    }

    private void downloadUadList() {
        if (uadDownloading) return;
        uadDownloading = true;
        executor.submit(new Runnable() {
            @Override
            public void run() {
                String error = null;
                java.net.HttpURLConnection conn = null;
                try {
                    java.util.Map<String, String> uadHdr = new java.util.LinkedHashMap<String, String>();
                    uadHdr.put("User-Agent", "ADB-Application-Manager");
                    conn = HttpSafe.open(UAD_LIST_URL, 15000, 30000, uadHdr);
                    int code = conn.getResponseCode();
                    if (code != 200) throw new IllegalStateException("HTTP " + code);
                    InputStream in = conn.getInputStream();
                    java.io.ByteArrayOutputStream buf = new java.io.ByteArrayOutputStream();
                    byte[] chunk = new byte[16384];
                    int n;
                    while ((n = in.read(chunk)) > 0) {
                        buf.write(chunk, 0, n);
                        if (buf.size() > 32 * 1024 * 1024) throw new IllegalStateException("List too large");
                    }
                    in.close();
                    String text = buf.toString("UTF-8");
                    JSONObject parsed = new JSONObject(text); // validate before replacing the cache
                    if (parsed.length() < 100) throw new IllegalStateException("List looks incomplete");

                    File tmp = new File(getFilesDir(), "uad_lists.json.tmp");
                    OutputStream out = new FileOutputStream(tmp);
                    out.write(buf.toByteArray());
                    out.close();
                    if (!tmp.renameTo(uadCacheFile())) {
                        uadCacheFile().delete();
                        if (!tmp.renameTo(uadCacheFile())) throw new IllegalStateException("Could not save list");
                    }
                    prefs.edit().putLong("uad_updated_at", System.currentTimeMillis()).putInt("uad_count", parsed.length()).apply();
                } catch (Exception e) {
                    error = e.getMessage() != null ? e.getMessage() : e.getClass().getSimpleName();
                    Log.w(TAG, "UAD list download failed: " + error);
                } finally {
                    if (conn != null) conn.disconnect();
                    uadDownloading = false;
                }
                try {
                    JSONObject status = uadStatus();
                    status.put("error", error == null ? "" : error);
                    notifyJs("window.onUadListUpdated && window.onUadListUpdated(" + JSONObject.quote(status.toString()) + ")");
                } catch (Exception ignored) {}
            }
        });
    }

    /** UAD-NG entries for packages on this device, including ones uninstalled for the current user. */
    private String uadMatches() {
        JSONObject res = new JSONObject();
        try {
            File f = uadCacheFile();
            if (!f.exists()) {
                res.put("packages", new JSONArray());
                return res.toString();
            }
            JSONObject list = new JSONObject(new String(AdbKeyManager.readFile(f), "UTF-8"));
            PackageManager pm = getPackageManager();
            List<ApplicationInfo> apps = pm.getInstalledApplications(PackageManager.MATCH_UNINSTALLED_PACKAGES);
            JSONArray out = new JSONArray();
            for (ApplicationInfo ai : apps) {
                JSONObject e = list.optJSONObject(ai.packageName);
                if (e == null) continue;
                JSONObject o = new JSONObject();
                o.put("pkg", ai.packageName);
                String label = ai.packageName;
                try {
                    CharSequence l = pm.getApplicationLabel(ai);
                    if (l != null && l.length() > 0) label = l.toString();
                } catch (Exception ignored) {}
                o.put("name", label);
                boolean installed = (ai.flags & ApplicationInfo.FLAG_INSTALLED) != 0;
                String state = !installed ? "uninstalled" : (!ai.enabled ? "disabled" : "enabled");
                o.put("state", state);
                o.put("isSystem", (ai.flags & ApplicationInfo.FLAG_SYSTEM) != 0);
                o.put("isSuspended", installed && (ai.flags & ApplicationInfo.FLAG_SUSPENDED) != 0);
                o.put("list", e.optString("list", "Misc"));
                o.put("removal", e.optString("removal", "Expert"));
                o.put("description", e.optString("description", ""));
                o.put("dependencies", e.optJSONArray("dependencies") != null ? e.optJSONArray("dependencies") : new JSONArray());
                o.put("neededBy", e.optJSONArray("neededBy") != null ? e.optJSONArray("neededBy") : new JSONArray());
                out.put(o);
            }
            res.put("packages", out);
        } catch (Exception e) {
            try {
                res.put("packages", new JSONArray());
                res.put("error", e.getMessage());
            } catch (Exception ignored) {}
        }
        return res.toString();
    }

    private volatile JSONObject uadListCache;
    private volatile long uadListCacheStamp;

    /** The cached UAD-NG list, read again only when its file changed (the single-app menu asks for one package at a time). */
    private JSONObject uadListCached() {
        try {
            File f = uadCacheFile();
            if (!f.exists()) return null;
            long stamp = f.lastModified() * 31 + f.length();
            JSONObject c = uadListCache;
            if (c != null && stamp == uadListCacheStamp) return c;
            c = new JSONObject(new String(AdbKeyManager.readFile(f), "UTF-8"));
            uadListCache = c;
            uadListCacheStamp = stamp;
            return c;
        } catch (Exception e) {
            return null;
        }
    }

    /** What the UAD-NG list says about one package: {found, pkg, list, removal, description, dependencies, neededBy}; {found:false} when it is not in the list or the list is not downloaded. */
    private String uadInfo(String pkg) {
        JSONObject res = new JSONObject();
        try {
            JSONObject list = uadListCached();
            JSONObject e = (list == null || pkg == null) ? null : list.optJSONObject(pkg);
            if (e == null) { res.put("found", false); res.put("downloaded", list != null); return res.toString(); }
            res.put("found", true);
            res.put("pkg", pkg);
            res.put("list", e.optString("list", "Misc"));
            res.put("removal", e.optString("removal", "Expert"));
            res.put("description", e.optString("description", ""));
            res.put("dependencies", e.optJSONArray("dependencies") != null ? e.optJSONArray("dependencies") : new JSONArray());
            res.put("neededBy", e.optJSONArray("neededBy") != null ? e.optJSONArray("neededBy") : new JSONArray());
        } catch (Exception ex) {
            try { res = new JSONObject().put("found", false); } catch (Exception ignored) {}
        }
        return res.toString();
    }

    // ---------------------------------------------------------------------------------------------
    // Updates tab: Galaxy Store (Samsung system / store apps) and this app's GitHub releases
    // ---------------------------------------------------------------------------------------------

    private final java.util.concurrent.ConcurrentHashMap<String, JSONObject> updateResults = new java.util.concurrent.ConcurrentHashMap<String, JSONObject>();
    private volatile boolean updateCheckRunning = false;
    private volatile long updateCheckedAt = 0;
    private final java.util.Set<String> installingUpdates = java.util.Collections.synchronizedSet(new HashSet<String>());

    private String currentVersionName() {
        try {
            return getPackageManager().getPackageInfo(getPackageName(), 0).versionName;
        } catch (Exception e) {
            return "0";
        }
    }

    private static long versionCodeOf(PackageInfo info) {
        return Build.VERSION.SDK_INT >= 28 ? info.getLongVersionCode() : info.versionCode;
    }

    private UpdateManager.Device updateDevice() {
        String mcc = "", mnc = "";
        try {
            android.telephony.TelephonyManager tm = (android.telephony.TelephonyManager) getSystemService(Context.TELEPHONY_SERVICE);
            String op = tm != null ? tm.getSimOperator() : "";
            if (op != null && op.length() >= 5) {
                mcc = op.substring(0, 3);
                mnc = op.substring(3);
            }
        } catch (Exception ignored) {}
        String csc = runProcessWithTimeout(new ProcessBuilder("getprop", "ro.csc.sales_code"), 2000).trim();
        if (csc.isEmpty() || csc.contains(" ")) csc = runProcessWithTimeout(new ProcessBuilder("getprop", "persist.omc.sales_code"), 2000).trim();
        if (csc.contains(" ")) csc = "";
        return new UpdateManager.Device(Build.MODEL, mcc, mnc, csc, Build.VERSION.SDK_INT);
    }

    /** Samsung system apps and apps installed from the Galaxy Store are checked against the Galaxy Store. */
    private boolean isGalaxyStoreCandidate(ApplicationInfo ai, String installer) {
        if (UpdateManager.GALAXY_STORE_PKG.equals(installer)) return true;
        boolean system = (ai.flags & ApplicationInfo.FLAG_SYSTEM) != 0;
        String p = ai.packageName;
        return system && (p.startsWith("com.samsung.") || p.startsWith("com.sec.") || p.startsWith("com.osp."));
    }

    private String installerOf(String pkg) {
        try {
            if (Build.VERSION.SDK_INT >= 30) {
                android.content.pm.InstallSourceInfo src = getPackageManager().getInstallSourceInfo(pkg);
                return src.getInstallingPackageName();
            }
            return getPackageManager().getInstallerPackageName(pkg);
        } catch (Exception e) {
            return null;
        }
    }

    private void notifyUpdates(String fn, JSONObject payload) {
        notifyJs("window." + fn + " && window." + fn + "(" + JSONObject.quote(payload.toString()) + ")");
    }

    /** The check that is running now (Cancel and onDestroy reach it here); null when none is. */
    private volatile UpdateChecker updateCheckRun;
    /** Cancel was pressed (or the window closed) while the run was still listing the apps, before its checker existed. */
    private volatile boolean updateCancelRequested;
    private final UpdateChecker.Generation updateRunGeneration = new UpdateChecker.Generation();   // a callback of an older check is dropped once a newer one has started
    /** The last full result (everything the page lists under the updates: not tracked, Obtainium-only, could not be checked ...); kept on disk for the next start. */
    private volatile JSONObject updateLastSummary;
    private volatile JSONObject updateProgressLast;
    private volatile String updateLastError = "";      // why the last check broke; empty after a check that gave a result
    private final Object updateStateLock = new Object();
    private boolean updateStateLoaded;
    private UpdateCache updateCacheInstance;

    private synchronized UpdateCache updateCache() {
        if (updateCacheInstance == null) updateCacheInstance = new UpdateCache(getFilesDir(), UpdateChecker.SYSTEM_CLOCK);
        return updateCacheInstance;
    }

    /** Whether a kept update row is still true: the app has the version code it had when the row was made, and the update is newer than what is installed now. */
    private boolean updateRowStillValid(JSONObject r) {
        try {
            PackageInfo info = getPackageManager().getPackageInfo(r.optString("pkg"), 0);
            long vc = versionCodeOf(info);
            if (vc != r.optLong("installedCode", -1)) return false;
            return UpdateChecker.stillNewer(r, vc, info.versionName != null ? info.versionName : String.valueOf(vc));
        } catch (Exception e) {
            return false;
        }
    }

    /**
     * Reads the last result from disk once (after a restart), keeping only what is still true: an update whose app has the same version code as when it was found,
     * and a list entry whose app is still installed. The updates go back into {@link #updateResults}, so the Update buttons work on them.
     */
    private void loadUpdateState() {
        synchronized (updateStateLock) {
            if (updateStateLoaded) return;
            updateStateLoaded = true;
            try {
                JSONObject last = updateCache().loadLast();
                if (last == null) return;
                JSONArray ups = new JSONArray();
                JSONArray old = last.optJSONArray("updates");
                for (int i = 0; old != null && i < old.length(); i++) {
                    JSONObject r = old.optJSONObject(i);
                    if (r == null || "self".equals(r.optString("source")) || !updateRowStillValid(r)) continue;
                    ups.put(r);
                    updateResults.put(r.optString("pkg"), r);
                }
                last.put("updates", ups);
                for (String key : new String[]{"untracked", "external", "failed"}) {
                    JSONArray in = last.optJSONArray(key), out = new JSONArray();
                    for (int i = 0; in != null && i < in.length(); i++) {
                        JSONObject r = in.optJSONObject(i);
                        try {
                            if (r != null) {
                                getPackageManager().getPackageInfo(r.optString("pkg"), 0);
                                out.put(r);
                            }
                        } catch (Exception gone) {}
                    }
                    last.put(key, out);
                }
                updateLastSummary = last;
                updateCheckedAt = last.optLong("checkedAt", 0);
            } catch (Throwable ignored) {}
        }
    }

    /** Puts back the update rows of an earlier result that are still true (the phone may have changed since) and returns them. */
    private JSONArray restoreUpdateRows(Map<String, JSONObject> rows) {
        updateResults.clear();
        JSONArray still = new JSONArray();
        for (JSONObject r : rows.values()) {
            if (!updateRowStillValid(r)) continue;
            updateResults.put(r.optString("pkg"), r);
            still.put(r);
        }
        return still;
    }

    /** Stops the check that is running, if any: what it found stays, the rest is reported as not checked. */
    private void cancelUpdateCheckRun() {
        updateCancelRequested = true;              // read by a run that has not made its checker yet
        UpdateChecker c = updateCheckRun;
        if (c != null) c.cancel();
    }

    private static Set<String> pkgsOfArray(JSONArray a) {
        Set<String> out = new HashSet<String>();
        for (int i = 0; a != null && i < a.length(); i++) {
            JSONObject o = a.optJSONObject(i);
            if (o != null) out.add(o.optString("pkg"));
        }
        return out;
    }

    /**
     * The check of the Updates tab. The work is {@link UpdateChecker}'s (every source at once, short waits, a deadline, a breaker per host, saved
     * answers); this method lists the installed apps, passes updates on to the page as they are found, and sends the summary at the end on every way out.
     * {@code force}: ignore the saved answers. {@code retryFailed}: check only the apps the last check could not.
     */
    // ---------------------------------------------------------------------------------------------
    // DNS speed test: DnsProbe (pure Java) does the work; this is the bridge. Needs no working mode: it only opens TCP/TLS connections of its own to
    // port 853 of the hosts the page names (checked again in Java), and sends one DNS query on each. A pool of its own, stopped in onDestroy.
    // ---------------------------------------------------------------------------------------------
    private final ExecutorService dnsProbeExec = Executors.newFixedThreadPool(DnsProbe.MAX_PARALLEL);
    private final DnsProbe.Runner dnsProbe = new DnsProbe.Runner(new DnsProbe.Env());

    private final DnsProbe.Sink dnsProbeSink = new DnsProbe.Sink() {
        @Override
        public void emit(String json) {
            notifyJs("window.onDnsProbe && window.onDnsProbe(" + JSONObject.quote(json) + ")");
        }
    };

    // ---------------------------------------------------------------------------------------------
    // Internet speed test (Task Manager > Network > Speed test): SpeedTest (pure Java) does the work; this is the bridge. Needs no working mode: it only
    // opens HTTPS connections of its own to speed.cloudflare.com through HttpSafe. Runs only while its screen is open (the page stops it on Close, Back
    // and when the app is hidden); a pool of its own whose idle threads end, stopped in onDestroy.
    // ---------------------------------------------------------------------------------------------
    private final ExecutorService speedTestExec = SpeedTest.newPool();
    private final SpeedTest.Runner speedTest = new SpeedTest.Runner(new SpeedTest.Config());

    private final SpeedTest.Sink speedTestSink = new SpeedTest.Sink() {
        @Override
        public void emit(String json) {
            notifyJs("window.onSpeedTest && window.onSpeedTest(" + JSONObject.quote(json) + ")");
        }
    };


    private void runUpdateCheck(final boolean force, final boolean retryFailed) {
        if (updateCheckRunning) return;
        updateCheckRunning = true;
        updateCancelRequested = false;
        try {
            executor.submit(new Runnable() {
                @Override
                public void run() {
                    JSONObject summary = null;
                    JSONObject before = null;
                    Map<String, JSONObject> rowsBefore = new java.util.HashMap<String, JSONObject>();
                    Set<String> retried = null;
                    try {
                        loadUpdateState();
                        before = updateLastSummary;
                        rowsBefore.putAll(updateResults);
                        approvedUpdates.clear();            // a yes holds for the update it was given for, not for what a new check finds
                        retried = retryFailed && before != null ? pkgsOfArray(before.optJSONArray("failed")) : null;
                        if (retried != null) {
                            for (String p : retried) updateResults.remove(p);
                        } else {
                            updateResults.clear();
                        }
                        if (retried != null && retried.isEmpty()) {
                            summary = before;               // nothing failed: nothing to do
                        } else {
                            PackageManager pm = getPackageManager();
                            JSONObject sources = updateSources();
                            List<UpdateChecker.App> apps = new ArrayList<UpdateChecker.App>();
                            Set<String> ownFonts = fmkMadeHere();          // font packages made in Custom Fonts: no store has them
                            for (ApplicationInfo ai : pm.getInstalledApplications(0)) {
                                if (ownFonts.contains(ai.packageName)) continue;
                                String inst = installerOf(ai.packageName);
                                boolean os = isOpenSourceCandidate(ai, inst, sources);
                                boolean gx = isGalaxyStoreCandidate(ai, inst);
                                if (!os && !gx) continue;
                                try {
                                    PackageInfo info = pm.getPackageInfo(ai.packageName, 0);
                                    apps.add(new UpdateChecker.App(ai.packageName, pm.getApplicationLabel(ai).toString(), info.versionName, versionCodeOf(info), inst,
                                            (ai.flags & ApplicationInfo.FLAG_SYSTEM) != 0, os, gx));
                                } catch (PackageManager.NameNotFoundException gone) {}
                            }
                            UpdateChecker.Options o = new UpdateChecker.Options();
                            o.generation = updateRunGeneration;
                            o.force = force;
                            o.refreshCatalog = force && !retryFailed;
                            o.only = retried;
                            o.sources = sources;
                            String token = secrets().get(SecretSettings.GITHUB_TOKEN);
                            o.githubToken = token == null ? "" : token;
                            o.abis = Build.SUPPORTED_ABIS;
                            o.galaxyTag = Build.MODEL == null ? "" : Build.MODEL;
                            o.device = new UpdateChecker.DeviceProvider() {
                                @Override
                                public UpdateManager.Device get() {
                                    return updateDevice();
                                }
                            };
                            if (retried == null) {
                                PackageInfo me = pm.getPackageInfo(getPackageName(), 0);
                                o.self = new UpdateChecker.App(getPackageName(), "ADB/Root Full System Toolbox", currentVersionName(), versionCodeOf(me), null, false, false, false);
                            }
                            UpdateChecker checker = new UpdateChecker(UpdateManager.netHttp(5000, 8000), UpdateChecker.SYSTEM_CLOCK, updateCache());
                            updateCheckRun = checker;
                            if (updateCancelRequested) checker.cancel();   // Cancel pressed while the apps were being listed
                            summary = checker.check(apps, o, new UpdateChecker.Listener() {
                                @Override
                                public void onUpdate(JSONObject row) {
                                    updateResults.put(row.optString("pkg"), row);
                                    notifyUpdates("onUpdateFound", row);
                                }

                                @Override
                                public void onProgress(JSONObject p) {
                                    updateProgressLast = p;
                                    notifyUpdates("onUpdateCheckProgress", p);
                                }
                            }).summary;
                            if (retried != null) summary = UpdateChecker.merge(before, summary, retried);
                            if (summary.optBoolean("offline") && before != null) {
                                // no internet: the answer from the last time that worked is still the best there is, and says so
                                summary = new JSONObject(before.toString()).put("offline", true).put("updates", restoreUpdateRows(rowsBefore));
                            }
                        }
                    } catch (Throwable e) {
                        try {
                            // a check that broke is a failure, not a result: what was known before stays (with its own time), and the failure is said next to it
                            String msg = e.getMessage() != null ? e.getMessage() : e.getClass().getSimpleName();
                            summary = before != null ? new JSONObject(before.toString()) : new JSONObject().put("failed", new JSONArray()).put("hostsDown", new JSONArray());
                            summary.put("updates", restoreUpdateRows(rowsBefore));
                            summary.put("error", msg);
                            updateLastError = msg;
                        } catch (Exception ignored) {}
                    } finally {
                        updateCheckRun = null;
                        updateProgressLast = null;
                        updateCheckRunning = false;
                        // the time of the last good check moves only when this one gave a result (not an error, not "no internet" with an older result to show)
                        if (summary != null && !summary.has("error") && !(summary.optBoolean("offline") && before != null)) {
                            updateCheckedAt = System.currentTimeMillis();
                            updateLastError = "";
                        }
                    }
                    try {
                        if (summary == null) summary = new JSONObject();
                        for (JSONObject r : updateResults.values()) {          // the rows the page acts on are exactly the ones the app holds
                            boolean have = false;
                            JSONArray ups = summary.optJSONArray("updates");
                            for (int i = 0; ups != null && i < ups.length() && !have; i++) have = r.optString("pkg").equals(ups.optJSONObject(i).optString("pkg"));
                            if (!have) {
                                if (ups == null) summary.put("updates", ups = new JSONArray());
                                ups.put(r);
                            }
                        }
                        if (!summary.has("updates")) summary.put("updates", new JSONArray());
                        if (!(summary.optBoolean("offline") && before != null)) summary.put("checkedAt", updateCheckedAt);
                        if (!summary.has("error")) {
                            if (!(summary.optBoolean("offline") && before != null)) updateLastSummary = summary;        // offline: what was known before stays the last result
                            JSONObject keep = new JSONObject(summary.toString());
                            JSONArray all = keep.optJSONArray("updates"), noSelf = new JSONArray();
                            for (int i = 0; all != null && i < all.length(); i++) if (!"self".equals(all.optJSONObject(i).optString("source"))) noSelf.put(all.optJSONObject(i));
                            keep.put("updates", noSelf);
                            if (!summary.optBoolean("offline")) updateCache().saveLast(keep);       // "no internet" is not a result worth keeping for the next start
                        }
                    } catch (Throwable ignored) {}
                    try {
                        notifyUpdates("onUpdatesChecked", summary == null ? new JSONObject() : summary);
                    } catch (Throwable ignored) {}
                }
            });
        } catch (RuntimeException e) {          // the executor is already shut down (the window is going away)
            updateCheckRunning = false;
        }
    }

    private JSONArray updatesArray() {
        JSONArray arr = new JSONArray();
        for (JSONObject o : updateResults.values()) arr.put(o);
        return arr;
    }

    private void progress(String pkg, String stage, int percent, String message) {
        try {
            JSONObject o = new JSONObject();
            o.put("pkg", pkg);
            o.put("stage", stage);
            o.put("percent", percent);
            o.put("message", message == null ? "" : message);
            notifyUpdates("onUpdateProgress", o);
        } catch (Exception ignored) {}
    }

    /** The yes to one "Update all" question, per app, bound to the update the check found (version, source); see {@link UpdateApprovals}. */
    private final UpdateApprovals approvedUpdates = new UpdateApprovals();
    private final java.util.concurrent.atomic.AtomicBoolean updateAllAsking = new java.util.concurrent.atomic.AtomicBoolean();

    /**
     * True once for an app the person approved in the "Update all" question, for the very update the check holds now (same version, same source), while
     * the working mode is privileged; the yes is spent by this call.
     */
    private boolean takeUpdateApproval(String pkg) {
        JSONObject cur = updateResults.get(pkg);
        boolean ok = approvedUpdates.take(pkg, cur == null ? null : cur.optString("availableVersion"), cur == null ? null : cur.optString("source"),
                resolveExecMode(), System.currentTimeMillis());
        return ok && cur != null;
    }

    /**
     * The one question for "Update all": the page names the packages it wants updated, the app keeps those it found an update for itself (not this app,
     * not one that opens elsewhere, not one already running), lists them in a native dialog and asks once, before anything is downloaded. A yes is
     * remembered per package, so the single installs that follow do not ask again. The answer goes to window.onUpdateAllAnswer(json): ok, pkgs.
     */
    private void runApproveUpdateAll(final String pkgsJson) {
        if (!updateAllAsking.compareAndSet(false, true)) return;     // a question is already on screen: its answer is coming
        // A new question replaces every earlier yes, whatever the answer turns out to be (No, a failed mode check, a lost answer): clear before the dialog opens
        approvedUpdates.clear();
        executor.submit(new Runnable() {
            @Override
            public void run() {
                JSONObject answer = new JSONObject();
                JSONArray ok = new JSONArray();
                try {
                    final String mode = resolveExecMode();
                    if (isPrivilegedMode(mode)) {
                        JSONArray asked = new JSONArray(pkgsJson);
                        java.util.LinkedHashSet<String> seen = new java.util.LinkedHashSet<String>();
                        List<String[]> rows = new ArrayList<String[]>();
                        java.util.Map<String, String[]> versions = new java.util.LinkedHashMap<String, String[]>();
                        for (int i = 0; i < asked.length(); i++) {
                            String p = asked.optString(i, "");
                            JSONObject u = p.isEmpty() ? null : updateResults.get(p);
                            if (u == null || "self".equals(u.optString("source")) || "external".equals(u.optString("source")) || installingUpdates.contains(p) || !seen.add(p)) continue;
                            rows.add(new String[]{u.optString("name"), p, u.optString("installedVersion"), u.optString("availableVersion")});
                            ok.put(p);
                            versions.put(p, new String[]{u.optString("availableVersion"), u.optString("source")});
                        }
                        if (rows.isEmpty()) {
                            answer.put("error", "There is nothing to update.");
                        } else if (confirmNative(InstallConfirm.titleUpdates(rows.size()), InstallConfirm.messageUpdateAll(rows, mode), "Update", "Cancel") == BundleApprovals.Answer.ALLOW) {
                            if (InstallGuards.sameMode(mode, resolveExecMode())) {
                                approvedUpdates.replace(versions, mode, System.currentTimeMillis());
                            } else {
                                ok = new JSONArray();
                                answer.put("error", InstallConfirm.MODE_CHANGED);
                            }
                        } else {
                            ok = new JSONArray();
                        }
                    } else {
                        answer.put("error", "installing updates needs ADB, Shizuku or Root. Set up a working mode first.");
                    }
                } catch (Exception e) {
                    ok = new JSONArray();
                    try { answer.put("error", errMsg(e)); } catch (Exception ignored) {}
                } finally {
                    updateAllAsking.set(false);
                }
                try {
                    answer.put("ok", ok.length() > 0);
                    answer.put("pkgs", ok);
                    notifyUpdates("onUpdateAllAnswer", answer);
                } catch (Exception ignored) {}
            }
        });
    }

    /** Downloads the official APK, verifies it, and installs it through the active privileged mode. */
    private void runInstallUpdate(final String pkg) {
        final JSONObject u = updateResults.get(pkg);
        if (u == null) {                    // a new check replaced the list meanwhile: the page is told, or its row would wait forever
            progress(pkg, "cancelled", 0, "Update cancelled: this update is no longer in the list. Check for updates again.");
            return;
        }
        if (!installingUpdates.add(pkg)) return;    // already running: that run reports
        executor.submit(new Runnable() {
            @Override
            public void run() {
                File apk = new File(new File(getCacheDir(), "updates"), pkg + ".apk");
                try {
                    String source = u.optString("source");
                    if ("self".equals(source) || "external".equals(source)) throw new IllegalStateException("this update opens in the browser or Obtainium");
                    if ("standard".equals(resolveExecMode())) {
                        throw new InstallCancelled("installing updates needs ADB, Shizuku or Root. Set up a working mode first.");
                    }
                    apk.getParentFile().mkdirs();
                    progress(pkg, "downloading", 0, "Getting download link...");
                    String url = "galaxy".equals(source) ? UpdateManager.galaxyDownloadUrl(pkg, updateDevice()) : u.optString("downloadUrl");
                    if (url.isEmpty()) throw new IllegalStateException("no APK for this phone in the latest release");
                    final String finalUrl = UpdateManager.download(url, apk, new UpdateManager.Progress() {
                        @Override
                        public void onProgress(long done, long total) {
                            progress(pkg, "downloading", total > 0 ? (int) (done * 100 / total) : -1, (done / (1024 * 1024)) + " MB");
                        }
                    });

                    // Only install what we asked for: same package, newer version
                    PackageInfo archive = getPackageManager().getPackageArchiveInfo(apk.getAbsolutePath(), 0);
                    if (archive == null || !pkg.equals(archive.packageName)) {
                        throw new IllegalStateException("downloaded file is not " + pkg);
                    }
                    long installedVc = versionCodeOf(getPackageManager().getPackageInfo(pkg, 0));
                    if (versionCodeOf(archive) <= installedVc) {
                        throw new IllegalStateException("downloaded version (" + archive.versionName + ") is not newer than the installed one");
                    }
                    // Android only accepts an update signed by the same key. Catch a mismatch (e.g. an F-Droid
                    // build over a developer build) before trying, and say why.
                    int sigFlags = Build.VERSION.SDK_INT >= 28 ? PackageManager.GET_SIGNING_CERTIFICATES : PackageManager.GET_SIGNATURES;
                    java.util.Set<String> installedSigners = signerDigests(getPackageManager().getPackageInfo(pkg, sigFlags), true);
                    PackageInfo archiveSigned = getPackageManager().getPackageArchiveInfo(apk.getAbsolutePath(), sigFlags);
                    java.util.Set<String> newSigners = archiveSigned != null ? signerDigests(archiveSigned, true) : new HashSet<String>();
                    String signerWhy = InstallGuards.checkSigners(installedSigners, newSigners);
                    if ("installed-unreadable".equals(signerWhy)) {
                        throw new IllegalStateException("couldn't read the signing certificate of the installed app, so the download can't be checked against it - not installed");
                    } else if ("unreadable".equals(signerWhy)) {
                        throw new IllegalStateException("couldn't read the signing certificate of the downloaded file, so it can't be checked against the installed app - not installed");
                    } else if (signerWhy != null) {
                        throw new IllegalStateException("signed with a different key than the installed app, so Android won't accept it as an update. "
                                + "Update from the source you originally installed from" + ("fdroid".equals(source) ? " (F-Droid signs its own builds)." : "."));
                    }

                    // A privileged install has no system installer in front of it: the person is asked here, in a dialog the page cannot press, with
                    // what was read from the downloaded file itself. A yes given for the whole "Update all" list already covers this app.
                    if (!takeUpdateApproval(pkg)) {
                        String mode = resolveExecMode();
                        if (!isPrivilegedMode(mode)) throw new InstallCancelled("installing updates needs ADB, Shizuku or Root. Set up a working mode first.");
                        String label = u.optString("name");
                        progress(pkg, "confirming", 100, "Waiting for your OK to update " + (label.isEmpty() ? pkg : label) + "...");
                        if (!confirmInMode(mode, null, InstallConfirm.messageUpdate(label, archive.packageName, archive.versionName, InstallConfirm.hostOf(finalUrl),
                                InstallConfirm.hostOf(url), installedVersionOrNull(pkg), mode))) {
                            throw new InstallCancelled("Update cancelled. Nothing was installed.");
                        }
                    }
                    progress(pkg, "installing", 100, "Installing " + archive.versionName + "...");
                    String out = installApk(apk);
                    if (out.contains("Success")) {
                        updateResults.remove(pkg);
                        progress(pkg, "done", 100, "Updated to " + archive.versionName);
                    } else {
                        throw new IllegalStateException(out.trim().isEmpty() ? "install failed" : out.trim());
                    }
                } catch (Exception e) {
                    // "cancelled": a No to the question, or no privileged mode - nothing was tried, and the page does not count it as a failure
                    progress(pkg, e instanceof InstallCancelled ? "cancelled" : "error", 0, e.getMessage() != null ? e.getMessage() : e.getClass().getSimpleName());
                } finally {
                    apk.delete();
                    installingUpdates.remove(pkg);
                }
            }
        });
    }

    private void selfUpdateProgress(String stage, int percent, String message) {
        try {
            JSONObject o = new JSONObject();
            o.put("stage", stage);
            o.put("percent", percent);
            o.put("message", message == null ? "" : message);
            notifyUpdates("onSelfUpdateProgress", o);
        } catch (Exception ignored) {}
    }

    /** Checks this app's own latest GitHub release and reports it to window.onSelfUpdate(json). */
    private void runCheckSelfUpdate() {
        executor.submit(new Runnable() {
            @Override
            public void run() {
                JSONObject o = new JSONObject();
                String installed = currentVersionName();
                try {
                    o.put("installedVersion", installed);
                    JSONObject rel = UpdateManager.githubLatest(UpdateManager.SELF_REPO, Build.SUPPORTED_ABIS);
                    String latest = rel.optString("version");
                    o.put("latestVersion", latest);
                    o.put("page", rel.optString("page"));
                    o.put("downloadUrl", rel.optString("url"));
                    o.put("notes", rel.optString("notes"));
                    o.put("hasApk", !rel.optString("url").isEmpty());
                    o.put("newer", UpdateManager.compareVersions(latest, installed) > 0);
                    o.put("status", "ok");
                } catch (Exception e) {
                    try {
                        o.put("installedVersion", installed);
                        String m = e.getMessage();
                        o.put("status", m != null && m.contains("404") ? "no_releases" : "error");
                        o.put("error", m);
                    } catch (Exception ignored) {}
                }
                notifyUpdates("onSelfUpdate", o);
            }
        });
    }

    /**
     * Downloads the latest release APK of this app, verifies it is this package, newer and signed with the
     * same key, then installs it: through the active privileged mode (seamless, the app restarts), or - with
     * no privileged mode - by handing it to the system package installer for a normal install confirmation.
     */
    private void runInstallSelfUpdate() {
        // No question here, on purpose: the page chooses nothing. The address is this app's own release page, and the file is installed only when it is
        // this package, newer, and signed with the key this install is signed with (checked below, failing closed): the only app it can replace is
        // this one, with a build of the same author. The question is for installs the page can point at a file, an address or an authorizer.
        final String pkg = getPackageName();
        if (!installingUpdates.add("self")) return;
        executor.submit(new Runnable() {
            @Override
            public void run() {
                File apk = new File(new File(getCacheDir(), "updates"), "self.apk");
                boolean standard = "standard".equals(resolveExecMode());
                try {
                    apk.getParentFile().mkdirs();
                    selfUpdateProgress("downloading", 0, "Getting the latest release...");
                    JSONObject rel = UpdateManager.githubLatest(UpdateManager.SELF_REPO, Build.SUPPORTED_ABIS);
                    String url = rel.optString("url");
                    if (url == null || url.isEmpty()) throw new IllegalStateException("the latest release has no APK to download");
                    UpdateManager.download(url, apk, new UpdateManager.Progress() {
                        @Override
                        public void onProgress(long done, long total) {
                            selfUpdateProgress("downloading", total > 0 ? (int) (done * 100 / total) : -1, (done / (1024 * 1024)) + " MB");
                        }
                    });

                    PackageInfo archive = getPackageManager().getPackageArchiveInfo(apk.getAbsolutePath(), 0);
                    if (archive == null || !pkg.equals(archive.packageName)) throw new IllegalStateException("the downloaded file is not this app");
                    long installedVc = versionCodeOf(getPackageManager().getPackageInfo(pkg, 0));
                    if (versionCodeOf(archive) <= installedVc) throw new IllegalStateException("already up to date (" + archive.versionName + ")");
                    // Android only accepts an update signed with the same key - fail clearly if it isn't.
                    int sigFlags = Build.VERSION.SDK_INT >= 28 ? PackageManager.GET_SIGNING_CERTIFICATES : PackageManager.GET_SIGNATURES;
                    java.util.Set<String> installedSigners = signerDigests(getPackageManager().getPackageInfo(pkg, sigFlags), true);
                    PackageInfo archiveSigned = getPackageManager().getPackageArchiveInfo(apk.getAbsolutePath(), sigFlags);
                    java.util.Set<String> newSigners = archiveSigned != null ? signerDigests(archiveSigned, true) : new HashSet<String>();
                    String signerWhy = InstallGuards.checkSigners(installedSigners, newSigners);
                    if ("installed-unreadable".equals(signerWhy)) throw new IllegalStateException("couldn't read the signing certificate of this install, so the download can't be checked against it - not installed");
                    if ("unreadable".equals(signerWhy)) throw new IllegalStateException("couldn't read the signing certificate of the downloaded file, so it can't be checked against this install - not installed");
                    if (signerWhy != null) throw new IllegalStateException("the release APK is signed with a different key than this install, so Android won't accept it as an update");

                    if (standard) {
                        selfUpdateProgress("installing", 100, "Opening the installer...");
                        launchSystemInstaller(apk);
                        selfUpdateProgress("opened", 100, "Confirm the install to update to " + archive.versionName + ".");
                    } else {
                        selfUpdateProgress("installing", 100, "Installing " + archive.versionName + "...");
                        String out = installApk(apk);
                        if (out != null && out.contains("Success")) {
                            selfUpdateProgress("done", 100, "Updated to " + archive.versionName + ". The app will restart.");
                        } else {
                            throw new IllegalStateException(out == null || out.trim().isEmpty() ? "install failed" : out.trim());
                        }
                    }
                } catch (Exception e) {
                    selfUpdateProgress("error", 0, e.getMessage() != null ? e.getMessage() : e.getClass().getSimpleName());
                } finally {
                    // Used up either way: launchSystemInstaller hands the system installer a copy of its own (in cache/share, swept
                    // by ShareProvider), and the privileged install has read it. Kept, it stayed in the cache for good.
                    apk.delete();
                    installingUpdates.remove("self");
                }
            }
        });
    }

    /** Hands an APK to the system package installer (normal install confirmation, no privileged mode needed). */
    private void launchSystemInstaller(File apk) throws Exception {
        File shareApk = ShareProvider.newShareFile(this, "app-update.apk");
        java.io.FileInputStream in = new java.io.FileInputStream(apk);
        try {
            FileOutputStream out = new FileOutputStream(shareApk);
            try {
                byte[] buf = new byte[65536];
                int r;
                while ((r = in.read(buf)) > 0) out.write(buf, 0, r);
            } finally { out.close(); }
        } finally { in.close(); }
        final Uri uri = ShareProvider.uriFor(shareApk);
        runOnUiThread(new Runnable() {
            @Override
            public void run() {
                try {
                    Intent i = new Intent(Intent.ACTION_VIEW);
                    i.setDataAndType(uri, "application/vnd.android.package-archive");
                    i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK | Intent.FLAG_GRANT_READ_URI_PERMISSION);
                    startActivity(i);
                } catch (Exception ignored) {}
            }
        });
    }

    private String installApk(File apk) throws Exception {
        String mode = resolveExecMode();
        if ("adb_tcp".equals(mode) || "adb_wireless".equals(mode)) {
            String target = "adb_tcp".equals(mode) ? tcpTarget() : wirelessTarget();
            if (!isAdbTargetConnected(target)) performConnect("adb_tcp".equals(mode) ? adbTcpHost : adbWirelessHost,
                    "adb_tcp".equals(mode) ? adbTcpPort : adbWirelessPort, null);
            // The adb client runs as this app, so it can read the file and stream it to the device
            return runProcessWithTimeout(buildAdbProcess("-s", target, "install", "-r", apk.getAbsolutePath()), 300000);
        }
        if ("shizuku".equals(mode)) {
            // The shell user can't read app-private files, so stream the APK into `pm install -S`
            return shizukuStream("pm install -r -S " + apk.length(), apk);
        }
        if ("root".equals(mode)) {
            apk.setReadable(true, false);
            ProcessBuilder pb = new ProcessBuilder("su", "-c", "pm install -r '" + apk.getAbsolutePath() + "'");
            pb.redirectErrorStream(true);
            return runProcessWithTimeout(pb, 300000);
        }
        return "Error: installing updates needs ADB, Shizuku or Root";
    }

    private static String errMsg(Throwable e) {
        return e.getMessage() != null && !e.getMessage().isEmpty() ? e.getMessage() : e.getClass().getSimpleName();
    }

    // ---------------------------------------------------------------------------------------------
    // Activity launch helpers
    // ---------------------------------------------------------------------------------------------

    /** True when an `am start` output indicates the activity actually started. */
    private static boolean isLaunchOk(String out) {
        String low = out == null ? "" : out.toLowerCase();
        boolean denied = low.contains("permission denial") || low.contains("securityexception")
                || low.contains("does not exist") || low.contains("unable to resolve")
                || low.contains("not found") || low.contains("exception");
        return low.contains("status: ok")
                || (low.contains("starting: intent") && !denied);
    }

    private String trimSetting(String s) {
        if (s == null) return "";
        s = s.trim();
        return "null".equals(s) ? "" : s;
    }

    private void restoreSecureSetting(AndroidBridge sh, String key, String val) {
        if (val == null || val.isEmpty()) sh.executeShell("settings delete secure " + key);
        else sh.executeShell("settings put secure " + key + " '" + val + "'");
    }

    /**
     * Launches an activity the system's way, so the exported / START_ANY_ACTIVITY check is bypassed:
     * temporarily make the target the device "assistant", press KEYCODE_ASSIST so the SYSTEM (not the
     * shell) starts it, then restore the user's assistant. This is how "Activity Manager" launches
     * unexported activities over Shizuku - a shell (uid 2000) can't `am start` an unexported activity of
     * another uid, but it can set the secure settings and inject the assist key. Needs WRITE_SECURE_SETTINGS,
     * which the shell (ADB / Shizuku) and root both already hold. Returns the `input keyevent` output.
     */
    private String launchViaAssistant(String comp, StringBuilder tried) {
        AndroidBridge sh = new AndroidBridge();
        // A previous run that was killed half way left the user's values in the record: put them back first.
        recoverPendingAssistant();
        // a record that could not be undone is the only copy of the user's own values: never overwrite it with the current ones
        if (prefs.contains("assistant_restore_pending")) {
            String msg = "Error: the assistant settings from an earlier launch could not be put back yet, so nothing was changed. Try again once the device is connected.";
            if (tried != null) tried.append(msg).append("\n");
            return msg;
        }
        String oldAssist = trimSetting(sh.executeShell("settings get secure assistant"));
        String oldVis = trimSetting(sh.executeShell("settings get secure voice_interaction_service"));
        // Only go on when both values were read as plain values: an error text read as "the old value" would be written back as the
        // user's assistant. The values are saved before anything is changed, so a killed process can be undone at the next start.
        String record = AssistantRestore.encode(oldAssist, oldVis);
        if (record == null) {
            String msg = "Error: could not read the current assistant settings, so they were not changed.";
            if (tried != null) tried.append(msg).append("\n");
            return msg;
        }
        prefs.edit().putString("assistant_restore_pending", record).commit();
        String keyOut = "";
        try {
            sh.executeShell("settings put secure assistant '" + comp + "'");
            // Clear the voice-interaction service so the assist key resolves to the 'assistant' component
            // (a set VIS takes precedence). It is restored in finally.
            sh.executeShell("settings delete secure voice_interaction_service");
            keyOut = sh.executeShell("input keyevent 219"); // KEYCODE_ASSIST
            if (tried != null) {
                tried.append("$ settings put secure assistant '").append(comp).append("'\n");
                tried.append("$ input keyevent 219 (KEYCODE_ASSIST)\n").append(keyOut == null ? "" : keyOut.trim()).append("\n\n");
            }
            // Give the system a moment to start the activity before the settings are restored.
            try { Thread.sleep(1500); } catch (InterruptedException ignored) {}
        } finally {
            recoverPendingAssistant();
        }
        return keyOut == null ? "" : keyOut;
    }

    /**
     * Puts back the assistant settings saved by {@link #launchViaAssistant} and clears the record, but only once a read-back shows
     * the values are really back (if the backend is not connected the record stays for the next try).
     */
    private void recoverPendingAssistant() {
        // A lock of its own, not the activity's: the shell commands below can take minutes on a backend that does not answer, and the
        // activity's monitor is also taken on the UI thread (onDestroy, the Morphe picker) and by every lazy getter (secrets(), vault() ...).
        synchronized (assistantLock) {
            String[] old = AssistantRestore.decode(prefs.getString("assistant_restore_pending", null));
            if (old == null) {
                if (prefs.contains("assistant_restore_pending")) prefs.edit().remove("assistant_restore_pending").commit();
                return;
            }
            try {
                AndroidBridge sh = new AndroidBridge();
                restoreSecureSetting(sh, "assistant", old[0]);
                restoreSecureSetting(sh, "voice_interaction_service", old[1]);
                boolean back = trimSetting(sh.executeShell("settings get secure assistant")).equals(old[0])
                        && trimSetting(sh.executeShell("settings get secure voice_interaction_service")).equals(old[1]);
                if (back) prefs.edit().remove("assistant_restore_pending").commit();
            } catch (Throwable t) {
                Log.w(TAG, "assistant restore: " + t.getMessage());
            }
        }
    }

    private final Object assistantLock = new Object();

    /** X.500 subject DNs of a package's signing certificates (for repackage / debug-key detection). */
    private List<String> signerDnList(String pkg) {
        List<String> out = new ArrayList<String>();
        try {
            int sigFlags = Build.VERSION.SDK_INT >= 28 ? PackageManager.GET_SIGNING_CERTIFICATES : PackageManager.GET_SIGNATURES;
            PackageInfo pi = getPackageManager().getPackageInfo(pkg, sigFlags);
            android.content.pm.Signature[] sigs;
            if (Build.VERSION.SDK_INT >= 28 && pi.signingInfo != null) {
                sigs = pi.signingInfo.hasMultipleSigners()
                        ? pi.signingInfo.getApkContentsSigners()
                        : pi.signingInfo.getSigningCertificateHistory();
            } else {
                sigs = pi.signatures;
            }
            if (sigs != null) {
                java.security.cert.CertificateFactory cf = java.security.cert.CertificateFactory.getInstance("X.509");
                for (android.content.pm.Signature s : sigs) {
                    try {
                        java.security.cert.X509Certificate c = (java.security.cert.X509Certificate)
                                cf.generateCertificate(new java.io.ByteArrayInputStream(s.toByteArray()));
                        out.add(c.getSubjectDN().getName());
                    } catch (Exception ignored) {}
                }
            }
        } catch (Exception ignored) {}
        return out;
    }

    // ---------------------------------------------------------------------------------------------
    // ShizuStore catalog (browse + install Shizuku apps straight from their upstream sources)
    // ---------------------------------------------------------------------------------------------

    /** Loads the ShizuStore catalog off-thread and reports it to window.onStoreCatalog(json). */
    private void runStoreCatalog() {
        executor.submit(new Runnable() {
            @Override
            public void run() {
                JSONObject o = new JSONObject();
                try {
                    JSONObject cat = ShizuStore.catalog(200, 2000);
                    o.put("status", "ok");
                    o.put("base", ShizuStore.BASE);
                    o.put("items", cat.optJSONArray("items"));
                    o.put("total", cat.optInt("total"));
                } catch (Exception e) {
                    try { o.put("status", "error"); o.put("error", errMsg(e)); } catch (Exception ignored) {}
                }
                notifyUpdates("onStoreCatalog", o);
            }
        });
    }

    /** Loads one ShizuStore app detail off-thread and reports it to window.onStoreApp(json). */
    private void runStoreApp(final String slug) {
        executor.submit(new Runnable() {
            @Override
            public void run() {
                JSONObject o = new JSONObject();
                try {
                    JSONObject detail = ShizuStore.app(slug);
                    o.put("status", "ok");
                    o.put("base", ShizuStore.BASE);
                    o.put("app", detail);
                    JSONObject dl = ShizuStore.primaryDownload(detail);
                    if (dl != null) o.put("download", dl);
                } catch (Exception e) {
                    try { o.put("status", "error"); o.put("error", errMsg(e)); } catch (Exception ignored) {}
                }
                try { o.put("slug", slug); } catch (Exception ignored) {}
                notifyUpdates("onStoreApp", o);
            }
        });
    }

    private final java.util.Set<String> storeInstalling =
            java.util.Collections.synchronizedSet(new HashSet<String>());

    /**
     * Downloads a ShizuStore APK from its upstream URL and installs it through the active mode (or hands
     * it to the system installer with no privileged mode). Progress -> window.onStoreInstallProgress(json).
     */
    private void runStoreInstall(final String apkUrl, final String pkg, final String label, final String sha256) {
        if (apkUrl == null || !apkUrl.startsWith("https://")) {
            storeInstallProgress(pkg, "error", 0, "This app has no direct APK to install.");
            return;
        }
        downloadAndInstall(apkUrl, pkg, label, pkg, sha256 == null ? "" : sha256);
    }

    /**
     * Downloads an https APK and installs it through the active mode (shared by every Store source).
     * {@code pkg}: the package the download must turn out to be ("" when the catalog doesn't know it).
     * {@code progressKey}: identity used for progress events and the one-at-a-time guard (a GitHub repo has no
     * package name until the APK is read). {@code sha256}: a checksum published by the repository, verified
     * before anything is installed ("" = none available).
     */
    private void downloadAndInstall(final String apkUrl, final String pkg, final String label,
                                    final String progressKey, final String sha256) {
        final String key = progressKey != null && !progressKey.isEmpty() ? progressKey
                : (pkg == null || pkg.isEmpty() ? apkUrl : pkg);
        if (!storeInstalling.add(key)) return;
        executor.submit(new Runnable() {
            @Override
            public void run() {
                File apk = null;
                boolean standard = "standard".equals(resolveExecMode());
                try {
                    // One file of its own for every call, never derived from the key (the page chooses the key, and two keys can share a hash code): the file
                    // the user is asked about is the file that is installed, and no other request can write into it in between
                    File dir = new File(getCacheDir(), "updates");
                    dir.mkdirs();
                    File[] old = dir.listFiles();
                    if (old != null) for (File f : old) if (f.getName().startsWith("store-") && (f.getName().endsWith(".apk") || f.getName().endsWith(".apk.part")) && f.lastModified() < System.currentTimeMillis() - 24L * 3600 * 1000) f.delete();
                    apk = File.createTempFile("store-", ".apk", dir);
                    final String name = label == null || label.isEmpty() ? (pkg == null || pkg.isEmpty() ? "app" : pkg) : label;
                    storeInstallProgress(key, "downloading", 0, "Downloading " + name + "…");
                    final String finalUrl = UpdateManager.download(apkUrl, apk, new UpdateManager.Progress() {
                        @Override
                        public void onProgress(long done, long total) {
                            storeInstallProgress(key, "downloading", total > 0 ? (int) (done * 100 / total) : -1,
                                    (done / (1024 * 1024)) + " MB");
                        }
                    });
                    // The repository's own checksum, when it publishes one (F-Droid index, ShizuStore)
                    if (InstallGuards.hasPublishedHash(sha256)) {
                        storeInstallProgress(key, "verifying", 100, "Checking the download's SHA-256…");
                        String why = InstallGuards.checkHash(sha256, InstallGuards.isSha256(InstallGuards.normalize(sha256)) ? VirusTotal.sha256(apk) : null);
                        if (why != null) throw new IllegalStateException(why);
                    }
                    PackageInfo archive = getPackageManager().getPackageArchiveInfo(apk.getAbsolutePath(), 0);
                    if (archive == null || archive.packageName == null) throw new IllegalStateException("the download is not a valid APK");
                    // Guard against a redirected/wrong download installing an unexpected package.
                    if (pkg != null && !pkg.isEmpty() && !pkg.equals(archive.packageName))
                        throw new IllegalStateException("the download is " + archive.packageName + ", not " + pkg);
                    if (standard) {
                        storeInstallProgress(key, "installing", 100, "Opening the installer…");
                        launchSystemInstaller(apk);
                        storeInstallProgress(key, "opened", 100, "Confirm the install of " + name + ".");
                    } else {
                        // A privileged install has no system installer in front of it, and the address, package and hash all come from the page:
                        // the user is asked here, with what was read from the file itself.
                        storeInstallProgress(key, "confirming", 100, "Waiting for your OK to install " + name + "…");
                        String installedVersion = null;
                        try {
                            PackageInfo cur = getPackageManager().getPackageInfo(archive.packageName, 0);
                            installedVersion = cur.versionName == null ? "" : cur.versionName;
                        } catch (PackageManager.NameNotFoundException notInstalled) { /* a new app */ }
                        boolean hashChecked = InstallGuards.hasPublishedHash(sha256) && InstallGuards.isSha256(InstallGuards.normalize(sha256));
                        if (!confirmPrivilegedInstall(InstallConfirm.message(name, archive.packageName, archive.versionName, InstallConfirm.hostOf(finalUrl), InstallConfirm.hostOf(apkUrl), installedVersion, hashChecked))) {
                            throw new IllegalStateException("Install cancelled.");
                        }
                        storeInstallProgress(key, "installing", 100, "Installing " + name + "…");
                        String out = installApk(apk);
                        if (out != null && out.contains("Success")) {
                            storeInstallProgress(key, "done", 100, "Installed " + name
                                    + (archive.versionName != null ? " " + archive.versionName : "") + ".",
                                    archive.packageName, name);
                        } else {
                            throw new IllegalStateException(out == null || out.trim().isEmpty() ? "install failed" : out.trim());
                        }
                    }
                } catch (Exception e) {
                    storeInstallProgress(key, "error", 0, errMsg(e));
                } finally {
                    if (apk != null) apk.delete();         // the system installer reads its own copy (launchSystemInstaller)
                    storeInstalling.remove(key);
                }
            }
        });
    }

    /**
     * Asks, in a native dialog the page cannot press, whether to go on with a privileged install. Blocks the calling (background) thread until the
     * user answers; no answer in two minutes, or the screen closing, is a no.
     */
    private boolean confirmPrivilegedInstall(final String message) {
        return confirmNative(InstallConfirm.title(), message, "Install", "Cancel") == BundleApprovals.Answer.ALLOW;
    }

    /**
     * {@link #confirmPrivilegedInstall} for a question that names the mode the install runs through. A Yes counts only if that mode is still the one
     * the install would use once the answer is in (the dialog can stay open while the working mode is changed): else nothing is installed and
     * {@link InstallCancelled} says why. {@code authorizer} is the Installer's authorizer choice when the mode came from it (null: the working mode).
     * False is a plain No.
     */
    private boolean confirmInMode(String mode, String authorizer, String message) {
        // a mode that is not privileged (the app went Read-Only after the install began) has nothing to ask about: no question, no install
        if (!InstallGuards.isPrivilegedMode(mode)) throw new InstallCancelled(InstallConfirm.NO_PRIVILEGED_MODE);
        if (!confirmPrivilegedInstall(message)) return false;
        String now = authorizer == null ? resolveExecMode() : resolveAuthorizerMode(authorizer);
        if (!InstallGuards.sameMode(mode, now)) throw new InstallCancelled(InstallConfirm.MODE_CHANGED);
        return true;
    }

    /**
     * The question dialog behind {@link #confirmPrivilegedInstall} and the one asked before a patch bundle (code) is loaded: a native dialog the page
     * cannot press, which blocks the calling (background) thread until the user answers. Only the yes button says yes; Back, a tap outside, no answer in
     * two minutes (the same time as {@link BundleApprovals#ANSWER_WAIT_SECONDS}) and the screen closing are all no. Each question tracks and dismisses its own dialog.
     * The answer says which kind of no it was: TIMEOUT is only "nobody answered in the whole wait"; a button, Back, a tap outside or the screen closing is DENY.
     */
    private BundleApprovals.Answer confirmNative(final String title, final String message, final String yesLabel, final String noLabel) {
        final java.util.concurrent.CountDownLatch answered = new java.util.concurrent.CountDownLatch(1);
        final boolean[] yes = { false };
        // This question's own dialog: several installs can ask at the same time, and each one dismisses only its own
        final java.util.concurrent.atomic.AtomicReference<android.app.AlertDialog> mine = new java.util.concurrent.atomic.AtomicReference<android.app.AlertDialog>();
        try {
            runOnUiThread(new Runnable() {
                @Override
                public void run() {
                    if (isFinishing() || isDestroyed()) { answered.countDown(); return; }
                    android.app.AlertDialog.Builder b = new android.app.AlertDialog.Builder(MainActivity.this);
                    b.setTitle(title);
                    b.setMessage(message);
                    b.setCancelable(true);
                    b.setPositiveButton(yesLabel, new android.content.DialogInterface.OnClickListener() {
                        @Override
                        public void onClick(android.content.DialogInterface d, int which) { yes[0] = true; }
                    });
                    b.setNegativeButton(noLabel, null);
                    // Any way the dialog goes away (a button, Back, a tap outside, a timeout, the screen closing) ends the wait; only "Install" says yes.
                    b.setOnDismissListener(new android.content.DialogInterface.OnDismissListener() {
                        @Override
                        public void onDismiss(android.content.DialogInterface d) {
                            installConfirmDialogs.remove(d);
                            answered.countDown();
                        }
                    });
                    android.app.AlertDialog dlg = b.create();
                    mine.set(dlg);
                    installConfirmDialogs.add(dlg);
                    dlg.show();
                }
            });
            if (!answered.await(BundleApprovals.ANSWER_WAIT_SECONDS, java.util.concurrent.TimeUnit.SECONDS)) {
                dismissInstallConfirm(mine);   // no answer is a no, and the question must not stay on screen to be answered later
                return BundleApprovals.Answer.TIMEOUT;
            }
        } catch (InterruptedException e) {
            dismissInstallConfirm(mine);
            Thread.currentThread().interrupt();
            return BundleApprovals.Answer.DENY;
        } catch (RuntimeException e) {
            return BundleApprovals.Answer.DENY;
        }
        return yes[0] ? BundleApprovals.Answer.ALLOW : BundleApprovals.Answer.DENY;
    }

    /** The page's alert / confirm / prompt in the app's look (its colours come from the page); see PageDialogs. */
    private final PageDialogs pageDialogs = new PageDialogs(this);

    /** The install questions on screen now (one per install waiting for an answer); touched on the UI thread. */
    private final java.util.Set<android.content.DialogInterface> installConfirmDialogs = new java.util.HashSet<android.content.DialogInterface>();

    private void dismissInstallConfirm(final java.util.concurrent.atomic.AtomicReference<android.app.AlertDialog> mine) {
        try {
            runOnUiThread(new Runnable() {
                @Override
                public void run() {
                    android.app.AlertDialog d = mine.get();
                    if (d != null) { installConfirmDialogs.remove(d); if (d.isShowing()) d.dismiss(); }
                }
            });
        } catch (RuntimeException ignored) { /* the screen is already gone */ }
    }

    /** The screen is closing: every install question still open is closed with it (each waiting install then reads that as no). */
    private void dismissAllInstallConfirms() {
        for (android.content.DialogInterface d : new java.util.ArrayList<android.content.DialogInterface>(installConfirmDialogs)) {
            try { d.dismiss(); } catch (Throwable ignored) {}
        }
        installConfirmDialogs.clear();
    }

    private void storeInstallProgress(String pkg, String stage, int percent, String message) {
        storeInstallProgress(pkg, stage, percent, message, "", "");
    }

    /**
     * {@code pkg} here is the progress key (a GitHub repo has no package name until the APK is read), so a
     * successful install also reports the real, installed package name and app label separately: the page
     * needs the true package name to offer Launch / Application Settings, which the key is not guaranteed to be.
     */
    private void storeInstallProgress(String pkg, String stage, int percent, String message, String installedPkg, String label) {
        try {
            JSONObject o = new JSONObject();
            o.put("pkg", pkg == null ? "" : pkg);
            o.put("stage", stage);
            o.put("percent", percent);
            o.put("message", message == null ? "" : message);
            o.put("installedPkg", installedPkg == null ? "" : installedPkg);
            o.put("label", label == null ? "" : label);
            notifyUpdates("onStoreInstallProgress", o);
        } catch (Exception ignored) {}
    }

    // ---------------------------------------------------------------------------------------------
    // Store sub-tabs: GitHub (Komi catalog), F-Droid repositories, Orion
    //
    // Catalogs reach the WebView as window.onStoreSource(json) events:
    //   {source, arg?, status:"ok", items:[...], append, done, total, note?, fallback?}   (chunks of <=400 items)
    //   {source, arg?, status:"progress", message}
    //   {source, arg?, status:"error", error}
    // The first chunk has append=false (replace the list); the last has done=true.
    // ---------------------------------------------------------------------------------------------

    private static final int STORE_CHUNK = 400;
    private static final long STORE_CACHE_TTL_MS = 12L * 3600 * 1000;
    private static final int GITHUB_MAX_APPS = 5000;

    private File storeCacheFile(String key) {
        File d = new File(getCacheDir(), "store");
        d.mkdirs();
        return new File(d, key.replaceAll("[^A-Za-z0-9._-]", "_") + ".json");
    }

    /** A cached catalog (JSON array of items) younger than {@code ttlMs}, or null. */
    private JSONArray storeCacheRead(String key, long ttlMs) {
        try {
            File f = storeCacheFile(key);
            if (!f.isFile() || System.currentTimeMillis() - f.lastModified() > ttlMs || f.length() > 40L * 1024 * 1024) return null;
            java.io.ByteArrayOutputStream bo = new java.io.ByteArrayOutputStream((int) f.length());
            java.io.FileInputStream in = new java.io.FileInputStream(f);
            try {
                byte[] buf = new byte[65536];
                int n;
                while ((n = in.read(buf)) > 0) bo.write(buf, 0, n);
            } finally { in.close(); }
            return new JSONArray(bo.toString("UTF-8"));
        } catch (Throwable t) {
            return null;
        }
    }

    private void storeCacheWrite(String key, JSONArray items) {
        try {
            FileOutputStream out = new FileOutputStream(storeCacheFile(key));
            try { out.write(items.toString().getBytes("UTF-8")); } finally { out.close(); }
        } catch (Throwable ignored) {}
    }

    private void storeCacheClear(String key) {
        try { storeCacheFile(key).delete(); } catch (Throwable ignored) {}
    }

    private JSONObject storeEvent(String source, String arg, String status) throws Exception {
        JSONObject o = new JSONObject();
        o.put("source", source);
        if (arg != null) o.put("arg", arg);
        o.put("status", status);
        return o;
    }

    private void storeProgress(String source, String arg, String message) {
        try {
            JSONObject o = storeEvent(source, arg, "progress");
            o.put("message", message);
            notifyUpdates("onStoreSource", o);
        } catch (Exception ignored) {}
    }

    private void storeError(String source, String arg, String message) {
        try {
            JSONObject o = storeEvent(source, arg, "error");
            o.put("error", message);
            notifyUpdates("onStoreSource", o);
        } catch (Exception ignored) {}
    }

    /** Sends one chunk of items. {@code extra} (may be null) is merged into the event. */
    private void storeChunk(String source, String arg, JSONArray items, boolean append, boolean done, int total, JSONObject extra) {
        try {
            JSONObject o = storeEvent(source, arg, "ok");
            o.put("items", items);
            o.put("append", append);
            o.put("done", done);
            o.put("total", total);
            if (extra != null) {
                java.util.Iterator<String> it = extra.keys();
                while (it.hasNext()) { String k = it.next(); o.put(k, extra.get(k)); }
            }
            notifyUpdates("onStoreSource", o);
        } catch (Exception ignored) {}
    }

    /** Delivers a whole catalog in chunks so no single message to the WebView is huge. */
    private void storeDeliver(String source, String arg, JSONArray items, JSONObject extra) {
        int total = items.length();
        if (total == 0) { storeChunk(source, arg, new JSONArray(), false, true, 0, extra); return; }
        for (int i = 0; i < total; i += STORE_CHUNK) {
            JSONArray part = new JSONArray();
            for (int j = i; j < Math.min(i + STORE_CHUNK, total); j++) part.put(items.opt(j));
            boolean last = i + STORE_CHUNK >= total;
            storeChunk(source, arg, part, i > 0, last, total, last ? extra : null);
        }
    }

    /**
     * The GitHub tab: pages the Komi catalog's whole Android list (50 per request, shown as it arrives), or
     * - for arg "q:<text>" - runs a live relevance search. When Komi's server can't be reached it falls back
     * to its offline mirror, then to a small built-in list, and says so.
     */
    private void loadGithubCatalog(String arg, boolean force) throws Exception {
        final String source = "github";
        if (arg != null && arg.startsWith("q:")) {
            String q = arg.substring(2).trim();
            if (q.isEmpty()) { storeDeliver(source, arg, new JSONArray(), null); return; }
            JSONArray found = new JSONArray();
            Set<String> seen = new HashSet<String>();
            for (int page = 0; page < 2; page++) {
                JSONObject body = KomiApi.searchRaw(q, "", page * KomiApi.PAGE, KomiApi.PAGE);
                JSONArray rawItems = body.optJSONArray("items");
                JSONArray part = KomiApi.mapItems(body, seen);
                for (int i = 0; i < part.length(); i++) found.put(part.get(i));
                if (rawItems == null || rawItems.length() < KomiApi.PAGE) break;
            }
            JSONObject extra = new JSONObject();
            extra.put("search", true);
            extra.put("query", q);
            storeDeliver(source, arg, found, extra);
            return;
        }

        if (force) storeCacheClear("github-browse");
        JSONArray cached = force ? null : storeCacheRead("github-browse", 6L * 3600 * 1000);
        if (cached != null && cached.length() > 0) {
            JSONObject extra = new JSONObject();
            extra.put("cached", true);
            storeDeliver(source, arg, cached, extra);
            return;
        }

        JSONArray all = new JSONArray();
        Set<String> seen = new HashSet<String>();
        boolean first = true;
        int offset = 0;
        String stopNote = "";
        try {
            while (all.length() < GITHUB_MAX_APPS) {
                JSONObject body = KomiApi.searchRaw("", "stars", offset, KomiApi.PAGE);
                JSONArray rawItems = body.optJSONArray("items");
                int got = rawItems == null ? 0 : rawItems.length();
                JSONArray part = KomiApi.mapItems(body, seen);
                for (int i = 0; i < part.length(); i++) all.put(part.get(i));
                if (part.length() > 0 || first) storeChunk(source, arg, part, !first, false, all.length(), null);
                first = false;
                if (got < KomiApi.PAGE) break;
                offset += got;
                Thread.sleep(100); // be a polite client: ~10 requests a second at most
            }
        } catch (Exception e) {
            if (all.length() == 0) {
                githubFallback(arg);
                return;
            }
            stopNote = "Stopped early after " + all.length() + " apps (" + errMsg(e) + "). Tap Refresh to retry.";
        }
        JSONObject extra = new JSONObject();
        if (!stopNote.isEmpty()) extra.put("note", stopNote);
        storeChunk(source, arg, new JSONArray(), true, true, all.length(), extra);
        if (stopNote.isEmpty() && all.length() > 0) storeCacheWrite("github-browse", all);
    }

    /** Komi's server is unreachable: its static mirror, else a small built-in list. */
    private void githubFallback(String arg) throws Exception {
        JSONObject extra = new JSONObject();
        extra.put("fallback", true);
        try {
            JSONArray mirror = KomiApi.mirrorItems();
            extra.put("note", "Couldn't reach the Komi catalog server, so this is its offline mirror (" + mirror.length()
                    + " popular apps). Tap Refresh to try the full catalog again.");
            storeDeliver("github", arg, mirror, extra);
        } catch (Exception e) {
            JSONArray builtin = Stores.githubBuiltin();
            extra.put("note", "Couldn't reach the Komi catalog. Showing " + builtin.length() + " built-in apps; search still works once you're online.");
            storeDeliver("github", arg, builtin, extra);
        }
    }

    private void loadOrionCatalog(boolean force) throws Exception {
        if (force) storeCacheClear("orion");
        JSONArray cached = force ? null : storeCacheRead("orion", STORE_CACHE_TTL_MS);
        if (cached != null && cached.length() > 0) { storeDeliver("orion", null, cached, null); return; }
        storeProgress("orion", null, "Downloading the Orion catalog…");
        JSONArray items = Stores.orionCatalog(4000).optJSONArray("items");
        if (items == null) items = new JSONArray();
        storeCacheWrite("orion", items);
        storeDeliver("orion", null, items, null);
    }

    private void loadFdroidRepo(final String address, boolean force) throws Exception {
        loadFdroidRepoAs("fdroid-repo", address, address, force);
    }

    /** The side file with the descriptions and screenshots of a repository's apps, next to its cached catalog. */
    private File storeDetailFile(String address) {
        String ckey = "fdroid-" + Integer.toHexString(address.hashCode());
        File d = new File(getCacheDir(), "store");
        d.mkdirs();
        return new File(d, ckey + ".detail");
    }

    /** Reads an F-Droid style repository and delivers it as {@code source}/{@code arg} (the F-Droid tab and the custom stores share this). */
    private void loadFdroidRepoAs(final String source, final String arg, final String address, boolean force) throws Exception {
        if (address == null || !address.startsWith("https://")) {
            storeError(source, arg, "Invalid repository address.");
            return;
        }
        final String ckey = "fdroid-" + Integer.toHexString(address.hashCode());
        if (force) { storeCacheClear(ckey); try { storeDetailFile(address).delete(); } catch (Throwable ignored) {} }
        JSONArray cached = force ? null : storeCacheRead(ckey, STORE_CACHE_TTL_MS);
        if (cached != null && cached.length() > 0) {
            JSONObject extra = new JSONObject();
            extra.put("cached", true);
            storeDeliver(source, arg, cached, extra);
            return;
        }
        storeProgress(source, arg, "Contacting the repository…");
        final File detailTmp = new File(storeDetailFile(address).getPath() + ".tmp");
        final java.io.BufferedWriter dw = new java.io.BufferedWriter(new java.io.OutputStreamWriter(new FileOutputStream(detailTmp), "UTF-8"), 65536);
        FdroidIndex.Result res;
        try {
            res = FdroidIndex.load(address, Build.SUPPORTED_ABIS, Build.VERSION.SDK_INT, new FdroidIndex.Sink() {
                @Override
                public void onProgress(long bytes, int apps) {
                    storeProgress(source, arg, "Reading the catalog… " + XapkInfo.humanBytes(bytes) + " · " + apps + " apps");
                }
            }, new FdroidIndex.Details() {
                @Override
                public void put(String pkg, JSONObject detail) {
                    try { dw.write(StoreDetail.detailLine(pkg, detail)); dw.write('\n'); } catch (java.io.IOException ignored) {}
                }
            });
        } catch (Exception e) {
            try { dw.close(); } catch (Exception ignored) {}
            detailTmp.delete();
            throw e;
        }
        try { dw.close(); } catch (Exception ignored) {}
        File detailFile = storeDetailFile(address);
        detailFile.delete();
        if (!detailTmp.renameTo(detailFile)) detailTmp.delete();
        storeCacheWrite(ckey, res.items);
        JSONObject extra = new JSONObject();
        extra.put("repoName", res.repoName);
        extra.put("format", res.format);
        extra.put("skipped", res.skipped);
        storeDeliver(source, arg, res.items, extra);
    }

    /**
     * The catalog of a custom store (the "+" tab). arg is {id, kind, url, owner, repo}: kind "fdroid" (an F-Droid style repository at url), "github-owner",
     * "github-repo", "codeberg-owner" or "codeberg-repo". Delivered as source "custom" with the same arg, so the page knows which tab it is for.
     */
    private void loadCustomStore(final String arg, boolean force) throws Exception {
        final String source = "custom";
        JSONObject a = new JSONObject(arg);
        String kind = a.optString("kind", ""), owner = a.optString("owner", ""), repo = a.optString("repo", ""), url = a.optString("url", "");
        if ("fdroid".equals(kind)) { loadFdroidRepoAs(source, arg, url, force); return; }
        final String ckey = "custom-" + Integer.toHexString((kind + "|" + owner + "|" + repo).hashCode());
        if (force) storeCacheClear(ckey);
        JSONArray cached = force ? null : storeCacheRead(ckey, STORE_CACHE_TTL_MS);
        if (cached != null && cached.length() > 0) { storeDeliver(source, arg, cached, null); return; }
        storeProgress(source, arg, "Asking " + ("github-owner".equals(kind) || "github-repo".equals(kind) ? "GitHub" : "Codeberg") + "…");
        String token = secrets().get(SecretSettings.GITHUB_TOKEN);
        JSONArray items;
        if ("github-owner".equals(kind)) items = StoreDetail.githubOwner(owner, token);
        else if ("github-repo".equals(kind)) items = StoreDetail.githubRepo(owner, repo, token);
        else if ("codeberg-owner".equals(kind)) items = StoreDetail.codebergOwner(owner);
        else if ("codeberg-repo".equals(kind)) items = StoreDetail.codebergRepo(owner, repo);
        else throw new IllegalStateException("unknown kind of store");
        storeCacheWrite(ckey, items);
        JSONObject extra = new JSONObject();
        if (items.length() == 0) extra.put("note", "No projects found there.");
        else if (kind.endsWith("-owner")) extra.put("note", "Not every project publishes an APK. Install says so when a project has none.");
        storeDeliver(source, arg, items, extra);
    }

    /**
     * Loads a sub-tab's catalog off-thread (see the event protocol above). source: "github" (arg "" = browse,
     * "q:<text>" = search), "orion", "fdroid-repos" (the known-repo directory) or "fdroid-repo" (arg = address).
     * {@code force} bypasses the on-disk cache.
     */
    private void runStoreSourceCatalog(final String source, final String arg, final boolean force) {
        executor.submit(new Runnable() {
            @Override
            public void run() {
                try {
                    if ("github".equals(source)) loadGithubCatalog(arg, force);
                    else if ("orion".equals(source)) loadOrionCatalog(force);
                    else if ("fdroid-repos".equals(source)) {
                        JSONObject res = Stores.fdroidRepos();
                        storeDeliver(source, arg, res.optJSONArray("items"), null);
                    } else if ("fdroid-repo".equals(source)) loadFdroidRepo(arg, force);
                    else if ("custom".equals(source)) loadCustomStore(arg, force);
                    else throw new IllegalStateException("unknown store source");
                } catch (Throwable e) {
                    storeError(source, arg, e instanceof Exception ? errMsg((Exception) e) : String.valueOf(e.getMessage()));
                }
            }
        });
    }

    /**
     * What an app of any store shows when it is opened: the long description, screenshots and links. item is the store item plus "repo" (the
     * address of the F-Droid repository it came from). Answer: window.onStoreSourceDetail(json) {key, ok, detail | error}.
     */
    private void runStoreSourceDetail(final String itemJson) {
        executor.submit(new Runnable() {
            @Override
            public void run() {
                String key = "";
                try {
                    JSONObject item = new JSONObject(itemJson);
                    key = item.optString("key", item.optString("id", ""));
                    String kind = item.optString("resolveKind", ""), source = item.optString("source", ""), owner = item.optString("owner", ""), repo = item.optString("repo", "");
                    String pkg = item.optString("pkg", ""), fdroidAddr = item.optString("fdroidRepo", "");
                    JSONObject detail = null;
                    String note = "";
                    if (!fdroidAddr.isEmpty() && !pkg.isEmpty()) {
                        detail = StoreDetail.fromFile(storeDetailFile(fdroidAddr), pkg);
                        if (detail == null) note = "Refresh this store to load the full description and the screenshots.";
                    } else if (!owner.isEmpty() && !repo.isEmpty() && "codeberg".equals(kind)) {
                        detail = StoreDetail.codeberg(owner, repo);
                    } else if (!owner.isEmpty() && !repo.isEmpty()) {
                        detail = StoreDetail.github(owner, repo, secrets().get(SecretSettings.GITHUB_TOKEN));
                    } else {
                        note = "This entry gives no more than what the list shows.";
                    }
                    JSONObject out = new JSONObject();
                    out.put("key", key).put("source", source).put("ok", true).put("note", note);
                    if (detail != null) out.put("detail", detail);
                    notifyUpdates("onStoreSourceDetail", out);
                } catch (Exception e) {
                    try {
                        String m = errMsg(e);
                        if (m != null && m.contains("limit for requests")) m += ". Save a GitHub token (Updates tab) to raise it.";
                        notifyUpdates("onStoreSourceDetail", new JSONObject().put("key", key).put("ok", false).put("error", m));
                    } catch (Exception ignored) {}
                }
            }
        });
    }

    /** Finds out what an address is for a custom store: an F-Droid style repository (and its name). Answer: window.onStoreCustomProbe(json). */
    private void runStoreCustomProbe(final String id, final String url) {
        executor.submit(new Runnable() {
            @Override
            public void run() {
                try {
                    String[] p = FdroidIndex.probe(url);
                    JSONObject out = new JSONObject().put("id", id).put("url", url);
                    if (p == null) out.put("ok", false).put("error", "That address is not a repository the app can read. Use the address of an F-Droid style repository, or a GitHub or Codeberg user, organization or project.");
                    else out.put("ok", true).put("kind", "fdroid").put("address", p[0]).put("title", p[1]).put("format", p[2]);
                    notifyUpdates("onStoreCustomProbe", out);
                } catch (Exception e) {
                    try { notifyUpdates("onStoreCustomProbe", new JSONObject().put("id", id).put("ok", false).put("error", errMsg(e))); } catch (Exception ignored) {}
                }
            }
        });
    }

    /**
     * Resolves a GitHub/Orion/F-Droid catalog item (a direct APK, or a GitHub/Codeberg release picked for
     * this device's ABI) and installs it. Progress -> window.onStoreInstallProgress(json), keyed by the item's key.
     */
    private void runStoreSourceInstall(final String itemJson) {
        executor.submit(new Runnable() {
            @Override
            public void run() {
                String key = "";
                try {
                    JSONObject item = new JSONObject(itemJson);
                    String pkg = item.optString("pkg", "");
                    key = item.optString("key", "");
                    if (key.isEmpty()) key = pkg.isEmpty() ? item.optString("id", "") : pkg;
                    String name = item.optString("name", pkg.isEmpty() ? "app" : pkg);
                    boolean direct = "direct".equals(item.optString("resolveKind", ""))
                            && !item.optString("apkUrl", "").isEmpty();
                    if (!direct) storeInstallProgress(key, "resolving", -1, "Finding the latest release of " + name + "…");
                    // A saved GitHub token (Updates tab) lifts the API's anonymous rate limit
                    JSONObject r = Stores.resolve(item, Build.SUPPORTED_ABIS, secrets().get(SecretSettings.GITHUB_TOKEN));
                    String apkUrl = r.optString("apkUrl", "");
                    String rpkg = r.optString("pkg", pkg);
                    downloadAndInstall(apkUrl, rpkg == null || rpkg.isEmpty() ? pkg : rpkg, name, key, item.optString("sha256", ""));
                } catch (Exception e) {
                    storeInstallProgress(key, "error", 0, errMsg(e));
                }
            }
        });
    }

    // ---------------------------------------------------------------------------------------------
    // VirusTotal (optional, user-supplied API key) pre-install scan
    // ---------------------------------------------------------------------------------------------

    /**
     * True when {@code f} is part of this app's own private data (settings, sealed secrets, the adb key ...) that must not be handed to a share sheet,
     * VirusTotal or another app. Its patched APKs, Helper downloads and the cache folders for picked or downloaded files are allowed (see PrivatePaths.exportable).
     */
    private boolean isPrivateData(File f) {
        return PrivatePaths.blocked(f, getDataDir(), new PrivatePaths.Links() {
                    @Override public long count(File x) throws Exception { return android.system.Os.stat(x.getPath()).st_nlink; }
                }, PrivatePaths.exportable(getFilesDir(), getCacheDir()));
    }

    private static final String PRIVATE_WHY = "That file is part of this app's own private data and is not opened or sent from here.";

    /**
     * Opens {@code f} for reading and only then decides whether it may be read: the decision is made from the open descriptor (where /proc/self/fd/N
     * points, and the link count from fstat), not from the name, so a name swapped for a link between a check and the open cannot lead into the private
     * part of the data folder. Fails closed: anything that cannot be read from the descriptor counts as private. Closing the stream closes the descriptor.
     */
    private InputStream openUnlessPrivate(File f) throws IOException {
        android.os.ParcelFileDescriptor pfd = android.os.ParcelFileDescriptor.open(f, android.os.ParcelFileDescriptor.MODE_READ_ONLY);
        boolean ok = false;
        try {
            checkOpenedNotPrivate(pfd);
            ok = true;
            return new android.os.ParcelFileDescriptor.AutoCloseInputStream(pfd);
        } finally {
            if (!ok) { try { pfd.close(); } catch (IOException ignored) {} }
        }
    }

    /** Throws unless the file behind {@code pfd} may be read (see {@link #openUnlessPrivate}); anything the descriptor cannot tell counts as private. */
    private void checkOpenedNotPrivate(android.os.ParcelFileDescriptor pfd) throws IOException {
        try {
            String target = android.system.Os.readlink("/proc/self/fd/" + pfd.getFd());
            long links = android.system.Os.fstat(pfd.getFileDescriptor()).st_nlink;
            if (!PrivatePaths.blockedOpened(target, links, getDataDir(), PrivatePaths.exportable(getFilesDir(), getCacheDir()))) return;
        } catch (Exception e) {
            // falls through: fail closed
        }
        throw new IOException(PRIVATE_WHY);
    }

    /** {@link #copyFile(File, OutputStream)} from a file that was opened and then judged (see {@link #openUnlessPrivate}); returns the bytes copied. */
    private long copyFileChecked(File src, OutputStream out) throws Exception {
        InputStream in = openUnlessPrivate(src);
        long total = 0;
        try {
            byte[] buf = new byte[65536];
            int n;
            while ((n = in.read(buf)) > 0) { out.write(buf, 0, n); total += n; }
        } finally { in.close(); }
        return total;
    }

    /**
     * What a file search leaves out: the app's own private data. The full check (a resolved path) runs only for what could lead there: a name below the data
     * folder (under either of its spellings) or a link; everything else in a walk is plainly outside it.
     */
    private FileSearch.Skip searchSkip() {
        final File data = getDataDir();
        File real;
        try { real = data.getCanonicalFile(); } catch (IOException e) { real = data; }
        final File dataReal = real;
        return new FileSearch.Skip() {
            @Override
            public boolean skip(File f) {
                if (PrivatePaths.inside(f, data) || PrivatePaths.inside(f, dataReal) || java.nio.file.Files.isSymbolicLink(f.toPath())) return isPrivateData(f);
                return false;
            }
        };
    }

    /** True when the file manager must not read, write or hand on {@code path}: the app's private data (see {@link #isPrivateData}); a content:// reference is never one. */
    private boolean fmPrivate(String path) {
        return path != null && !path.startsWith("content://") && isPrivateData(new File(path));
    }

    /** Why the file manager refuses item {@code q} of a cp / mv / rm batch into {@code dest} (see {@link FileRules#batchRefusal}), or null; both batch routes (plain and added storage) ask this. */
    private String fmBatchRefusal(String op, String q, String dest) {
        return FileRules.batchRefusal(op, q, dest, new FileRules.PrivateTest() {
            @Override public boolean isPrivate(String path) { return fmPrivate(path); }
        }, PRIVATE_WHY);
    }

    /**
     * Scans a local APK with VirusTotal. A SHA-256 lookup (private, no upload) when upload=false; a full
     * upload-and-wait when upload=true. Progress and the final result -> window.onVtResult(json), each with the
     * path it is for, so the page can drop a late answer for a package that was replaced while the scan ran.
     */
    private void runVirusTotalScan(final String apiKey, final String path, final boolean upload) {
        executor.submit(new Runnable() {
            @Override
            public void run() {
                File staged = null;
                try {
                    if (apiKey == null || apiKey.trim().isEmpty()) throw new IllegalStateException("Enter your VirusTotal API key first.");
                    if (path == null || path.isEmpty()) throw new IllegalStateException("Load a package first.");
                    File f = new File(path);
                    if (!f.exists()) throw new IllegalStateException("The selected package is no longer available. Pick it again.");
                    if (isPrivateData(f)) throw new IllegalStateException("That file is part of this app's own private data and is not sent anywhere.");
                    // what is hashed and uploaded is a copy made from a file that was opened and then judged, not whatever the name leads to a moment later
                    File dir = new File(getCacheDir(), "vt_stage");
                    if (!dir.isDirectory()) dir.mkdirs();
                    staged = File.createTempFile("vt", ".bin", dir);
                    FileOutputStream sout = new FileOutputStream(staged);
                    try { copyFileChecked(f, sout); } catch (IOException denied) { throw new IllegalStateException(denied.getMessage()); } finally { sout.close(); }
                    f = staged;
                    notifyUpdates("onVtResult", new JSONObject()
                            .put("stage", upload ? "uploading" : "scanning")
                            .put("message", upload ? "Uploading to VirusTotal… this can take a minute." : "Checking VirusTotal…")
                            .put("path", path));
                    String sha = VirusTotal.sha256(f);
                    JSONObject res = upload
                            ? VirusTotal.uploadAndWait(apiKey.trim(), f, sha, 180000)
                            : VirusTotal.lookup(apiKey.trim(), sha);
                    res.put("stage", "done");
                    res.put("size", f.length());
                    res.put("path", path);
                    notifyUpdates("onVtResult", res);
                } catch (Exception e) {
                    try {
                        notifyUpdates("onVtResult", new JSONObject().put("stage", "error").put("error", errMsg(e)).put("path", path));
                    } catch (Exception ignored) {}
                } finally {
                    if (staged != null) staged.delete();
                }
            }
        });
    }

    /** Runs a command through the Shizuku API, optionally streaming a file into its stdin. */
    private String shizukuStream(String cmd, File stdinFile) throws Exception {
        if (stdinFile == null) return shizukuPipe(cmd, null);
        java.io.FileInputStream in = new java.io.FileInputStream(stdinFile);
        try {
            return shizukuPipe(cmd, in);
        } finally {
            in.close();
        }
    }

    /** Runs a command through the Shizuku API, optionally streaming any InputStream into its stdin. */
    private String shizukuPipe(String cmd, InputStream stdin) throws Exception {
        return shizukuPipe(cmd, stdin, 300000);
    }

    private String shizukuPipe(String cmd, InputStream stdin, int timeoutMs) throws Exception {
        if (shizukuNewProcessMethod == null) {
            Method m = Shizuku.class.getDeclaredMethod("newProcess", String[].class, String[].class, String.class);
            m.setAccessible(true);
            shizukuNewProcessMethod = m;
        }
        final Process p = (Process) shizukuNewProcessMethod.invoke(null,
                new String[]{"sh", "-c", "exec 2>&1; " + cmd}, null, null);
        try {
            // stdin is fed on a thread of its own while the output is read: a command that stops reading early (an install-write that
            // refuses the file) would otherwise end this write with EPIPE before its own error line was ever read
            final OutputStream os = p.getOutputStream();
            final InputStream src = stdin;
            Thread pump = new Thread(new Runnable() {
                @Override
                public void run() {
                    try {
                        if (src != null) {
                            byte[] buf = new byte[65536];
                            int n;
                            while ((n = src.read(buf)) > 0) os.write(buf, 0, n);
                        }
                        os.flush();
                    } catch (IOException ignored) {       // the command ended first: what it printed says why
                    } finally {
                        try { os.close(); } catch (IOException ignored) {}
                    }
                }
            }, "shizuku-stdin");
            pump.setDaemon(true);
            pump.start();
            return readProcessWithTimeout(p, timeoutMs);
        } finally {
            try { p.destroy(); } catch (Exception ignored) {}
        }
    }

    /** Installs one APK, or a base APK with its splits, through a mode the caller already chose (and asked about): the working mode is not read again. */
    private String installApksIn(List<File> apks, String mode) throws Exception {
        if ("adb_tcp".equals(mode) || "adb_wireless".equals(mode)) {
            boolean tcp = "adb_tcp".equals(mode);
            String target = tcp ? tcpTarget() : wirelessTarget();
            if (!isAdbTargetConnected(target)) performConnect(tcp ? adbTcpHost : adbWirelessHost, tcp ? adbTcpPort : adbWirelessPort, null);
            List<String> args = new ArrayList<String>();
            args.add("-s");
            args.add(target);
            args.add(apks.size() == 1 ? "install" : "install-multiple");
            args.add("-r");
            for (File f : apks) args.add(f.getAbsolutePath());
            return runProcessWithTimeout(buildAdbProcess(args.toArray(new String[0])), 600000);
        }
        if ("shizuku".equals(mode)) {
            String created = shizukuStream("pm install-create -r", null);
            String id = BackupScripts.parseSessionId(created);
            if (id == null) return created;
            // A thrown exception mid-write (not just a "Success"-less return) must still abandon the
            // session - otherwise a staged PackageInstaller session and its backing files are left behind
            // with no owner. Only a successful commit excuses the cleanup below.
            boolean committed = false;
            try {
                int index = 0;
                for (File f : apks) {
                    String name = (index++) + "_" + f.getName().replaceAll("[^A-Za-z0-9._-]", "_");
                    String written = shizukuStream("pm install-write -S " + f.length() + " " + id + " " + name + " -", f);
                    if (!written.contains("Success")) return written;
                }
                String result = shizukuStream("pm install-commit " + id, null);
                committed = true;
                return result;
            } finally {
                if (!committed) {
                    try {
                        shizukuStream("pm install-abandon " + id, null);
                    } catch (Exception ignored) {}
                }
            }
        }
        if ("root".equals(mode)) {
            StringBuilder cmd = new StringBuilder(apks.size() == 1 ? "pm install -r" : "pm install-multiple -r");
            for (File f : apks) {
                f.setReadable(true, false);
                cmd.append(' ').append(BackupScripts.quote(f.getAbsolutePath()));
            }
            ProcessBuilder pb = new ProcessBuilder("su", "-c", cmd.toString());
            pb.redirectErrorStream(true);
            return runProcessWithTimeout(pb, 600000);
        }
        return "Error: restoring needs ADB, Shizuku or Root";
    }

    // ---------------------------------------------------------------------------------------------
    // All-in-one installer (APK / APKS / APKM) - the "Installer" tab.
    // Reuses the same per-backend install shapes as installApksIn() above, but with a caller-chosen set
    // of pm flags and a caller-chosen authorizer, plus a no-privilege PackageInstaller fallback. Picked
    // packages are staged into getCacheDir()/installer; nothing outside that directory is ever installed.
    // ---------------------------------------------------------------------------------------------

    /** The real current enabled state of a component: the pm override if one is set, else the manifest default. */
    private boolean componentEnabled(String pkg, String name, boolean manifestEnabled) {
        try {
            int st = getPackageManager().getComponentEnabledSetting(new android.content.ComponentName(pkg, name));
            if (st == PackageManager.COMPONENT_ENABLED_STATE_ENABLED) return true;
            if (st == PackageManager.COMPONENT_ENABLED_STATE_DISABLED) return false;
        } catch (Exception ignored) {}
        return manifestEnabled;
    }

    /** The explicit pm override of a component (ENABLED/DISABLED), or null when none is set (the manifest default is in force). Used to read a toggle back from the real state. */
    private Boolean componentOverrideState(String pkg, String name) {
        try {
            int st = getPackageManager().getComponentEnabledSetting(new android.content.ComponentName(pkg, name));
            if (st == PackageManager.COMPONENT_ENABLED_STATE_ENABLED) return Boolean.TRUE;
            if (st == PackageManager.COMPONENT_ENABLED_STATE_DISABLED) return Boolean.FALSE;
        } catch (Exception ignored) {}
        return null;
    }

    /**
     * The parts of an app that belong to a known tracker (TrackerParts.group), with each part's manifest default and its pm override. Disabled parts are
     * listed too (MATCH_DISABLED_COMPONENTS): a part switched off must stay in the list so it can be switched back on.
     */
    private List<TrackerParts.Group> readTrackerParts(String pkg, Trackers t) throws PackageManager.NameNotFoundException {
        int flags = PackageManager.GET_ACTIVITIES | PackageManager.GET_RECEIVERS | PackageManager.GET_SERVICES | PackageManager.GET_PROVIDERS
                | PackageManager.MATCH_DISABLED_COMPONENTS;
        PackageInfo info = getPackageManager().getPackageInfo(pkg, flags);
        List<TrackerParts.Part> parts = new ArrayList<TrackerParts.Part>();
        if (info.activities != null) for (ActivityInfo a : info.activities) addTrackerPart(parts, t, pkg, a.name, "activity", a.enabled);
        if (info.services != null) for (ServiceInfo s : info.services) addTrackerPart(parts, t, pkg, s.name, "service", s.enabled);
        if (info.receivers != null) for (ActivityInfo r : info.receivers) addTrackerPart(parts, t, pkg, r.name, "receiver", r.enabled);
        if (info.providers != null) for (android.content.pm.ProviderInfo p : info.providers) addTrackerPart(parts, t, pkg, p.name, "provider", p.enabled);
        return TrackerParts.group(t.db, pkg, parts);
    }

    /**
     * The app's parts with these names, whatever the tracker list says of them now (name -> part, with its manifest default and pm override). The
     * History's Undo names the parts its step switched, and a newer tracker list (Update the list, or a newer app) may no longer count one of them as a
     * tracker's: it is still the app's part, and still switched. A name the app no longer has is left out.
     */
    private Map<String, TrackerParts.Part> readNamedParts(String pkg, Set<String> names) throws PackageManager.NameNotFoundException {
        Map<String, TrackerParts.Part> out = new java.util.LinkedHashMap<String, TrackerParts.Part>();
        if (names == null || names.isEmpty()) return out;
        int flags = PackageManager.GET_ACTIVITIES | PackageManager.GET_RECEIVERS | PackageManager.GET_SERVICES | PackageManager.GET_PROVIDERS
                | PackageManager.MATCH_DISABLED_COMPONENTS;
        PackageInfo info = getPackageManager().getPackageInfo(pkg, flags);
        List<String[]> all = new ArrayList<String[]>();                     // {name, kind, manifest enabled}
        if (info.activities != null) for (ActivityInfo a : info.activities) all.add(new String[] { a.name, "activity", String.valueOf(a.enabled) });
        if (info.services != null) for (ServiceInfo sv : info.services) all.add(new String[] { sv.name, "service", String.valueOf(sv.enabled) });
        if (info.receivers != null) for (ActivityInfo rc : info.receivers) all.add(new String[] { rc.name, "receiver", String.valueOf(rc.enabled) });
        if (info.providers != null) for (android.content.pm.ProviderInfo pv : info.providers) all.add(new String[] { pv.name, "provider", String.valueOf(pv.enabled) });
        for (String[] c : all) {
            if (c[0] == null || !names.contains(c[0]) || out.containsKey(c[0])) continue;
            out.put(c[0], new TrackerParts.Part(c[0], c[1], Boolean.parseBoolean(c[2]), componentOverrideState(pkg, c[0])));
        }
        return out;
    }

    /** Adds one part when it belongs to a tracker; its pm override is asked only then (one call to the package manager per tracker part, not per part of the app). */
    private void addTrackerPart(List<TrackerParts.Part> parts, Trackers t, String pkg, String name, String kind, boolean manifestEnabled) {
        if (name == null || TrackerParts.trackerOf(t.db, pkg, name) < 0) return;
        parts.add(new TrackerParts.Part(name, kind, manifestEnabled, componentOverrideState(pkg, name)));
    }

    private JSONObject componentEntry(String pkg, String name, boolean exported, boolean manifestEnabled, String permission) throws Exception {
        JSONObject o = new JSONObject();
        o.put("name", name);
        o.put("exported", exported);
        o.put("enabled", componentEnabled(pkg, name, manifestEnabled));
        o.put("permission", permission != null ? permission : "");
        return o;
    }

    private File installerWorkDir() {
        return new File(getCacheDir(), "installer");
    }

    /**
     * The package loaded in the Installer (its own folder, its OBB / Android-data files, the archive that holds them and the name of the picked
     * file, read here for the question before a privileged install) and the installs running from it. One per process, like the cache folder.
     */
    private static InstallerStage<XapkInfo.Extra> installStage;

    private InstallerStage<XapkInfo.Extra> installStage() throws IOException {
        synchronized (InstallerStage.class) {       // not installInspectLock: an install must not wait for a long read of another package
            if (installStage == null) installStage = new InstallerStage<XapkInfo.Extra>(installerWorkDir().getCanonicalFile());
            return installStage;
        }
    }

    private static final Object installInspectLock = new Object();

    private static final Object fmBatchLock = new Object();
    private static boolean fmBatchBusy;
    private static volatile boolean archiveCancel;      // the page's Cancel for an extraction
    private static volatile boolean fmBatchCancel;       // the page's Cancel: the running batch stops at the next step

    private static final Object appBatchLock = new Object();
    private static boolean appBatchBusy;
    private static volatile boolean appBatchCancel;      // the page's Stop: the running batch stops after the app it is on

    private static final Object optimizeBatchLock = new Object();
    private static boolean optimizeBatchBusy;
    private static volatile boolean optimizeBatchCancel;  // same Stop convention, for Dex optimization (single app or several)

    // The success markers of the file and backup commands (FMOK, OK) are read with FileRules.okLine: a whole line, so a name or message that merely contains the letters never counts.
    /** What a failed app launch or app action prints, matched at the start of a line: "Error: ...", "Error type 3", an exception, "Warning: Activity not started", "No activities found", a permission denial. A package or app name that happens to contain "error" or "failed" is not a failure. */
    private static final java.util.regex.Pattern LAUNCH_FAILED = java.util.regex.Pattern.compile(
            "(?mi)^\\s*(error\\b|error type\\b|exception\\b|(java|android)\\.[a-z.]*(exception|error)\\b|security\\s*exception|failure\\b|failed\\b|aborted\\b|status:\\s*(failed|error)|warning: activity not started|no activities found|permission denial)");
    private static boolean launchOutputFailed(String out) {
        return out != null && LAUNCH_FAILED.matcher(out).find();
    }

    private static String fmBatchLabel(String op) {
        return "rm".equals(op) ? "Deleting" : "cp".equals(op) ? "Copying" : "Moving";
    }

    /** True when a shell answer says the link to the device is gone, so trying item after item is pointless (see FileRules). */
    private static boolean fmTransportLost(String msg) {
        return FileRules.transportLost(msg);
    }

    /** Places a batch delete / move must not touch: the root, any top-level folder, the user's whole storage, the system trees (see FileRules). */
    /** Whether the app can do this one with its own file access: it can read the source and write where the result goes. */
    private static boolean fmDirectOk(String op, String path, String destDir) {
        try {
            File f = new File(path);
            if (!f.exists() && !java.nio.file.Files.isSymbolicLink(f.toPath())) return false;
            File parent = f.getParentFile();
            if ("rm".equals(op)) return parent != null && parent.canWrite();
            if (!f.canRead()) return false;
            if ("mv".equals(op) && (parent == null || !parent.canWrite())) return false;
            File d = new File(destDir);
            while (d != null && !d.exists()) d = d.getParentFile();           // the folder may still have to be made: its nearest parent decides
            return d != null && d.isDirectory() && d.canWrite();
        } catch (Exception e) { return false; }
    }

    /**
     * One file operation with the app's own access: "" when it worked, a message when it failed, null when this one is not for Java
     * (the path is out of reach, or the shape of the operation needs the shell). A message starting with "?" means: try the shell.
     */
    private static String fmOpDirect(String op, String a, String b) {
        try {
            File fa = new File(a);
            if ("mkdir".equals(op)) {
                File d = fa;
                while (d != null && !d.exists()) d = d.getParentFile();
                if (d == null || !d.isDirectory() || !d.canWrite()) return null;
                if (fa.isDirectory()) return "";
                return fa.mkdirs() ? "" : "The folder could not be created";
            }
            if ("touch".equals(op)) {
                File p = fa.getParentFile();
                if (p == null || !p.isDirectory() || !p.canWrite()) return null;
                if (fa.exists()) return fa.setLastModified(System.currentTimeMillis()) ? "" : "?";
                return fa.createNewFile() ? "" : "The file could not be created";
            }
            if ("rm".equals(op)) {
                if (!fmDirectOk("rm", a, null)) return null;
                FileOps.Result r = FileOps.delete(java.util.Collections.singletonList(fa), null);
                return r.failed.isEmpty() ? "" : r.failed.get(0)[1];
            }
            if (("mv".equals(op) || "cp".equals(op)) && b != null && !b.isEmpty()) {
                File fb = new File(b);
                if ("mv".equals(op)) {                                          // a rename, or a move into a folder
                    if (fb.isDirectory()) { if (!fmDirectOk("mv", a, b)) return null; FileOps.Result r = FileOps.move(java.util.Collections.singletonList(fa), fb, FileOps.REPLACE, null); return r.failed.isEmpty() ? "" : r.failed.get(0)[1]; }
                    File pa = fa.getParentFile(), pb = fb.getParentFile();
                    if (pa == null || pb == null || !pa.canWrite() || !pb.isDirectory() || !pb.canWrite() || !fa.exists()) return null;
                    boolean same = false;
                    try { same = fb.exists() && java.nio.file.Files.isSameFile(fa.toPath(), fb.toPath()); } catch (Exception ignored) {}      // only the case of the name changes
                    if (fb.exists() && !same) return "A file or folder with that name is already there";
                    return fa.renameTo(fb) ? "" : "?";
                }
                if (fb.isDirectory()) { if (!fmDirectOk("cp", a, b)) return null; FileOps.Result r = FileOps.copy(java.util.Collections.singletonList(fa), fb, FileOps.REPLACE, null); return r.failed.isEmpty() ? "" : r.failed.get(0)[1]; }
            }
        } catch (Exception e) {
            return e.getMessage() == null ? "failed" : e.getMessage();
        }
        return null;
    }

    private static String fmBatchDoneText(String op, JSONObject res) {
        try {
            if (res.has("error")) return String.valueOf(res.optString("error"));
            String verb = "rm".equals(op) ? "Deleted" : "cp".equals(op) ? "Copied" : "Moved";
            int bad = res.optJSONArray("failed") == null ? 0 : res.optJSONArray("failed").length();
            return verb + " " + res.optInt("done") + " of " + res.optInt("total") + (bad > 0 ? " · " + bad + " failed" : "") + (res.optBoolean("cancelled") ? " · stopped" : "");
        } catch (Exception e) { return ""; }
    }

    private static boolean fmProtectedPath(String p) {
        return FileRules.isProtected(p);
    }

    /** Ends an install's hold on its files and deletes them when they are nobody's any more (see {@link InstallerStage#endInstall}). */
    private void endInstallStage(InstallerStage.Snapshot<XapkInfo.Extra> snap, boolean finished) {
        if (snap == null) return;
        try {
            File gone = installStage().endInstall(snap, finished);
            if (gone != null) deleteRecursively(gone);
        } catch (Exception ignored) {}
    }

    /** The split="..." value from an APK's binary manifest, or null for a base APK. Best-effort. */
    private String manifestSplitName(File apk) {
        String[] info = manifestSplitInfo(apk);
        return info == null ? null : info[0];
    }

    /**
     * What a split's manifest says about it: {split, configForSplit, isFeatureSplit}, or null when it can't be read. split is null for a
     * base APK; configForSplit is "" for the base's own config splits and names the feature module otherwise.
     */
    private String[] manifestSplitInfo(File apk) {
        try {
            // A config/feature split declares <manifest ... split="config.xxxhdpi">; a base APK has no such attribute (see SplitInfo).
            return SplitInfo.parse(ManifestDecoder.decodeApk(apk.getAbsolutePath(), null));
        } catch (Throwable ignored) {}
        return null;
    }

    /** The file name of a picked package: its display name for a content:// address, else the last part of the path; "" when there is none. */
    private String sourceNameOf(String ref) {
        try {
            if (ref == null || ref.isEmpty()) return "";
            if (ref.startsWith("content://")) return cdDisplayName(Uri.parse(ref));
            return new File(ref).getName();
        } catch (Exception e) {
            return "";
        }
    }

    /** Streams a picked .apk/.apks/.apkm into the installer cache and returns its package info + split list. */
    private JSONObject inspectInstallSourceImpl(String ref) throws Exception {
        // A folder of its own: an install still running from the package read before keeps its files (and its own OBB data, see runInstallSelected).
        InstallerStage<XapkInfo.Extra> stage = installStage();
        List<File> stale = new ArrayList<File>();
        File work = stage.beginRead(sourceNameOf(ref), ref, stale);
        final long gen = stage.generation();
        for (File f : stale) deleteRecursively(f);
        work.mkdirs();
        // A content:// stream is one-shot, so copy it to the cache once (capped like restore, so a crafted
        // archive can't fill storage) and work from concrete files afterwards.
        File raw = new File(work, "source.bin");
        long copied = 0;
        InputStream in0 = openRef(ref);
        try {
            FileOutputStream out = new FileOutputStream(raw);
            try {
                byte[] buf = new byte[65536];
                int r;
                while ((r = in0.read(buf)) > 0) {
                    copied += r;
                    if (copied > MAX_RESTORE_EXTRACT_BYTES) throw new IllegalStateException("file is far too large to be an app package");
                    out.write(buf, 0, r);
                }
            } finally { out.close(); }
        } finally { in0.close(); }

        PackageManager pm = getPackageManager();
        int sigFlags = Build.VERSION.SDK_INT >= 28 ? PackageManager.GET_SIGNING_CERTIFICATES : PackageManager.GET_SIGNATURES;

        List<File> splits = new ArrayList<File>();
        File base = null;
        String type;
        XapkInfo.Info xinfo = null;   // set for archives (.apks / .apkm / .xapk)

        // A lone APK is itself a ZIP, so tell them apart by whether the file parses as an installable APK.
        PackageInfo direct = pm.getPackageArchiveInfo(raw.getAbsolutePath(), 0);
        if (direct != null && direct.packageName != null) {
            type = "apk";
            File apk = new File(work, "base.apk");
            if (!raw.renameTo(apk)) apk = raw;
            base = apk;
            splits.add(apk);
        } else {
            // An .apks (bundletool) or .apkm (APKMirror) archive: a ZIP of split APKs. Extract every *.apk
            // entry through the same byte-capped loop restore uses (an unwanted entry is still drained,
            // never skipped, so the cap can't be bypassed by a huge entry under an unrecognized name).
            type = "apks";
            // XAPK: read the central directory (no extraction) for OBB / Android-data files and manifest.json.
            xinfo = XapkInfo.inspect(raw);
            java.util.zip.ZipInputStream zin = new java.util.zip.ZipInputStream(new java.io.BufferedInputStream(new java.io.FileInputStream(raw)));
            long extracted = 0;
            int idx = 0;
            boolean sawApkm = false;
            try {
                java.util.zip.ZipEntry e;
                while ((e = zin.getNextEntry()) != null) {
                    String n = e.getName();
                    String low = n.toLowerCase(java.util.Locale.US);
                    if (low.endsWith("info.json") || low.endsWith(".sai_v2.json") || low.endsWith("icon.png")) sawApkm = true;
                    File dest = null;
                    if (low.endsWith(".apk")) {
                        String flat = n.substring(n.lastIndexOf('/') + 1).replaceAll("[^A-Za-z0-9._-]", "_");
                        dest = new File(work, (idx++) + "__" + flat);
                    }
                    OutputStream out = dest != null ? new FileOutputStream(dest) : new OutputStream() {
                        public void write(int b) {}
                        public void write(byte[] b, int off, int len) {}
                    };
                    try {
                        byte[] buf = new byte[65536];
                        int r;
                        while ((r = zin.read(buf)) > 0) {
                            extracted += r;
                            if (extracted > MAX_RESTORE_EXTRACT_BYTES) throw new IllegalStateException("archive is far too large to be an app package");
                            out.write(buf, 0, r);
                        }
                    } finally { out.close(); }
                    if (dest != null) splits.add(dest);
                }
            } finally { zin.close(); }
            // The archive itself is kept (below) when it carries OBB / data files, so they can be copied
            // after the install; otherwise it is deleted once the package name is known.
            if (sawApkm) type = "apkm";
            if (xinfo.isXapk()) type = "xapk";
            if (splits.isEmpty()) throw new IllegalStateException("no APKs found inside this archive");
            // Base = the split whose manifest has no split="..." attribute.
            for (File f : splits) {
                if (manifestSplitName(f) == null) { base = f; break; }
            }
            if (base == null) base = splits.get(0);
        }

        PackageInfo archive = pm.getPackageArchiveInfo(base.getAbsolutePath(), sigFlags);
        boolean sigUnreadable = false;
        if (archive == null) {
            // Asking for the signature made Android refuse the file (edited after signing, or unsigned). Read it
            // without, so it can still be shown, and installed from Files, where Android gets the last word.
            archive = pm.getPackageArchiveInfo(base.getAbsolutePath(), 0);
            sigUnreadable = archive != null;
        }
        if (archive == null || archive.packageName == null) throw new IllegalStateException("could not read the base APK of this package");
        final String pkg = archive.packageName;

        // Data files that belong to THIS package (a wrong package folder in the archive is dropped). Keep the
        // archive only when there is something to copy from it later.
        List<XapkInfo.Extra> extras = xinfo != null ? xinfo.forPackage(pkg) : new ArrayList<XapkInfo.Extra>();
        File sourceZip = null;
        if (xinfo != null) {
            if (extras.isEmpty()) {
                raw.delete();
            } else {
                File keep = new File(work, "source.zip");
                sourceZip = raw.renameTo(keep) ? keep : raw;
            }
        }
        stage.loaded(gen, extras, sourceZip);

        JSONObject res = new JSONObject();
        res.put("ref", ref);
        res.put("type", type);
        res.put("pkg", pkg);
        JSONArray extraArr = new JSONArray();
        long extrasTotal = 0;
        for (XapkInfo.Extra x : extras) {
            JSONObject o = new JSONObject();
            o.put("name", x.dest.substring(x.dest.lastIndexOf('/') + 1));
            o.put("dest", x.dest);
            o.put("size", x.size);
            extraArr.put(o);
            if (x.size > 0) extrasTotal += x.size;
        }
        res.put("extras", extraArr);
        res.put("extrasTotal", extrasTotal);
        res.put("versionName", archive.versionName != null ? archive.versionName : "");
        res.put("versionCode", versionCodeOf(archive));
        if (archive.applicationInfo != null) {
            try {
                CharSequence lbl = pm.getApplicationLabel(archive.applicationInfo);
                if (lbl != null) res.put("label", lbl.toString());
            } catch (Exception ignored) {}
            if (Build.VERSION.SDK_INT >= 24) res.put("minSdk", archive.applicationInfo.minSdkVersion);
            res.put("targetSdk", archive.applicationInfo.targetSdkVersion);
        }

        List<File> ordered = new ArrayList<File>();
        ordered.add(base);
        for (File f : splits) if (f != base) ordered.add(f);
        long total = 0;
        JSONArray arr = new JSONArray();
        for (File f : ordered) {
            total += f.length();
            String[] info = (f == base) ? null : manifestSplitInfo(f);
            String split = info == null ? null : info[0];
            JSONObject s = new JSONObject();
            s.put("path", f.getAbsolutePath());
            s.put("name", f.getName());
            s.put("size", f.length());
            s.put("isBase", f == base);
            s.put("split", split != null ? split : "");
            s.put("configFor", info == null ? "" : info[1]);          // the feature module a config split belongs to ("" = the base)
            s.put("feature", info != null && "true".equals(info[2])); // a feature (dynamic) module of its own
            arr.put(s);
        }
        res.put("splits", arr);
        res.put("totalSize", total);

        // Signer of the archive + comparison to an already-installed copy, for the two signature gates. Both sides
        // are compared with their rotation history, so a rotated key still matches the key it replaced.
        java.util.Set<String> archiveSigners = signerDigests(archive, false);
        java.util.Set<String> archiveLineage = signerDigests(archive, true);
        res.put("signed", !archiveSigners.isEmpty());
        res.put("sigUnreadable", sigUnreadable);
        try {
            PackageInfo cur = pm.getPackageInfo(pkg, sigFlags);
            res.put("installed", true);
            res.put("installedVersionName", cur.versionName != null ? cur.versionName : "");
            res.put("installedVersionCode", versionCodeOf(cur));
            java.util.Set<String> curSigners = signerDigests(cur, true);
            java.util.Set<String> common = new HashSet<String>(curSigners);
            common.retainAll(archiveLineage);
            res.put("signerMatchesInstalled", !curSigners.isEmpty() && !archiveLineage.isEmpty() && !common.isEmpty());
        } catch (PackageManager.NameNotFoundException nf) {
            res.put("installed", false);
        }
        return res;
    }

    /**
     * Maps the installer's authorizer choice to a concrete backend mode. The page chooses the authorizer, so it is not trusted: in standard mode
     * (the Read-Only mode) no privileged authorizer is honoured, whatever the page sent and whatever is still connected, and the install goes through
     * the system installer ("none"), which asks the person itself (see {@link InstallGuards#authorizerFor}).
     */
    private String resolveAuthorizerMode(String authorizer) {
        final String exec = resolveExecMode();
        authorizer = InstallGuards.authorizerFor(authorizer, exec);
        if ("shizuku".equals(authorizer)) return "shizuku";
        if ("root".equals(authorizer)) return "root";
        if ("none".equals(authorizer)) return "none";
        if ("adb".equals(authorizer)) {
            if ("adb_tcp".equals(exec) || "adb_wireless".equals(exec)) return exec;
            if (isAdbTargetConnected(tcpTarget())) return "adb_tcp";
            if (isAdbTargetConnected(wirelessTarget())) return "adb_wireless";
            return "adb_tcp";
        }
        return exec;
    }

    /** ADB (TCP or Wireless Debugging), Shizuku or Root: a backend that runs `pm` with shell or root rights. */
    private static boolean isPrivilegedMode(String mode) {
        return InstallGuards.isPrivilegedMode(mode);
    }

    /** The app that provides Shizuku. With Shizuku as the backend, removing it would take the install's own rights away. */
    private static boolean isShizukuApp(String pkg) {
        return SHIZUKU_PKG.equals(pkg) || SHIZUKU_PLUS_PKG.equals(pkg);
    }

    /**
     * True when {@code pkg} is an installed, non-system app other than this one: the kind that can be removed to make room
     * for a differently signed copy. With Shizuku as the backend that excludes Shizuku's own app.
     */
    private boolean canUninstallFirst(String pkg, String mode) {
        if (pkg == null || !pkg.matches("[A-Za-z0-9._]+") || pkg.equals(getPackageName())) return false;
        if ("shizuku".equals(mode) && isShizukuApp(pkg)) return false;
        try {
            ApplicationInfo ai = getPackageManager().getApplicationInfo(pkg, 0);
            return (ai.flags & ApplicationInfo.FLAG_SYSTEM) == 0;
        } catch (PackageManager.NameNotFoundException nf) {
            return false;
        }
    }

    /**
     * Removes the installed copy of {@code pkg}, with all its data, so an APK signed with another key can take its place.
     * Throws with the reason when that can't be done. The caller asked for this explicitly.
     */
    private void uninstallInstalledCopy(String mode, String pkg) throws Exception {
        if (pkg == null || !pkg.matches("[A-Za-z0-9._]+")) throw new IllegalStateException("can't tell which app to uninstall first");
        if (pkg.equals(getPackageName())) throw new IllegalStateException("this app can't uninstall itself first");
        if ("shizuku".equals(mode) && isShizukuApp(pkg)) {
            throw new IllegalStateException("Shizuku is doing this install and can't remove its own app. Use ADB or Root for this one.");
        }
        if (!canUninstallFirst(pkg, mode)) {
            try {
                getPackageManager().getApplicationInfo(pkg, 0);
            } catch (PackageManager.NameNotFoundException nf) {
                return;                       // not installed (any more): nothing to remove
            }
            throw new IllegalStateException(pkg + " is a system app, so its signature can't be replaced this way");
        }
        String out = shellVia(mode, "pm uninstall " + pkg);
        if (out == null || !out.contains("Success")) {
            throw new IllegalStateException("could not uninstall the installed copy first: " + (out == null || out.trim().isEmpty() ? "no answer" : out.trim()));
        }
    }

    /**
     * Copies of the files, signed with this app's own key (APK Signature Scheme v2), written next to them in the installer
     * cache. Every split gets the same key, which is what Android needs. The originals are left as they were.
     */
    private List<File> signedCopies(List<File> files) throws Exception {
        long total = 0;
        for (File f : files) total += f.length();
        File dir = files.get(0).getParentFile();
        if (dir.getUsableSpace() < 2 * total + (16L << 20)) throw new IOException("not enough free space in the app cache to sign a copy");
        SigningKey k = SigningKey.getOrCreate();
        List<File> out = new ArrayList<File>();
        for (File f : files) {
            File prepared = new File(f.getParentFile(), "prep_" + f.getName());
            File signed = new File(f.getParentFile(), "signed_" + f.getName());
            try {
                ApkSigner.prepare(f, prepared);
                ApkSigner.signV2(prepared, signed, k.key, k.cert);
            } finally {
                prepared.delete();
            }
            out.add(signed);
        }
        return out;
    }

    /** Installs the given files (base first) with a caller-built flag set, via a specific backend. */
    private String installApksOptions(List<File> apks, String createFlags, String mode) throws Exception {
        // only the options the Installer page can build, as separate arguments; anything else stops the install
        List<String> flagArgs = ShellArgs.installFlags(createFlags);
        if (flagArgs == null) throw new IllegalArgumentException("Unsupported install options: not installed");
        createFlags = ShellArgs.join(flagArgs);
        if ("adb_tcp".equals(mode) || "adb_wireless".equals(mode)) {
            boolean tcp = "adb_tcp".equals(mode);
            String target = tcp ? tcpTarget() : wirelessTarget();
            if (!isAdbTargetConnected(target)) performConnect(tcp ? adbTcpHost : adbWirelessHost, tcp ? adbTcpPort : adbWirelessPort, null);
            List<String> args = new ArrayList<String>();
            args.add("-s");
            args.add(target);
            args.add(apks.size() == 1 ? "install" : "install-multiple");
            // adb forwards -r/-g/-d/-t natively and passes the pm-only flags (--user, --install-reason,
            // --package-source, --update-ownership, --bypass-low-target-sdk-block) through to install-create.
            args.addAll(flagArgs);
            for (File f : apks) args.add(f.getAbsolutePath());
            return runProcessWithTimeout(buildAdbProcess(args.toArray(new String[0])), 600000);
        }
        if ("shizuku".equals(mode)) {
            String created = shizukuStream("pm install-create " + createFlags, null);
            String id = BackupScripts.parseSessionId(created);
            if (id == null) return created;
            boolean committed = false;
            try {
                int index = 0;
                for (File f : apks) {
                    String name = (index++) + "_" + f.getName().replaceAll("[^A-Za-z0-9._-]", "_");
                    String written = shizukuStream("pm install-write -S " + f.length() + " " + id + " " + name + " -", f);
                    if (!written.contains("Success")) return written;
                }
                String result = shizukuStream("pm install-commit " + id, null);
                committed = true;
                return result;
            } finally {
                if (!committed) {
                    try { shizukuStream("pm install-abandon " + id, null); } catch (Exception ignored) {}
                }
            }
        }
        if ("root".equals(mode)) {
            StringBuilder cmd = new StringBuilder(apks.size() == 1 ? "pm install" : "pm install-multiple");
            cmd.append(' ').append(createFlags.trim());
            for (File f : apks) {
                f.setReadable(true, false);
                cmd.append(' ').append(BackupScripts.quote(f.getAbsolutePath()));
            }
            ProcessBuilder pb = new ProcessBuilder("su", "-c", cmd.toString());
            pb.redirectErrorStream(true);
            return runProcessWithTimeout(pb, 600000);
        }
        return "Error: this authorizer needs ADB, Shizuku or Root";
    }

    // ---------------------------------------------------------------------------------------------
    // Android settings (the Hidden Settings tab): `settings list|get|put|delete` on the global, secure and system tables, through the
    // active privileged backend. What may be touched and how a command is built is SettingsDb's job (it is tested off the device).
    // ---------------------------------------------------------------------------------------------

    /** One command through a privileged backend with a timeout of its own; the text is the (merged) output, or an "Error: ..." line. */
    private String runPrivilegedShell(String mode, String cmd, int timeoutMs) {
        try {
            if ("adb_tcp".equals(mode) || "adb_wireless".equals(mode)) {
                boolean tcp = "adb_tcp".equals(mode);
                if (!tcp && adbWirelessPort <= 0) return "Error: Wireless Debugging is not configured. Connect it in Working Modes.";
                String target = tcp ? tcpTarget() : wirelessTarget();
                String out = runProcessWithTimeout(buildAdbProcess("-s", target, "shell", cmd), timeoutMs);
                if (out != null && out.contains("device '") && out.contains("' not found")) {
                    // the link dropped (adbd restarted, say): reconnect once and ask again
                    runProcessWithTimeout(buildAdbProcess("connect", target), 5000);
                    out = runProcessWithTimeout(buildAdbProcess("-s", target, "shell", cmd), timeoutMs);
                }
                return out != null ? out : "";
            }
            if ("shizuku".equals(mode)) {
                try {
                    return shizukuPipe(cmd, null, timeoutMs);
                } catch (Exception e) {
                    return runShizukuShell(cmd);                 // the usual path, with its rish fallback
                }
            }
            if ("root".equals(mode)) {
                ProcessBuilder pb = new ProcessBuilder("su", "-c", cmd);
                pb.redirectErrorStream(true);
                return runProcessWithTimeout(pb, timeoutMs);
            }
            return "Error: this needs ADB, Wireless Debugging, Shizuku or Root";
        } catch (Throwable t) {
            return "Error: " + errMsg(t);
        }
    }

    private void settingsReply(String callback, JSONObject res) {
        notifyJs("window." + callback + " && window." + callback + "(" + JSONObject.quote(res.toString()) + ")");
    }

    /** The page gives up on a request after 60 s; one that waited this long behind slower ones is dropped instead of surprising the user later. */
    private static final long SETTINGS_JOB_MAX_WAIT_MS = 55000;

    private static boolean settingsJobStale(long queuedAt) {
        return android.os.SystemClock.elapsedRealtime() - queuedAt > SETTINGS_JOB_MAX_WAIT_MS;
    }

    /** Reads one table and reports it as window.onSettingsList(json): req, ns, ok, entries [[name, value], ...], error, advice, needsPrivilege, mode, ms. */
    private void settingsListJob(int req, String ns, long queuedAt) {
        JSONObject res = new JSONObject();
        long t0 = System.currentTimeMillis();
        try {
            res.put("req", req);
            res.put("ns", ns);
            if (settingsJobStale(queuedAt)) {
                res.put("ok", false);
                res.put("stale", true);
                res.put("error", "Skipped: it waited too long behind other requests");
                settingsReply("onSettingsList", res);
                return;
            }
            String mode = resolveExecMode();
            res.put("mode", mode);
            if ("standard".equals(mode)) {
                res.put("ok", false);
                res.put("needsPrivilege", true);
                res.put("error", "Needs ADB, Wireless Debugging, Shizuku or Root");
            } else {
                String out = runPrivilegedShell(mode, SettingsDb.listCommand(ns), 25000);
                SettingsDb.ListResult lr = SettingsDb.readList(out);
                String text = lr.text == null ? "" : lr.text.trim();
                if (!lr.complete) {
                    // the closing marker never came: the connection dropped or the command timed out, and what did arrive is only a part of the table
                    res.put("ok", false);
                    res.put("error", text.isEmpty() ? "Android returned no settings"
                            : text.contains("[Process timed out") ? "Android took too long to answer, so the list is incomplete"
                            : SettingsDb.looksLikeFailure(text) ? SettingsDb.summary(text)
                            : "The list was cut short on the way (the connection may have dropped)");
                    res.put("advice", SettingsDb.advice(text));
                } else if (lr.entries.isEmpty() && SettingsDb.looksLikeFailure(text)) {
                    res.put("ok", false);
                    res.put("error", SettingsDb.summary(text));
                    res.put("advice", SettingsDb.advice(text));
                } else {
                    JSONArray arr = new JSONArray();
                    for (String[] e : lr.entries) arr.put(new JSONArray().put(e[0]).put(e[1]));
                    res.put("ok", true);
                    res.put("entries", arr);
                }
            }
        } catch (Throwable t) {
            try {
                res.put("ok", false);
                res.put("error", errMsg(t));
            } catch (Exception ignored) {}
        }
        try { res.put("ms", System.currentTimeMillis() - t0); } catch (Exception ignored) {}
        settingsReply("onSettingsList", res);
    }

    /**
     * Reads, sets or deletes one setting and reports it as window.onSettingsOp(json): req, op, ns, key, ok, value (what the key
     * holds now, "null" when it is not there), requested, deleted, answer, error, advice, needsPrivilege, unknown (the phone
     * stopped answering, so what became of the change is not known), mode. Whether it worked is decided by the read-back (and,
     * where the word null cannot vouch for itself, by Android's own error text, exit status and a listing), not by silence.
     */
    private void settingsOpJob(int req, String op, String ns, String key, String value, long queuedAt) {
        JSONObject res = new JSONObject();
        try {
            res.put("req", req);
            res.put("op", op);
            res.put("ns", ns);
            res.put("key", key);
            if (value != null) res.put("requested", value);
            if (settingsJobStale(queuedAt)) {
                res.put("ok", false);
                res.put("stale", true);
                res.put("error", "Skipped: it waited too long behind other requests");
                settingsReply("onSettingsOp", res);
                return;
            }
            String mode = resolveExecMode();
            res.put("mode", mode);
            if ("standard".equals(mode)) {
                res.put("ok", false);
                res.put("needsPrivilege", true);
                res.put("error", "Needs ADB, Wireless Debugging, Shizuku or Root");
            } else {
                String out = runPrivilegedShell(mode, SettingsDb.writeScript(op, ns, key, value), 20000);
                SettingsDb.WriteResult w = SettingsDb.parseWrite(out, key);
                SettingsDb.Verdict verdict = SettingsDb.judge(op, value, w);
                res.put("ok", verdict.ok);
                if (verdict.unknown) res.put("unknown", true);
                if (w.value != null) res.put("value", w.value);
                if (w.deleted >= 0) res.put("deleted", w.deleted);
                String said = !w.answer.isEmpty() ? w.answer : w.readError;
                if (!said.isEmpty()) res.put("answer", said.length() > 600 ? said.substring(0, 600) + "…" : said);
                if (!verdict.ok) {
                    res.put("error", verdict.error);
                    res.put("advice", SettingsDb.advice(said));
                }
            }
        } catch (Throwable t) {
            try {
                res.put("ok", false);
                res.put("error", errMsg(t));
            } catch (Exception ignored) {}
        }
        settingsReply("onSettingsOp", res);
    }

    // ---------------------------------------------------------------------------------------------
    // Overlays tab: `cmd overlay list|enable|disable`, the Material You theme setting, and the colours the system uses now. What may
    // be touched and how a command is built is OverlayRules' job (tested off the device). They share the Hidden Settings tab's single
    // thread, so a theme change and a settings change reach the phone in the order they were made.
    // ---------------------------------------------------------------------------------------------

    private static JSONArray overlaysToJson(List<OverlayRules.Overlay> all) {
        JSONArray arr = new JSONArray();
        for (OverlayRules.Overlay o : all) arr.put(new JSONArray().put(o.id).put(o.target).put(o.state));
        return arr;
    }

    private static String clipAnswer(String text) {
        return text.length() > 600 ? text.substring(0, 600) + "…" : text;
    }

    /** Reads the overlays and reports them as window.onOverlayList(json): req, ok, list [[id, target, state], ...], error, advice, needsPrivilege, mode, ms. */
    private void overlayListJob(int req, long queuedAt) {
        JSONObject res = new JSONObject();
        long t0 = System.currentTimeMillis();
        try {
            res.put("req", req);
            if (settingsJobStale(queuedAt)) {
                res.put("ok", false);
                res.put("stale", true);
                res.put("error", "Skipped: it waited too long behind other requests");
                settingsReply("onOverlayList", res);
                return;
            }
            String mode = resolveExecMode();
            res.put("mode", mode);
            if ("standard".equals(mode)) {
                res.put("ok", false);
                res.put("needsPrivilege", true);
                res.put("error", "Needs ADB, Wireless Debugging, Shizuku or Root");
            } else {
                String out = runPrivilegedShell(mode, OverlayRules.listScript(), 25000);
                OverlayRules.ListResult lr = OverlayRules.readList(out);
                String text = lr.text == null ? "" : lr.text.trim();
                if (!lr.complete) {
                    res.put("ok", false);
                    res.put("error", text.isEmpty() ? "Android returned no overlays"
                            : text.contains("[Process timed out") ? "Android took too long to answer, so the list is incomplete"
                            : OverlayRules.looksLikeFailure(text) ? OverlayRules.summary(text)
                            : "The list was cut short on the way (the connection may have dropped)");
                    res.put("advice", OverlayRules.advice(text));
                } else if (lr.overlays.isEmpty() && OverlayRules.looksLikeFailure(text)) {
                    res.put("ok", false);
                    res.put("error", OverlayRules.summary(text));
                    res.put("advice", OverlayRules.advice(text));
                } else {
                    res.put("ok", true);
                    res.put("list", overlaysToJson(lr.overlays));
                }
            }
        } catch (Throwable t) {
            try {
                res.put("ok", false);
                res.put("error", errMsg(t));
            } catch (Exception ignored) {}
        }
        try { res.put("ms", System.currentTimeMillis() - t0); } catch (Exception ignored) {}
        settingsReply("onOverlayList", res);
    }

    /**
     * Switches one overlay on or off and reports it as window.onOverlayOp(json): req, op, id, ok, state (1 on, 0 off, -1 cannot be
     * switched, -2 not listed), list (every overlay as it is now), answer, error, advice, needsPrivilege, unknown, mode.
     * Whether it worked is decided by the list that follows the change, not by the command's silence.
     */
    private void overlayOpJob(int req, String op, String id, long queuedAt) {
        JSONObject res = new JSONObject();
        try {
            res.put("req", req);
            res.put("op", op);
            res.put("id", id);
            if (settingsJobStale(queuedAt)) {
                res.put("ok", false);
                res.put("stale", true);
                res.put("error", "Skipped: it waited too long behind other requests");
                settingsReply("onOverlayOp", res);
                return;
            }
            String mode = resolveExecMode();
            res.put("mode", mode);
            if ("standard".equals(mode)) {
                res.put("ok", false);
                res.put("needsPrivilege", true);
                res.put("error", "Needs ADB, Wireless Debugging, Shizuku or Root");
            } else {
                String out = runPrivilegedShell(mode, OverlayRules.changeScript(op, id), 30000);
                OverlayRules.ChangeResult cr = OverlayRules.parseChange(out);
                OverlayRules.Verdict v = OverlayRules.judge(op, id, cr);
                res.put("ok", v.ok);
                res.put("state", v.state);
                if (v.unknown) res.put("unknown", true);
                // an empty list after a change is not "this phone has no overlays": the page keeps the list it has and looks again
                if (cr.all != null && !cr.all.isEmpty()) res.put("list", overlaysToJson(cr.all));
                if (!cr.answer.isEmpty()) res.put("answer", clipAnswer(cr.answer));
                if (!v.ok) {
                    res.put("error", v.error);
                    res.put("advice", OverlayRules.advice(cr.answer + "\n" + cr.listError));
                }
            }
        } catch (Throwable t) {
            try {
                res.put("ok", false);
                res.put("error", errMsg(t));
            } catch (Exception ignored) {}
        }
        settingsReply("onOverlayOp", res);
    }

    /**
     * Writes this app's fabricated colour overlay (op "fabricate", the plan's entries) or switches off the overlays it wrote (op
     * "disable", their ids) with root, and reports it as window.onOverlayFab(json): req, op, ids (the overlay identifiers written or
     * switched off), ok, state (the first overlay as the list has it: 1 on, 0 off, -1 cannot be switched, -2 not listed), list, answer,
     * lookups (resource -> what Android printed for it), error, advice, needsPrivilege, unknown, mode.
     * The root user only (RootGate.uid0): cmd overlay fabricate turns away anyone but uid 0, so this is Root with su granted, or a
     * Shizuku server started as root (uid 0). The system user (uid 1000) and the ADB shell user (uid 2000) are refused and stay
     * locked. The gate is checked before any shell runs. Whether it worked is decided by the list and the lookups that follow the write
     * (OverlayRules.judgeFabricate), never by the commands' own text. {@code profile}: the build family the bridge checked the plan for
     * (MonetProfile's id), which also decides the entries looked up after the write.
     */
    private void overlayFabricateJob(int req, String op, String profile, List<OverlayRules.FabEntry> entries, List<String> ids, long queuedAt) {
        JSONObject res = new JSONObject();
        try {
            res.put("req", req);
            res.put("op", op);
            if (settingsJobStale(queuedAt)) {
                res.put("ok", false);
                res.put("stale", true);
                res.put("error", "Skipped: it waited too long behind other requests");
                settingsReply("onOverlayFab", res);
                return;
            }
            String mode = resolveExecMode();
            res.put("mode", mode);
            // Writing a fabricated colour overlay needs the root user (uid 0): Android's overlay service refuses `cmd overlay fabricate`
            // to anyone else, the ADB and system shell users included. That is Root with su, or a Shizuku server started as root (uid 0).
            // Shizuku as the system user (uid 1000) is privileged but still refused here, and is kept locked on the page. su is asked only
            // while Root is the mode (probeWorkingMode does the same), so no root-manager prompt pops up under Shizuku or ADB.
            boolean suGranted = "root".equals(mode) && isRootGranted();
            int fabSzUid = "shizuku".equals(mode) ? shizukuServerUid() : -1;
            boolean fabShizuku = "shizuku".equals(mode) && isShizukuAuthorized();
            if (!RootGate.uid0(mode, suGranted, fabShizuku, fabSzUid)) {
                res.put("ok", false);
                res.put("needsPrivilege", true);
                res.put("error", "Needs Super User");
            } else {
                int sdk = Build.VERSION.SDK_INT;
                boolean disable = "disable".equals(op);
                List<String> wrote = disable ? ids : OverlayRules.fabricateIds(sdk, entries);
                JSONArray idArr = new JSONArray();
                for (String id : wrote) idArr.put(id);
                res.put("ids", idArr);
                String script = disable ? OverlayRules.disableScript(ids) : OverlayRules.fabricateScript(sdk, profile, entries);
                String out = runPrivilegedShell(mode, script, 30000);
                // the script is long, not secret, but a release build logs sizes only (the rule is general); a debuggable build the whole exchange
                if (isDebuggableBuild()) Log.d(TAG, "overlayFabricate [" + op + "]: " + script + " -> " + (out != null ? out.trim() : ""));
                else Log.d(TAG, "overlayFabricate [" + op + "]: " + script.length() + " chars -> " + (out != null ? out.length() : 0) + " chars");
                OverlayRules.FabResult fr = OverlayRules.parseFabricate(out);
                OverlayRules.FabVerdict v = OverlayRules.judgeFabricate(op, wrote, profile, disable ? null : entries, fr);
                res.put("ok", v.ok);
                res.put("state", v.state);
                if (v.unknown) res.put("unknown", true);
                // an empty list after a change is not "this phone has no overlays": the page keeps the list it has and looks again
                if (fr.change.all != null && !fr.change.all.isEmpty()) res.put("list", overlaysToJson(fr.change.all));
                if (!fr.change.answer.isEmpty()) res.put("answer", clipAnswer(fr.change.answer));
                if (!fr.lookups.isEmpty()) {
                    JSONObject lk = new JSONObject();
                    for (Map.Entry<String, String> e : fr.lookups.entrySet()) lk.put(e.getKey(), clipAnswer(e.getValue()));
                    res.put("lookups", lk);
                }
                if (!v.ok) {
                    res.put("error", v.error);
                    res.put("advice", OverlayRules.advice(fr.change.answer + "\n" + fr.change.listError));
                }
            }
        } catch (Throwable t) {
            try {
                res.put("ok", false);
                res.put("error", errMsg(t));
            } catch (Exception ignored) {}
        }
        settingsReply("onOverlayFab", res);
    }

    private void saveFlagSnapshot(String snapshot) {
        if (snapshot == null || snapshot.isEmpty()) prefs.edit().remove("ovl_flag_snap").apply();
        else prefs.edit().putString("ovl_flag_snap", snapshot).apply();
    }

    /**
     * Writes the Material You theme setting (and Samsung's wallpaper-colours switch where the phone has one) and reports it as
     * window.onThemeOp(json): req, kind, ok, value (what the setting holds now, "null" when it is not there), before (what it held
     * when this change began; apply only), flags (the settings tables whose switch now holds what was wanted), warning (a switch
     * that would not change), flagsRestored, answer, error, advice, needsPrivilege, unknown, mode.
     * What a change does, step by step, is OverlayRules.runTheme's job (tested off the device).
     */
    private void themeJob(int req, String kind, String source, String hex, String style, String raw, long queuedAt) {
        JSONObject res = new JSONObject();
        try {
            res.put("req", req);
            res.put("kind", kind);
            if (settingsJobStale(queuedAt)) {
                res.put("ok", false);
                res.put("stale", true);
                res.put("error", "Skipped: it waited too long behind other requests");
                settingsReply("onThemeOp", res);
                return;
            }
            final String mode = resolveExecMode();
            res.put("mode", mode);
            if ("standard".equals(mode)) {
                res.put("ok", false);
                res.put("needsPrivilege", true);
                res.put("error", "Needs ADB, Wireless Debugging, Shizuku or Root");
            } else {
                OverlayRules.ThemeOutcome oc = OverlayRules.runTheme(new OverlayRules.ThemeEnv() {
                    @Override
                    public String run(String script, int timeoutMs) {
                        return runPrivilegedShell(mode, script, timeoutMs);
                    }

                    @Override
                    public String snapshot() {
                        return prefs.getString("ovl_flag_snap", "");
                    }

                    @Override
                    public void saveSnapshot(String snapshot) {
                        saveFlagSnapshot(snapshot);
                    }

                    @Override
                    public long now() {
                        return System.currentTimeMillis();
                    }
                }, kind, source, hex, style, raw);
                res.put("ok", oc.ok);
                if (oc.unknown) res.put("unknown", true);
                if (oc.value != null) res.put("value", oc.value);
                if (oc.before != null) res.put("before", oc.before);
                JSONArray flags = new JSONArray();
                for (String f : oc.flags) flags.put(f);
                res.put("flags", flags);
                if (oc.flagsRestored) res.put("flagsRestored", true);
                if (!oc.answer.isEmpty()) res.put("answer", clipAnswer(oc.answer));
                if (!oc.warning.isEmpty()) res.put("warning", oc.warning);
                if (!oc.ok) {
                    res.put("error", oc.error);
                    res.put("advice", oc.advice);
                }
            }
        } catch (Throwable t) {
            try {
                res.put("ok", false);
                res.put("error", errMsg(t));
            } catch (Exception ignored) {}
        }
        settingsReply("onThemeOp", res);
    }

    /** The five tonal palettes the system builds from its theme colour (Android 12+): 13 steps each, light to dark. */
    private String systemPaletteJson() {
        JSONObject o = new JSONObject();
        try {
            o.put("sdk", Build.VERSION.SDK_INT);
            if (Build.VERSION.SDK_INT < 31) {
                o.put("ok", false);
                o.put("error", "Material You colors need Android 12 or newer (this phone runs Android " + Build.VERSION.RELEASE + ").");
                return o.toString();
            }
            // for the root-only colours: the Android build family they are computed for ("profile", MonetProfile's id or "unknown", and
            // "profileReason": ok, notYet or unknown), the build itself (the page keeps it with the colours it wrote, so it can
            // tell when Android was updated after), the contrast SystemUI computes at and, on One UI only, "oneUi" (MonetProfile.oneUi: the
            // page shows its One UI note on the card; PR 13)
            MonetProfile.Result profile = monetProfile();
            o.put("profile", profile.profile);
            o.put("profileReason", profile.reason);
            String oneUi = monetOneUi();
            if (!oneUi.isEmpty()) o.put("oneUi", oneUi);
            o.put("build", Build.FINGERPRINT == null ? "" : Build.FINGERPRINT);
            o.put("contrast", systemContrast());
            int[] tones = {0, 10, 50, 100, 200, 300, 400, 500, 600, 700, 800, 900, 1000};
            String[] names = {"accent1", "accent2", "accent3", "neutral1", "neutral2"};
            JSONArray t = new JSONArray();
            for (int tone : tones) t.put(tone);
            o.put("tones", t);
            for (String n : names) {
                JSONArray a = new JSONArray();
                for (int tone : tones) a.put(colorHex(systemColor("system_" + n + "_" + tone)));
                o.put(n, a);
            }
            // "wallpaper": up to three RRGGBB, the primary, secondary and tertiary colours of the wallpaper set most recently (API 27+, no
            // permission; the seed the page's root-only styles fall back to when the theme setting names no colour). Lock or home is chosen
            // as SystemUI does (MonetProfile.lockWallpaperIsLatest: the higher WallpaperManager id); a lock wallpaper without colours of its
            // own falls back to the home one. These are WallpaperColors' main colours, ranked by chroma and population; SystemUI ranks the
            // whole colour map by hue (ColorScheme.getSeedColors), and that map is not public (getAllColors is @hide), so the colour can
            // differ from the one Android picks. Anything going wrong leaves it out.
            if (Build.VERSION.SDK_INT >= 27) {
                try {
                    android.app.WallpaperManager wm = android.app.WallpaperManager.getInstance(this);
                    android.app.WallpaperColors wc = null;
                    if (wm != null) {
                        if (MonetProfile.lockWallpaperIsLatest(wm.getWallpaperId(android.app.WallpaperManager.FLAG_LOCK), wm.getWallpaperId(android.app.WallpaperManager.FLAG_SYSTEM))) {
                            wc = wm.getWallpaperColors(android.app.WallpaperManager.FLAG_LOCK);
                        }
                        if (wc == null) wc = wm.getWallpaperColors(android.app.WallpaperManager.FLAG_SYSTEM);
                    }
                    if (wc != null) {
                        JSONArray w = new JSONArray();
                        Color[] picks = {wc.getPrimaryColor(), wc.getSecondaryColor(), wc.getTertiaryColor()};
                        for (Color c : picks) if (c != null) w.put(String.format("%06X", 0xFFFFFF & c.toArgb()));
                        o.put("wallpaper", w);
                    }
                } catch (Throwable ignored) {}
            }
            o.put("ok", true);
        } catch (Throwable t) {
            try {
                o.put("ok", false);
                o.put("error", "The system colors could not be read: " + errMsg(t));
            } catch (Exception ignored) {}
        }
        return o.toString();
    }

    /** Runs a short pm command through a specific backend (for post-install dexopt). */
    private String shellVia(String mode, String cmd) throws Exception {
        if ("adb_tcp".equals(mode) || "adb_wireless".equals(mode)) {
            boolean tcp = "adb_tcp".equals(mode);
            String target = tcp ? tcpTarget() : wirelessTarget();
            if (!isAdbTargetConnected(target)) performConnect(tcp ? adbTcpHost : adbWirelessHost, tcp ? adbTcpPort : adbWirelessPort, null);
            return runProcessWithTimeout(buildAdbProcess("-s", target, "shell", cmd), 600000);
        }
        if ("shizuku".equals(mode)) return shizukuStream(cmd, null);
        if ("root".equals(mode)) {
            ProcessBuilder pb = new ProcessBuilder("su", "-c", cmd);
            pb.redirectErrorStream(true);
            return runProcessWithTimeout(pb, 600000);
        }
        return "Error: needs ADB, Shizuku or Root";
    }

    /** Post-install OBB/data copy, dexopt and auto-delete of the source, then reports the outcome to the WebView. */
    private void finishInstall(final JSONObject res, final JSONObject opts, final String mode, final InstallerStage.Snapshot<XapkInfo.Extra> snap) {
        // The no-privilege install result arrives on the main thread; copying GB-sized OBB files there would ANR.
        if (android.os.Looper.myLooper() == android.os.Looper.getMainLooper()) {
            Runnable end = new Runnable() {
                @Override
                public void run() { finishInstallImpl(res, opts, mode, snap); }
            };
            try {
                executor.submit(end);
            } catch (java.util.concurrent.RejectedExecutionException e) {
                new Thread(end, "install-end").start();       // the window is gone (its executor stopped): the install's folder is still released
            }
            return;
        }
        finishInstallImpl(res, opts, mode, snap);
    }

    private void notifyInstallProgress(String msg) {
        notifyJs("window.onInstallProgress && window.onInstallProgress(" + JSONObject.quote(msg) + ")");
    }

    /** Extracts one archive entry to a temp file in the install's own folder of the installer cache. */
    private File extractExtraToTemp(File workDir, java.util.zip.ZipFile zf, java.util.zip.ZipEntry e) throws Exception {
        File tmp = new File(workDir, "extra.tmp");
        InputStream in = zf.getInputStream(e);
        try {
            FileOutputStream out = new FileOutputStream(tmp);
            try {
                byte[] buf = new byte[65536];
                int n;
                while ((n = in.read(buf)) > 0) out.write(buf, 0, n);
            } finally { out.close(); }
        } finally { in.close(); }
        return tmp;
    }

    /** Writes one data file to {@code dest} (an absolute path on shared storage). Returns null on success, else why not. */
    private String writeInstallExtra(String mode, File workDir, java.util.zip.ZipFile zf, java.util.zip.ZipEntry e, String dir, String dest) throws Exception {
        if ("shizuku".equals(mode)) {
            // Streams straight from the archive through Shizuku's shell: no temp copy of a multi-GB file.
            InputStream in = zf.getInputStream(e);
            try {
                String out = shizukuPipe("mkdir -p " + BackupScripts.quote(dir) + " && cat > " + BackupScripts.quote(dest) + " && echo COPY_OK", in);
                return out != null && out.contains("COPY_OK") ? null : (out == null || out.trim().isEmpty() ? "copy failed" : out.trim());
            } finally { in.close(); }
        }
        if ("adb_tcp".equals(mode) || "adb_wireless".equals(mode)) {
            File tmp = extractExtraToTemp(workDir, zf, e);
            try {
                boolean tcp = "adb_tcp".equals(mode);
                String target = tcp ? tcpTarget() : wirelessTarget();
                if (!isAdbTargetConnected(target)) performConnect(tcp ? adbTcpHost : adbWirelessHost, tcp ? adbTcpPort : adbWirelessPort, null);
                shellVia(mode, "mkdir -p " + BackupScripts.quote(dir));
                String out = runProcessWithTimeout(buildAdbProcess("-s", target, "push", tmp.getAbsolutePath(), dest), 3600000);
                return out != null && out.toLowerCase(java.util.Locale.US).contains("pushed") ? null
                        : (out == null || out.trim().isEmpty() ? "push failed" : out.trim());
            } finally { tmp.delete(); }
        }
        if ("root".equals(mode)) {
            File tmp = extractExtraToTemp(workDir, zf, e);
            try {
                tmp.setReadable(true, false);
                ProcessBuilder pb = new ProcessBuilder("su", "-c", "mkdir -p " + BackupScripts.quote(dir)
                        + " && cp " + BackupScripts.quote(tmp.getAbsolutePath()) + " " + BackupScripts.quote(dest) + " && echo COPY_OK");
                pb.redirectErrorStream(true);
                String out = runProcessWithTimeout(pb, 3600000);
                return out != null && out.contains("COPY_OK") ? null : (out == null || out.trim().isEmpty() ? "copy failed" : out.trim());
            } finally { tmp.delete(); }
        }
        // No privilege: only works where this app may write there itself (older Android, or open storage).
        File d = new File(dir);
        if (!d.isDirectory() && !d.mkdirs()) {
            return "Android doesn't let this app create that folder without ADB, Shizuku or Root. Copy it by hand to " + dest;
        }
        InputStream in = zf.getInputStream(e);
        try {
            FileOutputStream out = new FileOutputStream(new File(dest));
            try {
                byte[] buf = new byte[65536];
                int n;
                while ((n = in.read(buf)) > 0) out.write(buf, 0, n);
            } finally { out.close(); }
        } catch (java.io.IOException io) {
            return "can't write there without ADB, Shizuku or Root (" + io.getMessage() + ")";
        } finally { in.close(); }
        return null;
    }

    /** Copies the XAPK's OBB / Android-data files into place after a successful install: those of the package it installed (its snapshot). Returns a summary. */
    private String copyInstallExtras(String mode, InstallerStage.Snapshot<XapkInfo.Extra> snap) {
        final List<XapkInfo.Extra> extras = snap.extras;
        final File zip = snap.zip;
        if (extras == null || extras.isEmpty() || zip == null || !zip.exists()) return "";
        String root = fmCanonicalPath("/sdcard");
        StringBuilder problems = new StringBuilder();
        int done = 0;
        long bytes = 0;
        String lastDir = "";
        java.util.zip.ZipFile zf = null;
        try {
            zf = new java.util.zip.ZipFile(zip);
            for (int i = 0; i < extras.size(); i++) {
                XapkInfo.Extra x = extras.get(i);
                String shortName = x.dest.substring(x.dest.lastIndexOf('/') + 1);
                java.util.zip.ZipEntry e = zf.getEntry(x.entry);
                if (e == null) { problems.append(shortName).append(": missing from the archive\n"); continue; }
                notifyInstallProgress("Copying data file " + (i + 1) + " of " + extras.size() + ": " + shortName + " (" + XapkInfo.humanBytes(x.size) + ")…");
                String dest = root + "/" + x.dest;
                String dir = dest.substring(0, dest.lastIndexOf('/'));
                String err;
                try {
                    err = writeInstallExtra(mode, snap.dir, zf, e, dir, dest);
                } catch (Exception ex) {
                    err = ex.getMessage() != null ? ex.getMessage() : ex.getClass().getSimpleName();
                }
                if (err == null) { done++; if (x.size > 0) bytes += x.size; lastDir = x.dest.substring(0, x.dest.lastIndexOf('/')); }
                else problems.append(shortName).append(": ").append(err).append('\n');
            }
        } catch (Exception ex) {
            problems.append("Error: ").append(ex.getMessage()).append('\n');
        } finally {
            if (zf != null) try { zf.close(); } catch (Exception ignored) {}
        }
        String head = done + " of " + extras.size() + " data file" + (extras.size() == 1 ? "" : "s") + " copied"
                + (done > 0 ? " (" + XapkInfo.humanBytes(bytes) + ") to " + lastDir + "/" : "");
        return problems.length() == 0 ? head : head + "\n" + problems.toString().trim();
    }

    private void finishInstallImpl(JSONObject res, JSONObject opts, String mode, InstallerStage.Snapshot<XapkInfo.Extra> snap) {
        try {
            boolean success = res.optBoolean("ok", false);
            if (success && opts.optBoolean("copyExtras", false) && snap != null && !snap.extras.isEmpty()) {
                try {
                    res.put("extras", copyInstallExtras(mode, snap));
                } catch (Exception e) {
                    try { res.put("extras", "Error: " + e.getMessage()); } catch (Exception ignored) {}
                }
            }
            if (success && opts.optBoolean("dexopt", false) && !"none".equals(mode)) {
                String pkg = opts.optString("pkg");
                String cm = opts.optString("dexoptMode", "speed").replaceAll("[^a-z-]", "");
                if (!pkg.isEmpty() && !cm.isEmpty() && pkg.matches("[A-Za-z0-9._]+")) {
                    try {
                        String comp = "pm compile -m " + cm + (opts.optBoolean("dexForce", false) ? " -f " : " ") + pkg;
                        res.put("dexopt", shellVia(mode, comp).trim());
                    } catch (Exception e) {
                        try { res.put("dexopt", "Error: " + e.getMessage()); } catch (Exception ignored) {}
                    }
                }
            }
            if (success && opts.optBoolean("autoDelete", false)) {
                // The file this install was read from, as the Installer recorded it: not a path the page names (which could be any file,
                // the app's own data among them), and never the app's private data.
                String ref = snap == null || snap.sourceRef == null ? "" : snap.sourceRef;
                boolean deleted = false;
                try {
                    if (ref.startsWith("content://")) {
                        deleted = android.provider.DocumentsContract.deleteDocument(getContentResolver(), Uri.parse(ref));
                    } else if (!ref.isEmpty() && !isPrivateData(new File(ref))) {
                        deleted = new File(ref).delete();
                    }
                } catch (Exception ignored) {}
                try { res.put("sourceDeleted", deleted); } catch (Exception ignored) {}
            }
        } catch (Exception ignored) {}
        // Its own files only (a package read since keeps its folder), and only a successful install uses them up: after a failure or a
        // Cancel in the system installer they stay, so "turn on Allow downgrade and install again" does not need the package picked again.
        endInstallStage(snap, res.optBoolean("ok", false));
        notifyJs("window.onInstallResult && window.onInstallResult(" + JSONObject.quote(res.toString()) + ")");
    }

    /** Installs via the platform PackageInstaller with user confirmation - no ADB/Shizuku/Root. The
     *  privileged pm flags (grant-all, downgrade, all-users, bypass, update-ownership) are not available
     *  to an ordinary app here, so only install reason / package source are passed through. */
    private void installNoPrivilege(final List<File> apks, final JSONObject opts, final InstallerStage.Snapshot<XapkInfo.Extra> snap) {
        try {
            android.content.pm.PackageInstaller pi = getPackageManager().getPackageInstaller();
            android.content.pm.PackageInstaller.SessionParams params =
                    new android.content.pm.PackageInstaller.SessionParams(android.content.pm.PackageInstaller.SessionParams.MODE_FULL_INSTALL);
            try { if (opts.optInt("installReason", -1) >= 0) params.setInstallReason(opts.optInt("installReason")); } catch (Exception ignored) {}
            try { if (Build.VERSION.SDK_INT >= 33 && opts.optInt("packageSource", -1) >= 0) params.setPackageSource(opts.optInt("packageSource")); } catch (Exception ignored) {}
            final int sessionId = pi.createSession(params);
            android.content.pm.PackageInstaller.Session session = pi.openSession(sessionId);
            boolean staged = false;
            try {
                for (File f : apks) {
                    java.io.FileInputStream fin = new java.io.FileInputStream(f);
                    OutputStream sout = session.openWrite(f.getName().replaceAll("[^A-Za-z0-9._-]", "_"), 0, f.length());
                    try {
                        byte[] buf = new byte[65536];
                        int r;
                        while ((r = fin.read(buf)) > 0) sout.write(buf, 0, r);
                        session.fsync(sout);
                    } finally { fin.close(); sout.close(); }
                }
                staged = true;
            } finally {
                if (!staged) { try { session.abandon(); } catch (Exception ignored) {} }
            }

            final String action = getPackageName() + ".INSTALL_RESULT." + (installReceiverSeq++);
            android.content.BroadcastReceiver rcv = new android.content.BroadcastReceiver() {
                @Override
                public void onReceive(Context c, Intent i) {
                    int status = i.getIntExtra(android.content.pm.PackageInstaller.EXTRA_STATUS, -999);
                    if (status == android.content.pm.PackageInstaller.STATUS_PENDING_USER_ACTION) {
                        Intent confirm = (Intent) i.getParcelableExtra(Intent.EXTRA_INTENT);
                        if (confirm != null) {
                            confirm.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
                            try { c.startActivity(confirm); } catch (Exception ignored) {}
                        }
                        return; // not terminal - wait for the user to confirm or cancel
                    }
                    try { c.unregisterReceiver(this); } catch (Exception ignored) {}
                    JSONObject r = new JSONObject();
                    try {
                        boolean success = status == android.content.pm.PackageInstaller.STATUS_SUCCESS;
                        String msg = i.getStringExtra(android.content.pm.PackageInstaller.EXTRA_STATUS_MESSAGE);
                        r.put("ok", success);
                        r.put("method", "No privilege");
                        r.put("output", success ? "Success"
                                : ("Install " + (status == android.content.pm.PackageInstaller.STATUS_FAILURE_ABORTED ? "cancelled" : "failed")
                                   + (msg != null && !msg.isEmpty() ? ": " + msg : "")));
                    } catch (Exception ignored) {}
                    finishInstall(r, opts, "none", snap);
                }
            };
            android.content.IntentFilter filter = new android.content.IntentFilter(action);
            // On the application, not this window: a window re-created (theme change) or closed while the system's install question is open
            // would take the receiver with it, and the result (the release of the install's work folder, "delete after install") would be lost.
            Context appCtx = getApplicationContext();
            if (Build.VERSION.SDK_INT >= 33) appCtx.registerReceiver(rcv, filter, Context.RECEIVER_NOT_EXPORTED);
            else appCtx.registerReceiver(rcv, filter);
            int piFlags = android.app.PendingIntent.FLAG_UPDATE_CURRENT | (Build.VERSION.SDK_INT >= 31 ? android.app.PendingIntent.FLAG_MUTABLE : 0);
            android.app.PendingIntent sender = android.app.PendingIntent.getBroadcast(this, sessionId, new Intent(action).setPackage(getPackageName()), piFlags);
            session.commit(sender.getIntentSender());
            session.close();
        } catch (Exception e) {
            JSONObject r = new JSONObject();
            try {
                r.put("ok", false);
                r.put("method", "No privilege");
                r.put("output", "Error: " + (e.getMessage() != null ? e.getMessage() : e.getClass().getSimpleName()));
            } catch (Exception ignored) {}
            finishInstall(r, opts, "none", snap);
        }
    }

    /** The Installer tab's install action. Validates the selection, runs the signature gates, installs
     *  through the chosen authorizer, then dexopts/auto-deletes. Result: window.onInstallResult(json). */
    private void runInstallSelected(final String optsJson) {
        executor.submit(new Runnable() {
            @Override
            public void run() {
                JSONObject res = new JSONObject();
                // What was done to the phone along the way; it leads the report, also when a later step fails.
                StringBuilder notes = new StringBuilder();
                InstallerStage.Snapshot<XapkInfo.Extra> snap = null;      // the package this install works from, to its end
                try {
                    JSONObject opts = new JSONObject(optsJson);
                    JSONArray sel = opts.optJSONArray("splits");
                    if (sel == null || sel.length() == 0) throw new IllegalStateException("no APK selected to install");
                    // Only ever install files we extracted into our own installer cache - never an arbitrary
                    // path handed in from JS.
                    String workPath = installerWorkDir().getCanonicalPath();
                    List<File> files = new ArrayList<File>();
                    File base = null;
                    for (int i = 0; i < sel.length(); i++) {
                        JSONObject s = sel.optJSONObject(i);
                        if (s == null) continue;
                        File f = new File(s.optString("path"));
                        if (!f.getCanonicalPath().startsWith(workPath + File.separator) || !f.exists()) {
                            throw new IllegalStateException("install files are no longer available - pick the package again");
                        }
                        if (s.optBoolean("isBase")) base = f;
                        files.add(f);
                    }
                    if (files.isEmpty()) throw new IllegalStateException("no APK selected to install");
                    if (base != null) { files.remove(base); files.add(0, base); }
                    // The files must be those of the package loaded now; from here on reading another package neither deletes them nor
                    // swaps its data files (OBB) in for theirs.
                    File filesDir = files.get(0).getCanonicalFile().getParentFile();
                    for (File f : files) {
                        if (!f.getCanonicalFile().getParentFile().equals(filesDir)) throw new IllegalStateException("install files are no longer available - pick the package again");
                    }
                    snap = installStage().beginInstall(filesDir);
                    if (snap == null) throw new IllegalStateException("install files are no longer available - pick the package again");

                    // Signature gates, read from the base APK, before anything is installed.
                    PackageManager pm = getPackageManager();
                    int sigFlags = Build.VERSION.SDK_INT >= 28 ? PackageManager.GET_SIGNING_CERTIFICATES : PackageManager.GET_SIGNATURES;
                    File gateApk = base != null ? base : files.get(0);
                    PackageInfo archive = pm.getPackageArchiveInfo(gateApk.getAbsolutePath(), sigFlags);
                    java.util.Set<String> archiveSigners = archive != null ? signerDigests(archive, false) : new HashSet<String>();
                    if (opts.optBoolean("blockUnknown", true) && archiveSigners.isEmpty()) {
                        throw new IllegalStateException("this package is unsigned or its signature can't be read (blocked by \"block unknown signature\")");
                    }
                    if (opts.optBoolean("blockMismatch", true) && archive != null && archive.packageName != null) {
                        try {
                            PackageInfo cur = pm.getPackageInfo(archive.packageName, sigFlags);
                            java.util.Set<String> curSigners = signerDigests(cur, true);
                            java.util.Set<String> archiveLineage = archive != null ? signerDigests(archive, true) : new HashSet<String>();
                            if (!curSigners.isEmpty() && !archiveLineage.isEmpty()) {
                                java.util.Set<String> common = new HashSet<String>(curSigners);
                                common.retainAll(archiveLineage);
                                if (common.isEmpty()) {
                                    throw new IllegalStateException(archive.packageName + " is already installed with a different signing key (blocked by \"block signature mismatch\")");
                                }
                            }
                        } catch (PackageManager.NameNotFoundException ignored) {}
                    }

                    // From the file manager an install always runs through a privileged backend (ADB, Wireless
                    // Debugging, Shizuku or Root), never the system installer.
                    boolean viaFiles = opts.optBoolean("fromFiles", false);
                    String asked = opts.optString("authorizer", "");
                    String mode = resolveAuthorizerMode(asked);
                    if (viaFiles && !isPrivilegedMode(mode)) {
                        throw new IllegalStateException("installing from Files needs ADB, Wireless Debugging, Shizuku or Root - set one up in Working Modes and try again");
                    }
                    if ("none".equals(mode)) {
                        // A privileged authorizer the page asked for is not honoured in standard mode: the system installer asks instead.
                        if (!"none".equals(asked)) notifyInstallProgress("Read-Only mode: the system installer asks you, so the ADB, Shizuku and Root options are not used.");
                        installNoPrivilege(files, opts, snap); // result arrives via the PackageInstaller receiver
                        return;
                    }
                    String flags = opts.optString("createFlags", "-r");
                    // Only the options the Installer page can build; anything else stops the install, before the person is asked about it.
                    List<String> flagArgs = ShellArgs.installFlags(flags);
                    if (flagArgs == null) throw new IllegalArgumentException("Unsupported install options: not installed");
                    // The app's name, read without its signature so it is known even when that is broken.
                    PackageInfo named = pm.getPackageArchiveInfo(gateApk.getAbsolutePath(), 0);
                    String pkgName = named != null ? named.packageName : null;
                    res.put("pkg", pkgName == null ? "" : pkgName);
                    // A privileged install has no system installer in front of it, and the page chose the file, the authorizer and the options: the
                    // person is asked here, in a dialog the page cannot press, with what the app read from the file itself.
                    {
                        List<String> acts = new ArrayList<String>();
                        if (viaFiles && opts.optBoolean("uninstallFirst", false)) acts.add(InstallConfirm.REMOVES_FIRST);
                        notifyInstallProgress("Waiting for your OK to install...");
                        if (!confirmInMode(mode, asked, InstallConfirm.messageLocalFile(snap.sourceName, pkgName, named != null ? named.versionName : null,
                                installedVersionOrNull(pkgName), files.size(), mode, ShellArgs.join(flagArgs), acts))) {
                            throw new InstallCancelled();
                        }
                    }
                    List<File> preSigned = null;
                    if (viaFiles && opts.optBoolean("uninstallFirst", false)) {
                        // Whatever can fail without touching the phone is done before the installed copy (and its data) goes:
                        // an APK Android can't read a signature from will need the signed copy, so make it now.
                        if (archiveSigners.isEmpty()) {
                            notifyInstallProgress("Signing a copy with this app's key...");
                            preSigned = signedCopies(files);
                        }
                        notifyInstallProgress("Uninstalling the installed copy first...");
                        uninstallInstalledCopy(mode, pkgName);
                        notes.append("The installed copy was uninstalled first.\n");
                    }
                    String out = installApksOptions(files, flags, mode);
                    if (viaFiles && !InstallHints.success(out) && InstallHints.brokenSignature(out)) {
                        // Android won't take the signature as it is (edited after signing, or unsigned). Sign a copy
                        // with this app's own key and try once more; the original file is not touched.
                        notifyInstallProgress("Android couldn't verify the signature - signing a copy with this app's key...");
                        String again = installApksOptions(preSigned != null ? preSigned : signedCopies(files), flags, mode);
                        if (InstallHints.success(again)) {
                            notes.append("Android could not verify the APK's signature, so a copy was signed with this app's key and installed.\n");
                            out = again;
                        } else {
                            out = out.trim() + "\n\nAfter signing a copy with this app's key:\n" + (again == null ? "" : again.trim());
                        }
                    }
                    boolean ok = InstallHints.success(out);
                    String advice = ok ? "" : InstallHints.advice(out);
                    String text = notes + (out != null ? out.trim() : "") + (advice.isEmpty() ? "" : "\n\nNote: " + advice);
                    res.put("method", mode);
                    res.put("output", text);
                    if (!ok && viaFiles && !opts.optBoolean("uninstallFirst", false)
                            && InstallHints.updateIncompatible(out) && canUninstallFirst(pkgName, mode)) {
                        // The page may ask for the installed copy to be removed and this to run again, so the
                        // staged files stay until it decides.
                        res.put("ok", false);
                        res.put("retry", "uninstall");
                        endInstallStage(snap, false);
                        notifyJs("window.onInstallResult && window.onInstallResult(" + JSONObject.quote(res.toString()) + ")");
                        return;
                    }
                    res.put("ok", ok);
                    finishInstall(res, opts, mode, snap);
                } catch (Exception e) {
                    endInstallStage(snap, false);          // the files stay for another try (unless a package read since made them nobody's)
                    try {
                        res.put("ok", false);
                        res.put("method", "none");
                        res.put("output", notes + (e instanceof InstallCancelled ? e.getMessage() : "Error: " + (e.getMessage() != null ? e.getMessage() : e.getClass().getSimpleName())));
                    } catch (Exception ignored) {}
                    notifyJs("window.onInstallResult && window.onInstallResult(" + JSONObject.quote(res.toString()) + ")");
                }
            }
        });
    }

    /** The person answered No to the question before a privileged install (or did not answer): nothing was installed. */
    private static final class InstallCancelled extends IllegalStateException {
        InstallCancelled() { super("Install cancelled. Nothing was installed."); }
        InstallCancelled(String why) { super(why); }
    }

    /** The version name installed now, "" when the installed app has none, or null when the package is not installed (or is unknown). */
    private String installedVersionOrNull(String pkg) {
        if (pkg == null || pkg.isEmpty()) return null;
        try {
            PackageInfo cur = getPackageManager().getPackageInfo(pkg, 0);
            return cur.versionName == null ? "" : cur.versionName;
        } catch (PackageManager.NameNotFoundException notInstalled) {
            return null;
        }
    }

    // ---------------------------------------------------------------------------------------------
    // Archive browser: File manager -> View on an .apk / .zip / package file opens its contents as a folder
    // tree without extracting. ZipTool does the zip work; this part resolves the path, picks the route for
    // files only a privileged shell can reach, and reports long jobs to the page.
    // ---------------------------------------------------------------------------------------------

    private static final int ARCHIVE_PAGE = 400;
    private static final int ARCHIVE_TEXT_LIMIT = 262144;            // preview / edit limit for text
    private static final int ARCHIVE_IMAGE_LIMIT = 4 * 1024 * 1024;
    private static final int ARCHIVE_AXML_LIMIT = 8 * 1024 * 1024;
    private static final String ARCHIVE_STAGE_DIR = "/data/local/tmp";
    private static final String ARCHIVE_STAGE_PREFIX = "fm_archive_";
    private static final long ARCHIVE_STAGE_MAX = 2L << 30;          // largest entry copied out to install / open
    private static final String[] ARCHIVE_NO_EDIT = {"/system/", "/product/", "/vendor/", "/system_ext/", "/apex/", "/odm/", "/data/app/"};

    private static final Object archiveLock = new Object();
    private static boolean archiveBusy;        // an extract / edit / stage / compare / sign job is running (process-wide, so a re-created Activity can't start a second one)
    private static boolean stageSwept;         // leftover shell-staged copies from an earlier run were removed

    // ---- Task Manager: a lightweight native poll, separate from JobService (which is for long file jobs with their own notification).
    // Runs only while the tab is open (started/stopped by the page); each tick is one shell round trip for CPU/RAM/network/processes/GPU,
    // marker-delimited so a slow or truncated read of one piece never corrupts another, plus a synchronous (no shell) battery read.
    private static final Object tmLock = new Object();
    private ScheduledExecutorService tmExec;
    private ScheduledFuture<?> tmTask;
    private boolean tmClosed;           // set under tmLock by onDestroy: a late tmStart from the page must not bring the poll back
    private CpuStats.Reading tmLastCpu;
    private NetStats.Reading tmLastNet;
    private long tmLastSampleAt;
    // a tick that is still running makes the next one (a scheduled one or "Refresh now") a no-op instead of a second shell round trip queued behind it
    private final java.util.concurrent.atomic.AtomicBoolean tmTickBusy = new java.util.concurrent.atomic.AtomicBoolean(false);
    // the thread count reads every process's status file: it is taken at most once every TM_THREADS_EVERY_MS and the last count is shown in between
    private static final long TM_THREADS_EVERY_MS = 3000;
    private long tmThreadsAt;
    private long tmThreadsLast = -1;
    // what does not change while the app runs is read once: the GPU facts, each core's min / max clock, which thermal zone is the CPU's
    private volatile JSONObject tmGpuInfoCache;
    private volatile long[] tmCpuMinHz, tmCpuMaxHz;
    private volatile String tmThermalPath;              // "" when no zone was readable

    private static final class ArcSlot {
        final ZipTool.Archive archive;
        final String stagedPath;     // the shell-staged copy the archive was read from, or null when the real file is read directly
        final String stamp;          // size:mtime of the real file when it was staged (to notice it changing underneath an edit)

        ArcSlot(ZipTool.Archive archive, String stagedPath, String stamp) {
            this.archive = archive;
            this.stagedPath = stagedPath;
            this.stamp = stamp;
        }
    }

    private static final java.util.ArrayList<String> archiveEvictedStages = new java.util.ArrayList<String>();

    /** The last two archives used (the open one and the one it is compared with / nested inside), by canonical path. */
    private static final java.util.LinkedHashMap<String, ArcSlot> archiveSlots = new java.util.LinkedHashMap<String, ArcSlot>(4, 0.75f, true) {
        @Override
        protected boolean removeEldestEntry(java.util.Map.Entry<String, ArcSlot> eldest) {
            if (size() <= 2) return false;
            if (eldest.getValue().stagedPath != null) archiveEvictedStages.add(eldest.getValue().stagedPath);
            return true;
        }
    };

    private File archiveNestedDir() {
        return new File(getCacheDir(), "archive_nested");
    }

    private File archiveStageDirLocal() {
        return new File(getCacheDir(), "archive_stage");
    }

    private static void deleteContents(File dir) {
        File[] kids = dir.listFiles();
        if (kids == null) return;
        for (File k : kids) {
            if (k.isDirectory()) deleteContents(k);
            k.delete();
        }
    }

    private boolean archiveStaged(String canonicalPath) {
        synchronized (archiveLock) {
            ArcSlot s = archiveSlots.get(canonicalPath);
            return s != null && s.stagedPath != null;
        }
    }

    /** The longest a listing may take when the bridge thread itself is waiting for it (the page cannot cancel then, nothing else gets through). */
    private static final long ARCHIVE_LIST_LIMIT_MS = 20000;
    private static final String ARCHIVE_TOO_BIG = "This archive is too big to list here: extract it instead";

    /** The archive the page named: the file itself when this app can read it, else a copy staged through the shell. */
    private ZipTool.Archive archiveFor(String path, boolean fresh) throws Exception {
        return archiveFor(path, fresh, null, null);
    }

    /** As {@link #archiveFor(String, boolean)}; {@code password} is tried only for a fresh open of a format whose listing itself needs one
     *  (7z with encrypted names, rar -hp) — a zip's directory is never encrypted, so a zip never needs it here. */
    private ZipTool.Archive archiveFor(String path, boolean fresh, char[] password) throws Exception {
        return archiveFor(path, fresh, password, null);
    }

    /**
     * For a call that runs on the bridge thread and wants an archive that may have to be opened again (it was evicted, or changed on disk):
     * the page's Cancel cannot get through while this waits, so a listing that needs a long unpacking is given up after
     * {@link #ARCHIVE_LIST_LIMIT_MS} in words ("open it again": that goes through the background open, which can be cancelled).
     */
    private ZipTool.Archive archiveForUi(String path) throws Exception {
        final long end = System.nanoTime() + ARCHIVE_LIST_LIMIT_MS * 1000000L;
        final boolean[] late = {false};
        try {
            return archiveFor(path, false, null, new ArchiveIo.Progress() {
                @Override
                public boolean tick(long bytesDone) {
                    if (System.nanoTime() - end > 0) { late[0] = true; return false; }
                    return true;
                }
            });
        } catch (IOException e) {
            if (late[0]) throw new IOException(ARCHIVE_TOO_BIG);
            throw e;
        }
    }

    // Opening an archive can take long (a compressed tar is unpacked whole to list it), so the lock is never held while it runs. Each open takes a
    // ticket, and the newest ticket per archive is the only one allowed to publish into archiveSlots: an open that was cancelled, superseded by
    // another open of the same archive, or overtaken by Close, throws its result away (and its staged copy) instead of putting it over a newer one.
    // A ticket is taken when the open is requested (on the bridge thread, in the page's order) and handed to the worker: workers come from a cached
    // pool, so taking it when a worker starts would let a cancelled older open that starts late supersede the open that replaced it.
    private static final ArchiveTickets archiveTickets = new ArchiveTickets();

    /** A background open of an archive whose listing needs a full unpacking; {@code cancel} is the page's Cancel. */
    private static final class ArchiveOpenJob {
        final String token, path;
        final MainActivity owner;       // the window whose page is waiting for it (released when the job ends or that window is destroyed)
        final long ticket;              // taken when the open was requested, not when its worker starts
        volatile boolean cancel;
        ArchiveOpenJob(String token, String path, MainActivity owner, long ticket) { this.token = token; this.path = path; this.owner = owner; this.ticket = ticket; }
    }

    private volatile boolean activityDestroyed;     // set by onDestroy: a background job must not call into this window's page any more

    /** onDestroy: the open of an archive that this window started is not wanted: it stops at its next ask, its ticket is dropped (so it publishes nothing and removes its staged copy). */
    private void cancelArchiveOpenOnDestroy() {
        synchronized (archiveLock) {
            ArchiveOpenJob job = archiveOpening;
            if (job != null && job.owner == this) {
                job.cancel = true;
                archiveTickets.remove(job.path);
                archiveOpening = null;
            }
        }
    }

    /** True when listing this archive means unpacking all of it (a compressed tar), so it is opened in the background. A file this app cannot read is judged by its name. */
    private boolean archiveOpenIsSlow(String canonicalPath) {
        File f = new File(canonicalPath);
        try {
            if (f.isFile() && f.canRead()) return ArchiveIo.slowToList(ArchiveIo.detect(f));
        } catch (RuntimeException ignored) {}
        return ArchiveIo.slowToListByName(f.getName());
    }

    private static ArchiveOpenJob archiveOpening;      // the background open that is running (guarded by archiveLock)
    private static long archiveOpenJobs;               // for the tokens

    /**
     * As {@link #archiveFor(String, boolean, char[])}. {@code cb} (may be null) is asked while the listing is unpacked and answers false to stop it
     * ({@code IOException("Cancelled")}); it is asked once more just before the result is published.
     */
    private ZipTool.Archive archiveFor(String path, boolean fresh, char[] password, ArchiveIo.Progress cb) throws Exception {
        return archiveFor(path, fresh, password, cb, 0);
    }

    /** As above; {@code requested} (0: none) is the ticket the caller took when the open was asked for, so an open that a newer request or Close has overtaken ends as Cancelled before it starts. */
    private ZipTool.Archive archiveFor(String path, boolean fresh, char[] password, ArchiveIo.Progress cb, long requested) throws Exception {
        String p = fmCanonicalPath(path);
        if (fmPrivate(p)) throw new IOException(PRIVATE_WHY);
        long ticket;
        synchronized (archiveLock) {
            ArcSlot hit = fresh ? null : archiveSlots.get(p);
            if (hit != null && !hit.archive.isStale()) return hit.archive;
            if (requested > 0) {
                ticket = requested;
                if (!archiveTickets.isNewest(p, ticket)) throw new IOException("Cancelled");      // overtaken before it started: it must not touch the newer open's ticket
            } else {
                ticket = archiveTickets.issue(p);
            }
        }
        String stagedPath = null, stamp = null;
        boolean published = false;
        try {
            File f = new File(p);
            File use = f;
            if (!(f.isFile() && f.canRead())) {
                String[] st = stageArchive(p);
                stagedPath = st[0];
                stamp = st[1];
                use = new File(stagedPath);
            }
            ZipTool.Archive a = openAnyArchive(use, password, cb);
            java.util.ArrayList<String> gone = new java.util.ArrayList<String>();
            synchronized (archiveLock) {
                boolean newest = archiveTickets.isNewest(p, ticket);
                if (!newest || (cb != null && !cb.tick(0))) {
                    // a newer open of this archive (or Close) came first. A plain read is happy with what the newer one published.
                    ArcSlot now = fresh ? null : archiveSlots.get(p);
                    if (now != null && !now.archive.isStale() && !newest) return now.archive;
                    throw new IOException("Cancelled");
                }
                ArcSlot old = archiveSlots.get(p);
                archiveSlots.put(p, new ArcSlot(a, stagedPath, stamp));
                published = true;
                gone.addAll(archiveEvictedStages);
                archiveEvictedStages.clear();
                if (old != null && old.stagedPath != null && !old.stagedPath.equals(stagedPath)) gone.add(old.stagedPath);
            }
            if (!gone.isEmpty()) deleteStagedFiles(gone);
            return a;
        } finally {
            synchronized (archiveLock) {
                archiveTickets.finish(p, ticket);
            }
            if (!published && stagedPath != null) deleteStagedFiles(java.util.Collections.singletonList(stagedPath));
        }
    }

    /** Opens any archive format this app reads, decided by the file's first bytes (a tar of APKs is a tar, not its last APK); see {@link ZipTool#openAny}. */
    private ZipTool.Archive openAnyArchive(File use, char[] password, ArchiveIo.Progress cb) throws IOException {
        return ZipTool.openAny(use, password, cb);
    }

    /** Forgets an archive that changed on disk, and removes the shell-staged copy it was read from. */
    private void dropSlot(String canonicalPath) {
        String staged = null;
        synchronized (archiveLock) {
            archiveTickets.remove(canonicalPath);
            ArcSlot slot = archiveSlots.remove(canonicalPath);
            if (slot != null) staged = slot.stagedPath;
        }
        if (staged != null) deleteStagedFiles(java.util.Collections.singletonList(staged));
    }

    /** A new name for each staging, so removing an old copy can never take a newer one with it. */
    private static String newStagePath(String p) {
        return ARCHIVE_STAGE_DIR + "/" + ARCHIVE_STAGE_PREFIX + Long.toHexString(System.nanoTime()) + "_" + Integer.toHexString(p.hashCode()) + ".zip";
    }

    /** "size:mtime" of a file as the shell sees it, or null when it can't be read. */
    private String statStamp(String mode, String p) {
        try {
            String out = shellVia(mode, "stat -c %s:%Y " + BackupScripts.quote(p) + " 2>&1");
            for (String line : out.split("\n")) if (line.trim().matches("[0-9]+:[0-9]+")) return line.trim();
        } catch (Exception ignored) {}
        return null;
    }

    /** Throws when a staged archive's real file changed after it was staged, so an edit can't overwrite those changes. */
    private void requireUnchanged(String p) throws Exception {
        ArcSlot slot;
        synchronized (archiveLock) {
            slot = archiveSlots.get(p);
        }
        if (slot == null || slot.stagedPath == null || slot.stamp == null) return;
        String now = statStamp(resolveExecMode(), p);
        if (now != null && !now.equals(slot.stamp)) {
            throw new IOException("This file changed after it was opened. Close it and open it again, then redo the edit.");
        }
    }

    private String[] stageArchive(String p) throws Exception {
        String mode = resolveExecMode();
        if ("standard".equals(mode)) {
            needFileAccess("To open this file", p);
            throw new IOException("Can't read this file. For storage, grant All-files access; for system folders, set up ADB, Shizuku or Root.");
        }
        String sz = shellVia(mode, "stat -c %s " + BackupScripts.quote(p) + " 2>&1");
        long size = -1;
        try { size = Long.parseLong(sz.trim()); } catch (Exception ignored) {}
        if (size > (3L << 30)) {
            throw new IOException("This file is " + XapkInfo.humanBytes(size) + ", too large to open through the shell. Copy it to storage first.");
        }
        String stage = newStagePath(p);
        String sweep = "";
        synchronized (archiveLock) {
            if (!stageSwept) {          // the first staging of this run: copies a killed earlier run left behind go first
                stageSwept = true;
                sweep = "rm -f " + ARCHIVE_STAGE_DIR + "/" + ARCHIVE_STAGE_PREFIX + "*.zip " + ARCHIVE_STAGE_DIR + "/fm_archive.zip; ";     // the second is v5.7's single fixed name
            }
        }
        String out = shellVia(mode, sweep + "cp " + BackupScripts.quote(p) + " " + stage + " && chmod 644 " + stage + " && stat -c %s:%Y " + BackupScripts.quote(p) + " && echo OK");
        if (!FileRules.okLine(out, "OK")) {
            deleteStagedFiles(java.util.Collections.singletonList(stage));
            throw new IOException(out == null || out.trim().isEmpty() ? "copy failed" : out.trim());
        }
        String stamp = null;
        for (String line : out.split("\n")) if (line.trim().matches("[0-9]+:[0-9]+")) stamp = line.trim();
        File f = new File(stage);
        if (!f.canRead()) {
            deleteStagedFiles(java.util.Collections.singletonList(stage));
            throw new IOException("The shell copied the file, but this app can't read " + stage);
        }
        return new String[]{stage, stamp};
    }

    /** Null when the archive can be edited and written back, else why not. */
    private String archiveEditBlock(String p) {
        String canon = p;
        try {
            canon = new File(p).getCanonicalPath();           // resolves ".." and symlinks, so a path can't sidestep the list below
        } catch (IOException ignored) {}
        for (String s : ARCHIVE_NO_EDIT) {
            if (p.startsWith(s) || canon.startsWith(s)) return "Installed and system packages can't be edited in place. Copy it to storage first.";
        }
        File f = new File(p);
        File dir = f.getParentFile();
        if (f.canWrite() && dir != null && dir.canWrite()) return null;
        if ("standard".equals(resolveExecMode())) { needFileAccess("To change this file", p); return "Editing needs All-files access for storage, or ADB / Shizuku / Root for other folders."; }
        return null;
    }

    private static String archiveFail(Throwable t) {
        if (t instanceof ZipTool.NeedPassword) {
            ZipTool.NeedPassword np = (ZipTool.NeedPassword) t;
            try {
                return new JSONObject().put("ok", false).put("error", np.getMessage()).put("needPassword", true).put("wrong", np.wrong).toString();
            } catch (Exception e) {
                return "{\"ok\":false,\"needPassword\":true}";
            }
        }
        return archiveFail(errMsg(t));
    }

    /** Puts ok:false, error and (for a NeedPassword) needPassword/wrong into a result JSON built by an async job. */
    private static void putArchiveError(JSONObject res, Throwable t) {
        try {
            res.put("ok", false);
            if (t instanceof ZipTool.NeedPassword) {
                ZipTool.NeedPassword np = (ZipTool.NeedPassword) t;
                res.put("error", np.getMessage());
                res.put("needPassword", true);
                res.put("wrong", np.wrong);
            } else {
                res.put("error", errMsg(t));
            }
        } catch (Exception ignored) {}
    }

    private static String archiveFail(String message) {
        try {
            return new JSONObject().put("ok", false).put("error", message).toString();
        } catch (Exception e) {
            return "{\"ok\":false}";
        }
    }

    /** Copies a file this app can read to dest through the best route: its own access, else the active privileged mode. */
    private String writeFileTo(File src, String dest) {
        try {
            File d = new File(dest);
            File dir = d.getParentFile();
            if (dir != null && (dir.isDirectory() || dir.mkdirs()) && dir.canWrite()) {
                File tmp = new File(dir, "." + d.getName() + ".copy-tmp");
                try {
                    copyFile(src, tmp);
                } catch (IOException ioe) {
                    tmp.delete();                       // no half-written hidden file left behind
                    throw ioe;
                }
                if (!tmp.renameTo(d)) {
                    tmp.delete();
                    return "Couldn't replace " + dest;
                }
                return null;
            }
        } catch (IOException ioe) {
            String why = ioe.getMessage() == null ? "" : ioe.getMessage();
            if (why.contains("ENOSPC") || why.toLowerCase(java.util.Locale.US).contains("no space left")) {
                return "There is not enough free space to write " + dest;       // not a permission problem: say so
            }
            // otherwise fall through to the privileged route
        }
        String mode = resolveExecMode();
        if ("standard".equals(mode)) {
            needFileAccess("To save a file there", dest);
            return "This app can't write there. Grant All-files access, or set up ADB, Shizuku or Root.";
        }
        try {
            return writeFileViaMode(mode, src, dest);
        } catch (Exception e) {
            return errMsg(e);
        }
    }

    private static void copyFile(File src, File dst) throws IOException {
        InputStream in = new java.io.FileInputStream(src);
        try {
            OutputStream out = new FileOutputStream(dst);
            try {
                byte[] buf = new byte[65536];
                int n;
                while ((n = in.read(buf)) > 0) out.write(buf, 0, n);
            } finally { out.close(); }
        } finally { in.close(); }
    }

    /** Writes src to dest through ADB / Shizuku / Root, via a temp name so an interrupted copy never corrupts dest. */
    private String writeFileViaMode(String mode, File src, String dest) throws Exception {
        String dir = dest.substring(0, dest.lastIndexOf('/'));
        String tmpDest = dest + ".copy-tmp";
        String qd = BackupScripts.quote(dest), qt = BackupScripts.quote(tmpDest);
        if ("shizuku".equals(mode)) {
            InputStream in = new java.io.FileInputStream(src);
            try {
                String out = shizukuPipe("{ mkdir -p " + BackupScripts.quote(dir) + " && cat > " + qt + " && mv -f " + qt + " " + qd + " && echo COPY_OK; } || rm -f " + qt, in);
                return out != null && out.contains("COPY_OK") ? null : (out == null || out.trim().isEmpty() ? "copy failed" : out.trim());
            } finally { in.close(); }
        }
        if ("adb_tcp".equals(mode) || "adb_wireless".equals(mode)) {
            boolean tcp = "adb_tcp".equals(mode);
            String target = tcp ? tcpTarget() : wirelessTarget();
            if (!isAdbTargetConnected(target)) performConnect(tcp ? adbTcpHost : adbWirelessHost, tcp ? adbTcpPort : adbWirelessPort, null);
            shellVia(mode, "mkdir -p " + BackupScripts.quote(dir));
            String out = runProcessWithTimeout(buildAdbProcess("-s", target, "push", src.getAbsolutePath(), tmpDest), 3600000);
            if (out == null || !out.toLowerCase(java.util.Locale.US).contains("pushed")) {
                try { shellVia(mode, "rm -f " + qt); } catch (Exception ignored) {}
                return out == null || out.trim().isEmpty() ? "push failed" : out.trim();
            }
            String mv = shellVia(mode, "mv -f " + qt + " " + qd + " && echo COPY_OK || rm -f " + qt);
            return mv != null && mv.contains("COPY_OK") ? null : (mv == null || mv.trim().isEmpty() ? "move failed" : mv.trim());
        }
        if ("root".equals(mode)) {
            src.setReadable(true, false);
            ProcessBuilder pb = new ProcessBuilder("su", "-c", "{ mkdir -p " + BackupScripts.quote(dir) + " && cp " + BackupScripts.quote(src.getAbsolutePath())
                    + " " + qt + " && mv -f " + qt + " " + qd + " && echo COPY_OK; } || rm -f " + qt);
            pb.redirectErrorStream(true);
            String out = runProcessWithTimeout(pb, 3600000);
            return out != null && out.contains("COPY_OK") ? null : (out == null || out.trim().isEmpty() ? "copy failed" : out.trim());
        }
        return "needs ADB, Shizuku or Root";
    }

    private static JSONObject signingKeyJson(SigningKey k) throws Exception {
        JSONObject o = new JSONObject().put("ok", true).put("exists", k != null);
        if (k != null) {
            o.put("sha256", k.sha256()).put("subject", k.subject()).put("created", k.created).put("hardware", k.hardware).put("bits", k.bits);
        }
        return o;
    }

    /** Where "save a signed copy" goes: next to the file, or Downloads when that folder is not one we may write to. */
    private static String signedCopyPath(String p) {
        File f = new File(p);
        String name = FileRules.signedName(f.getName());       // app.apk -> app-signed.apk; never the file it was made from
        String dir = f.getParent();
        boolean blocked = dir == null;
        for (String s : ARCHIVE_NO_EDIT) if (p.startsWith(s)) blocked = true;
        if (blocked) dir = android.os.Environment.getExternalStoragePublicDirectory(android.os.Environment.DIRECTORY_DOWNLOADS).getAbsolutePath();
        return dir + "/" + name;
    }

    private static final long SIGN_CHECK_MAX = 1536L << 20;       // larger APKs skip the (slow) signature read-back

    /** Refuses to extract a file onto the archive it is being read from (a staged archive's real path included). */
    private void requireNotArchive(String archivePath, File target) throws IOException {
        if (target.getCanonicalPath().equals(new File(fmCanonicalPath(archivePath)).getCanonicalPath())) {
            throw new IOException("That would overwrite the archive itself. Pick another folder.");
        }
    }

    private void notifyArchiveProgress(String msg) {
        if (activityDestroyed) return;
        notifyJs("window.onArchiveProgress && window.onArchiveProgress(" + JSONObject.quote(msg) + ")");
    }

    private static JSONArray diffJson(List<ZipTool.DiffItem> items) throws Exception {
        JSONArray arr = new JSONArray();
        for (ZipTool.DiffItem i : items) arr.put(new JSONObject().put("p", i.name).put("a", i.sizeA).put("b", i.sizeB));
        return arr;
    }

    /** Removes specific shell-staged archive copies (they live in /data/local/tmp, which this app can't delete from). */
    private void deleteStagedFiles(final java.util.List<String> paths) {
        final StringBuilder cmd = new StringBuilder();
        for (String sp : paths) {
            if (sp != null && sp.startsWith(ARCHIVE_STAGE_DIR + "/" + ARCHIVE_STAGE_PREFIX) && sp.matches("[A-Za-z0-9_./]+")) {
                cmd.append(cmd.length() == 0 ? "rm -f " : " ").append(sp);
            }
        }
        if (cmd.length() == 0) return;
        executor.submit(new Runnable() {
            @Override
            public void run() {
                try {
                    shellVia(resolveExecMode(), cmd.toString());
                } catch (Throwable ignored) {}
            }
        });
    }

    private static JSONObject archiveEntryJson(ZipTool.Entry e) throws Exception {
        return new JSONObject().put("n", e.baseName()).put("p", e.name).put("d", e.dir).put("s", e.size).put("c", e.csize)
                .put("t", e.mtime()).put("m", e.method).put("e", e.encrypted());
    }

    private static JSONObject archiveChildJson(ZipTool.Child c) throws Exception {
        JSONObject o = new JSONObject().put("n", c.name).put("p", c.path).put("d", c.dir).put("s", c.size).put("c", c.csize)
                .put("t", c.mtime).put("f", c.count);
        if (c.entry != null) o.put("m", c.entry.method).put("e", c.entry.encrypted());
        else o.put("m", -1).put("e", false);
        return o;
    }

    // ---------------------------------------------------------------------------------------------
    // Installer: find package files (.apk / .apks / .apkm / .xapk) on storage
    // ---------------------------------------------------------------------------------------------

    /** Whether this app can read shared storage itself (All-files access on Android 11+, else the storage permission). */
    private boolean hasStorageAccess() {
        try {
            if (Build.VERSION.SDK_INT >= 30) return android.os.Environment.isExternalStorageManager();
            return checkSelfPermission(android.Manifest.permission.READ_EXTERNAL_STORAGE) == PackageManager.PERMISSION_GRANTED;
        } catch (Exception e) { return false; }
    }

    /**
     * Tells the page an action on {@code path} has just failed for want of All-files access, so that it asks for it. Nothing happens
     * when the app has the access (the failure was something else), nor when the path is not on shared storage (system folders, other
     * apps' data: the access would not help there), and the page shows its prompt once, not once per failure.
     */
    private void needFileAccess(String reason, String path) {
        try {
            if (hasStorageAccess()) return;
            if (path == null || ApkTrash.volumeRoot(fmCanonicalPath(path)) == null) return;
            notifyJs("window.onFileAccessNeeded && window.onFileAccessNeeded(" + JSONObject.quote(reason == null ? "" : reason) + ")");
        } catch (Exception ignored) {}
    }

    // ---------------------------------------------------------------------------------------------
    // Deleting a package file the search found, with an Undo (the rules are in ApkTrash)
    // ---------------------------------------------------------------------------------------------

    /**
     * Asks the working mode whether {@code test} (-e, -f) holds for a path: it answers YES or NO. Any other reply (the link is down, su is
     * missing: the shell helpers report those as text, they do not throw) is an error and not a "no", so a dead shell is never read as
     * "that file is not there".
     */
    private boolean shellTest(String mode, String test, String path) throws Exception {
        return ApkTrash.yesNo(shellVia(mode, "[ " + test + " " + BackupScripts.quote(path) + " ] && echo YES || echo NO"));
    }

    // A purge at start-up can take seconds (the working mode may still be connecting): it must not touch what the person deletes meanwhile
    private final Object apkTrashLock = new Object();
    private volatile boolean apkTrashedThisRun = false;

    private boolean pathExists(String mode, String path) throws Exception {
        if (new File(path).exists()) return true;
        if ("standard".equals(mode)) return false;
        return shellTest(mode, "-e", path);
    }

    /** True for a regular file (not a folder that happens to be called "x.apk"). */
    private boolean isRegularFile(String mode, String path) throws Exception {
        File f = new File(path);
        if (f.isFile()) return true;
        if (f.exists() || "standard".equals(mode)) return false;
        return shellTest(mode, "-f", path);
    }

    /**
     * Moves one file: with the app's own access when it has it, else through the privileged shell. Never replaces a file that is already
     * at the target (a rename would). null when it worked, otherwise why not.
     */
    private String moveFile(String mode, String from, String to) {
        try {
            File src = new File(from), dst = new File(to);
            boolean own = hasStorageAccess();
            if (own && src.isFile() && !dst.exists()) {
                File dir = dst.getParentFile();
                if (dir != null && (dir.mkdirs() || dir.isDirectory()) && src.renameTo(dst)) return null;          // (mkdirs is false when another call made it a moment ago)
            }
            if ("standard".equals(mode)) return own ? "Android wouldn't let this app move that file." : "This needs All-files access, or ADB, Shizuku or Root.";
            String dir = to.substring(0, to.lastIndexOf('/'));
            String out = shellVia(mode, "mkdir -p " + BackupScripts.quote(dir) + " && [ ! -e " + BackupScripts.quote(to) + " ] && mv " + BackupScripts.quote(from) + " " + BackupScripts.quote(to) + " && echo FMOK");
            if (FileRules.okLine(out, "FMOK")) return null;
            String why = out == null ? "" : out.trim();
            return why.isEmpty() ? "The file could not be moved." : why;
        } catch (Exception e) {
            return e.getMessage() != null ? e.getMessage() : "The file could not be moved.";
        }
    }

    /** Deletes one trashed file or a whole trash folder, with the app's own access when it can and else through the shell. */
    private void deleteQuietly(String mode, String path, boolean folder) {
        try {
            File f = new File(path);
            if (hasStorageAccess()) {
                if (folder && f.isDirectory()) { File[] kids = f.listFiles(); if (kids != null) for (File k : kids) k.delete(); }
                f.delete();
                if (!f.exists()) return;
            }
            if (!"standard".equals(mode)) shellVia(mode, (folder ? "rm -rf " : "rm -f ") + BackupScripts.quote(path));
        } catch (Exception ignored) {}
    }

    /** The storage volumes a package file can be on: the primary storage and any SD card or USB drive. */
    private List<String> storageVolumes() {
        List<String> roots = new ArrayList<String>();
        roots.add(fmCanonicalPath("/sdcard"));
        File[] vols = new File("/storage").listFiles();
        if (vols != null) {
            for (File v : vols) if (v.getName().matches("[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}")) roots.add(v.getAbsolutePath());
        }
        return roots;
    }

    /**
     * Deletes what every trash folder holds (what an app that was closed during an Undo's few seconds left behind). The "something is
     * waiting" mark is cleared only when every trash folder is seen to be gone; when the app can neither read storage nor use a working
     * mode (the connection is not up yet, say) it can't see them, so the mark stays and the next start tries again. true when all is gone.
     */
    private boolean purgeApkTrash() {
        if (apkTrashedThisRun) return false;                  // a file deleted in this run waits for its Undo: leave it all to the next start
        String mode = resolveExecMode();
        boolean gone = hasStorageAccess() || !"standard".equals(mode);
        for (String root : storageVolumes()) {
            if (apkTrashedThisRun) return false;
            String dir = ApkTrash.trashDir(root);
            deleteQuietly(mode, dir, true);
            try { if (hasStorageAccess() ? new File(dir).exists() : pathExists(mode, dir)) gone = false; } catch (Exception e) { gone = false; }
        }
        synchronized (apkTrashLock) {
            if (gone && !apkTrashedThisRun) prefs.edit().putBoolean("apk_trash_pending", false).apply();
        }
        return gone && !apkTrashedThisRun;
    }

    /** op "trash" (a = path): move the file into its volume's trash; "untrash" (a = trash path, b = original path): put it back; "purge" (a = trash path, or empty for all): delete for good. */
    private JSONObject apkFileOpImpl(String op, String a, String b) throws Exception {
        JSONObject res = new JSONObject();
        String mode = resolveExecMode();
        if ("trash".equals(op)) {
            String src = fmCanonicalPath(a);
            if (!ApkTrash.deletable(src)) throw new IOException("Only app package files on storage can be deleted here.");
            if ("standard".equals(mode) && !hasStorageAccess()) {          // the list came from a working mode that has gone since
                needFileAccess("To delete files from storage", src);
                throw new IOException("This needs All-files access, or ADB, Shizuku or Root.");
            }
            if (!isRegularFile(mode, src)) throw new IOException(pathExists(mode, src) ? "That is not a package file." : "That file is already gone.");
            String dest = ApkTrash.trashPath(src, ApkTrash.nextStamp(System.currentTimeMillis()));
            // marked before the move: if the app is killed in between, the next start still knows to look in the trash folders
            synchronized (apkTrashLock) {
                apkTrashedThisRun = true;
                prefs.edit().putBoolean("apk_trash_pending", true).commit();
            }
            String why = moveFile(mode, src, dest);
            if (why != null) {
                if (why.contains("All-files access")) needFileAccess("To delete files from storage", src);
                throw new IOException(why);
            }
            res.put("ok", true);
            res.put("trash", dest);
        } else if ("untrash".equals(op)) {
            String trash = fmCanonicalPath(a), orig = fmCanonicalPath(b);
            if (!ApkTrash.restorable(trash, orig)) throw new IOException("That file can't be put back.");
            // a file of the same name may be there again: both are kept
            final String m = mode;
            String target = ApkTrash.uniqueTarget(orig, new ApkTrash.Exists() {
                @Override
                public boolean at(String path) throws Exception { return pathExists(m, path); }
            });
            if (target == null) throw new IOException("A file with that name is in the way.");
            String why = moveFile(mode, trash, target);
            if (why != null) throw new IOException(why);
            res.put("ok", true);
            res.put("path", target);
        } else if ("purge".equals(op)) {
            if (a == null || a.trim().isEmpty()) {
                if (prefs.getBoolean("apk_trash_pending", false)) purgeApkTrash();          // nothing waiting: nothing to look for
            } else {
                String trash = fmCanonicalPath(a);
                if (!ApkTrash.isTrashPath(trash)) throw new IOException("That is not a deleted file.");
                deleteQuietly(mode, trash, false);
                if (pathExists(mode, trash)) throw new IOException("The file could not be removed now. It is removed the next time the app starts.");
            }
            res.put("ok", true);
        } else {
            throw new IOException("Unknown operation: " + op);
        }
        return res;
    }

    private volatile long apkScanProgressAt = 0;
    // numbers the searches: when a newer one starts (the page gave up on the first, or was reloaded), the older one's progress and answer are dropped
    private final java.util.concurrent.atomic.AtomicInteger apkScanSeq = new java.util.concurrent.atomic.AtomicInteger();

    /** Tells the page how far the search has got: window.onApkScanProgress({pct (-1 = no way to tell), msg, found}). At most a few times a second unless forced. */
    private void sendApkScanProgress(int scanId, int pct, String msg, int found, boolean force) {
        if (scanId != apkScanSeq.get()) return;
        long now = android.os.SystemClock.elapsedRealtime();
        if (!force && now - apkScanProgressAt < 120) return;
        apkScanProgressAt = now;
        try {
            JSONObject o = new JSONObject();
            o.put("pct", pct);
            o.put("msg", msg);
            o.put("found", found);
            notifyJs("window.onApkScanProgress && window.onApkScanProgress(" + JSONObject.quote(o.toString()) + ")");
        } catch (Exception ignored) {}
    }

    /**
     * Scans storage off-thread and reports to window.onApkScan(json): {status, files[], truncated, ms, fs, shell}.
     * Folders this app can read are walked directly; with a privileged mode the shell also covers the ones it
     * can't (Android/data, Android/obb - or everything when All-files access isn't granted).
     */
    private void runApkScan() {
        final int scanId = apkScanSeq.incrementAndGet();
        executor.submit(new Runnable() {
            @Override
            public void run() {
                JSONObject res = new JSONObject();
                long t0 = System.currentTimeMillis();
                try {
                    boolean fsAccess = hasStorageAccess();
                    String mode = resolveExecMode();
                    boolean privileged = !"standard".equals(mode);
                    res.put("fs", fsAccess);
                    res.put("shell", privileged);
                    if (!fsAccess && !privileged) {
                        res.put("status", "noaccess");
                        if (scanId == apkScanSeq.get()) notifyJs("window.onApkScan && window.onApkScan(" + JSONObject.quote(res.toString()) + ")");
                        return;
                    }

                    List<ApkScan.Entry> found = new ArrayList<ApkScan.Entry>();
                    Set<String> seen = new HashSet<String>();
                    ApkScan.Limits lim = new ApkScan.Limits();
                    lim.deadlineMs = t0 + 25000;

                    String primary = fmCanonicalPath("/sdcard");
                    List<File> roots = new ArrayList<File>();
                    roots.add(new File(primary));
                    File[] vols = new File("/storage").listFiles();   // SD cards / USB drives
                    if (vols != null) {
                        for (File v : vols) if (v.getName().matches("[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}")) roots.add(v);
                    }

                    // Progress: the folders this app can read fill the first part of the bar (all of it without a privileged mode),
                    // the shell's search and its size look-ups the rest. The unit is a top-level folder of each volume.
                    final int walkShare = privileged ? 85 : 98;
                    apkScanProgressAt = 0;
                    sendApkScanProgress(scanId, 0, "Looking through storage…", 0, true);
                    if (fsAccess) {
                        final int totalTop = ApkScan.countTopFolders(roots);
                        int doneBefore = 0;
                        for (File r : roots) {
                            doneBefore += ApkScan.walkRoot(r, found, seen, lim, doneBefore, totalTop, new ApkScan.Progress() {
                                @Override
                                public void onProgress(int done, int total, String folder, int foundNow) {
                                    int pct = total > 0 ? Math.min(walkShare, done * walkShare / total) : walkShare;
                                    sendApkScanProgress(scanId, pct, "Searched " + folder + " (" + done + " of " + total + " folders)", foundNow, done >= total);
                                }
                            });
                        }
                    }

                    if (privileged) {
                        StringBuilder where = new StringBuilder();
                        if (fsAccess) {
                            where.append(BackupScripts.quote(primary + "/Android/data")).append(' ')
                                 .append(BackupScripts.quote(primary + "/Android/obb"));
                        } else {
                            for (File r : roots) where.append(BackupScripts.quote(r.getAbsolutePath())).append(' ');
                        }
                        AndroidBridge sh = new AndroidBridge();
                        sendApkScanProgress(scanId, -1, fsAccess ? "Searching Android/data and Android/obb with the privileged mode…" : "Searching storage with the privileged mode…", found.size(), true);
                        // find gets a time of its own: executeShell's 8-10 s cut a search of a full storage short, and what it had read so far
                        // looked complete. No end line means a partial list, and the page says the search stopped early.
                        String out = runPrivilegedShell(mode, "find " + where.toString().trim() + " -maxdepth 12 " + ApkScan.FIND_PREDICATE
                                + " 2>/dev/null | head -n 2500; echo " + ApkScan.FIND_END, 25000);
                        if (!ApkScan.findComplete(out)) lim.hitLimit = true;
                        List<String> unreadable = new ArrayList<String>();
                        for (String path : ApkScan.parseFindOutput(out, 2500)) {
                            if (found.size() >= lim.maxResults) { lim.hitLimit = true; break; }
                            if (!seen.add(path)) continue;
                            ApkScan.Entry e = new ApkScan.Entry();
                            e.path = path;
                            e.name = path.substring(path.lastIndexOf('/') + 1);
                            e.kind = ApkScan.kindOf(e.name);
                            File f = new File(path);
                            if (f.isFile() && f.canRead()) {
                                e.size = f.length();
                                e.mtime = f.lastModified();
                                e.shell = false;
                            } else {
                                e.shell = true;
                                unreadable.add(path);
                            }
                            found.add(e);
                        }
                        // Size + date of the files only the shell can see, 40 per call
                        Map<String, long[]> stats = new java.util.HashMap<String, long[]>();
                        for (int i = 0; i < unreadable.size(); i += 40) {
                            sendApkScanProgress(scanId, 90 + Math.min(9, i * 9 / Math.max(1, unreadable.size())), "Reading sizes and dates (" + Math.min(i + 40, unreadable.size()) + " of " + unreadable.size() + " files)", found.size(), false);
                            StringBuilder args = new StringBuilder();
                            for (int j = i; j < Math.min(i + 40, unreadable.size()); j++) {
                                args.append(' ').append(BackupScripts.quote(unreadable.get(j)));
                            }
                            stats.putAll(ApkScan.parseStatOutput(sh.executeShell("stat -c '%s|%Y|%n'" + args + " 2>/dev/null")));
                        }
                        List<ApkScan.Entry> keep = new ArrayList<ApkScan.Entry>();
                        for (ApkScan.Entry e : found) {
                            if (e.shell) {
                                long[] st = stats.get(e.path);
                                if (st != null) { e.size = st[0]; e.mtime = st[1] * 1000L; }
                                if (stats.size() > 0 && st != null && st[0] <= 0) continue; // empty placeholder
                            }
                            keep.add(e);
                        }
                        found = keep;
                    }

                    ApkScan.sort(found);
                    JSONArray files = new JSONArray();
                    for (ApkScan.Entry e : found) files.put(ApkScan.toJson(e));
                    res.put("status", "ok");
                    res.put("files", files);
                    res.put("truncated", lim.hitLimit);
                    res.put("ms", System.currentTimeMillis() - t0);
                } catch (Exception e) {
                    try { res.put("status", "error"); res.put("error", e.getMessage() != null ? e.getMessage() : "scan failed"); } catch (Exception ignored) {}
                }
                if (scanId == apkScanSeq.get()) notifyJs("window.onApkScan && window.onApkScan(" + JSONObject.quote(res.toString()) + ")");
            }
        });
    }

    // ---------------------------------------------------------------------------------------------
    // The app's own font: found on storage or chosen with the file chooser, kept in the app's files, handed to the page as base64
    // ---------------------------------------------------------------------------------------------

    private static final int REQ_PICK_FONT = 4204;
    private static final int REQ_PICK_TEXT = 4290;       // a small text file for the page (presets and saved commands)
    private static final int REQ_PICK_BACKUP_DIR = 4291; // a folder the page keeps its backups in (saved lists)
    private volatile String pickBackupDirTag = "";
    // ---- Connected Devices: another device (a watch, a phone, a TV) driven through the app's own adb server ----
    private static final int REQ_PICK_CD = 4293;         // package files to send to a connected device
    private static final int REQ_BT_CONNECT = 9203;
    private final ExecutorService cdExecutor = Executors.newFixedThreadPool(3);
    private final java.util.concurrent.ConcurrentHashMap<String, Process> cdProcs = new java.util.concurrent.ConcurrentHashMap<String, Process>();
    private final java.util.Set<String> cdCancelled = java.util.Collections.synchronizedSet(new HashSet<String>());
    private volatile String cdPickTag = "";
    private volatile List<String> cdPickInUse = new ArrayList<String>();   // files of earlier picks the page still holds (Send queue, a push): kept by the clean-up of old picks

    /** Runs the app's adb with these arguments; the process is kept under the tag so Stop can end it. Answer: what it printed (stdout and stderr). */
    private String cdExec(String tag, List<String> args, int timeoutMs) {
        if (tag != null && cdCancelled.contains(tag)) return "Error: stopped";
        try {
            Process p = buildAdbProcess(args.toArray(new String[0])).start();
            if (tag != null && !tag.isEmpty()) cdProcs.put(tag, p);
            try {
                return readProcessWithTimeout(p, timeoutMs);
            } finally {
                if (tag != null) cdProcs.remove(tag);
            }
        } catch (Exception e) {
            return "Error: " + e.getMessage();
        }
    }

    /** adb -s serial, then these arguments (the ADB Stub's calls). */
    private static List<String> cdStubArgs(String serial, String... rest) {
        List<String> a = new ArrayList<String>();
        a.add("-s");
        a.add(serial);
        java.util.Collections.addAll(a, rest);
        return a;
    }

    /** The ADB Stub APK this build carries (assets/adb_stub.apk), copied out once per app version into the cache; null when there is none. */
    private File cdStubApk() {
        try {
            int ver = getPackageManager().getPackageInfo(getPackageName(), 0).versionCode;
            File dir = new File(getCacheDir(), "adb_stub");
            File f = new File(dir, "adb_stub_" + ver + "_" + WearStub.VERSION + ".apk");
            if (f.length() > 0) return f;
            dir.mkdirs();
            File[] old = dir.listFiles();
            if (old != null) for (File o : old) o.delete();
            File tmp = new File(dir, "partial.tmp");
            InputStream in = getAssets().open("adb_stub.apk");
            try {
                OutputStream out = new FileOutputStream(tmp);
                try {
                    byte[] buf = new byte[8192];
                    int n;
                    while ((n = in.read(buf)) > 0) out.write(buf, 0, n);
                } finally {
                    out.close();
                }
            } finally {
                in.close();
            }
            if (tmp.length() > 0 && tmp.renameTo(f)) return f;
            tmp.delete();
        } catch (Exception ignored) {}
        return null;
    }

    /**
     * The file sent to another device to remove a system app there: the small jar built with the app (assets/uninstall_runner.jar, only the runner's
     * classes), kept per app version; or, with a build that has none, this app's own APK, which holds the same class. Null when neither can be found.
     */
    private String cdUninstallHelperPath() {
        try {
            int ver = getPackageManager().getPackageInfo(getPackageName(), 0).versionCode;
            File f = new File(getFilesDir(), "uninstall_runner_" + ver + ".jar");
            extractAsset("uninstall_runner.jar", f);
            if (f.length() > 0) return f.getAbsolutePath();
            f.delete();
        } catch (Exception ignored) {}
        try {
            return getPackageManager().getApplicationInfo(getPackageName(), 0).sourceDir;
        } catch (Exception e) {
            return null;
        }
    }

    private static String cdErrorJson(String tag, String out) {
        try {
            return new JSONObject().put("tag", tag).put("out", out).toString();
        } catch (Exception e) {
            return "{}";
        }
    }

    private static String cdSafeName(String name) {
        String n = name == null ? "file" : name.replaceAll("[\\\\/:*?\"<>|\\p{Cntrl}]", "_").trim();
        return n.isEmpty() ? "file" : (n.length() > 120 ? n.substring(n.length() - 120) : n);
    }

    private String cdDisplayName(Uri uri) {
        android.database.Cursor c = null;
        try {
            c = getContentResolver().query(uri, new String[]{android.provider.OpenableColumns.DISPLAY_NAME}, null, null, null);
            if (c != null && c.moveToFirst() && !c.isNull(0)) return c.getString(0);
        } catch (Exception ignored) {
        } finally {
            if (c != null) c.close();
        }
        String last = uri.getLastPathSegment();
        return last == null ? "file" : last.substring(last.lastIndexOf('/') + 1);
    }

    private volatile String pickTextTag = "";
    private volatile long fontScanProgressAt = 0;
    // numbers the searches, like the one for packages: an older search's progress and answer are dropped
    private final java.util.concurrent.atomic.AtomicInteger fontScanSeq = new java.util.concurrent.atomic.AtomicInteger();
    // the page's Cancel: every search numbered up to this has been cancelled (a search started after it is not), so a late Cancel can never stop a newer search
    private final java.util.concurrent.atomic.AtomicInteger fontScanCancelledUpTo = new java.util.concurrent.atomic.AtomicInteger();

    private FontStore fontStore;                         // the font files and their lock: held only to swap files, never while a source is read

    private synchronized FontStore fontStore() {
        if (fontStore == null) fontStore = new FontStore(new File(getFilesDir(), "ui_font"));
        return fontStore;
    }

    private File fontDir() {
        File d = new File(getFilesDir(), "ui_font");
        if (!d.isDirectory()) d.mkdirs();
        return d;
    }

    /** Tells the page how far the font search has got: window.onFontScanProgress({pct, msg, found}). At most a few times a second unless forced. */
    private void sendFontScanProgress(int scanId, int pct, String msg, int found, boolean force) {
        if (scanId != fontScanSeq.get()) return;
        long now = android.os.SystemClock.elapsedRealtime();
        if (!force && now - fontScanProgressAt < 120) return;
        fontScanProgressAt = now;
        try {
            JSONObject o = new JSONObject();
            o.put("pct", pct);
            o.put("msg", msg);
            o.put("found", found);
            notifyJs("window.onFontScanProgress && window.onFontScanProgress(" + JSONObject.quote(o.toString()) + ")");
        } catch (Exception ignored) {}
    }

    /** Searches the folders this app can read for .ttf / .otf files and reports to window.onFontScan({status, fonts[], truncated, ms}). */
    private void runFontScan() {
        final int scanId = fontScanSeq.incrementAndGet();
        executor.submit(new Runnable() {
            @Override
            public void run() {
                JSONObject res = new JSONObject();
                long t0 = System.currentTimeMillis();
                final FontScan.Limits lim = new FontScan.Limits();
                lim.cancel = new FontScan.Cancel() {
                    @Override public boolean isCancelled() { return scanId != fontScanSeq.get() || scanId <= fontScanCancelledUpTo.get(); }   // cancelled, or a newer search started
                };
                try {
                    if (!hasStorageAccess()) {
                        res.put("status", "noaccess");
                    } else {
                        lim.deadlineMs = t0 + 25000;
                        List<File> roots = new ArrayList<File>();
                        roots.add(new File(fmCanonicalPath("/sdcard")));
                        File[] vols = new File("/storage").listFiles();   // SD cards / USB drives
                        if (vols != null) {
                            for (File v : vols) if (v.getName().matches("[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}")) roots.add(v);
                        }
                        fontScanProgressAt = 0;
                        sendFontScanProgress(scanId, 0, "Looking through storage…", 0, true);
                        List<FontScan.Entry> found = new ArrayList<FontScan.Entry>();
                        Set<String> seen = new HashSet<String>();
                        final int totalTop = FontScan.countTopFolders(roots);
                        int doneBefore = 0;
                        for (File r : roots) {
                            doneBefore += FontScan.walkRoot(r, found, seen, lim, doneBefore, totalTop, new FontScan.Progress() {
                                @Override
                                public void onProgress(int done, int total, String folder, int foundNow) {
                                    if (lim.cancel.isCancelled()) return;                                  // cancelled, or a newer search started: the walk stops at its next file
                                    int pct = total > 0 ? Math.min(99, done * 99 / total) : 99;
                                    sendFontScanProgress(scanId, pct, "Searched " + folder + " (" + done + " of " + total + " folders)", foundNow, done >= total);
                                }
                            });
                        }
                        FontScan.sort(found);
                        JSONArray fonts = new JSONArray();
                        for (FontScan.Entry e : found) fonts.put(FontScan.toJson(e));
                        res.put("status", "ok");
                        res.put("fonts", fonts);
                        res.put("truncated", lim.hitLimit);
                        res.put("ms", System.currentTimeMillis() - t0);
                    }
                } catch (Exception e) {
                    try { res.put("status", "error"); res.put("error", e.getMessage() != null ? e.getMessage() : "search failed"); } catch (Exception ignored) {}
                }
                if (lim.cancelled || scanId <= fontScanCancelledUpTo.get()) {                // cancelled: no list, just the word, so the page can tidy up
                    res = new JSONObject();
                    try { res.put("status", "cancelled"); } catch (Exception ignored) {}
                }
                if (scanId == fontScanSeq.get()) notifyJs("window.onFontScan && window.onFontScan(" + JSONObject.quote(res.toString()) + ")");
            }
        });
    }

    /** The name a content:// address is shown with (its last part when the provider does not say). */
    private String contentName(Uri u) {
        android.database.Cursor c = null;
        try {
            c = getContentResolver().query(u, new String[]{android.provider.OpenableColumns.DISPLAY_NAME}, null, null, null);
            if (c != null && c.moveToFirst()) { String n = c.getString(0); if (n != null && !n.isEmpty()) return n; }
        } catch (Exception ignored) {
        } finally {
            if (c != null) try { c.close(); } catch (Exception ignored) {}
        }
        String last = u.getLastPathSegment();
        return last == null ? "font" : last.substring(last.lastIndexOf('/') + 1);
    }

    /** Copies the font in ref (a path, or the content:// address the file chooser gave) to the preview slot after checking it. Answer: {ok, family, style, name, kind, variable, size} or {ok:false, error}. */
    private JSONObject stageFont(final String ref) {
        return fontStore().stage(new FontStore.Opener() {
            private String name = "font";
            @Override public InputStream open() throws Exception {
                if (ref == null || ref.isEmpty()) throw new IllegalStateException("No file was chosen.");
                if (ref.startsWith("content:")) {
                    Uri u = Uri.parse(ref);
                    name = contentName(u);
                    return getContentResolver().openInputStream(u);
                }
                File f = new File(fmCanonicalPath(ref));
                if (!f.isFile() || !f.canRead()) throw new IllegalStateException("The app cannot read that file. Grant All-files access, or choose the file with the file chooser.");
                name = f.getName();
                return new java.io.FileInputStream(f);
            }
            @Override public String name() { return name; }
        }, FontScan.READ_TIMEOUT_MS);
    }

    // FONTMAKER:BEGIN
    // ---------------------------------------------------------------------------------------------
    // Custom Fonts (v7.17.0): fonts made on the phone from the user's own files, the library of them (My fonts), the five emoji downloads,
    // the Samsung font changer and the system emoji swap; the bridge is design section 6 (fontMaker*, emoji*, sysEmoji*, softRestart). What
    // needs no Android classes is FontLibrary's (ids, tokens, the request, meta.json, jobs), the fonts are FontBuilder's and FontPackage's,
    // the privileged scripts SamsungFonts', the downloads EmojiCatalog's: all tested on the JDK.
    // ---------------------------------------------------------------------------------------------

    private static final int REQ_FONTMAKER_PICK = 4294;     // a font file for the font maker (Regular, Bold or emoji)
    private static final int REQ_FONTMAKER_EXPORT = 4295;   // where an exported font package is saved
    /** The options of every font package install: an update replaces, and Samsung's store is named as the installer (One UI lists fonts by it). */
    private static final String FMK_INSTALL_FLAGS = "-r -i com.sec.android.app.samsungapps";
    private static final String FMK_LOCK_CHANGER = "Needs Root, or Shizuku running as the system user (UID 1000) or root (UID 0).";
    private static final String FMK_LOCK_SYS = "Needs Root, or Shizuku running as root (UID 0).";
    private static final String FMK_NOT_SAMSUNG = "Font packages work only on Samsung phones.";
    private static final String FMK_NOT_FOUND = "That font is not in My fonts any more.";
    private static final String FMK_CHANGED = "This font's files changed since it was made. Make it again.";
    private static final String FMK_NO_MEMORY = "The phone ran out of memory for this font. Close other apps and try again, or choose smaller fonts.";
    private static final String FMK_EMOJI_UPDATED = "This phone's emoji were updated by Google Play services, and the swap cannot replace updated emoji safely. It does not run on this phone.";
    private static final String FMK_NO_MOUNTS = "The app cannot read the phone's list of mounts, so it cannot tell its own emoji swap from another tool's and changes nothing. A restart of the phone always puts its own emoji back.";
    // copies of picked files, builds, downloads, exports, installs (side by side); the font changer, the system emoji and Soft reboot one after
    // the other, in the order they were asked for. Both are stopped in onDestroy.
    private final ExecutorService fontExec = Executors.newCachedThreadPool();
    private final ExecutorService fontPrivExec = Executors.newSingleThreadExecutor();
    private final java.security.SecureRandom fmkRandom = new java.security.SecureRandom();
    // The library, the jobs and the open downloads belong to the process, not to one window: a second window (an APK opened with this app from
    // a file manager, a Quick Settings tile's long press) sees what the first one runs, and the folders are tidied once, before anything uses
    // them. A window's picked files are in a folder of its own, and a window that closes stops only the jobs it started.
    private static final FontLibrary.Jobs fmkJobs = new FontLibrary.Jobs();
    // the open downloads by job id: Cancel (and the window closing) disconnects them, so a stalled connect or read ends at once
    private static final java.util.concurrent.ConcurrentHashMap<String, java.net.HttpURLConnection> fmkConns = new java.util.concurrent.ConcurrentHashMap<String, java.net.HttpURLConnection>();
    private static final Object fmkSharedLock = new Object();
    private static FontLibrary.Dirs fmkSharedDirs;      // made on first use in the process: the files folder is not there before onCreate
    // the system emoji's steps (status, Apply, Undo, a staged copy's delete) one at a time in the whole process: each window has a fontPrivExec
    // of its own, and a step of one window must never read or delete what another window's Apply is staging or binding
    private static final Object fmkSysLock = new Object();
    private static final String STATE_FMK_EXPORT = "fontmaker_export_id";
    private final Object fmkLock = new Object();
    private FontLibrary.Picks fmkPicks;
    private String fmkPickSlot, fmkExportId;     // what the open file chooser / "save as" is for, one at a time (guarded by fmkLock)
    private volatile int fmkOneUiRaw = -1;       // ro.build.version.oneui (80500 = 8.5), read once
    private volatile String fmkOneUiText;

    private FontLibrary.Dirs fmkDirs() {
        synchronized (fmkSharedLock) {
            if (fmkSharedDirs == null) {
                FontLibrary.Dirs d = new FontLibrary.Dirs(getFilesDir(), getCacheDir());
                // once per process, before any job: what a crash, a power cut or a killed process left
                FontLibrary.sweep(d);                       // staged folders, a folder a rebuild moved aside, an entry whose files did not reach the disk
                EmojiCatalog.sweep(d.emoji);                // a download's .part file and Twemoji's zip
                FontLibrary.deleteTree(d.work);
                FontLibrary.deleteTree(d.in);               // picked copies: the pages that knew their tokens are gone
                fmkSharedDirs = d;
            }
            return fmkSharedDirs;
        }
    }

    private FontLibrary.Picks fmkPicks() {
        FontLibrary.Dirs d = fmkDirs();
        synchronized (fmkLock) {
            if (fmkPicks == null) fmkPicks = new FontLibrary.Picks(d.pickFolder(FontLibrary.newId(fmkRandom)));     // this window's own folder
            return fmkPicks;
        }
    }

    private static String fmkErr(String code, String message) {
        return FontLibrary.error(code, message).toString();
    }

    private static String fmkOk(String key, String value) {
        try {
            JSONObject o = new JSONObject().put("ok", true);
            if (key != null) o.put(key, value);
            return o.toString();
        } catch (Exception e) {
            return "{\"ok\":true}";
        }
    }

    /**
     * Who may run the font scripts now, or null: the font changer needs the root user or the system user (RootGate.unlocked: Root with su
     * granted, or Shizuku as uid 0 or 1000), the system emoji swap and Soft reboot the root user (RootGate.uid0), the same gates as the tracker
     * switches and the overlay fabricate. The answer is the backend: "root" (su), "system" (Shizuku as uid 1000) or "uid0" (Shizuku as uid 0).
     */
    private String fmkGate(boolean rootUserOnly) {
        String mode = resolveExecMode();
        boolean suGranted = "root".equals(mode) && isRootGranted();
        boolean sz = "shizuku".equals(mode) && isShizukuAuthorized();
        int szUid = sz ? shizukuServerUid() : -1;
        boolean open = rootUserOnly ? RootGate.uid0(mode, suGranted, sz, szUid) : RootGate.unlocked(mode, suGranted, sz, szUid);
        if (!open) return null;
        return "root".equals(mode) ? "root" : szUid == 1000 ? "system" : "uid0";
    }

    /**
     * Runs one script through the backend fmkGate chose and returns what it printed (the script's own read-back decides what happened, never
     * an exit text). A font for the script's stdin is streamed from this app's file: through the Shizuku API (the system user cannot read this
     * app's files), or with su from the file itself.
     */
    private String fmkRun(String backend, String script, File stdin, int timeoutMs) throws Exception {
        if ("root".equals(backend)) {
            if (stdin == null) return runRootScript(script, timeoutMs);
            File f = new File(getCacheDir(), "root_" + System.nanoTime() + ".sh");
            try {
                FileOutputStream out = new FileOutputStream(f);
                try {
                    out.write(script.getBytes("UTF-8"));
                } finally {
                    out.close();
                }
                f.setReadable(true, false);
                ProcessBuilder pb = new ProcessBuilder("su", "-c", "sh " + BackupScripts.quote(f.getAbsolutePath()) + " < " + BackupScripts.quote(stdin.getAbsolutePath()));
                pb.redirectErrorStream(true);
                String r = runProcessWithTimeout(pb, timeoutMs);
                return r == null ? "" : r;
            } finally {
                f.delete();
            }
        }
        if (!"system".equals(backend) && !"uid0".equals(backend)) throw new IllegalStateException(FMK_LOCK_CHANGER);
        InputStream in = stdin == null ? null : new java.io.FileInputStream(stdin);
        try {
            return shizukuPipe(script, in, timeoutMs);
        } finally {
            if (in != null) try { in.close(); } catch (IOException ignored) {}
        }
    }

    private void fmkProgress(String job, String stage, long done, long total) {
        notifyJs("window.onFontMakerProgress && window.onFontMakerProgress(" + JSONObject.quote(job) + ", " + JSONObject.quote(stage) + ", " + done + ", " + total + ")");
    }

    private void fmkPicked(String slot, JSONObject res) {
        notifyJs("window.onFontMakerPicked && window.onFontMakerPicked(" + JSONObject.quote(slot) + ", " + JSONObject.quote(res.toString()) + ")");
    }

    private void fmkExported(String id, JSONObject res) {
        notifyJs("window.onFontMakerExported && window.onFontMakerExported(" + JSONObject.quote(id) + ", " + JSONObject.quote(res.toString()) + ")");
    }

    /** The versionCode of an installed package, 0 when it is not installed. */
    private long fmkInstalledVersion(String pkg) {
        try {
            PackageInfo pi = getPackageManager().getPackageInfo(pkg, 0);
            return Build.VERSION.SDK_INT >= 28 ? pi.getLongVersionCode() : pi.versionCode;
        } catch (Throwable notInstalled) {
            return 0;
        }
    }

    /** The installed FlipFont packages (com.monotype.android.font.*), for the row Settings > Font style highlights. */
    private List<String> fmkFontPackages() {
        List<String> out = new ArrayList<String>();
        try {
            for (PackageInfo pi : getPackageManager().getInstalledPackages(0)) {
                if (pi.packageName != null && pi.packageName.startsWith(FontPackage.PACKAGE_PREFIX)) out.add(pi.packageName);
            }
        } catch (Throwable ignored) {}
        return out;
    }

    /**
     * The installed font packages this app made (FontPackage.madeHere: in My fonts, or signed with the app's key), which the update check
     * leaves out. Install names Samsung's store as their installer, so the check would otherwise ask the Galaxy Store about each one, sending
     * the font's name along with the phone's model and region, for a package no store has.
     */
    private Set<String> fmkMadeHere() {
        Set<String> out = new HashSet<String>();
        try {
            Set<String> suffixes = new HashSet<String>();
            for (FontLibrary.Entry e : FontLibrary.list(fmkDirs())) suffixes.add(e.suffix);
            String key = null;
            try {
                SigningKey k = SigningKey.existing();
                if (k != null) key = k.sha256();
            } catch (Throwable noKey) {}
            int sigFlags = Build.VERSION.SDK_INT >= 28 ? PackageManager.GET_SIGNING_CERTIFICATES : PackageManager.GET_SIGNATURES;
            for (String pkg : fmkFontPackages()) {
                try {
                    PackageInfo pi = getPackageManager().getPackageInfo(pkg, sigFlags);
                    boolean system = pi.applicationInfo != null && (pi.applicationInfo.flags & ApplicationInfo.FLAG_SYSTEM) != 0;
                    if (FontPackage.madeHere(pkg, system, suffixes, signerDigests(pi, true), key)) out.add(pkg);
                } catch (Throwable gone) {}
            }
        } catch (Throwable ignored) {}
        return out;
    }

    /** One UI as major*100 + minor*10 (8.5 is 850; 0 off Samsung or unreadable), from ro.build.version.oneui, else Build.VERSION.SEM_PLATFORM_INT. */
    private int fmkOneUi100() {
        if (!isSamsung()) return 0;
        int raw = fmkOneUiRaw;
        if (raw < 0) {
            raw = 0;
            try {
                String line = runProcessWithTimeout(new ProcessBuilder("getprop", "ro.build.version.oneui"), 2000).trim();
                if (line.matches("\\d{4,7}")) raw = Integer.parseInt(line);
            } catch (Throwable ignored) {}
            if (raw <= 0) {
                try {
                    int sem = Build.VERSION.class.getField("SEM_PLATFORM_INT").getInt(null);
                    if (sem >= 100000) raw = sem - 90000;
                } catch (Throwable ignored) {}
            }
            fmkOneUiRaw = raw;
        }
        return SamsungFonts.oneUiTimes100(raw);
    }

    /** {samsung, oneUi, appliesSelfSigned, sdk, userId}: what My fonts says about installing on this phone. */
    private JSONObject fmkDevice() throws Exception {
        String text = fmkOneUiText;
        if (text == null) fmkOneUiText = text = oneUiVersion();
        boolean samsung = isSamsung();
        return new JSONObject().put("samsung", samsung).put("oneUi", text)
                .put("appliesSelfSigned", samsung && SamsungFonts.appliesSelfSigned(fmkOneUi100(), Build.VERSION.SECURITY_PATCH))
                .put("sdk", Build.VERSION.SDK_INT).put("userId", FontLibrary.userIdOf(android.os.Process.myUid()));
    }

    private String fmkLibraryJson() throws Exception {
        FontLibrary.Dirs d = fmkDirs();
        String applied = FontLibrary.readApplied(d);
        JSONArray rows = new JSONArray();
        for (FontLibrary.Entry e : FontLibrary.list(d)) rows.put(FontLibrary.entryJson(e, fmkInstalledVersion(e.pkg), applied != null && applied.equals(e.suffix)));
        return new JSONObject().put("ok", true).put("entries", rows).put("device", fmkDevice()).toString();
    }

    /** A file as base64 for a FontFace preview; "" when it is missing or larger than 24 MB (the page then shows it in its own font). */
    private String fmkBase64(File f) {
        try {
            long len = f.length();
            if (!f.isFile() || len <= 0 || len > FontLibrary.MAX_PREVIEW_BYTES) return "";
            return android.util.Base64.encodeToString(FontLibrary.readFile(f, FontLibrary.MAX_PREVIEW_BYTES), android.util.Base64.NO_WRAP);
        } catch (Throwable e) {                                         // OutOfMemoryError on a small phone included
            return "";
        }
    }

    // ---- picking ----

    /** The file chooser answered for a slot: the file is copied and read on fontExec. */
    private void fmkPickResult(final String slot, final Uri uri) {
        if (slot == null) return;
        if (uri == null) { fmkPicked(slot, FontLibrary.error("cancelled", "No file was chosen.")); return; }
        // the choices are numbered as they come in (fontMakerPick made the picks already, so nothing is read here, on the UI thread): a copy
        // from a slow provider that ends after a later choice of the slot does not replace it
        final int ask = fmkPicks().ask(slot);
        try {
            fontExec.submit(new Runnable() {
                @Override
                public void run() {
                    fmkPicked(slot, fmkCopyPick(slot, uri, ask));
                }
            });
        } catch (RejectedExecutionException closing) {}
    }

    /**
     * Copies the chosen file to this window's folder in cache/fontmaker/in/ (at most 96 MB: one byte more and the copy stops and is deleted),
     * reads what it is with FontInspect and keeps it under a new random token, the only name the page gets for it, unless a later choice of
     * the slot ({@code ask}) came in meanwhile. The emoji slot takes only a colour (COLR) font with TrueType outlines, and is not warned that
     * it has no letters.
     * {ok, token, fileName, size, info} or {ok:false, code, error} ("cancelled" for a choice a later one replaced).
     */
    private JSONObject fmkCopyPick(String slot, Uri uri, int ask) {
        FontLibrary.Picks picks = fmkPicks();
        String token = FontLibrary.newToken(fmkRandom);
        File f = picks.fileFor(slot, token);
        boolean kept = false;
        try {
            File dir = f.getParentFile();
            if (!dir.isDirectory() && !dir.mkdirs()) throw new IOException("The app has no room for a copy of the file.");
            String name = cdSafeName(contentName(uri));
            InputStream in = getContentResolver().openInputStream(uri);
            if (in == null) throw new IOException("The app could not open that file.");
            long size;
            try {
                FileOutputStream out = new FileOutputStream(f);
                try {
                    size = FontLibrary.copyCapped(in, out, FontLibrary.MAX_PICK_BYTES);
                } finally {
                    out.close();
                }
            } finally {
                in.close();
            }
            if (size <= 0) throw new Sfnt.FontException("not_a_font", "This file is empty.");
            FontInspect.Info info = FontInspect.inspect(FontLibrary.readFile(f, FontLibrary.MAX_PICK_BYTES));
            if ("emoji".equals(slot)) {
                if ("CBDT".equals(info.color) || "sbix".equals(info.color))
                    throw new Sfnt.FontException("bitmap_emoji", "This emoji font is made of pictures (" + info.color + "), which cannot be put inside a font. Choose a COLR emoji font.");
                if (!info.color.startsWith("COLR")) throw new Sfnt.FontException("not_emoji", "This font has no colour emoji (COLR). Choose a COLR emoji font.");
                // the merge takes only TrueType outlines (EmojiMerge.checkEmoji): refused here, not after the Regular is read
                if (!"TrueType".equals(info.outlines))
                    throw new Sfnt.FontException("emoji_outlines", "This emoji font's outlines are PostScript ones (" + info.outlines
                            + "); only an emoji font with TrueType outlines (glyf) can be added. Choose another emoji font.");
                info.warnings.remove(FontInspect.W_NO_LATIN);                 // an emoji font needs no letters
            }
            if (!picks.put(new FontLibrary.Pick(slot, token, name, f, size, info.color, info.outlines, info.variable), ask))
                return FontLibrary.error("cancelled", "A later choice replaced this file.");
            kept = true;
            return new JSONObject().put("ok", true).put("token", token).put("fileName", name).put("size", size).put("info", FontLibrary.infoJson(info));
        } catch (Sfnt.FontException fe) {
            return FontLibrary.error(fe.code, fe.getMessage());
        } catch (OutOfMemoryError oom) {
            return FontLibrary.error("no_memory", FMK_NO_MEMORY);
        } catch (Throwable t) {
            return FontLibrary.error("unreadable", "The app could not read that file: " + errMsg(t));
        } finally {
            if (!kept) f.delete();
        }
    }

    // ---- building ----

    /** fontMakerBuild: the request and every input it names are checked here, then the font is made on fontExec. {ok, job} or {ok:false, code, error}. */
    private String fmkStartBuild(String json) {
        final FontLibrary.Request req;
        try {
            req = FontLibrary.parseRequest(json);
        } catch (FontLibrary.BadRequest bad) {
            return fmkErr(bad.code, bad.getMessage());
        }
        final FontLibrary.Dirs d = fmkDirs();
        final FontLibrary.Picks picks = fmkPicks();
        final FontLibrary.Pick reg = picks.get(req.regular.token);
        if (reg == null || "emoji".equals(reg.slot)) return fmkErr("no_regular", "Choose the Regular font again.");
        final FontLibrary.Pick bold = req.bold == null ? null : picks.get(req.bold.token);
        if (req.bold != null && (bold == null || "emoji".equals(bold.slot))) return fmkErr("bad_request", "Choose the Bold font again.");
        EmojiCatalog.Item item = null;
        FontLibrary.Pick emo = null;
        if (req.emojiCatalogId != null) {
            item = EmojiCatalog.byId(req.emojiCatalogId);
            if (item == null) return fmkErr("bad_request", "That emoji font is not in the list.");
            if (!item.mergeable) return fmkErr("bitmap_emoji", "Emoji font: " + item.name + " is made of pictures, which cannot be put inside a font. It can only be the phone's emoji.");
            EmojiCatalog.Item kept = FontLibrary.keptBuild(item, d.emojiFile(item.id));
            if (kept == null) return fmkErr("not_downloaded", "Download " + item.name + " first.");
            if (kept.minApiForMerge > Build.VERSION.SDK_INT) return fmkErr("not_usable", item.name + " needs a newer Android to show inside a font.");
        } else if (req.emojiToken != null) {
            emo = picks.get(req.emojiToken);
            if (emo == null || !"emoji".equals(emo.slot)) return fmkErr("bad_request", "Choose the emoji font file again.");
            // Android draws COLRv1 from 13 on: inside a font on an older phone, every emoji would be blank (the font's own emoji hide the phone's)
            if (FontLibrary.minApiForEmoji(emo.color) > Build.VERSION.SDK_INT)
                return fmkErr("not_usable", "Emoji font: this COLRv1 emoji font needs Android 13 or newer to show inside a font.");
        }
        FontLibrary.Entry rebuild = null;
        if (req.rebuildId != null) {
            rebuild = FontLibrary.read(d, req.rebuildId);
            if (rebuild == null) return fmkErr("not_found", FMK_NOT_FOUND);
        }
        // one build at a time (a variable font made static twice and an emoji merge can take a few hundred MB). A font made again is not
        // started while it is installed, uninstalled, applied or saved ("id:"), and holds "make:" so an install, an apply or a save does not
        // start while its files are replaced.
        final FontLibrary.Jobs.Job job = fmkJobs.startFor(this, rebuild == null ? null : "id:" + rebuild.id, "build", "only",
                "tok:" + reg.token, bold == null ? null : "tok:" + bold.token, emo == null ? null : "tok:" + emo.token, item == null ? null : "cat:" + item.id,
                rebuild == null ? null : "id:" + rebuild.id, rebuild == null ? null : "make:" + rebuild.id);
        if (job == null) {
            if (fmkJobs.running("build", "only") != null) return fmkErr("busy", "A font is being made. Wait for it to finish, or cancel it.");
            return fmkErr("busy", "This font is busy. Wait for it to finish.");     // any of the jobs that hold "id:"
        }
        picks.hold(reg);
        picks.hold(bold);
        picks.hold(emo);
        final EmojiCatalog.Item emojiItem = item;
        final FontLibrary.Pick emojiPick = emo;
        final FontLibrary.Entry again = rebuild;
        try {
            fontExec.submit(new Runnable() {
                @Override
                public void run() {
                    fmkBuildJob(job, req, reg, bold, emojiPick, emojiItem, again);
                }
            });
        } catch (RejectedExecutionException closing) {
            picks.release(reg);
            picks.release(bold);
            picks.release(emo);
            fmkJobs.finish(job);
            return fmkErr("failed", "The app is closing.");
        }
        return fmkOk("job", job.id);
    }

    private static JSONObject fmkSource(FontLibrary.Pick p, Map<String, Double> location) throws Exception {
        JSONObject c = null;
        if (location != null) {
            c = new JSONObject();
            for (Map.Entry<String, Double> e : location.entrySet()) c.put(e.getKey(), e.getValue());
        }
        return new JSONObject().put("fileName", p.fileName).put("coords", c == null ? JSONObject.NULL : c);
    }

    private String fmkNewId(FontLibrary.Dirs d) {
        for (int i = 0; ; i++) {
            String id = FontLibrary.newId(fmkRandom);
            if (!d.entryDir(id).exists() || i > 20) return id;
        }
    }

    /**
     * Makes the font: FontBuilder makes the faces (stages read, instance, convert, emoji), FontPackage writes the package (package), it is signed
     * with this app's key (sign) and the entry is put in the library whole (save: staged, then renamed into place). A font made again keeps its
     * package and gets the next versionCode, so it installs over the one on the phone. Answer: window.onFontMakerBuilt(job, {ok, entry, warnings}).
     */
    private void fmkBuildJob(final FontLibrary.Jobs.Job job, FontLibrary.Request req, FontLibrary.Pick reg, FontLibrary.Pick bold,
                             FontLibrary.Pick emojiPick, EmojiCatalog.Item emojiItem, FontLibrary.Entry rebuild) {
        final FontLibrary.Dirs d = fmkDirs();
        final FontLibrary.Throttle throttle = new FontLibrary.Throttle(125);
        FontProgress p = new FontProgress() {
            @Override
            public void step(String stage, int done, int total) {
                if (throttle.due(stage, done, total, android.os.SystemClock.elapsedRealtime())) fmkProgress(job.id, stage, done, total);
            }

            @Override
            public boolean cancelled() {
                return job.cancelled() || activityDestroyed;
            }
        };
        JSONObject res;
        File staged = null, unsigned = null, prepared = null;
        try {
            FontBuilder.Request br = new FontBuilder.Request();
            br.name = req.name;
            byte[] regData = FontLibrary.readFile(reg.file, FontLibrary.MAX_PICK_BYTES);
            br.regular = new FontBuilder.Face(regData, req.regular.coords);
            if (bold != null) br.bold = new FontBuilder.Face(bold == reg ? regData : FontLibrary.readFile(bold.file, FontLibrary.MAX_PICK_BYTES), req.bold.coords);
            if (emojiItem != null) {
                // checked by SHA-256 when it was downloaded; checked again, since a build puts it inside a package the phone installs
                File ef = d.emojiFile(emojiItem.id);
                EmojiCatalog.Item kept = FontLibrary.keptBuild(emojiItem, ef);
                byte[] em = kept == null ? null : FontLibrary.readFile(ef, FontLibrary.MAX_EMOJI_BYTES);
                if (em == null || !kept.sha256.equals(FontLibrary.sha256(em)))
                    throw new Sfnt.FontException("emoji_changed", "Emoji font: the downloaded file changed on the phone. Delete it and download it again.");
                br.emoji = em;
            } else if (emojiPick != null) {
                br.emoji = FontLibrary.readFile(emojiPick.file, FontLibrary.MAX_PICK_BYTES);
            }
            br.emojiScale = req.emojiScale;
            long now = System.currentTimeMillis();
            br.time = now;
            FontBuilder.Result out = FontBuilder.build(br, p);
            br = null;                                                   // the sources can go before the package is written
            regData = null;

            FontLibrary.Entry e = FontLibrary.entryFor(req.name, rebuild, rebuild != null ? null : fmkNewId(d), now);
            long installed = fmkInstalledVersion(e.pkg);
            e.versionCode = FontLibrary.versionCodeFor(rebuild, installed);
            e.hasBold = out.bold != null;
            if (emojiItem != null) { e.emojiId = emojiItem.id; e.emojiName = emojiItem.name; }
            else if (emojiPick != null) { e.emojiId = "own"; e.emojiName = emojiPick.fileName; }
            e.sources = new JSONObject().put("regular", fmkSource(reg, out.regularLocation)).put("bold", bold == null ? JSONObject.NULL : fmkSource(bold, out.boldLocation));
            e.warnings.addAll(out.warnings);

            staged = FontLibrary.stageDir(d, e.id, fmkRandom);
            File regFile = new File(staged, FontLibrary.REGULAR), boldFile = new File(staged, FontLibrary.BOLD);
            java.nio.file.Files.write(regFile.toPath(), out.regular);
            e.regularSize = out.regular.length;
            e.regularSha = FontLibrary.sha256(out.regular);
            out.regular = null;
            if (e.hasBold) {
                java.nio.file.Files.write(boldFile.toPath(), out.bold);
                e.boldSize = out.bold.length;
                e.boldSha = FontLibrary.sha256(out.bold);
                out.bold = null;
            }
            FontPackage.Spec spec = new FontPackage.Spec();
            spec.displayName = e.name;
            spec.suffix = e.suffix;
            spec.versionCode = e.versionCode;
            spec.regularFile = regFile;
            spec.boldFile = e.hasBold ? boldFile : null;
            if (!d.work.isDirectory() && !d.work.mkdirs()) throw new IOException("There is no room in the app's cache for the package.");
            unsigned = new File(d.work, e.id + "-" + System.nanoTime() + ".apk");
            prepared = new File(d.work, "prep_" + unsigned.getName());
            FontPackage.writeUnsigned(unsigned, spec, p);
            FontProgress.Check.cancel(p);
            fmkProgress(job.id, "sign", 0, 0);
            SigningKey k = SigningKey.getOrCreate();
            File apk = new File(staged, FontLibrary.APK);
            ApkSigner.prepare(unsigned, prepared);
            ApkSigner.signV2(prepared, apk, k.key, k.cert);
            e.apkSize = apk.length();
            e.apkSha = FontLibrary.sha256(apk);
            FontProgress.Check.cancel(p);
            fmkProgress(job.id, "save", 0, 0);
            FontLibrary.commit(d, staged, e);
            staged = null;
            String applied = FontLibrary.readApplied(d);
            res = new JSONObject().put("ok", true).put("entry", FontLibrary.entryJson(e, installed, applied != null && applied.equals(e.suffix))).put("warnings", new JSONArray(e.warnings));
        } catch (Sfnt.FontException fe) {
            res = FontLibrary.error(fe.code, fe.getMessage());
        } catch (OutOfMemoryError oom) {
            res = FontLibrary.error("no_memory", FMK_NO_MEMORY);
        } catch (Throwable t) {
            res = FontLibrary.error("failed", "The font could not be made: " + errMsg(t));
        } finally {
            if (staged != null) FontLibrary.deleteTree(staged);
            if (unsigned != null) unsigned.delete();
            if (prepared != null) prepared.delete();
            FontLibrary.Picks picks = fmkPicks();
            picks.release(reg);
            picks.release(bold);
            picks.release(emojiPick);
            fmkJobs.finish(job);
        }
        if (!res.optBoolean("ok") && p.cancelled()) res = FontLibrary.error("cancelled", "The build was cancelled.");
        notifyJs("window.onFontMakerBuilt && window.onFontMakerBuilt(" + JSONObject.quote(job.id) + ", " + JSONObject.quote(res.toString()) + ")");
    }

    // ---- the library: delete, export, install, uninstall ----

    private String fmkDelete(String id) {
        if (!FontLibrary.isId(id)) return fmkErr("not_found", FMK_NOT_FOUND);
        final FontLibrary.Dirs d = fmkDirs();
        final FontLibrary.Entry e = FontLibrary.read(d, id);
        if (e != null) {
            String applied = FontLibrary.readApplied(d);
            if (applied != null && applied.equals(e.suffix)) return fmkErr("applied", "Reset the font changer first.");
        }
        if (fmkJobs.inUse("id:" + id)) {
            if (fmkJobs.inUse("make:" + id)) return fmkErr("busy", "This font is being made again. Wait for it to finish.");
            return fmkErr("busy", "This font is busy. Wait for it to finish.");     // an install, an uninstall, an apply or a save
        }
        if (!FontLibrary.delete(d, id)) return fmkErr("not_found", FMK_NOT_FOUND);
        if (e != null) {
            // the copy a font changer left in /data/app_fonts/<user>/<suffix>/ (applied once, then reset): removed when the changer is open, and
            // only while the phone's sans.loc reads another font (the app's record of what it applied can be behind the phone)
            try {
                fontPrivExec.submit(new Runnable() {
                    @Override
                    public void run() {
                        if (activityDestroyed || !isSamsung()) return;
                        String backend = fmkGate(false);
                        if (backend == null) return;
                        try {
                            SamsungFonts.Roots r = SamsungFonts.Roots.system();
                            int user = FontLibrary.userIdOf(android.os.Process.myUid());
                            String st = fmkRun(backend, SamsungFonts.statusScript(r, user), null, 20000);
                            if (!st.contains(SamsungFonts.M_END) || e.suffix.equals(SamsungFonts.parseStatus(st).currentSuffix)) return;
                            fmkRun(backend, SamsungFonts.removeSuffixScript(r, user, e.suffix), null, 30000);
                        } catch (Throwable ignored) {}
                    }
                });
            } catch (RejectedExecutionException closing) {}
        }
        return fmkOk(null, null);
    }

    /**
     * The "save as" answered: the entry's font.apk is copied there, as a job that holds the entry ("id:"), so it is not made again or deleted
     * while it is copied. {ok, name} or {ok:false, code, error}. A document nothing is copied into (an answer with no export waiting, a font
     * being made again, the app closing) is deleted only when it is empty (fmkDeleteIfEmpty): Overwrite in the save screen hands over the
     * user's own file.
     */
    private void fmkExportResult(final String id, final Uri uri) {
        if (id == null) {
            if (uri != null) fmkDropDocument(uri);
            return;
        }
        if (uri == null) { fmkExported(id, FontLibrary.error("cancelled", "Nothing was saved.")); return; }
        final FontLibrary.Jobs.Job job = fmkJobs.startFor(this, "make:" + id, "export", String.valueOf(System.nanoTime()), "id:" + id);
        if (job == null) {
            fmkDropDocument(uri);
            fmkExported(id, FontLibrary.error("busy", "This font is being made again. Wait for it to finish, then save it."));
            return;
        }
        try {
            fontExec.submit(new Runnable() {
                @Override
                public void run() {
                    try {
                        fmkExported(id, fmkExportTo(id, uri));
                    } finally {
                        fmkJobs.finish(job);
                    }
                }
            });
        } catch (RejectedExecutionException closing) {
            fmkJobs.finish(job);
            fmkDeleteIfEmpty(uri);
        }
    }

    /**
     * Copies the entry's package into the document. Once it is open for writing (emptied), a copy that does not finish deletes it; a refusal
     * before that (the font gone or changed, a document that cannot be written) deletes it only when it is empty.
     */
    private JSONObject fmkExportTo(String id, Uri uri) {
        boolean opened = false, whole = false;
        try {
            FontLibrary.Dirs d = fmkDirs();
            FontLibrary.Entry e = FontLibrary.read(d, id);
            if (e == null) return FontLibrary.error("not_found", FMK_NOT_FOUND);
            File apk = new File(d.entryDir(id), FontLibrary.APK);
            if (!e.apkSha.equals(FontLibrary.sha256(apk))) return FontLibrary.error("changed", FMK_CHANGED);
            OutputStream out;
            try {
                out = getContentResolver().openOutputStream(uri, "wt");
            } catch (Exception noTruncate) {
                out = getContentResolver().openOutputStream(uri, "w");
            }
            if (out == null) throw new IOException("The app could not write there.");
            opened = true;
            InputStream in = new java.io.FileInputStream(apk);
            try {
                byte[] buf = new byte[65536];
                int n;
                while ((n = in.read(buf)) > 0) out.write(buf, 0, n);
            } finally {
                in.close();
                out.close();
            }
            whole = true;
            return new JSONObject().put("ok", true).put("name", cdSafeName(contentName(uri)));
        } catch (Throwable t) {
            return FontLibrary.error("failed", "The font package could not be saved: " + errMsg(t));
        } finally {
            // a package cut short must not stay behind looking like one that installs; a file nothing was written into may be the user's own
            if (opened && !whole) fmkDeleteDocument(uri);
            else if (!whole) fmkDeleteIfEmpty(uri);
        }
    }

    /** Deletes a document the system's "save as" handed over, best effort. */
    private void fmkDeleteDocument(Uri uri) {
        try {
            android.provider.DocumentsContract.deleteDocument(getContentResolver(), uri);
        } catch (Throwable ignored) {}
    }

    /**
     * Deletes a document nothing was written into only when it is empty: the save screen makes a new, empty one, but Overwrite hands over the
     * file the user tapped as it is, and that stays. A provider that does not give the size keeps the document.
     */
    private void fmkDeleteIfEmpty(Uri uri) {
        android.database.Cursor c = null;
        try {
            c = getContentResolver().query(uri, new String[]{android.provider.OpenableColumns.SIZE}, null, null, null);
            if (c == null || !c.moveToFirst() || c.isNull(0) || c.getLong(0) != 0) return;
        } catch (Throwable unknown) {
            return;
        } finally {
            if (c != null) try { c.close(); } catch (Exception ignored) {}
        }
        fmkDeleteDocument(uri);
    }

    /** {@link #fmkDeleteIfEmpty} off the UI thread (a provider can be slow to answer); in the window's last moments, at once. */
    private void fmkDropDocument(final Uri uri) {
        try {
            fontExec.submit(new Runnable() {
                @Override
                public void run() {
                    fmkDeleteIfEmpty(uri);
                }
            });
        } catch (RejectedExecutionException closing) {
            fmkDeleteIfEmpty(uri);
        }
    }

    /** The first line that says what went wrong in a pm answer (a Failure [...] line), at most 300 characters. */
    private static String fmkFailLine(String out) {
        String o = out == null ? "" : out.trim();
        for (String line : o.split("\n")) {
            String t = line.trim();
            if (t.startsWith("Failure") || t.startsWith("Error") || t.contains("INSTALL_FAILED") || t.contains("DELETE_FAILED")) { o = t; break; }
        }
        if (o.isEmpty()) o = "The phone gave no answer.";
        return o.length() > 300 ? o.substring(0, 300) + "…" : o;
    }

    /**
     * Installs an entry's package. A privileged mode installs through the app's own install path for that mode (pm with -r and Samsung's store
     * as the installer), after the same native question every privileged install asks (InstallConfirm), and reads the versionCode back from the
     * package manager; without one, Android's installer opens. {ok, how:"pm"|"installer", note} or {ok:false, code, error}.
     */
    private JSONObject fmkInstall(FontLibrary.Entry e) {
        File copy = null;
        try {
            FontLibrary.Dirs d = fmkDirs();
            File apk = new File(d.entryDir(e.id), FontLibrary.APK);
            String mode = resolveExecMode();
            if (!InstallGuards.isPrivilegedMode(mode)) {
                if (!e.apkSha.equals(FontLibrary.sha256(apk))) return FontLibrary.error("changed", FMK_CHANGED);
                launchSystemInstaller(apk);
                return new JSONObject().put("ok", true).put("how", "installer").put("note", "");
            }
            if (!d.work.isDirectory() && !d.work.mkdirs()) throw new IOException("There is no room in the app's cache for the package.");
            copy = new File(d.work, e.suffix + "-" + System.nanoTime() + ".apk");     // a copy: the root install makes its file readable to pm
            java.nio.file.Files.copy(apk.toPath(), copy.toPath(), java.nio.file.StandardCopyOption.REPLACE_EXISTING);
            // the file pm gets is the one checked against the SHA-256 recorded when the package was made (the question says so)
            if (!e.apkSha.equals(FontLibrary.sha256(copy))) return FontLibrary.error("changed", FMK_CHANGED);
            if (!confirmInMode(mode, null, InstallConfirm.messageFontPackage(e.name, e.pkg, FontPackage.versionName(e.versionCode),
                    installedVersionOrNull(e.pkg), mode, FMK_INSTALL_FLAGS))) {
                throw new InstallCancelled();
            }
            String out = installApksOptions(Collections.singletonList(copy), FMK_INSTALL_FLAGS, mode);
            if (InstallHints.success(out) && fmkInstalledVersion(e.pkg) == e.versionCode) return new JSONObject().put("ok", true).put("how", "pm").put("note", "");
            String advice = InstallHints.advice(out);
            return FontLibrary.error("install_failed", fmkFailLine(out) + (advice.isEmpty() ? "" : " " + advice));
        } catch (InstallCancelled c) {
            return FontLibrary.error("cancelled", errMsg(c));
        } catch (Throwable t) {
            return FontLibrary.error("failed", "The font could not be installed: " + errMsg(t));
        } finally {
            if (copy != null) copy.delete();
        }
    }

    /**
     * Uninstalls an entry's package: pm uninstall through the privileged mode, read back from the package manager; without one, the package's
     * App info opens (the app holds no permission to ask Android to remove another package). {ok, how:"pm"|"settings", note}.
     */
    private JSONObject fmkUninstall(final FontLibrary.Entry e) {
        try {
            if (!BackupScripts.isPackageName(e.pkg) || FontPackage.suffixOf(e.pkg) == null) return FontLibrary.error("not_found", FMK_NOT_FOUND);
            String mode = resolveExecMode();
            if (!InstallGuards.isPrivilegedMode(mode)) {
                runOnUiThread(new Runnable() {
                    @Override
                    public void run() {
                        try {
                            Intent i = new Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS, Uri.parse("package:" + e.pkg));
                            i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
                            startActivity(i);
                        } catch (Exception ignored) {}
                    }
                });
                return new JSONObject().put("ok", true).put("how", "settings").put("note", "");
            }
            if (fmkInstalledVersion(e.pkg) == 0) return new JSONObject().put("ok", true).put("how", "pm").put("note", "");
            String out = shellVia(mode, "pm uninstall " + BackupScripts.quote(e.pkg));
            if (fmkInstalledVersion(e.pkg) == 0) return new JSONObject().put("ok", true).put("how", "pm").put("note", "");
            return FontLibrary.error("uninstall_failed", fmkFailLine(out));
        } catch (Throwable t) {
            return FontLibrary.error("failed", "The font could not be uninstalled: " + errMsg(t));
        }
    }

    // ---- the font changer (RootGate.unlocked) ----

    /** {sansLoc, files: [{name, size, sha256, label}]}: what the phone shows after an apply or a reset. */
    private static JSONObject fmkReadBack(SamsungFonts.ApplyResult ar) throws Exception {
        JSONArray files = new JSONArray();
        for (SamsungFonts.FileInfo f : ar.files) {
            files.put(new JSONObject().put("name", f.name).put("size", Math.max(0, f.size)).put("sha256", f.sha256 == null ? "" : f.sha256)
                    .put("label", f.label == null ? "" : f.label));
        }
        return new JSONObject().put("sansLoc", ar.sansLoc).put("files", files);
    }

    /** Puts one Settings.Global value and reads it back; true when the key holds it afterwards. WRITE_SECURE_SETTINGS when the app has it, else the changer's shell. */
    private boolean fmkGlobalPut(String backend, String key, int value) {
        String v = String.valueOf(value);
        if (hasWriteSecureSettingsAccess()) {
            try {
                android.provider.Settings.Global.putString(getContentResolver(), key, v);
                if (v.equals(android.provider.Settings.Global.getString(getContentResolver(), key))) return true;
            } catch (Throwable notThisWay) {}                            // Android 12+ may refuse to read a hidden key back: the shell reads it below
        }
        try {
            String out = fmkRun(backend, SettingsDb.writeScript("put", "global", key, v), null, 15000);
            return SettingsDb.judge("put", v, SettingsDb.parseWrite(out, key)).ok;
        } catch (Throwable t) {
            return false;
        }
    }

    /**
     * Settings > Font style takes a new font up when flip_font_style and font_style_index change (design section 1): another value first, about
     * 600 ms, then the target (0 Default, else 1 + the package's row; cosmetic, the font itself is sans.loc). True when both read back as the target.
     */
    private boolean fmkRefreshFontStyle(String backend, int target) {
        String[] keys = { "flip_font_style", "font_style_index" };
        int other = target == 0 ? 1 : 0;
        for (String k : keys) fmkGlobalPut(backend, k, other);
        try {
            Thread.sleep(600);
        } catch (InterruptedException closing) {
            Thread.currentThread().interrupt();
        }
        boolean ok = true;
        for (String k : keys) ok &= fmkGlobalPut(backend, k, target);
        return ok;
    }

    /** {ok, available, unlocked, lockReason, mode:"root"|"system"|"none", current:{suffix, id, name}|null}; the phone's sans.loc decides "current". */
    private JSONObject fmkChangerStatus() {
        try {
            JSONObject o = new JSONObject().put("ok", true);
            if (!isSamsung()) return o.put("available", false).put("unlocked", false).put("lockReason", FMK_NOT_SAMSUNG).put("mode", "none").put("current", JSONObject.NULL);
            String backend = fmkGate(false);
            if (backend == null) return o.put("available", true).put("unlocked", false).put("lockReason", FMK_LOCK_CHANGER).put("mode", "none").put("current", JSONObject.NULL);
            FontLibrary.Dirs d = fmkDirs();
            String out = fmkRun(backend, SamsungFonts.statusScript(SamsungFonts.Roots.system(), FontLibrary.userIdOf(android.os.Process.myUid())), null, 20000);
            if (out == null || !out.contains(SamsungFonts.M_END)) return FontLibrary.error("no_answer", "The phone did not answer. Try again.");
            SamsungFonts.Status st = SamsungFonts.parseStatus(out);
            o.put("available", st.available).put("unlocked", true).put("lockReason", "").put("mode", "system".equals(backend) ? "system" : "root");
            if (!st.available) return o.put("current", JSONObject.NULL);
            FontLibrary.writeApplied(d, st.currentSuffix, System.currentTimeMillis());
            if (st.currentSuffix == null) return o.put("current", JSONObject.NULL);
            FontLibrary.Entry e = FontLibrary.bySuffix(FontLibrary.list(d), st.currentSuffix);
            return o.put("current", new JSONObject().put("suffix", st.currentSuffix).put("id", e == null ? JSONObject.NULL : e.id).put("name", e == null ? st.currentSuffix : e.name));
        } catch (Throwable t) {
            return FontLibrary.error("failed", errMsg(t));
        }
    }

    /**
     * Applies an entry with the font changer: each font streamed into /data/app_fonts/<user>/<suffix>/ as DroidSans.ttf.new (and
     * DroidSans-Bold.ttf.new) and checked there by size and SHA-256; only when every file has arrived does one install call move them into
     * place together (taking away a Bold an earlier build left, for a font without one), point sans.loc at them, set the ownership and SELinux
     * label, and read everything back. A step that fails leaves the font in use as it was: what it staged is cleared (fmkDiscard). The font is
     * applied only when sans.loc and the hashes read back as asked. Then Settings is told (fmkRefreshFontStyle).
     * {ok, readBack:{sansLoc, files}, refreshed, styleIndex} or {ok:false, code, error, readBack}.
     */
    private JSONObject fmkApply(String id) {
        try {
            String backend = fmkGate(false);
            if (backend == null) return FontLibrary.error("locked", FMK_LOCK_CHANGER);
            FontLibrary.Dirs d = fmkDirs();
            FontLibrary.Entry e = FontLibrary.read(d, id);
            if (e == null) return FontLibrary.error("not_found", FMK_NOT_FOUND);
            File dir = d.entryDir(id);
            File[] files = e.hasBold ? new File[] { new File(dir, FontLibrary.REGULAR), new File(dir, FontLibrary.BOLD) } : new File[] { new File(dir, FontLibrary.REGULAR) };
            String[] names = e.hasBold ? new String[] { FontLibrary.DROID_REGULAR, FontLibrary.DROID_BOLD } : new String[] { FontLibrary.DROID_REGULAR };
            String[] shas = e.hasBold ? new String[] { e.regularSha, e.boldSha } : new String[] { e.regularSha };
            long[] sizes = e.hasBold ? new long[] { e.regularSize, e.boldSize } : new long[] { e.regularSize };
            for (int i = 0; i < files.length; i++) if (!shas[i].equals(FontLibrary.sha256(files[i]))) return FontLibrary.error("changed", FMK_CHANGED);
            int user = FontLibrary.userIdOf(android.os.Process.myUid());
            SamsungFonts.Roots r = SamsungFonts.Roots.system();
            boolean placed = false;
            try {
                for (int i = 0; i < files.length; i++) {
                    String out = fmkRun(backend, SamsungFonts.writeFontScript(r, user, e.suffix, names[i], sizes[i], shas[i]), files[i], 180000);
                    SamsungFonts.WriteResult w = SamsungFonts.parseWrite(out, names[i]);
                    if (!w.ok || !shas[i].equals(w.sha256)) return FontLibrary.error("failed", w.ok ? "The font did not arrive whole on the phone." : w.error);
                }
                // a Bold an earlier build of this font left would be drawn for bold text: the install takes only that file away
                String[] drop = e.hasBold ? new String[0] : new String[] { FontLibrary.DROID_BOLD };
                SamsungFonts.ApplyResult ar = SamsungFonts.parseApply(fmkRun(backend, SamsungFonts.installScript(r, user, e.suffix, names, shas, drop), null, 60000));
                JSONObject rb = fmkReadBack(ar);
                boolean filesOk = true;
                for (int i = 0; i < names.length; i++) {
                    boolean seen = false;
                    for (SamsungFonts.FileInfo f : ar.files) if (names[i].equals(f.name) && shas[i].equals(f.sha256)) seen = true;
                    filesOk &= seen;
                }
                if (!e.hasBold) for (SamsungFonts.FileInfo f : ar.files) if (FontLibrary.DROID_BOLD.equals(f.name)) filesOk = false;
                String want = r.appFonts + "/" + user + "/" + e.suffix + "#" + e.suffix;
                if (!ar.ok || !want.equals(ar.sansLoc) || !filesOk) {
                    String why = !ar.error.isEmpty() ? ar.error : "The phone did not take the font (sans.loc reads \"" + ar.sansLoc + "\").";
                    return FontLibrary.error("failed", why).put("readBack", rb);
                }
                placed = true;
                FontLibrary.writeApplied(d, e.suffix, System.currentTimeMillis());
                int target = SamsungFonts.styleIndex(fmkFontPackages(), e.pkg);
                boolean refreshed = fmkRefreshFontStyle(backend, target);
                return new JSONObject().put("ok", true).put("readBack", rb).put("refreshed", refreshed).put("styleIndex", target);
            } finally {
                if (!placed) fmkDiscard(backend, r, user, e.suffix);
            }
        } catch (Throwable t) {
            return FontLibrary.error("failed", "The font could not be applied: " + errMsg(t));
        }
    }

    /** What an Apply that stopped part way staged in the font's folder (.new and .part files, and the folder when it is then empty) goes; the font in use stays. */
    private void fmkDiscard(String backend, SamsungFonts.Roots r, int user, String suffix) {
        try {
            fmkRun(backend, SamsungFonts.discardScript(r, user, suffix, new String[] { FontLibrary.DROID_REGULAR, FontLibrary.DROID_BOLD }), null, 30000);
        } catch (Throwable ignored) {}                                  // a leftover .new is never drawn, and the next Apply writes over it
    }

    /** Back to the phone's own font: sans.loc is default#default again (read back), and Settings is told. {ok, readBack, refreshed}. */
    private JSONObject fmkReset() {
        try {
            String backend = fmkGate(false);
            if (backend == null) return FontLibrary.error("locked", FMK_LOCK_CHANGER);
            SamsungFonts.ApplyResult ar = SamsungFonts.parseApply(fmkRun(backend, SamsungFonts.resetScript(SamsungFonts.Roots.system(), FontLibrary.userIdOf(android.os.Process.myUid())), null, 30000));
            JSONObject rb = fmkReadBack(ar);
            if (!ar.ok || !"default#default".equals(ar.sansLoc)) {
                String why = !ar.error.isEmpty() ? ar.error : "The phone did not go back to Default (sans.loc reads \"" + ar.sansLoc + "\").";
                return FontLibrary.error("failed", why).put("readBack", rb);
            }
            FontLibrary.writeApplied(fmkDirs(), null, System.currentTimeMillis());
            boolean refreshed = fmkRefreshFontStyle(backend, 0);
            return new JSONObject().put("ok", true).put("readBack", rb).put("refreshed", refreshed);
        } catch (Throwable t) {
            return FontLibrary.error("failed", "The default font could not be put back: " + errMsg(t));
        }
    }

    // ---- emoji downloads ----

    /** Disconnects the downloads of these jobs (a window that closes: the ones it started, which it has just cancelled). */
    private static void fmkDisconnect(List<FontLibrary.Jobs.Job> jobs) {
        final List<java.net.HttpURLConnection> open = new ArrayList<java.net.HttpURLConnection>();
        for (FontLibrary.Jobs.Job j : jobs) {
            java.net.HttpURLConnection c = fmkConns.remove(j.id);
            if (c != null) open.add(c);
        }
        if (open.isEmpty()) return;
        Thread t = new Thread(new Runnable() {                          // closing a TLS connection writes to the network: never on the UI thread
            @Override
            public void run() {
                for (java.net.HttpURLConnection c : open) try { c.disconnect(); } catch (Throwable ignored) {}
            }
        }, "fontmaker-disconnect");
        t.setDaemon(true);
        t.start();
    }

    /**
     * Downloads one catalog emoji font (the build this phone gets: OpenMoji's COLRv0 one below Android 13) through HttpSafe, which follows
     * GitHub's redirect, into files/fontmaker/emoji/<id>.ttf. The file must have the exact size and SHA-256 the catalog gives; anything else
     * is deleted (EmojiCatalog.download fails closed). Twemoji's zip is checked whole, then its font is taken out and checked too.
     * Answer: window.onEmojiDone(id, {ok, size, sha256} | {ok:false, code, error}).
     */
    private void fmkDownloadJob(final FontLibrary.Jobs.Job job, final EmojiCatalog.Item item) {
        final FontLibrary.Dirs d = fmkDirs();
        final FontLibrary.Throttle throttle = new FontLibrary.Throttle(250);
        EmojiCatalog.Item b = item.forSdk(Build.VERSION.SDK_INT);
        final EmojiCatalog.Progress p = new EmojiCatalog.Progress() {
            @Override
            public void onProgress(long done, long total) {
                if (throttle.due("download", done, total, android.os.SystemClock.elapsedRealtime()))
                    notifyJs("window.onEmojiProgress && window.onEmojiProgress(" + JSONObject.quote(item.id) + ", " + done + ", " + total + ")");
            }

            @Override
            public boolean cancelled() {
                return job.cancelled() || activityDestroyed;
            }
        };
        JSONObject res;
        java.net.HttpURLConnection c = null;
        File zip = null;
        int status = 0;
        try {
            java.util.Map<String, String> hdr = new java.util.LinkedHashMap<String, String>();
            hdr.put("User-Agent", "ADB-Application-Manager");
            c = HttpSafe.open(b.url, 15000, 30000, hdr, new HttpSafe.Hops() {
                @Override
                public void opened(java.net.HttpURLConnection hop) throws IOException {
                    // each hop (the release address, then the one it redirects to) can be disconnected by Cancel while it connects or waits
                    fmkConns.put(job.id, hop);
                    if (p.cancelled()) throw new EmojiCatalog.VerifyException("cancelled", "The download was cancelled.");
                }
            });
            fmkConns.put(job.id, c);
            if (p.cancelled()) throw new EmojiCatalog.VerifyException("cancelled", "The download was cancelled.");
            int code = c.getResponseCode();
            if (code != 200) {
                status = code;
                throw new IOException("the server answered HTTP " + code);
            }
            InputStream in = c.getInputStream();
            try {
                File dest = d.emojiFile(item.id);
                if (b.isZip()) {
                    zip = new File(d.emoji, "." + item.id + ".zip");
                    EmojiCatalog.download(in, zip, b.zipSize, b.zipSha256, FontLibrary.MAX_EMOJI_BYTES, p);
                    EmojiCatalog.extractEntry(zip, b.zipEntry, dest, b.size, b.sha256, FontLibrary.MAX_EMOJI_BYTES, p);
                } else {
                    EmojiCatalog.download(in, dest, b.size, b.sha256, FontLibrary.MAX_EMOJI_BYTES, p);
                }
            } finally {
                try { in.close(); } catch (IOException ignored) {}
            }
            res = new JSONObject().put("ok", true).put("size", b.size).put("sha256", b.sha256);
        } catch (EmojiCatalog.VerifyException ve) {
            res = FontLibrary.error(ve.code, ve.getMessage());
        } catch (Throwable t) {
            res = p.cancelled() ? FontLibrary.error("cancelled", "The download was cancelled.") : FontLibrary.downloadError(status, errMsg(t));
        } finally {
            if (zip != null) zip.delete();
            fmkConns.remove(job.id);
            if (c != null) try { c.disconnect(); } catch (Throwable ignored) {}
            fmkJobs.finish(job);
        }
        notifyJs("window.onEmojiDone && window.onEmojiDone(" + JSONObject.quote(item.id) + ", " + JSONObject.quote(res.toString()) + ")");
    }

    // ---- the system emoji (RootGate.uid0), until the next restart ----

    /** The boot this phone is in (/proc/sys/kernel/random/boot_id): a swap recorded in another boot was undone by that restart. "" when unreadable. */
    private static String fmkBootId() {
        try {
            byte[] b = java.nio.file.Files.readAllBytes(new File("/proc/sys/kernel/random/boot_id").toPath());
            return new String(b, "UTF-8").trim();
        } catch (Throwable t) {
            return "";
        }
    }

    /** A small system file (fonts.xml), read by the app, else through the backend's shell; "" when neither can. */
    private String fmkReadSystemFile(String backend, File f) {
        try {
            if (f.isFile() && f.length() <= 4L * 1024 * 1024) return new String(java.nio.file.Files.readAllBytes(f.toPath()), "UTF-8");
        } catch (Throwable unreadable) {}
        try {
            return fmkRun(backend, "cat " + BackupScripts.quote(f.getAbsolutePath()) + " 2>/dev/null", null, 15000);
        } catch (Throwable t) {
            return "";
        }
    }

    /** The phone's emoji font files: the swap's targets (in /system/fonts or /product/fonts), and the updated ones its font map draws from instead. */
    private static final class FmkEmoji {
        final List<String> targets, updated;

        FmkEmoji(List<String> targets, List<String> updated) {
            this.targets = targets;
            this.updated = updated;
        }
    }

    /**
     * The emoji files the swap binds over: every und-Zsye family's file in fonts.xml and font_fallback.xml that is on this phone (in
     * /system/fonts or /product/fonts). And the updated emoji fonts under /data/fonts/files the phone draws from instead (listed with the
     * backend's shell, the app cannot): the swap never binds over those, and while there is one it does not run.
     */
    private FmkEmoji fmkEmojiFiles(String backend) {
        SamsungFonts.Roots r = SamsungFonts.Roots.system();
        String fontsXml = fmkReadSystemFile(backend, new File("/system/etc/fonts.xml"));
        String fallbackXml = fmkReadSystemFile(backend, new File("/system/etc/font_fallback.xml"));
        List<String> updatable = new ArrayList<String>();
        try {
            String out = fmkRun(backend, "find " + BackupScripts.quote(r.dataFonts) + " -type f 2>/dev/null", null, 20000);
            for (String line : out.split("\n")) {
                String t = line.trim();
                if (t.startsWith(r.dataFonts + "/")) updatable.add(t);
            }
        } catch (Throwable ignored) {}
        // a file reached through a link (a /product that links to /system/product, an emoji file that links to another) is bound, and listed
        // in the mount table, under its real path: the swap uses that path when it is a file in the font folders, each once
        List<String> targets = new ArrayList<String>();
        for (String t : SamsungFonts.emojiFiles(r, fontsXml, fallbackXml)) {
            try {
                File f = new File(t);
                if (!f.exists()) continue;
                String real = f.getCanonicalPath();
                if (SamsungFonts.isSwapTarget(r, real) && !targets.contains(real)) targets.add(real);
            } catch (IOException unreadable) {}
        }
        return new FmkEmoji(targets, SamsungFonts.updatedEmojiFiles(r, fontsXml, fallbackXml, updatable));
    }

    /** The swap's own binds, from init's mount table (/proc/1/mountinfo) read through the backend's shell. */
    private SamsungFonts.Mounts fmkMounts(String backend) throws Exception {
        return SamsungFonts.parseMounts(fmkRun(backend, SamsungFonts.emojiMountsScript(SamsungFonts.Roots.system()), null, 20000));
    }

    /**
     * Takes the swap's own binds off: on this boot's recorded targets, and on every file the mount table shows a bind of the swap's own on (a
     * swap whose record was lost). The script takes off only the swap's own binds on top of a file, never another tool's, and reads back each
     * file's hash and how many of the swap's binds are left on it. Null when the mount table cannot be read: nothing is taken off then.
     */
    private List<SamsungFonts.BindResult> fmkTakeOff(String backend, FontLibrary.Swap active) throws Exception {
        SamsungFonts.Mounts m = fmkMounts(backend);
        if (!m.readable) return null;
        List<String> targets = FontLibrary.undoTargets(active, m.targets);
        if (targets.isEmpty()) return new ArrayList<SamsungFonts.BindResult>();
        return SamsungFonts.parseSwap(fmkRun(backend, SamsungFonts.emojiUndoScript(SamsungFonts.Roots.system(), targets), null, 60000));
    }

    /** The names a staged emoji copy can have in /data/adb/adbmgr_fonts/: one per catalog font. */
    private static List<String> fmkStagedNames() {
        List<String> out = new ArrayList<String>();
        for (EmojiCatalog.Item it : EmojiCatalog.ITEMS) out.add(it.id + ".ttf");
        return out;
    }

    /**
     * Deletes the staged copies among names that nothing is bound from any more (the script reads the mount table again, so a copy still in
     * use stays) and reads back that they are gone. True when every one of them is gone.
     */
    private boolean fmkRemoveStaged(String backend, List<String> names) {
        try {
            Map<String, Boolean> gone = SamsungFonts.parseStaged(fmkRun(backend, SamsungFonts.removeStagedScript(SamsungFonts.Roots.system(), names), null, 30000));
            for (String n : names) if (!Boolean.TRUE.equals(gone.get(n))) return false;
            return true;
        } catch (Throwable t) {
            return false;
        }
    }

    /** After a downloaded emoji font is deleted, its staged copy goes too, when the root user is on and nothing is bound from it. */
    private void fmkDropStaged(final String id) {
        try {
            fontPrivExec.submit(new Runnable() {
                @Override
                public void run() {
                    synchronized (fmkSysLock) {
                        if (activityDestroyed) return;
                        String backend = fmkGate(true);
                        if (backend != null) fmkRemoveStaged(backend, Collections.singletonList(id + ".ttf"));
                    }
                }
            });
        } catch (RejectedExecutionException closing) {}
    }

    /**
     * {ok, unlocked, lockReason, targets, active:{id, name}|null, blocked:{code, error}|null}. Active is this boot's swap or, when its record
     * was lost, the font a bind of the swap's own still shows (so Undo is offered). Blocked says why a swap would be refused now: the phone's
     * emoji come from an update in /data/fonts/files, or the mount table cannot be read. It only reads, and waits for an Apply or Undo another
     * window runs: a copy a restart left unused is deleted by the next Apply, or with its emoji font.
     */
    private JSONObject fmkSysStatus() {
        synchronized (fmkSysLock) {
            try {
                JSONObject o = new JSONObject().put("ok", true);
                String backend = fmkGate(true);
                if (backend == null) return o.put("unlocked", false).put("lockReason", FMK_LOCK_SYS).put("targets", new JSONArray()).put("active", JSONObject.NULL).put("blocked", JSONObject.NULL);
                FontLibrary.Swap s = FontLibrary.activeSwap(fmkDirs(), fmkBootId());
                SamsungFonts.Mounts m = fmkMounts(backend);
                String id = s != null ? s.id : m.showing();
                FmkEmoji ef = fmkEmojiFiles(backend);
                String code = !m.readable ? "mounts_unreadable" : !ef.updated.isEmpty() ? "emoji_updated" : null;
                EmojiCatalog.Item it = id == null ? null : EmojiCatalog.byId(id);
                return o.put("unlocked", true).put("lockReason", "").put("targets", new JSONArray(ef.targets))
                        .put("active", id == null ? JSONObject.NULL : new JSONObject().put("id", id).put("name", it != null ? it.name : id))
                        .put("blocked", code == null ? JSONObject.NULL : new JSONObject().put("code", code).put("error", "emoji_updated".equals(code) ? FMK_EMOJI_UPDATED : FMK_NO_MOUNTS));
            } catch (Throwable t) {
                return FontLibrary.error("failed", errMsg(t));
            }
        }
    }

    /**
     * Uses a downloaded emoji font as the phone's emoji until the next restart: the file (its SHA-256 checked again) is streamed to
     * /data/adb/adbmgr_fonts/<id>.ttf and checked there, then bind-mounted over each target, whose hash is read back before and after. It
     * refuses, changing nothing, on a phone whose emoji come from an update in /data/fonts/files (never bound over) or whose mount table
     * cannot be read. The swap's own binds still in place go first (fmkTakeOff), and the copies nothing is bound from any more are deleted.
     * The swap is recorded with this boot's id before the bind, so Undo knows its targets even when the app dies right after, and again
     * afterwards with what was bound and each target's hash before. {ok, readBack:[{target, sha256, ok}]} or {ok:false, code, error, readBack}.
     */
    private JSONObject fmkSysApply(EmojiCatalog.Item item) {
        synchronized (fmkSysLock) {
            try {
                String backend = fmkGate(true);
                if (backend == null) return FontLibrary.error("locked", FMK_LOCK_SYS);
                FontLibrary.Dirs d = fmkDirs();
                File f = d.emojiFile(item.id);
                EmojiCatalog.Item kept = FontLibrary.keptBuild(item, f);
                if (kept == null) return FontLibrary.error("not_downloaded", "Download " + item.name + " first.");
                // Android draws COLRv1 from 13 on: an older phone would show every emoji blank until the restart (the page offers only what it can draw)
                if ("COLRv1".equals(kept.format) && Build.VERSION.SDK_INT < 33) return FontLibrary.error("not_usable", item.name + " needs Android 13 or newer.");
                String sha = FontLibrary.sha256(f);
                if (!kept.sha256.equals(sha)) return FontLibrary.error("emoji_changed", "The downloaded file changed on the phone. Delete it and download it again.");
                SamsungFonts.Roots r = SamsungFonts.Roots.system();
                // the phone draws its emoji from an update in /data/fonts/files: that file is never bound over, and a bind over the original would not show
                FmkEmoji ef = fmkEmojiFiles(backend);
                if (!ef.updated.isEmpty()) return FontLibrary.error("emoji_updated", FMK_EMOJI_UPDATED);
                String boot = fmkBootId();
                FontLibrary.Swap prev = FontLibrary.activeSwap(d, boot);       // a record from another boot: that restart took its binds away
                // a swap on top of one still bound would stack, and Undo would take only the top one away: the swap's own binds go first (this
                // boot's record and whatever the mount table shows), and one that stays stops it
                List<SamsungFonts.BindResult> off = fmkTakeOff(backend, prev);
                if (off == null) return FontLibrary.error("mounts_unreadable", FMK_NO_MOUNTS);
                for (SamsungFonts.BindResult b : off) {
                    if (b.own != 0) return FontLibrary.error("failed", "The emoji used before could not be taken away. Restart the phone, then try again.");
                }
                FontLibrary.clearSwap(d);
                fmkRemoveStaged(backend, fmkStagedNames());
                List<String> targets = ef.targets;
                if (targets.isEmpty()) return FontLibrary.error("no_targets", "This phone's emoji font file was not found.");
                String name = item.id + ".ttf";
                SamsungFonts.WriteResult w = SamsungFonts.parseWrite(fmkRun(backend, SamsungFonts.stageEmojiScript(r, name, f.length(), sha), f, 180000), name);
                if (!w.ok || !sha.equals(w.sha256)) return FontLibrary.error("failed", w.ok ? "The emoji font did not arrive whole on the phone." : w.error);
                String bootTag = boot.isEmpty() ? "unknown" : boot;
                // remembered before the bind: a bind the app could not record afterwards (the app killed, the storage full) is still known to Undo
                FontLibrary.writeSwap(d, new FontLibrary.Swap(item.id, bootTag, sha, targets));
                List<SamsungFonts.BindResult> bound = SamsungFonts.parseSwap(fmkRun(backend, SamsungFonts.emojiSwapScript(r, r.adbmgrFonts() + "/" + name, targets), null, 60000));
                JSONArray rb = new JSONArray();
                List<String> mounted = new ArrayList<String>();
                Map<String, String> originals = new java.util.LinkedHashMap<String, String>();
                boolean all = true, any = false;
                for (SamsungFonts.BindResult b : bound) {
                    if ("missing".equals(b.state)) continue;
                    boolean good = "ok".equals(b.state) && sha.equals(b.sha256);
                    if ("ok".equals(b.state)) {
                        mounted.add(b.target);
                        if (b.original != null) originals.put(b.target, b.original);
                    }
                    rb.put(new JSONObject().put("target", b.target).put("sha256", b.sha256 == null ? "" : b.sha256).put("ok", good));
                    all &= good;
                    any |= good;
                }
                if (mounted.isEmpty()) {
                    FontLibrary.clearSwap(d);
                    fmkRemoveStaged(backend, Collections.singletonList(name));          // nothing is bound from the copy
                } else {
                    try {
                        FontLibrary.writeSwap(d, new FontLibrary.Swap(item.id, bootTag, sha, mounted, originals));   // even a part: Undo must know it
                    } catch (IOException notNow) {}                                     // the record written before the bind still names every target
                }
                if (!any) return FontLibrary.error("failed", "No emoji file could be replaced.").put("readBack", rb);
                if (!all) return FontLibrary.error("failed", "Some emoji files did not change.").put("readBack", rb);
                return new JSONObject().put("ok", true).put("readBack", rb);
            } catch (Throwable t) {
                return FontLibrary.error("failed", "The emoji could not be swapped: " + errMsg(t));
            }
        }
    }

    /**
     * Takes the swap off (fmkTakeOff: only the swap's own binds, on this boot's recorded targets and wherever the mount table shows one) and
     * reads each file back: a file is back when none of the swap's binds is left on it and it hashes as it did before the swap (when that was
     * recorded). Then the record goes, and the staged copy is deleted and read back. {ok, readBack, copyRemoved} or {ok:false, code, error, readBack}.
     */
    private JSONObject fmkSysUndo() {
        synchronized (fmkSysLock) {
            try {
                String backend = fmkGate(true);
                if (backend == null) return FontLibrary.error("locked", FMK_LOCK_SYS);
                FontLibrary.Dirs d = fmkDirs();
                FontLibrary.Swap s = FontLibrary.activeSwap(d, fmkBootId());   // a record from another boot: that restart took its binds away
                List<SamsungFonts.BindResult> undone = fmkTakeOff(backend, s);
                if (undone == null) return FontLibrary.error("mounts_unreadable", FMK_NO_MOUNTS);
                JSONArray rb = new JSONArray();
                boolean all = true;
                for (SamsungFonts.BindResult b : undone) {
                    boolean good = b.back(s == null ? null : s.originals.get(b.target));
                    rb.put(new JSONObject().put("target", b.target).put("sha256", b.sha256 == null ? "" : b.sha256).put("ok", good));
                    all &= good;
                }
                if (!all) return FontLibrary.error("failed", "Some emoji files did not change. Restart the phone to undo the swap.").put("readBack", rb);
                FontLibrary.clearSwap(d);
                boolean removed = fmkRemoveStaged(backend, fmkStagedNames());
                return new JSONObject().put("ok", true).put("readBack", rb).put("copyRemoved", removed);
            } catch (Throwable t) {
                return FontLibrary.error("failed", "The swap could not be undone: " + errMsg(t));
            }
        }
    }
    // FONTMAKER:END

    // ---------------------------------------------------------------------------------------------
    // Backup and restore
    //
    // A backup is one .adbbackup file (a zip): backup.json, apk/<each APK>, and data.tar when the data
    // was included. App data is private to the app, so it needs Root; the APK, permissions and app ops
    // work in every privileged mode.
    // ---------------------------------------------------------------------------------------------

    private static final int REQ_PICK_BACKUP = 4202;
    private static final int REQ_PICK_INSTALL = 4203;
    // Distinguishes each no-privilege install's result broadcast so two in-flight installs can't cross wires.
    private int installReceiverSeq = 0;
    private final java.util.concurrent.atomic.AtomicBoolean backupBusy = new java.util.concurrent.atomic.AtomicBoolean(false);
    // A real app + its data is rarely anywhere near this; bounds how much a crafted or damaged backup can
    // make the restore step write before it gives up, instead of grinding on a zip bomb until storage fills.
    private static final long MAX_RESTORE_EXTRACT_BYTES = 8L * 1024 * 1024 * 1024;

    private void backupEvent(String op, String stage, int pct, String message) {
        try {
            JSONObject o = new JSONObject();
            o.put("op", op);
            o.put("stage", stage);
            o.put("pct", pct);
            o.put("msg", message);
            notifyJs("window.onBackupProgress && window.onBackupProgress(" + JSONObject.quote(o.toString()) + ")");
        } catch (Exception ignored) {}
    }

    private void backupDone(JSONObject res) {
        notifyJs("window.onBackupDone && window.onBackupDone(" + JSONObject.quote(res.toString()) + ")");
    }

    /** Runs a script as root through su, whatever working mode is selected. */
    private String runRootScript(String script, int timeoutMs) throws Exception {
        File f = new File(getCacheDir(), "root_" + System.nanoTime() + ".sh");
        try {
            FileOutputStream out = new FileOutputStream(f);
            try {
                out.write(script.getBytes("UTF-8"));
            } finally {
                out.close();
            }
            f.setReadable(true, false);
            ProcessBuilder pb = new ProcessBuilder("su", "-c", "sh " + BackupScripts.quote(f.getAbsolutePath()));
            pb.redirectErrorStream(true);
            String out2 = runProcessWithTimeout(pb, timeoutMs);
            return out2 == null ? "" : out2;
        } finally {
            f.delete();
        }
    }

    private static String rootError(String out) {
        for (String line : out.split("\n")) {
            if (line.startsWith("ERROR")) return line.substring(line.indexOf(':') + 1).trim();
        }
        return out.trim().isEmpty() ? "Root access was denied or is not available" : out.trim();
    }

    private static String installHint(String out) {
        String o = out == null ? "" : out;
        if (o.contains("INSTALL_FAILED_VERSION_DOWNGRADE")) return "A newer version is installed than the one in the backup. Uninstall the app first (keep its data if you want it restored), then restore.";
        if (o.contains("INSTALL_FAILED_UPDATE_INCOMPATIBLE") || o.contains("signatures do not match")) return "The installed app is signed with a different key than the backup. Uninstall it first, then restore.";
        if (o.contains("INSTALL_FAILED_INSUFFICIENT_STORAGE")) return "Not enough storage to install the app.";
        if (o.contains("INSTALL_FAILED_MISSING_SPLIT")) return "A split APK is missing from the backup.";
        return o.trim().isEmpty() ? "install failed" : o.trim();
    }

    private InputStream openRef(String ref) throws Exception {
        if (ref != null && ref.startsWith("content://")) {
            InputStream in = getContentResolver().openInputStream(Uri.parse(ref));
            if (in == null) throw new java.io.FileNotFoundException("cannot open the backup file");
            return in;
        }
        // A path the page (or an "Open with" intent) names: never the app's own private data, which would otherwise be copied into the
        // Installer's work folder, a folder the share sheet and VirusTotal may read.
        return openUnlessPrivate(new File(ref));
    }

    /**
     * Resolves the primary-storage aliases to the concrete /storage/emulated/0 path. /sdcard and
     * /storage/self/primary are symlinks, and the "self" view resolves differently for an ADB/Shizuku
     * shell (uid 2000) than for the app, so a shell often can't read through them. The concrete
     * /storage/emulated/0 path is readable the same way by both, so browsing storage works regardless
     * of mode. Also collapses duplicate slashes, strips a trailing slash (except root), makes the path absolute and
     * folds "." and ".." (after the aliases, as the shell would follow them), so a typed or composed path such as
     * /storage/emulated/0/../0 can neither reach nor hide a place the protection list names.
     */
    private String fmCanonicalPath(String path) {
        // A storage root added through pickAddStorage() is an opaque content:// tree/document URI, not a POSIX
        // path - running it through alias-swapping and "." / ".." folding would corrupt it (SAF URIs can
        // legitimately contain their own "/" and ":" in the document id). Pass it through untouched.
        if (path != null && path.startsWith("content://")) return path;
        String primary = "/storage/emulated/0";
        try {
            File ext = android.os.Environment.getExternalStorageDirectory();
            if (ext != null && ext.getAbsolutePath() != null && !ext.getAbsolutePath().isEmpty())
                primary = ext.getAbsolutePath();
        } catch (Exception ignored) {}
        return FileRules.canonical(path, primary);
    }

    /** A human-readable name for a picked storage tree: the root document's own display name, falling back to
     *  the volume-ish part of its tree id (most DocumentsProviders encode it as "authority:label", e.g.
     *  "primary:Download" or an SD card's "1234-5678:"), and the raw URI as a last resort. */
    private String storageRootLabel(Uri treeUri) {
        String docId = null;
        try {
            docId = android.provider.DocumentsContract.getTreeDocumentId(treeUri);
            Uri docUri = android.provider.DocumentsContract.buildDocumentUriUsingTree(treeUri, docId);
            android.database.Cursor c = getContentResolver().query(docUri,
                    new String[]{android.provider.DocumentsContract.Document.COLUMN_DISPLAY_NAME}, null, null, null);
            if (c != null) {
                try {
                    if (c.moveToFirst()) {
                        String name = c.getString(0);
                        if (name != null && !name.isEmpty()) return name;
                    }
                } finally { c.close(); }
            }
        } catch (Throwable ignored) {}
        if (docId != null) {
            int colon = docId.indexOf(':');
            if (colon >= 0 && colon + 1 < docId.length()) return docId.substring(colon + 1);
            if (colon < 0 && !docId.isEmpty()) return docId;
        }
        return treeUri.toString();
    }

    private boolean backupExists(String ref) {
        try {
            if (ref != null && ref.startsWith("content://")) {
                android.os.ParcelFileDescriptor pfd = getContentResolver().openFileDescriptor(Uri.parse(ref), "r");
                if (pfd == null) return false;
                pfd.close();
                return true;
            }
            return ref != null && new File(ref).exists();
        } catch (Exception e) {
            return false;
        }
    }

    /** Held for every read-modify-write of the backups list (a backup that finishes, a delete, the pruning of missing files). */
    private final Object backupIndexLock = new Object();

    private JSONArray backupIndex() {
        try {
            return new JSONArray(prefs.getString("backups_index", "[]"));
        } catch (Exception e) {
            return new JSONArray();
        }
    }

    /** backup.json must be the first entry, so this reads a few KB even from a multi-GB backup. */
    private JSONObject readBackupMeta(String ref) throws Exception {
        java.util.zip.ZipInputStream zin = new java.util.zip.ZipInputStream(new java.io.BufferedInputStream(openRef(ref)));
        try {
            // A picked backup file is untrusted, so scanning forward for backup.json by name cannot be
            // allowed: skipping a non-matching entry via another getNextEntry() call first fully inflates
            // it to find its end, with no byte cap - a tiny zip bomb placed before backup.json would be
            // decompressed in full before this method ever gets to check anything. Require it to be the
            // very first entry instead and refuse immediately otherwise.
            java.util.zip.ZipEntry e = zin.getNextEntry();
            if (e == null || !"backup.json".equals(e.getName())) {
                throw new IllegalStateException("not a valid backup file (backup.json must be the first entry)");
            }
            {
                java.io.ByteArrayOutputStream buf = new java.io.ByteArrayOutputStream();
                byte[] b = new byte[8192];
                int n;
                while ((n = zin.read(b)) > 0) {
                    buf.write(b, 0, n);
                    if (buf.size() > 1024 * 1024) throw new IllegalStateException("backup.json is too large");
                }
                JSONObject meta = new JSONObject(buf.toString("UTF-8"));
                if (!"adb-app-manager-backup".equals(meta.optString("format")) || meta.optInt("v") != 1) {
                    throw new IllegalStateException("this backup was made by a different version of the app");
                }
                BackupScripts.checkedPackage(meta.optString("pkg"));
                return meta;
            }
        } finally {
            zin.close();
        }
    }

    private static boolean isDangerousPermission(PackageManager pm, String name) {
        try {
            android.content.pm.PermissionInfo info = pm.getPermissionInfo(name, 0);
            return (info.protectionLevel & android.content.pm.PermissionInfo.PROTECTION_MASK_BASE) == android.content.pm.PermissionInfo.PROTECTION_DANGEROUS;
        } catch (Exception e) {
            return false;
        }
    }

    private void runBackup(final String pkg, final boolean includeData) {
        if (!backupBusy.compareAndSet(false, true)) {
            JSONObject busy = new JSONObject();
            try { busy.put("op", "backup"); busy.put("ok", false); busy.put("error", "Another backup or restore is still running"); } catch (Exception ignored) {}
            backupDone(busy);
            return;
        }
        executor.submit(new Runnable() {
            @Override
            public void run() {
                JSONObject res = new JSONObject();
                File tmpTar = null;
                Object[] target = null;
                try {
                    res.put("op", "backup");
                    res.put("pkg", pkg);
                    BackupScripts.checkedPackage(pkg);
                    if ("standard".equals(resolveExecMode())) {
                        throw new IllegalStateException("backing up needs ADB, Shizuku or Root (app ops can't be read otherwise). Set up a working mode first.");
                    }
                    PackageManager pm = getPackageManager();
                    ApplicationInfo ai = pm.getApplicationInfo(pkg, PackageManager.MATCH_UNINSTALLED_PACKAGES);
                    int sigFlags = Build.VERSION.SDK_INT >= 28 ? PackageManager.GET_SIGNING_CERTIFICATES : PackageManager.GET_SIGNATURES;
                    PackageInfo pi = pm.getPackageInfo(pkg, PackageManager.MATCH_UNINSTALLED_PACKAGES | PackageManager.GET_PERMISSIONS | sigFlags);
                    File[] files = apkFiles(ai);
                    if (files.length == 0 || !files[0].canRead()) throw new IllegalStateException("the APK is not readable");
                    String label = pm.getApplicationLabel(ai).toString();
                    String version = pi.versionName != null ? pi.versionName : String.valueOf(versionCodeOf(pi));
                    backupEvent("backup", "info", 5, "Reading " + label + "...");

                    JSONObject meta = new JSONObject();
                    meta.put("format", "adb-app-manager-backup");
                    meta.put("v", 1);
                    meta.put("pkg", pkg);
                    meta.put("label", label);
                    meta.put("versionName", version);
                    meta.put("versionCode", versionCodeOf(pi));
                    meta.put("createdAt", System.currentTimeMillis());
                    meta.put("device", Build.MODEL);
                    meta.put("sdk", Build.VERSION.SDK_INT);
                    meta.put("installer", installerOf(pkg));
                    meta.put("suspended", (ai.flags & ApplicationInfo.FLAG_SUSPENDED) != 0);
                    JSONArray signers = new JSONArray();
                    for (String d : signerDigests(pi, false)) signers.put(d);
                    meta.put("signers", signers);
                    JSONArray perms = new JSONArray();
                    if (pi.requestedPermissions != null && pi.requestedPermissionsFlags != null) {
                        for (int i = 0; i < pi.requestedPermissions.length; i++) {
                            String name = pi.requestedPermissions[i];
                            if ((pi.requestedPermissionsFlags[i] & PackageInfo.REQUESTED_PERMISSION_GRANTED) != 0
                                    && BackupScripts.isPermission(name) && isDangerousPermission(pm, name)) perms.put(name);
                        }
                    }
                    meta.put("permissions", perms);
                    JSONArray warnings = new JSONArray();
                    JSONObject ops = new JSONObject();
                    try {
                        String opsRaw = new AndroidBridge().executeShell("cmd appops get " + pkg);
                        for (Map.Entry<String, String> e : BackupScripts.changedAppOps(opsRaw).entrySet()) {
                            ops.put(e.getKey(), e.getValue());
                        }
                        // An empty result is the common, legitimate case (no overrides) - but if the backend
                        // reported a failure instead of actual appops output, that looks identical unless
                        // checked for, and the backup would otherwise silently claim a complete settings
                        // snapshot it doesn't have.
                        String lowered = opsRaw == null ? "" : opsRaw.toLowerCase();
                        if (ops.length() == 0 && (opsRaw == null || lowered.contains("error") || lowered.contains("exception") || lowered.contains("denied") || lowered.contains("unknown command"))) {
                            warnings.put("Could not read this app's app ops" + (opsRaw == null || opsRaw.trim().isEmpty() ? "" : " (" + opsRaw.trim() + ")") + "; any app op overrides will be missing from this backup");
                        }
                    } catch (Exception e) {
                        warnings.put("Could not read this app's app ops (" + e.getMessage() + "); any app op overrides will be missing from this backup");
                    }
                    meta.put("appops", ops);
                    boolean withData = false;
                    if (includeData) {
                        backupEvent("backup", "data", 20, "Backing up data (Root)...");
                        tmpTar = new File(getCacheDir(), "backup_data_" + System.nanoTime() + ".tar");
                        String out = runRootScript(BackupScripts.dataBackup("/data", pkg, tmpTar.getAbsolutePath(), android.os.Process.myUid()), 900000);
                        if (!FileRules.okLine(out, "OK")) throw new IllegalStateException("data: " + rootError(out));
                        if (out.contains("WARN")) warnings.put("Some data changed while it was being read; the backup may be incomplete");
                        withData = true;
                    }
                    meta.put("hasData", withData);
                    meta.put("dataBytes", withData ? tmpTar.length() : 0);

                    backupEvent("backup", "write", 55, "Saving the backup...");
                    // Millisecond precision: on Android 8-9 (API 26-28, see openDownloadOutput) this name is
                    // opened directly with FileOutputStream, so two backups of the same app/version within
                    // the same minute would otherwise overwrite each other while both index records still
                    // point at one file - and a failed second write could delete an earlier, valid backup.
                    String stamp = new java.text.SimpleDateFormat("yyyyMMdd-HHmmss-SSS", java.util.Locale.US).format(new java.util.Date());
                    String fileName = (label.isEmpty() ? pkg : label) + "_" + version + "_" + stamp + ".adbbackup";
                    target = openDownloadOutput(fileName, "application/octet-stream", "Backups");
                    java.util.zip.ZipOutputStream zip = new java.util.zip.ZipOutputStream(new java.io.BufferedOutputStream((OutputStream) target[0]));
                    long total = 0;
                    try {
                        zip.setLevel(1); // APKs are already compressed; keep it fast
                        zip.putNextEntry(new java.util.zip.ZipEntry("backup.json"));
                        zip.write(meta.toString(2).getBytes("UTF-8"));
                        zip.closeEntry();
                        for (int i = 0; i < files.length; i++) {
                            // apkFiles() always returns the base APK (ai.sourceDir) first; name it "base.apk"
                            // regardless of its real on-disk name, since restore looks for that name and a
                            // system app's source file is rarely actually called that (e.g. .../Settings.apk)
                            String entryName = i == 0 ? "base.apk" : files[i].getName();
                            zip.putNextEntry(new java.util.zip.ZipEntry("apk/" + entryName));
                            total += copyFile(files[i], zip);
                            zip.closeEntry();
                        }
                        if (withData) {
                            zip.putNextEntry(new java.util.zip.ZipEntry("data.tar"));
                            total += copyFile(tmpTar, zip);
                            zip.closeEntry();
                        }
                    } finally {
                        zip.close();
                    }

                    JSONObject rec = new JSONObject();
                    rec.put("ref", target[2]);
                    rec.put("path", target[1]);
                    rec.put("name", fileName);
                    rec.put("pkg", pkg);
                    rec.put("label", label);
                    rec.put("versionName", version);
                    rec.put("createdAt", meta.getLong("createdAt"));
                    rec.put("bytes", total);
                    rec.put("hasData", withData);
                    synchronized (backupIndexLock) {
                        JSONArray index = backupIndex();
                        JSONArray next = new JSONArray();
                        next.put(rec);
                        for (int i = 0; i < index.length() && next.length() < 200; i++) next.put(index.get(i));
                        prefs.edit().putString("backups_index", next.toString()).apply();
                    }

                    res.put("ok", true);
                    res.put("label", label);
                    res.put("path", target[1]);
                    res.put("ref", target[2]);
                    res.put("bytes", total);
                    res.put("hasData", withData);
                    res.put("warnings", warnings);
                } catch (Exception e) {
                    // A target already created (a MediaStore row on Android 10+, indexed the moment it's
                    // inserted, before any bytes are written) must not survive a failure partway through
                    // writing it - otherwise a failed backup still shows up in Downloads looking like a
                    // complete, restorable .adbbackup file.
                    deleteDownloadTarget(target);
                    try {
                        res.put("ok", false);
                        res.put("error", e.getMessage() != null ? e.getMessage() : e.getClass().getSimpleName());
                    } catch (Exception ignored) {}
                } finally {
                    if (tmpTar != null) tmpTar.delete();
                    backupBusy.set(false);
                }
                backupDone(res);
            }
        });
    }

    private void runRestore(final String ref, final boolean restoreData) {
        if (!backupBusy.compareAndSet(false, true)) {
            JSONObject busy = new JSONObject();
            try { busy.put("op", "restore"); busy.put("ok", false); busy.put("error", "Another backup or restore is still running"); } catch (Exception ignored) {}
            backupDone(busy);
            return;
        }
        executor.submit(new Runnable() {
            @Override
            public void run() {
                JSONObject res = new JSONObject();
                File work = new File(getCacheDir(), "restore_" + System.nanoTime());
                try {
                    res.put("op", "restore");
                    JSONObject meta = readBackupMeta(ref);
                    // backup.json can come from "Choose backup file..." - an arbitrary file the user picked -
                    // so nothing in it is trusted yet. It only supplies a label for the UI until the APK inside
                    // proves what it actually is, below.
                    String claimedPkg = meta.optString("pkg", "");
                    res.put("pkg", claimedPkg);
                    res.put("label", meta.optString("label", claimedPkg));
                    if ("standard".equals(resolveExecMode())) {
                        throw new IllegalStateException("restoring needs ADB, Shizuku or Root. Set up a working mode first.");
                    }
                    boolean wantData = restoreData && meta.optBoolean("hasData");
                    if (restoreData && !meta.optBoolean("hasData")) {
                        res.put("data", "this backup has no data");
                    }

                    backupEvent("restore", "read", 10, "Reading the backup...");
                    File apkDir = new File(work, "apk");
                    apkDir.mkdirs();
                    File dataTar = wantData ? new File(work, "data.tar") : null;
                    long extracted = 0;
                    java.util.zip.ZipInputStream zin = new java.util.zip.ZipInputStream(new java.io.BufferedInputStream(openRef(ref)));
                    try {
                        java.util.zip.ZipEntry e;
                        while ((e = zin.getNextEntry()) != null) {
                            String n = e.getName();
                            // runBackup always writes data.tar last. Skipping an unwanted entry by calling
                            // getNextEntry() again would still make ZipInputStream fully inflate it first just to
                            // find the end - for a multi-gigabyte data.tar that defeats the byte cap below before
                            // it ever runs. Since nothing of ours follows data.tar, stop scanning instead.
                            if ("data.tar".equals(n) && dataTar == null) break;
                            File dest = null;
                            if (n.matches("apk/[A-Za-z0-9_.+-]+\\.apk")) dest = new File(apkDir, n.substring(4));
                            else if ("data.tar".equals(n)) dest = dataTar;
                            // Anything else in the file is ignored, but still has to be read through the same
                            // counted loop below: a bare "continue" here would make the next getNextEntry()
                            // call silently inflate the whole entry first to find its end, bypassing the byte
                            // cap entirely for a huge entry under a name this code doesn't recognize.
                            OutputStream out = dest != null ? new FileOutputStream(dest) : new OutputStream() {
                                public void write(int b) {}
                                public void write(byte[] b, int off, int len) {}
                            };
                            try {
                                byte[] buf = new byte[65536];
                                int r;
                                while ((r = zin.read(buf)) > 0) {
                                    extracted += r;
                                    // A real app plus its data is rarely anywhere near this; past it, this is either
                                    // a damaged file or one crafted to fill the phone's storage, so stop reading it.
                                    if (extracted > MAX_RESTORE_EXTRACT_BYTES) {
                                        throw new IllegalStateException("this backup is far larger than any real app (stopped past "
                                                + (MAX_RESTORE_EXTRACT_BYTES / (1024 * 1024)) + " MB) - it looks damaged or unsafe to extract");
                                    }
                                    out.write(buf, 0, r);
                                }
                            } finally {
                                out.close();
                            }
                        }
                    } finally {
                        zin.close();
                    }
                    File[] apks = apkDir.listFiles();
                    if (apks == null || apks.length == 0) throw new IllegalStateException("the backup has no APK");
                    java.util.Arrays.sort(apks);
                    // The base APK must come first
                    List<File> ordered = new ArrayList<File>();
                    File baseApk = null;
                    for (File f : apks) if (f.getName().equals("base.apk")) { ordered.add(f); baseApk = f; }
                    for (File f : apks) if (!f.getName().equals("base.apk")) ordered.add(f);
                    if (baseApk == null) throw new IllegalStateException("the backup has no base.apk");

                    // The truth from here on is the APK itself, never backup.json: a picked file can claim to be
                    // anything, but its APK cannot lie about the package name it installs as or who signed it.
                    PackageManager pm = getPackageManager();
                    int sigFlags = Build.VERSION.SDK_INT >= 28 ? PackageManager.GET_SIGNING_CERTIFICATES : PackageManager.GET_SIGNATURES;
                    PackageInfo archiveInfo = pm.getPackageArchiveInfo(baseApk.getAbsolutePath(), sigFlags);
                    if (archiveInfo == null || archiveInfo.packageName == null) {
                        throw new IllegalStateException("base.apk in this backup could not be read as an APK");
                    }
                    final String pkg = archiveInfo.packageName;
                    res.put("pkg", pkg);
                    if (!claimedPkg.isEmpty() && !claimedPkg.equals(pkg)) {
                        throw new IllegalStateException("backup.json says " + claimedPkg + " but base.apk installs as " + pkg + " - this backup looks damaged or tampered with");
                    }
                    long archiveVersionCode = versionCodeOf(archiveInfo);
                    java.util.Set<String> archiveSigners = signerDigests(archiveInfo, true);

                    // Same package already installed? Compare keys and versions - both read from the APK above,
                    // not from backup.json - before deciding whether install can be skipped.
                    boolean installed = false;
                    boolean sameVersion = false;
                    try {
                        PackageInfo cur = pm.getPackageInfo(pkg, sigFlags);
                        installed = (cur.applicationInfo.flags & ApplicationInfo.FLAG_INSTALLED) != 0;
                        if (installed) {
                            requireCompatibleSigner(signerDigests(cur, true), archiveSigners,
                                    "the installed app is signed with a different key than this backup's APK. Uninstall it first, then restore.");
                        }
                        sameVersion = installed && versionCodeOf(cur) == archiveVersionCode;
                    } catch (PackageManager.NameNotFoundException ignored) {}

                    // A system app removed for this user is still on the system image: bring it back instead of
                    // installing. getPackageInfo(pkg, sigFlags) above throws for an app uninstalled-for-user, so
                    // this is the only identity check this path gets - it must verify the signer itself, the
                    // same as the installed-app branch above, rather than trusting the archive on its say-so.
                    String installNote = null;
                    if (!installed) {
                        PackageInfo sysInfo = null;
                        try {
                            sysInfo = pm.getPackageInfo(pkg, PackageManager.MATCH_UNINSTALLED_PACKAGES | sigFlags);
                        } catch (PackageManager.NameNotFoundException ignored) {}
                        // Only a system app has a copy on the system image to bring back. A user app removed with pm uninstall -k (data kept) is returned
                        // by MATCH_UNINSTALLED_PACKAGES too, but without signing info: it is installed from the backup below.
                        if (RestorePlan.bringBackSystemApp(sysInfo != null, sysInfo == null || sysInfo.applicationInfo == null ? 0 : sysInfo.applicationInfo.flags)) {
                            requireCompatibleSigner(signerDigests(sysInfo, true), archiveSigners,
                                    "the system app on this phone is signed with a different key than this backup's APK - it does not match this device");
                            // This too is a privileged install, of a copy that is on the phone already: asked before it, like the install below.
                            backupEvent("restore", "confirm", 30, "Waiting for your OK to bring back " + meta.optString("label", pkg) + "...");
                            List<String> sysActs = new ArrayList<String>();
                            sysActs.add(InstallConfirm.REINSTATES_SYSTEM);
                            final String sysMode = resolveExecMode();
                            if (!confirmInMode(sysMode, null, InstallConfirm.messageLocalFile(sourceNameOf(ref), pkg, archiveInfo.versionName,
                                    installedVersionOrNull(pkg), ordered.size(), sysMode, "", sysActs))) {
                                throw new InstallCancelled();
                            }
                            String o = new AndroidBridge().executeShell("pm install-existing " + pkg);
                            if (o.contains("installed for user")) {
                                installed = true;
                                sameVersion = true;
                                installNote = "restored for your user (it is part of the system)";
                            }
                        }
                    }

                    if (installed && sameVersion) {
                        // Nothing is installed here, but "Also restore app data" still replaces the app's data as root from a file the page named:
                        // the same dialog as the install branch below (a system app just brought back has asked already).
                        if (RestorePlan.askBeforeSameVersionRestore(installNote != null, wantData)) {
                            List<String> dataActs = new ArrayList<String>();
                            dataActs.add(InstallConfirm.RESTORES_DATA);
                            final String dataMode = resolveExecMode();
                            if (!confirmInMode(dataMode, null, InstallConfirm.messageLocalFile(sourceNameOf(ref), pkg, archiveInfo.versionName,
                                    installedVersionOrNull(pkg), 1, dataMode, "", dataActs))) {
                                throw new InstallCancelled();
                            }
                        }
                        res.put("install", installNote != null ? installNote : "already installed (same version)");
                    } else {
                        // The backup is a file the page named (or the person picked) and it is installed without the system installer's question:
                        // ask here, in a dialog the page cannot press, with what was read from the APK inside it.
                        backupEvent("restore", "confirm", 38, "Waiting for your OK to install " + meta.optString("label", pkg) + "...");
                        List<String> acts = new ArrayList<String>();
                        if (wantData) acts.add(InstallConfirm.RESTORES_DATA);
                        final String restoreMode = resolveExecMode();
                        if (!confirmInMode(restoreMode, null, InstallConfirm.messageLocalFile(sourceNameOf(ref), pkg, archiveInfo.versionName,
                                installedVersionOrNull(pkg), ordered.size(), restoreMode, "", acts))) {
                            throw new InstallCancelled();
                        }
                        backupEvent("restore", "install", 40, "Installing " + meta.optString("label", pkg) + "...");
                        String out = installApksIn(ordered, restoreMode);
                        if (!out.contains("Success")) throw new IllegalStateException(installHint(out));
                        // the version of the APK that was installed (the same one the question above showed), not backup.json's claim
                        res.put("install", "installed " + (archiveInfo.versionName != null ? archiveInfo.versionName : String.valueOf(archiveVersionCode)));
                    }

                    // Permissions and app ops
                    backupEvent("restore", "settings", 65, "Restoring permissions...");
                    AndroidBridge bridge = new AndroidBridge();
                    JSONArray perms = meta.optJSONArray("permissions");
                    // total counts the permissions that are tried, not the ones skipped below (a backup made on a newer Android lists some that are
                    // not dangerous here), so "X of Y granted" does not read a good restore as failed grants.
                    int granted = 0, total = 0, listed = perms == null ? 0 : perms.length();
                    for (int i = 0; i < listed; i++) {
                        String perm = perms.optString(i);
                        // backup.json is untrusted, so restore must accept nothing wider than what backup
                        // creation itself ever writes: a syntactically valid, dangerous runtime permission.
                        // Without the same isDangerousPermission check used there, a crafted backup wrapped
                        // around an otherwise-legitimate APK could list any real, syntactically valid
                        // permission - including signature/development-level ones this format never
                        // produces - and have the privileged backend asked to grant it.
                        if (!BackupScripts.isPermission(perm) || !isDangerousPermission(pm, perm)) continue;
                        total++;
                        String o = bridge.setPermission(pkg, perm, true).toLowerCase();
                        if (!o.contains("exception") && !o.contains("error") && !o.contains("not a changeable")) granted++;
                    }
                    res.put("permissionsGranted", granted);
                    res.put("permissionsTotal", total);
                    JSONObject ops = meta.optJSONObject("appops");
                    int opsSet = 0;
                    java.util.Iterator<String> it = ops == null ? null : ops.keys();
                    while (it != null && it.hasNext()) {
                        String op = it.next();
                        String mode = ops.optString(op);
                        if (!op.matches("[A-Z][A-Z0-9_]+") || !mode.matches("allow|ignore|deny|foreground")) continue;
                        String o = bridge.setAppOp(pkg, op, mode).toLowerCase();
                        if (!o.contains("exception") && !o.contains("error")) opsSet++;
                    }
                    res.put("appopsSet", opsSet);

                    // Data (Root only)
                    JSONArray warnings = new JSONArray();
                    if (wantData) {
                        backupEvent("restore", "data", 80, "Restoring data (Root)...");
                        String out = runRootScript(BackupScripts.dataRestore("/data", pkg, dataTar.getAbsolutePath()), 900000);
                        if (FileRules.okLine(out, "OK")) {
                            res.put("data", "restored");
                        } else {
                            res.put("data", "not restored");
                            warnings.put("Data was not restored: " + rootError(out));
                        }
                    }
                    res.put("warnings", warnings);
                    res.put("ok", true);
                } catch (Exception e) {
                    try {
                        res.put("ok", false);
                        res.put("error", e.getMessage() != null ? e.getMessage() : e.getClass().getSimpleName());
                    } catch (Exception ignored) {}
                } finally {
                    deleteRecursively(work);
                    backupBusy.set(false);
                }
                backupDone(res);
            }
        });
    }

    private static void deleteRecursively(File f) {
        File[] kids = f.listFiles();
        if (kids != null) for (File k : kids) deleteRecursively(k);
        f.delete();
    }

    // ---------------------------------------------------------------------------------------------
    // Open-source / sideloaded app updates
    // ---------------------------------------------------------------------------------------------

    private static final java.util.Set<String> STORE_INSTALLERS = new HashSet<String>(java.util.Arrays.asList(
            "com.android.vending", UpdateManager.GALAXY_STORE_PKG, "com.aurora.store", "com.amazon.venezia",
            "com.huawei.appmarket", "com.xiaomi.market", "com.xiaomi.mipicks", "com.heytap.market", "com.oppo.market",
            "com.bbk.appstore", "com.google.android.feedback"));

    private JSONObject updateSources() {
        try {
            return new JSONObject(prefs.getString("update_sources", "{}"));
        } catch (Exception e) {
            return new JSONObject();
        }
    }

    private void saveUpdateSources(JSONObject o) {
        prefs.edit().putString("update_sources", o.toString()).apply();
    }

    /** Apps that may have an open-source update: user-mapped apps, or user apps not from an app store. */
    private boolean isOpenSourceCandidate(ApplicationInfo ai, String installer, JSONObject sources) {
        if (sources.has(ai.packageName)) return true;
        if ((ai.flags & ApplicationInfo.FLAG_SYSTEM) != 0) return false;
        if (ai.packageName.equals(getPackageName())) return false;
        return installer == null || !STORE_INSTALLERS.contains(installer);
    }

    /**
     * SHA-256 digests of the signing certificates. With {@code includeHistory}, a key that was rotated also lists the
     * keys before it, which is what two packages are compared by: an APK signed with the newer key of a rotation may
     * update an install signed with the older one, and the other way round.
     */
    private static java.util.Set<String> signerDigests(PackageInfo pi, boolean includeHistory) {
        java.util.Set<String> out = new HashSet<String>();
        try {
            android.content.pm.Signature[] sigs = null;
            if (Build.VERSION.SDK_INT >= 28 && pi.signingInfo != null) {
                if (includeHistory && !pi.signingInfo.hasMultipleSigners()) sigs = pi.signingInfo.getSigningCertificateHistory();
                if (sigs == null || sigs.length == 0) sigs = pi.signingInfo.getApkContentsSigners();
            } else {
                sigs = pi.signatures;
            }
            if (sigs == null) return out;
            java.security.MessageDigest md = java.security.MessageDigest.getInstance("SHA-256");
            for (android.content.pm.Signature s : sigs) {
                byte[] d = md.digest(s.toByteArray());
                StringBuilder sb = new StringBuilder();
                for (byte b : d) sb.append(String.format("%02x", b & 0xFF));
                out.add(sb.toString());
            }
        } catch (Exception ignored) {}
        return out;
    }

    /**
     * Throws when two non-empty signer sets share no certificate. Used by both restore paths (an app
     * currently installed for the user, and a system app only present on the system image) so a future
     * change to this check can't land in one copy and leave the other unprotected.
     */
    private static void requireCompatibleSigner(java.util.Set<String> installedSigners, java.util.Set<String> archiveSigners, String message) {
        // Fail closed: every real, installable APK has at least one signer, so an empty set here means the
        // archive is unsigned/unreadable, not "nothing to compare". Treating that as a pass would let a
        // backup whose signature can't be read skip verification entirely.
        if (installedSigners.isEmpty() || archiveSigners.isEmpty()) throw new IllegalStateException(message);
        java.util.Set<String> common = new HashSet<String>(installedSigners);
        common.retainAll(archiveSigners);
        if (common.isEmpty()) throw new IllegalStateException(message);
    }

    private static final int REQ_IMPORT_OBTAINIUM = 4201;
    private static final int REQ_PICK_STORAGE_TREE = 4205;

    /** Opens a system picker on the UI thread. False (and a toast) when the phone has none, for example with the Files app frozen:
     *  startActivityForResult throws ActivityNotFoundException then, and uncaught on the UI thread it would end the app. */
    private boolean startPicker(Intent i, int request) {
        try {
            startActivityForResult(i, request);
            return true;
        } catch (Exception e) {
            Toast.makeText(this, "No file picker available", Toast.LENGTH_LONG).show();
            return false;
        }
    }

    @Override
    protected void onActivityResult(int requestCode, int resultCode, Intent data) {
        super.onActivityResult(requestCode, resultCode, data);
        if (requestCode == REQ_PICK_STORAGE_TREE) {
            final Uri picked = (resultCode == RESULT_OK && data != null) ? data.getData() : null;
            if (picked == null) { notifyJs("window.onStorageRootPicked && window.onStorageRootPicked(null)"); return; }
            try {
                getContentResolver().takePersistableUriPermission(picked,
                        Intent.FLAG_GRANT_READ_URI_PERMISSION | Intent.FLAG_GRANT_WRITE_URI_PERMISSION);
            } catch (Exception ignored) {
                // some providers (notably a few cloud ones) don't support a persistable grant; the tree URI
                // still works for the rest of this session, it just won't survive a process restart.
            }
            String label = storageRootLabel(picked);
            notifyJs("window.onStorageRootPicked && window.onStorageRootPicked(" + JSONObject.quote(picked.toString()) + "," + JSONObject.quote(label) + ")");
            return;
        }
        if (requestCode == REQ_PICK_BACKUP_DIR) {
            final String tag = pickBackupDirTag;
            final Uri picked = (resultCode == RESULT_OK && data != null) ? data.getData() : null;
            JSONObject res = new JSONObject();
            try {
                res.put("tag", tag);
                if (picked == null) {
                    res.put("cancelled", true);
                } else {
                    try {
                        getContentResolver().takePersistableUriPermission(picked, Intent.FLAG_GRANT_READ_URI_PERMISSION | Intent.FLAG_GRANT_WRITE_URI_PERMISSION);
                    } catch (Exception ignored) {
                        // a provider that cannot keep the grant (a few cloud ones) still works until the app is closed
                    }
                    res.put("uri", picked.toString());
                    res.put("label", storageRootLabel(picked));
                }
            } catch (Exception ignored) {}
            notifyJs("window.onBackupFolderPicked && window.onBackupFolderPicked(" + res.toString() + ")");
            return;
        }
        if (requestCode == REQ_PICK_BACKUP) {
            final Uri picked = (resultCode == RESULT_OK && data != null) ? data.getData() : null;
            if (picked == null) return;
            executor.submit(new Runnable() {
                @Override
                public void run() {
                    JSONObject res = new JSONObject();
                    try {
                        JSONObject meta = readBackupMeta(picked.toString());
                        res.put("ref", picked.toString());
                        res.put("pkg", meta.optString("pkg"));
                        res.put("label", meta.optString("label"));
                        res.put("versionName", meta.optString("versionName"));
                        res.put("createdAt", meta.optLong("createdAt"));
                        res.put("hasData", meta.optBoolean("hasData"));
                        res.put("bytes", meta.optLong("dataBytes"));
                    } catch (Exception e) {
                        try { res.put("error", e.getMessage() != null ? e.getMessage() : "not a backup file"); } catch (Exception ignored) {}
                    }
                    notifyJs("window.onBackupPicked && window.onBackupPicked(" + JSONObject.quote(res.toString()) + ")");
                }
            });
            return;
        }
        if (requestCode == REQ_PICK_INSTALL) {
            final Uri picked = (resultCode == RESULT_OK && data != null) ? data.getData() : null;
            if (picked == null) return;
            notifyJs("window.onInstallFilePicked && window.onInstallFilePicked(" + JSONObject.quote(picked.toString()) + ")");
            return;
        }
        if (requestCode == REQ_PICK_MORPHE) { morphePicked(data, resultCode); return; }
        if (requestCode == REQ_PICK_CD) {
            final String tag = cdPickTag;
            final List<Uri> uris = new ArrayList<Uri>();
            if (resultCode == RESULT_OK && data != null) {
                if (data.getClipData() != null) {
                    for (int i = 0; i < data.getClipData().getItemCount(); i++) uris.add(data.getClipData().getItemAt(i).getUri());
                } else if (data.getData() != null) {
                    uris.add(data.getData());
                }
            }
            if (uris.isEmpty()) { notifyJs("window.onCdPicked && window.onCdPicked({\"tag\":" + JSONObject.quote(tag) + ",\"files\":[]})"); return; }
            cdExecutor.submit(new Runnable() {
                @Override
                public void run() {
                    JSONObject res = new JSONObject();
                    JSONArray files = new JSONArray();
                    try {
                        res.put("tag", tag);
                        File root = new File(getCacheDir(), "cd_pick");
                        root.mkdirs();
                        DeviceLink.clearOldPicks(root, System.currentTimeMillis(), 60 * 60 * 1000L, cdPickInUse);
                        for (Uri u : uris) {
                            try {
                                String name = cdSafeName(cdDisplayName(u));
                                File dir = new File(root, Long.toHexString(System.nanoTime()));
                                dir.mkdirs();
                                File out = new File(dir, name);
                                InputStream in = getContentResolver().openInputStream(u);
                                if (in == null) throw new IOException("could not open the file");
                                java.io.OutputStream os = new java.io.FileOutputStream(out);
                                try {
                                    byte[] buf = new byte[65536];
                                    int n;
                                    while ((n = in.read(buf)) > 0) os.write(buf, 0, n);
                                } finally {
                                    os.close();
                                    in.close();
                                }
                                files.put(new JSONObject().put("name", name).put("path", out.getAbsolutePath()).put("size", out.length()));
                            } catch (Exception one) {
                                files.put(new JSONObject().put("name", String.valueOf(u.getLastPathSegment())).put("error", String.valueOf(one.getMessage())));
                            }
                        }
                        res.put("files", files);
                    } catch (Exception e) {
                        try { res.put("error", e.getMessage()); res.put("files", files); } catch (Exception ignored) {}
                    }
                    notifyJs("window.onCdPicked && window.onCdPicked(" + res.toString() + ")");
                }
            });
            return;
        }
        if (requestCode == REQ_PICK_TEXT) {
            final String tag = pickTextTag;
            final Uri textUri = (resultCode == RESULT_OK && data != null) ? data.getData() : null;
            if (textUri == null) return;
            executor.submit(new Runnable() {
                @Override
                public void run() {
                    JSONObject res = new JSONObject();
                    try {
                        res.put("tag", tag);
                        InputStream in = getContentResolver().openInputStream(textUri);
                        if (in == null) throw new IllegalStateException("could not open the file");
                        java.io.ByteArrayOutputStream buf = new java.io.ByteArrayOutputStream();
                        try {
                            byte[] b = new byte[16384];
                            int n;
                            while ((n = in.read(b)) > 0) {
                                buf.write(b, 0, n);
                                if (buf.size() > 1024 * 1024) throw new IllegalStateException("the file is over 1 MB, too big for this");
                            }
                        } finally {
                            in.close();
                        }
                        String name = "";
                        try {
                            android.database.Cursor c = getContentResolver().query(textUri, new String[]{android.provider.OpenableColumns.DISPLAY_NAME}, null, null, null);
                            if (c != null) {
                                try { if (c.moveToFirst()) name = c.getString(0); } finally { c.close(); }
                            }
                        } catch (Exception ignored) {}
                        res.put("name", name);
                        res.put("text", buf.toString("UTF-8"));
                    } catch (Exception e) {
                        try { res.put("error", e.getMessage() == null ? "could not read the file" : e.getMessage()); } catch (Exception ignored) {}
                    }
                    notifyJs("window.onTextFilePicked && window.onTextFilePicked(" + res.toString() + ")");
                }
            });
            return;
        }
        if (requestCode == REQ_FONTMAKER_PICK) {
            final String slot;
            synchronized (fmkLock) {
                slot = fmkPickSlot;
                fmkPickSlot = null;
            }
            fmkPickResult(slot, (resultCode == RESULT_OK && data != null) ? data.getData() : null);
            return;
        }
        if (requestCode == REQ_FONTMAKER_EXPORT) {
            final String id;
            synchronized (fmkLock) {
                id = fmkExportId;
                fmkExportId = null;
            }
            fmkExportResult(id, (resultCode == RESULT_OK && data != null) ? data.getData() : null);
            return;
        }
        if (requestCode == REQ_PICK_FONT) {
            final Uri picked = (resultCode == RESULT_OK && data != null) ? data.getData() : null;
            if (picked == null) return;
            notifyJs("window.onFontPicked && window.onFontPicked(" + JSONObject.quote(picked.toString()) + ")");
            return;
        }
        if (requestCode != REQ_IMPORT_OBTAINIUM) return;
        final Uri uri = (resultCode == RESULT_OK && data != null) ? data.getData() : null;
        executor.submit(new Runnable() {
            @Override
            public void run() {
                JSONObject res = new JSONObject();
                try {
                    if (uri == null) throw new IllegalStateException("cancelled");
                    InputStream in = getContentResolver().openInputStream(uri);
                    java.io.ByteArrayOutputStream buf = new java.io.ByteArrayOutputStream();
                    byte[] b = new byte[16384];
                    int n;
                    while ((n = in.read(b)) > 0) {
                        buf.write(b, 0, n);
                        if (buf.size() > 20 * 1024 * 1024) throw new IllegalStateException("file too large");
                    }
                    in.close();
                    res.put("imported", importObtainiumJson(buf.toString("UTF-8")));
                } catch (Exception e) {
                    try { res.put("error", e.getMessage()); } catch (Exception ignored) {}
                }
                notifyUpdates("onObtainiumImported", res);
            }
        });
    }

    /** Merges an Obtainium export ({"apps":[{"id","url","additionalSettings",...}]}) into the update sources. */
    private int importObtainiumJson(String text) throws Exception {
        text = text.trim();
        JSONArray apps = text.startsWith("[") ? new JSONArray(text) : new JSONObject(text).optJSONArray("apps");
        if (apps == null) throw new IllegalStateException("not an Obtainium export (no \"apps\" list)");
        JSONObject sources = updateSources();
        int count = 0;
        for (int i = 0; i < apps.length(); i++) {
            JSONObject a = apps.optJSONObject(i);
            if (a == null) continue;
            String id = a.optString("id"), url = a.optString("url");
            if (id.isEmpty() || url.isEmpty()) continue;
            JSONObject entry = new JSONObject();
            entry.put("url", url);
            entry.put("origin", "obtainium-import");
            entry.put("settings", UpdateManager.obtainiumSettings(a));
            sources.put(id, entry);
            count++;
        }
        saveUpdateSources(sources);
        return count;
    }

    // ---------------------------------------------------------------------------------------------
    // App sizes, storage stats and APK extraction
    // ---------------------------------------------------------------------------------------------

    private static File[] apkFiles(ApplicationInfo ai) {
        List<File> files = new ArrayList<File>();
        if (ai.sourceDir != null) files.add(new File(ai.sourceDir));
        if (ai.splitSourceDirs != null) {
            for (String split : ai.splitSourceDirs) files.add(new File(split));
        }
        return files.toArray(new File[0]);
    }

    private static long apkBytes(ApplicationInfo ai) {
        long total = 0;
        for (File f : apkFiles(ai)) total += f.length();
        return total;
    }

    /** "Display over other apps" (a special access with its own settings screen from Android 6 on). */
    private boolean hasOverlayAccess() {
        try {
            return Build.VERSION.SDK_INT < 23 || android.provider.Settings.canDrawOverlays(this);
        } catch (Exception e) {
            return false;
        }
    }

    private boolean hasUsageAccess() {
        try {
            android.app.AppOpsManager ops = (android.app.AppOpsManager) getSystemService(Context.APP_OPS_SERVICE);
            int mode = ops.checkOpNoThrow(android.app.AppOpsManager.OPSTR_GET_USAGE_STATS, android.os.Process.myUid(), getPackageName());
            return mode == android.app.AppOpsManager.MODE_ALLOWED;
        } catch (Exception e) {
            return false;
        }
    }

    private boolean hasLegacyStorageAccess() {
        try {
            return checkSelfPermission(android.Manifest.permission.READ_EXTERNAL_STORAGE) == PackageManager.PERMISSION_GRANTED
                    && checkSelfPermission(android.Manifest.permission.WRITE_EXTERNAL_STORAGE) == PackageManager.PERMISSION_GRANTED;
        } catch (Exception e) {
            return false;
        }
    }

    /** A Settings.Global number any app may read; -1 when the phone has no such setting or refuses the read. */
    private int readGlobalInt(String name) {
        try {
            return android.provider.Settings.Global.getInt(getContentResolver(), name, -1);
        } catch (Exception e) {
            return -1;
        }
    }

    private boolean hasWriteSecureSettingsAccess() {
        try {
            return checkSelfPermission(android.Manifest.permission.WRITE_SECURE_SETTINGS) == PackageManager.PERMISSION_GRANTED;
        } catch (Exception e) {
            return false;
        }
    }

    /** DUMP (signature|privileged|development): the phone's own answer to checkSelfPermission, never a command's output. */
    private boolean hasDumpAccess() {
        try {
            return checkSelfPermission(android.Manifest.permission.DUMP) == PackageManager.PERMISSION_GRANTED;
        } catch (Exception e) {
            return false;
        }
    }

    /** READ_LOGS (signature|privileged|development): like DUMP, granted only with pm grant through ADB/Shizuku/root, and read back from the phone's own permission check. */
    private boolean hasReadLogsAccess() {
        try {
            return checkSelfPermission(android.Manifest.permission.READ_LOGS) == PackageManager.PERMISSION_GRANTED;
        } catch (Exception e) {
            return false;
        }
    }

    /** BLUETOOTH_CONNECT is a runtime permission from Android 12 on; below that the app needs nothing to be allowed (it counts as held). */
    private boolean hasBluetoothConnectAccess() {
        if (Build.VERSION.SDK_INT < 31) return true;
        try {
            return checkSelfPermission("android.permission.BLUETOOTH_CONNECT") == PackageManager.PERMISSION_GRANTED;
        } catch (Exception e) {
            return false;
        }
    }

    /** POST_NOTIFICATIONS is a runtime permission from Android 13 on; below that notifications need no permission (it counts as held). */
    private boolean hasNotificationAccess() {
        if (Build.VERSION.SDK_INT < 33) return true;
        try {
            return checkSelfPermission("android.permission.POST_NOTIFICATIONS") == PackageManager.PERMISSION_GRANTED;
        } catch (Exception e) {
            return false;
        }
    }

    /** "Allow restricted settings" - an app-op (android:read_write_restricted_settings), not a manifest
     *  permission, so there is nothing to declare in AndroidManifest.xml for this one. */
    /** "Install unknown apps" for this app (Android 8+): whether it may start the installation of package files. Older phones have one global switch: nothing to ask. */
    private boolean hasInstallUnknownAccess() {
        try {
            return Build.VERSION.SDK_INT < 26 || getPackageManager().canRequestPackageInstalls();
        } catch (Exception e) {
            return false;
        }
    }

    /** "Allow restricted settings" is the app-op ACCESS_RESTRICTED_SETTINGS (Android 13 and newer). Below that there is nothing to allow. A grant made through the working mode is remembered
     *  here, because some phones do not report the op to the app itself. */
    private boolean hasRestrictedSettingsAccess() {
        if (Build.VERSION.SDK_INT < 33) return true;
        try {
            if (getSharedPreferences("perms", MODE_PRIVATE).getBoolean("restricted_granted", false)) return true;
            android.app.AppOpsManager ops = (android.app.AppOpsManager) getSystemService(Context.APP_OPS_SERVICE);
            for (String op : new String[]{"android:access_restricted_settings", "android:read_write_restricted_settings"}) {
                try {
                    int mode = ops.checkOpNoThrow(op, android.os.Process.myUid(), getPackageName());
                    if (mode == android.app.AppOpsManager.MODE_ALLOWED) return true;
                } catch (IllegalArgumentException unknown) {
                    // this phone does not have that op: try the next name
                }
            }
            return false;
        } catch (Exception e) {
            return false;
        }
    }

    /** {"app":..,"data":..,"cache":..} bytes from StorageStatsManager (needs usage access), or null */
    private JSONObject storageStats(String pkg) {
        if (!hasUsageAccess()) return null;
        try {
            android.app.usage.StorageStatsManager ssm = (android.app.usage.StorageStatsManager) getSystemService(Context.STORAGE_STATS_SERVICE);
            android.app.usage.StorageStats st = ssm.queryStatsForPackage(android.os.storage.StorageManager.UUID_DEFAULT, pkg, android.os.Process.myUserHandle());
            JSONObject o = new JSONObject();
            o.put("app", st.getAppBytes());
            o.put("data", Math.max(0, st.getDataBytes() - st.getCacheBytes()));
            o.put("cache", st.getCacheBytes());
            return o;
        } catch (Exception e) {
            return null;
        }
    }

    /** Opens a file in Download/ADB App Manager/<sub> via MediaStore (Android 10+). Before MediaStore.Downloads
     *  existed (Android 8.0-9, API 26-28) this instead uses this app's own external-files storage, which is
     *  removed if the app is uninstalled - there is no public-Downloads write path on those versions without
     *  a runtime WRITE_EXTERNAL_STORAGE grant this app doesn't request. target[1], returned to the caller,
     *  always reflects the real path used, so the UI and the backup index never claim the wrong one. */
    private Object[] openDownloadOutput(String fileName, String mime, String sub) throws Exception {
        String safeName = fileName.replaceAll("[^A-Za-z0-9._ -]", "_").trim();
        String folder = "ADB App Manager" + (sub == null || sub.isEmpty() ? "" : "/" + sub);
        if (Build.VERSION.SDK_INT >= 29) {
            android.content.ContentValues values = new android.content.ContentValues();
            values.put(android.provider.MediaStore.MediaColumns.DISPLAY_NAME, safeName);
            values.put(android.provider.MediaStore.MediaColumns.MIME_TYPE, mime);
            values.put(android.provider.MediaStore.MediaColumns.RELATIVE_PATH, "Download/" + folder);
            Uri uri = getContentResolver().insert(android.provider.MediaStore.Downloads.EXTERNAL_CONTENT_URI, values);
            if (uri == null) throw new IllegalStateException("could not create " + safeName);
            return new Object[]{getContentResolver().openOutputStream(uri), "Download/" + folder + "/" + safeName, uri.toString()};
        }
        File dir = new File(getExternalFilesDir(null), folder);
        if (!dir.exists()) dir.mkdirs();
        File file = new File(dir, safeName);
        return new Object[]{new FileOutputStream(file), file.getAbsolutePath(), file.getAbsolutePath()};
    }

    /** Deletes a target from openDownloadOutput after a failure, so a file that never finished writing
     *  doesn't stay indexed (or on disk) looking like a complete, usable one. */
    private void deleteDownloadTarget(Object[] target) {
        if (target == null) return;
        try {
            String ref = (String) target[2];
            if (ref.startsWith("content://")) {
                getContentResolver().delete(Uri.parse(ref), null, null);
            } else {
                new File(ref).delete();
            }
        } catch (Exception ignored) {}
    }

    /** App icons for the list, kept on disk (files/icon_cache/<pkg>_<lastUpdateTime>.png, 96 px) so later launches skip the drawing. */
    private File iconCacheDir(String pack) {
        File d = new File(getFilesDir(), pack == null || pack.isEmpty() ? "icon_cache" : "icon_cache_" + pack.replaceAll("[^A-Za-z0-9._]", "_"));
        if (!d.isDirectory()) d.mkdirs();
        return d;
    }

    private static final String[] ICON_PACK_ACTIONS = {"org.adw.launcher.THEMES", "com.novalauncher.THEME", "com.anddoes.launcher.THEME", "com.gau.go.launcherex.theme"};
    private final Map<String, Map<String, String>> iconPackFilters = new java.util.HashMap<String, Map<String, String>>();

    /** Installed icon packs (the ADW / Nova / Apex / Go theme convention): [{pkg, label}]. */
    private String listIconPacks() {
        JSONArray out = new JSONArray();
        try {
            PackageManager pm = getPackageManager();
            java.util.Set<String> seen = new java.util.HashSet<String>();
            for (String action : ICON_PACK_ACTIONS) {
                for (android.content.pm.ResolveInfo ri : pm.queryIntentActivities(new Intent(action), 0)) {
                    String pkg = ri.activityInfo.packageName;
                    if (!seen.add(pkg)) continue;
                    out.put(new JSONObject().put("pkg", pkg).put("label", String.valueOf(ri.loadLabel(pm))));
                }
            }
        } catch (Throwable ignored) {}
        return out.toString();
    }

    /** What an icon pack's appfilter.xml maps: "ComponentInfo{pkg/cls}" and bare "pkg" to a drawable name. */
    private synchronized Map<String, String> iconPackFilter(String pack) {
        Map<String, String> m = iconPackFilters.get(pack);
        if (m != null) return m;
        m = new java.util.HashMap<String, String>();
        try {
            Resources res = getPackageManager().getResourcesForApplication(pack);
            org.xmlpull.v1.XmlPullParser xp = null;
            int id = res.getIdentifier("appfilter", "xml", pack);
            if (id != 0) {
                xp = res.getXml(id);
            } else {
                try {
                    xp = android.util.Xml.newPullParser();
                    xp.setInput(res.getAssets().open("appfilter.xml"), "UTF-8");
                } catch (Exception noAsset) {
                    xp = null;
                }
            }
            if (xp != null) {
                int ev;
                StringBuilder backs = new StringBuilder();
                while ((ev = xp.next()) != org.xmlpull.v1.XmlPullParser.END_DOCUMENT) {
                    if (ev != org.xmlpull.v1.XmlPullParser.START_TAG) continue;
                    String tag = xp.getName();
                    if ("iconback".equals(tag)) {
                        for (int i = 0; i < xp.getAttributeCount(); i++) {
                            if (xp.getAttributeName(i).startsWith("img")) backs.append(backs.length() > 0 ? "," : "").append(xp.getAttributeValue(i));
                        }
                        continue;
                    }
                    if ("iconmask".equals(tag) || "iconupon".equals(tag)) {
                        if (xp.getAttributeCount() > 0 && !m.containsKey("#" + tag)) m.put("#" + tag, xp.getAttributeValue(0));
                        continue;
                    }
                    if ("scale".equals(tag)) {
                        String fct = xp.getAttributeValue(null, "factor");
                        if (fct != null) m.put("#scale", fct);
                        continue;
                    }
                    if (!"item".equals(tag)) continue;
                    String comp = xp.getAttributeValue(null, "component");
                    String dr = xp.getAttributeValue(null, "drawable");
                    if (comp == null || dr == null || dr.isEmpty()) continue;
                    if (!m.containsKey(comp)) m.put(comp, dr);
                    int slash = comp.indexOf('/');
                    if (comp.startsWith("ComponentInfo{") && slash > 14) {
                        String pkg = comp.substring(14, slash);
                        if (!m.containsKey(pkg)) m.put(pkg, dr);
                    }
                }
                if (backs.length() > 0) m.put("#iconback", backs.toString());
            }
        } catch (Throwable ignored) {}
        iconPackFilters.put(pack, m);
        return m;
    }

    private android.graphics.drawable.Drawable iconPackDrawable(String pack, String pkg) {
        try {
            PackageManager pm = getPackageManager();
            Map<String, String> f = iconPackFilter(pack);
            String name = null;
            Intent li = pm.getLaunchIntentForPackage(pkg);
            if (li != null && li.getComponent() != null) name = f.get("ComponentInfo{" + li.getComponent().getPackageName() + "/" + li.getComponent().getClassName() + "}");
            if (name == null) name = f.get(pkg);
            if (name == null) return null;
            Resources res = pm.getResourcesForApplication(pack);
            int id = res.getIdentifier(name, "drawable", pack);
            if (id == 0) id = res.getIdentifier(name, "mipmap", pack);
            return id == 0 ? null : res.getDrawable(id, null);
        } catch (Throwable t) {
            return null;
        }
    }

    /** The icon of {@code pkg} at px x px: from the icon pack {@code pack} when it has one for the app, else the app's own. */
    private android.graphics.Bitmap renderAppIcon(String pkg, int px, String pack) throws Exception {
        PackageManager pm = getPackageManager();
        android.graphics.drawable.Drawable d = pack == null || pack.isEmpty() ? null : iconPackDrawable(pack, pkg);
        boolean themed = d != null;
        if (d == null) d = pm.getApplicationIcon(pm.getApplicationInfo(pkg, PackageManager.MATCH_UNINSTALLED_PACKAGES));
        android.graphics.Bitmap b = android.graphics.Bitmap.createBitmap(px, px, android.graphics.Bitmap.Config.ARGB_8888);
        android.graphics.Canvas c = new android.graphics.Canvas(b);
        if (!themed && pack != null && !pack.isEmpty()) {
            Map<String, String> f = iconPackFilter(pack);
            if (f.containsKey("#iconback") || f.containsKey("#iconmask") || f.containsKey("#iconupon")) {
                return themedFallbackIcon(pack, pkg, d, px, f);
            }
        }
        d.setBounds(0, 0, px, px);
        d.draw(c);
        return b;
    }

    private android.graphics.drawable.Drawable packDrawableByName(String pack, String name) {
        try {
            if (name == null || name.isEmpty()) return null;
            Resources res = getPackageManager().getResourcesForApplication(pack);
            int id = res.getIdentifier(name, "drawable", pack);
            if (id == 0) id = res.getIdentifier(name, "mipmap", pack);
            return id == 0 ? null : res.getDrawable(id, null);
        } catch (Throwable t) {
            return null;
        }
    }

    /** An app the pack has no icon for, dressed the way the pack dresses such apps: its iconback, the app icon scaled by the pack's factor and cut by its iconmask, then its iconupon. */
    private android.graphics.Bitmap themedFallbackIcon(String pack, String pkg, android.graphics.drawable.Drawable app, int px, Map<String, String> f) {
        android.graphics.Bitmap out = android.graphics.Bitmap.createBitmap(px, px, android.graphics.Bitmap.Config.ARGB_8888);
        android.graphics.Canvas c = new android.graphics.Canvas(out);
        String backs = f.get("#iconback");
        if (backs != null) {
            String[] names = backs.split(",");
            android.graphics.drawable.Drawable back = packDrawableByName(pack, names[Math.abs(pkg.hashCode()) % names.length]);
            if (back != null) {
                back.setBounds(0, 0, px, px);
                back.draw(c);
            }
        }
        float factor = 1f;
        try {
            if (f.containsKey("#scale")) factor = Float.parseFloat(f.get("#scale"));
        } catch (Exception ignored) {}
        if (factor <= 0f || factor > 1.5f) factor = 1f;
        android.graphics.Bitmap fg = android.graphics.Bitmap.createBitmap(px, px, android.graphics.Bitmap.Config.ARGB_8888);
        android.graphics.Canvas fc = new android.graphics.Canvas(fg);
        int inset = Math.round(px * (1f - factor) / 2f);
        app.setBounds(inset, inset, px - inset, px - inset);
        app.draw(fc);
        android.graphics.drawable.Drawable mask = packDrawableByName(pack, f.get("#iconmask"));
        if (mask != null) {
            android.graphics.Paint mp = new android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG);
            mp.setXfermode(new android.graphics.PorterDuffXfermode(android.graphics.PorterDuff.Mode.DST_OUT));
            android.graphics.Bitmap mb = android.graphics.Bitmap.createBitmap(px, px, android.graphics.Bitmap.Config.ARGB_8888);
            mask.setBounds(0, 0, px, px);
            mask.draw(new android.graphics.Canvas(mb));
            fc.drawBitmap(mb, 0, 0, mp);
        }
        c.drawBitmap(fg, 0, 0, null);
        android.graphics.drawable.Drawable upon = packDrawableByName(pack, f.get("#iconupon"));
        if (upon != null) {
            upon.setBounds(0, 0, px, px);
            upon.draw(c);
        }
        return out;
    }

    /** Clears the cached list icons (every pack); returns how many files went. */
    private int clearIconCache() {
        int n = 0;
        File[] dirs = getFilesDir().listFiles();
        if (dirs != null) for (File d : dirs) {
            if (!d.isDirectory() || !d.getName().startsWith("icon_cache")) continue;
            File[] fs = d.listFiles();
            if (fs != null) for (File x : fs) if (x.delete()) n++;
            d.delete();
        }
        return n;
    }

    /** The cached PNG of {@code pkg}'s icon (in {@code pack} when given) as a data: URI, drawn and cached on first use; null when it has none. */
    private String iconDataUri(String pkg, String pack) {
        try {
            long stamp = 0;
            PackageManager pm = getPackageManager();
            try {
                stamp = pm.getPackageInfo(pkg, PackageManager.MATCH_UNINSTALLED_PACKAGES).lastUpdateTime;
            } catch (Exception ignored) {}
            if (pack != null && !pack.isEmpty()) {
                try {
                    stamp += pm.getPackageInfo(pack, 0).lastUpdateTime;
                } catch (Exception ignored) {}
            }
            File dir = iconCacheDir(pack);
            File f = new File(dir, pkg + "_" + stamp + ".png");
            if (!f.isFile()) {
                final String prefix = pkg + "_";
                File[] old = dir.listFiles();
                if (old != null) for (File o : old) {
                    String n = o.getName();
                    if (n.startsWith(prefix) && n.substring(prefix.length()).matches("\\d+\\.png")) o.delete();
                }
                android.graphics.Bitmap b = renderAppIcon(pkg, 96, pack);
                FileOutputStream out = new FileOutputStream(f);
                try {
                    b.compress(android.graphics.Bitmap.CompressFormat.PNG, 100, out);
                } finally {
                    out.close();
                }
            }
            java.io.ByteArrayOutputStream bos = new java.io.ByteArrayOutputStream();
            java.io.FileInputStream in = new java.io.FileInputStream(f);
            try {
                byte[] buf = new byte[8192];
                int n;
                while ((n = in.read(buf)) > 0) bos.write(buf, 0, n);
            } finally {
                in.close();
            }
            return "data:image/png;base64," + android.util.Base64.encodeToString(bos.toByteArray(), android.util.Base64.NO_WRAP);
        } catch (Throwable t) {
            return null;
        }
    }

    /** Copies an app's APK (or base + splits as a .apks bundle) to Downloads. Result via window.onApkExtracted(json). */
    private void runExtractApk(final String pkg) {
        executor.submit(new Runnable() {
            @Override
            public void run() {
                JSONObject res = new JSONObject();
                Object[] target = null;
                try {
                    res.put("pkg", pkg);
                    PackageManager pm = getPackageManager();
                    ApplicationInfo ai = pm.getApplicationInfo(pkg, PackageManager.MATCH_UNINSTALLED_PACKAGES);
                    PackageInfo pi = pm.getPackageInfo(pkg, PackageManager.MATCH_UNINSTALLED_PACKAGES);
                    File[] files = apkFiles(ai);
                    if (files.length == 0 || !files[0].canRead()) throw new IllegalStateException("APK not readable");
                    String label = pm.getApplicationLabel(ai).toString();
                    String base = (label.isEmpty() ? pkg : label) + "_" + (pi.versionName != null ? pi.versionName : String.valueOf(versionCodeOf(pi)));
                    long total = 0;
                    if (files.length == 1) {
                        target = openDownloadOutput(base + ".apk", "application/vnd.android.package-archive", "APKs");
                        OutputStream out = (OutputStream) target[0];
                        try {
                            total = copyFile(files[0], out);
                        } finally {
                            out.close();
                        }
                    } else {
                        // Split app: one .apks bundle (a zip of base.apk + splits) that split-APK installers accept
                        // octet-stream so MediaStore keeps the .apks name instead of appending .zip
                        target = openDownloadOutput(base + ".apks", "application/octet-stream", "APKs");
                        java.util.zip.ZipOutputStream zip = new java.util.zip.ZipOutputStream((OutputStream) target[0]);
                        try {
                            for (File f : files) {
                                zip.putNextEntry(new java.util.zip.ZipEntry(f.getName()));
                                total += copyFile(f, zip);
                                zip.closeEntry();
                            }
                        } finally {
                            zip.close();
                        }
                    }
                    res.put("ok", true);
                    res.put("path", target[1]);
                    res.put("ref", target[2]);
                    res.put("mime", files.length == 1 ? "application/vnd.android.package-archive" : "application/octet-stream");
                    res.put("bytes", total);
                    res.put("splits", files.length);
                } catch (Exception e) {
                    deleteDownloadTarget(target);
                    try {
                        res.put("ok", false);
                        res.put("error", e.getMessage() != null ? e.getMessage() : e.getClass().getSimpleName());
                    } catch (Exception ignored) {}
                }
                notifyJs("window.onApkExtracted && window.onApkExtracted(" + JSONObject.quote(res.toString()) + ")");
            }
        });
    }

    private static long copyFile(File f, OutputStream out) throws Exception {
        java.io.FileInputStream in = new java.io.FileInputStream(f);
        long total = 0;
        try {
            byte[] buf = new byte[65536];
            int n;
            while ((n = in.read(buf)) > 0) {
                out.write(buf, 0, n);
                total += n;
            }
        } finally {
            in.close();
        }
        return total;
    }

    // Small JSON documents the UI keeps between launches (remembered filters, debloat history)
    private static final java.util.Set<String> UI_STORE_KEYS = new HashSet<String>(java.util.Arrays.asList("ui_state", "debloat_history", "profiles", "seen_version"));

    private int systemColor(String name) {
        int id = getResources().getIdentifier(name, "color", "android");
        if (id == 0) throw new IllegalStateException("Missing system color " + name);
        return getColor(id);
    }


    // ---- Morphe Patcher tab: the bridge does the work, the activity gives it the picker, the installer, sharing and the network state ----
    private static final int REQ_PICK_MORPHE = 4292;
    private volatile String morphePickTag = "";
    private MorpheBridge morpheBridge;
    private MorpheBridge.Host morpheHostInstance;

    private AuthManager authManagerInstance;

    /** The one holder of this app's authorization code (kept in private preferences). */
    private synchronized AuthManager authManager() {
        if (authManagerInstance == null) {
            final android.content.SharedPreferences sp = getApplicationContext().getSharedPreferences("auth_manager", Context.MODE_PRIVATE);
            authManagerInstance = new AuthManager(new AuthManager.Store() {
                @Override public String get(String k) { return sp.getString(k, null); }
                @Override public void put(String k, String v) { sp.edit().putString(k, v).apply(); }
            }, new java.security.SecureRandom());
        }
        return authManagerInstance;
    }

    /**
     * Opens the share sheet for the staged signing key (see {@link KeyShare}) and removes the copy, and the grant on it, {@link KeyShare#KEEP_MS} later.
     * The timer is a static class that holds the application context, the address and the file, not this activity. If the process dies first, the next
     * start removes what is left.
     * The sheet is opened on the UI thread. If the UI thread has not started the task after 10 seconds (or this thread is interrupted), the task is
     * given up before the failure is passed on: the caller then removes the copy, and a task that ran late must not open a sheet for an address that no
     * longer resolves. Whoever gets there first decides (a compare-and-set on {@code state}): the task starts the sheet only if it can move 0 to 1, the waiter gives up
     * only if it can move 0 to 2.
     */
    private void shareMorpheKey(final File staged) throws Exception {
        final Uri uri = ShareProvider.uriForKey(staged);
        final Context app = getApplicationContext();
        final java.util.concurrent.atomic.AtomicInteger state = new java.util.concurrent.atomic.AtomicInteger();   // 0 waiting, 1 started, 2 given up
        final java.util.concurrent.FutureTask<Boolean> open = new java.util.concurrent.FutureTask<Boolean>(new java.util.concurrent.Callable<Boolean>() {
            @Override public Boolean call() {
                if (!state.compareAndSet(0, 1)) return Boolean.FALSE;       // the caller gave up while this waited in the UI queue: no sheet
                Intent send = new Intent(Intent.ACTION_SEND);
                send.setType("application/octet-stream");
                send.putExtra(Intent.EXTRA_STREAM, uri);
                send.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
                Intent chooser = Intent.createChooser(send, "Share");
                chooser.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
                startActivity(chooser);
                return Boolean.TRUE;
            }
        });
        runOnUiThread(open);
        try {
            open.get(10, java.util.concurrent.TimeUnit.SECONDS);
        } catch (java.util.concurrent.ExecutionException e) {
            throw e.getCause() instanceof Exception ? (Exception) e.getCause() : e;
        } catch (java.util.concurrent.TimeoutException e) {
            if (state.compareAndSet(0, 2)) { open.cancel(false); throw e; }
            awaitStarted(open);
        } catch (InterruptedException e) {
            if (state.compareAndSet(0, 2)) { open.cancel(false); Thread.currentThread().interrupt(); throw e; }
            awaitStarted(open);
            Thread.currentThread().interrupt();
        }
        new android.os.Handler(android.os.Looper.getMainLooper()).postDelayed(new KeyShareExpiry(app, uri, staged), KeyShare.KEEP_MS);
    }

    /** The UI thread had already started the sheet when the wait ended: wait for it to finish (it is running), and pass on an error it ended with. */
    private static void awaitStarted(java.util.concurrent.FutureTask<Boolean> open) throws Exception {
        boolean interrupted = false;
        try {
            for (;;) {
                try { open.get(); return; }
                catch (InterruptedException e) { interrupted = true; }
                catch (java.util.concurrent.ExecutionException e) { throw e.getCause() instanceof Exception ? (Exception) e.getCause() : e; }
            }
        } finally { if (interrupted) Thread.currentThread().interrupt(); }
    }

    /** Ends a key share: revokes the grant and removes the staged copy. Static, so it cannot hold the activity: only the application context, the address and the file. */
    private static final class KeyShareExpiry implements Runnable {
        private final Context app;
        private final Uri uri;
        private final File staged;
        KeyShareExpiry(Context app, Uri uri, File staged) { this.app = app; this.uri = uri; this.staged = staged; }
        @Override public void run() {
            try { app.revokeUriPermission(uri, Intent.FLAG_GRANT_READ_URI_PERMISSION); } catch (Throwable ignored) {}
            KeyShare.remove(staged);
        }
    }

    private synchronized MorpheBridge morphe() {
        if (morpheBridge == null) morpheBridge = new MorpheBridge(morpheHost(), new File(getFilesDir(), "morphe"));
        return morpheBridge;
    }

    /**
     * What this window gives the Morphe bridge. Made without the bridge (which reads its files) so onCreate can name this window as the newest one
     * (MorpheBridge.windowOpened) before its page makes any Morphe call: a patch that is going then asks this window, not a closed one, for the installer.
     */
    private synchronized MorpheBridge.Host morpheHost() {
        if (morpheHostInstance == null) morpheHostInstance = new MorpheBridge.Host() {
            @Override public Context context() { return MainActivity.this; }
            @Override public void js(String script) { notifyJs(script); }
            @Override public boolean pick(final String tag, String kind) {
                morphePickTag = tag;
                runOnUiThread(new Runnable() {
                    @Override public void run() {
                        try {
                            Intent i = new Intent(Intent.ACTION_OPEN_DOCUMENT);
                            i.addCategory(Intent.CATEGORY_OPENABLE);
                            i.setType("*/*");
                            startActivityForResult(i, REQ_PICK_MORPHE);
                        } catch (Exception e) {
                            morphe().pickDone(tag, new JSONArray());
                        }
                    }
                });
                return true;
            }
            @Override public JSONObject install(File apk, String pkg, boolean uninstallFirst) throws Exception { return morpheInstall(apk, pkg, uninstallFirst); }
            @Override public void share(File f, String mime) { new AndroidBridge().shareStoredFile(f.getAbsolutePath(), mime, f.getName()); }
            @Override public void shareKey(File staged) throws Exception { shareMorpheKey(staged); }
            @Override public boolean privileged() { return isPrivilegedMode(resolveExecMode()); }
            @Override public boolean connectionOk(String conn) { return morpheConnectionOk(conn); }
            @Override public File downloadsDir() { return android.os.Environment.getExternalStoragePublicDirectory(android.os.Environment.DIRECTORY_DOWNLOADS); }
            @Override public boolean storageAccess() { return hasStorageAccess(); }
            @Override public BundleApprovals.Answer confirmBundle(String title, String text) { return confirmNative(title, text, "Allow", "Don't allow"); }
            @Override public String copyToTree(File file, String treeUri, String name) throws Exception {
                Uri tree = Uri.parse(treeUri);
                String safe = name == null ? "app.apk" : name.replaceAll("[^A-Za-z0-9._ ()-]", "_");
                String lower = safe.toLowerCase(java.util.Locale.ROOT);
                String mime = lower.endsWith(".apk") ? "application/vnd.android.package-archive" : "application/octet-stream";
                try {
                    Uri parent = android.provider.DocumentsContract.buildDocumentUriUsingTree(tree, android.provider.DocumentsContract.getTreeDocumentId(tree));
                    Uri target = android.provider.DocumentsContract.createDocument(getContentResolver(), parent, mime, safe);
                    if (target == null) throw new IllegalStateException("the folder would not make the file");
                    boolean whole = false;
                    try {
                        OutputStream out = getContentResolver().openOutputStream(target, "wt");
                        if (out == null) throw new IllegalStateException("the folder would not open the file");
                        try { copyFileChecked(file, out); } finally { out.close(); }        // judged once open: the app's private data (the signing key) never leaves
                        whole = true;
                    } finally {
                        // a copy that stopped half way must not stay behind looking like the app file
                        if (!whole) { try { android.provider.DocumentsContract.deleteDocument(getContentResolver(), target); } catch (Throwable ignored) { } }
                    }
                    return safe;
                } catch (SecurityException e) {
                    throw new IllegalStateException("Android no longer lets this app use that folder: choose it again");
                }
            }
            @Override public BrowserDownload.Cookies cookies() { return new WebViewCookies(); }
            @Override public Runnable openBrowser(final String url, final File dir, final HelperDownloads downloads, final BrowserDownload.Events events) {
                final HelperBrowser[] box = new HelperBrowser[1];
                runOnUiThread(new Runnable() {
                    @Override public void run() {
                        try { box[0] = HelperBrowser.show(MainActivity.this, url, dir, downloads, events); }
                        catch (Throwable t) { Log.e(TAG, "in-app browser failed", t); events.onFailed("the browser could not be opened: " + t.getMessage()); events.onClosed(); }
                    }
                });
                return new Runnable() { @Override public void run() { runOnUiThread(new Runnable() { @Override public void run() { if (box[0] != null) box[0].close(); } }); } };
            }
        };
        return morpheHostInstance;
    }

    /** The in-app browser's cookies for an address. A static class: the Helper's download list is the process's and keeps it, so it must not hold a window. */
    private static final class WebViewCookies implements BrowserDownload.Cookies {
        @Override public String forUrl(String u) { try { return android.webkit.CookieManager.getInstance().getCookie(u); } catch (Throwable t) { return null; } }
    }

    private boolean morpheConnectionOk(String conn) {
        if (conn == null || "both".equals(conn)) return true;
        try {
            android.net.ConnectivityManager cm = (android.net.ConnectivityManager) getSystemService(Context.CONNECTIVITY_SERVICE);
            android.net.Network n = cm.getActiveNetwork();
            android.net.NetworkCapabilities nc = n == null ? null : cm.getNetworkCapabilities(n);
            if (nc == null) return false;
            boolean wifi = nc.hasTransport(android.net.NetworkCapabilities.TRANSPORT_WIFI) || nc.hasTransport(android.net.NetworkCapabilities.TRANSPORT_ETHERNET);
            return "wifi".equals(conn) ? wifi : !wifi;
        } catch (Exception e) {
            return true;
        }
    }

    /** Installs a patched app or a downloaded original: through the working mode when there is one (a bundle's splits together), else the system installer. */
    private JSONObject morpheInstall(File apk, String pkg, boolean uninstallFirst) throws Exception {
        JSONObject r = new JSONObject();
        String mode = resolveExecMode();
        String lname = apk.getName().toLowerCase(java.util.Locale.ROOT);
        if (!isPrivilegedMode(mode) && (lname.endsWith(".apks") || lname.endsWith(".apkm") || lname.endsWith(".xapk"))) {
            // the system installer cannot open a bundle by itself: stage every split in one installer session and wait for the answer
            return morpheInstallBundleNoPrivilege(apk);
        }
        if (!isPrivilegedMode(mode)) {
            File copy = ShareProvider.newShareFile(this, apk.getName());
            java.io.FileOutputStream out = new java.io.FileOutputStream(copy);
            try { copyFile(apk, out); } finally { out.close(); }
            final Uri uri = ShareProvider.uriFor(copy);
            runOnUiThread(new Runnable() {
                @Override public void run() {
                    try {
                        Intent i = new Intent(Intent.ACTION_VIEW).setDataAndType(uri, "application/vnd.android.package-archive")
                                .addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION | Intent.FLAG_ACTIVITY_NEW_TASK);
                        startActivity(i);
                    } catch (Exception e) { Log.e(TAG, "system installer failed", e); }
                }
            });
            r.put("ok", true);
            r.put("system", true);
            r.put("handedOff", true);       // opened, not installed: the person has not answered yet (the bridge keeps the patched APK)
            r.put("output", "The system installer was opened. Confirm the install there. (Set up a working mode to install through ADB, Shizuku or Root.)");
            return r;
        }
        StringBuilder notes = new StringBuilder();
        List<File> files = new ArrayList<File>();
        String name = apk.getName().toLowerCase(java.util.Locale.ROOT);
        // the folder the APK is copied (or the bundle unpacked) into: filled inside the try below, so a copy that fails half way is removed too
        File tmp = new File(getCacheDir(), "morphe_inst/" + Long.toHexString(System.nanoTime()));
        String out;
        String insidePkg = null;       // the package the APK itself names; outside the try so the retry decision below can use it too
        try {
            if (name.endsWith(".apks") || name.endsWith(".apkm") || name.endsWith(".xapk")) {
                files.addAll(MorpheLibrary.unzipApks(apk, tmp));
            } else {
                // A plain APK may sit in shared storage (Downloads), where another app can swap it between the manifest read below and the
                // install: copy it into the private cache first, like a bundle, so the file confirmed is the file installed.
                tmp.mkdirs();
                File copy = new File(tmp, apk.getName());
                copyFile(apk, copy);
                files.add(copy);
            }
            if (files.isEmpty()) throw new IOException("there is no APK inside " + apk.getName());
            // A privileged install has no system installer in front of it, and the page chose the file: ask here, in a dialog the page cannot press,
            // with the package and version read from the APK itself. Before anything is removed or installed.
            PackageInfo inside = getPackageManager().getPackageArchiveInfo(files.get(0).getAbsolutePath(), 0);
            insidePkg = inside != null && inside.packageName != null ? inside.packageName : null;
            if (uninstallFirst && insidePkg == null) throw new IllegalStateException("can't tell which app to uninstall first: the package name can't be read from the APK");
            List<String> acts = new ArrayList<String>();
            if (uninstallFirst) acts.add(InstallConfirm.REMOVES_FIRST);
            if (!confirmInMode(mode, null, InstallConfirm.messageLocalFile(apk.getName(), insidePkg, inside != null ? inside.versionName : null,
                    installedVersionOrNull(insidePkg), files.size(), mode, "", acts))) {
                r.put("ok", false);
                r.put("cancelled", true);
                r.put("output", "Install cancelled. Nothing was installed.");
                return r;
            }
            if (uninstallFirst) {
                // the app removed is the one the APK is, as read from the APK: never the package name the page sent
                uninstallInstalledCopy(mode, insidePkg);
                notes.append("The installed copy was uninstalled first.\n");
            }
            out = installApksIn(files, mode);          // the mode the question named and the removal above used
        } finally {
            File[] fs = tmp.listFiles(); if (fs != null) for (File f : fs) f.delete(); tmp.delete();
        }
        boolean ok = InstallHints.success(out);
        r.put("ok", ok);
        r.put("output", notes + (out == null ? "" : out.trim()));
        if (!ok) {
            r.put("advice", InstallHints.advice(out));
            // eligibility is judged on the app the APK is (the one an uninstall-first retry would remove), not on the package name the page sent; unreadable: no retry
            if (!uninstallFirst && insidePkg != null && InstallHints.updateIncompatible(out) && canUninstallFirst(insidePkg, mode)) r.put("retry", "uninstall");
        }
        return r;
    }

    /** Installs a bundle (.apkm/.apks/.xapk) without a working mode: all splits go into one PackageInstaller session, the system asks the
     *  user to confirm, and this waits (up to ten minutes) for the verdict so the Helper can report it. */
    private JSONObject morpheInstallBundleNoPrivilege(File bundle) throws Exception {
        File tmp = new File(getCacheDir(), "morphe_inst/" + Long.toHexString(System.nanoTime()));
        List<File> files = MorpheLibrary.unzipApks(bundle, tmp);
        final java.util.concurrent.CountDownLatch done = new java.util.concurrent.CountDownLatch(1);
        final int[] status = {-999};
        final String[] message = {""};
        android.content.BroadcastReceiver rcv = null;
        android.content.pm.PackageInstaller.Session session = null;
        try {
            if (files.isEmpty()) throw new IOException("there is no APK inside " + bundle.getName());
            android.content.pm.PackageInstaller pi = getPackageManager().getPackageInstaller();
            final int sessionId = pi.createSession(new android.content.pm.PackageInstaller.SessionParams(android.content.pm.PackageInstaller.SessionParams.MODE_FULL_INSTALL));
            session = pi.openSession(sessionId);
            for (File f : files) {
                OutputStream sout = session.openWrite(f.getName().replaceAll("[^A-Za-z0-9._-]", "_"), 0, f.length());
                try { copyFile(f, sout); session.fsync(sout); } finally { sout.close(); }
            }
            final String action = getPackageName() + ".INSTALL_RESULT." + (installReceiverSeq++);
            rcv = new android.content.BroadcastReceiver() {
                @Override public void onReceive(Context c, Intent i) {
                    int st = i.getIntExtra(android.content.pm.PackageInstaller.EXTRA_STATUS, -999);
                    if (st == android.content.pm.PackageInstaller.STATUS_PENDING_USER_ACTION) {
                        Intent confirm = (Intent) i.getParcelableExtra(Intent.EXTRA_INTENT);
                        if (confirm != null) {
                            confirm.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
                            try { startActivity(confirm); } catch (Exception ignored) {}
                        }
                        return;
                    }
                    status[0] = st;
                    String m = i.getStringExtra(android.content.pm.PackageInstaller.EXTRA_STATUS_MESSAGE);
                    message[0] = m == null ? "" : m;
                    done.countDown();
                }
            };
            android.content.IntentFilter filter = new android.content.IntentFilter(action);
            if (Build.VERSION.SDK_INT >= 33) registerReceiver(rcv, filter, Context.RECEIVER_NOT_EXPORTED);
            else registerReceiver(rcv, filter);
            int piFlags = android.app.PendingIntent.FLAG_UPDATE_CURRENT | (Build.VERSION.SDK_INT >= 31 ? android.app.PendingIntent.FLAG_MUTABLE : 0);
            android.app.PendingIntent sender = android.app.PendingIntent.getBroadcast(this, sessionId, new Intent(action).setPackage(getPackageName()), piFlags);
            session.commit(sender.getIntentSender());
            session.close();
            session = null;
            boolean answered = done.await(10, java.util.concurrent.TimeUnit.MINUTES);
            JSONObject r = new JSONObject();
            boolean ok = answered && status[0] == android.content.pm.PackageInstaller.STATUS_SUCCESS;
            r.put("ok", ok);
            r.put("system", true);
            r.put("output", ok ? "Success" : !answered ? "The system installer did not answer in time."
                    : "Install " + (status[0] == android.content.pm.PackageInstaller.STATUS_FAILURE_ABORTED ? "cancelled" : "failed") + (message[0].isEmpty() ? "" : ": " + message[0]));
            if (!ok && answered) r.put("advice", InstallHints.advice(message[0]));
            return r;
        } finally {
            if (session != null) { try { session.abandon(); } catch (Exception ignored) {} }
            if (rcv != null) { try { unregisterReceiver(rcv); } catch (Exception ignored) {} }
            File[] fs = tmp.listFiles();
            if (fs != null) for (File f : fs) f.delete();
            tmp.delete();
        }
    }

    /** A file the Morphe tab asked for: copied into this app's cache (the page works with those copies), then handed to the bridge. */
    private void morphePicked(final Intent data, final int resultCode) {
        final String tag = morphePickTag;
        final List<Uri> uris = new ArrayList<Uri>();
        if (resultCode == RESULT_OK && data != null) {
            if (data.getClipData() != null) {
                for (int i = 0; i < data.getClipData().getItemCount(); i++) uris.add(data.getClipData().getItemAt(i).getUri());
            } else if (data.getData() != null) {
                uris.add(data.getData());
            }
        }
        if (uris.isEmpty()) { morphe().pickDone(tag, new JSONArray()); return; }
        executor.submit(new Runnable() {
            @Override public void run() {
                JSONArray files = new JSONArray();
                File root = new File(getCacheDir(), "morphe_pick");
                root.mkdirs();
                long old = System.currentTimeMillis() - 24L * 60 * 60 * 1000;
                File[] dirs = root.listFiles();
                if (dirs != null) {
                    java.util.List<File> toDelete = new java.util.ArrayList<File>();
                    for (File d : dirs) if (d.lastModified() < old) toDelete.add(d);
                    if (!toDelete.isEmpty()) FileOps.delete(toDelete, null);
                }
                for (Uri u : uris) {
                    try {
                        String nm = cdSafeName(cdDisplayName(u));
                        File dir = new File(root, Long.toHexString(System.nanoTime()));
                        dir.mkdirs();
                        File out = new File(dir, nm);
                        InputStream in = getContentResolver().openInputStream(u);
                        if (in == null) throw new IOException("could not open the file");
                        java.io.OutputStream os = new java.io.FileOutputStream(out);
                        try {
                            byte[] buf = new byte[65536];
                            int n;
                            while ((n = in.read(buf)) > 0) os.write(buf, 0, n);
                        } finally { os.close(); in.close(); }
                        files.put(new JSONObject().put("name", nm).put("path", out.getAbsolutePath()).put("size", out.length()));
                    } catch (Exception one) {
                        try { files.put(new JSONObject().put("name", String.valueOf(u.getLastPathSegment())).put("error", String.valueOf(one.getMessage()))); } catch (Exception ignored) {}
                    }
                }
                morphe().pickDone(tag, files);
            }
        });
    }

    // The log recorder is held by the app, not by an activity or its bridge: a recording goes on across a recreate() (a theme change,
    // Back and reopen), the new activity sees it in the status and can stop it, and it cannot start a second one beside it.
    private static volatile LogRecorder logRec;

    // File Manager thumbnails, one picture at a time (a long list must not decode ten at once). A field of the activity, not of the bridge,
    // so onDestroy can stop it: every recreate() makes a new bridge, and each pool's idle thread would otherwise live on.
    private final ExecutorService thumbExec = Executors.newSingleThreadExecutor();

