        /**
         * Requests Shizuku authorization through the official Shizuku API. The result is delivered
         * asynchronously to window.onShizukuPermissionResult(granted). Returns a status string:
         * granted, requested, not_installed, not_running, pre_v11 or error:...
         */
        @JavascriptInterface
        public String requestShizukuPermission() {
            try {
                if (!isShizukuBinderAlive()) {
                    if (installedShizukuPackage() == null) return "not_installed";
                    return "not_running";
                }
                if (Shizuku.isPreV11()) return "pre_v11";
                if (Shizuku.checkSelfPermission() == PackageManager.PERMISSION_GRANTED) {
                    setConfiguredMode("shizuku");
                    return "granted";
                }
                runOnUiThread(new Runnable() {
                    @Override
                    public void run() {
                        try {
                            Shizuku.requestPermission(SHIZUKU_REQUEST_CODE);
                        } catch (Throwable t) {
                            Toast.makeText(MainActivity.this, "Shizuku request failed: " + t.getMessage(), Toast.LENGTH_LONG).show();
                        }
                    }
                });
                return "requested";
            } catch (Throwable t) {
                return "error: " + t.getMessage();
            }
        }

        /**
         * Starts the Shizuku service through ADB (the installed Shizuku app's own start script). Returns at once: "started_async" (the result comes
         * to window.onShizukuStartResult({status, pkg, script, exit, text}), status being started, already_running, not_installed, no_adb,
         * no_script or failed), or "busy" while an earlier start is still running.
         */
        @JavascriptInterface
        public String startShizukuViaAdb() {
            if (!shizukuStarting.compareAndSet(false, true)) return "busy";
            try {
                executor.submit(new Runnable() {
                    @Override
                    public void run() {
                        JSONObject res;
                        try {
                            res = startShizukuNow();
                        } catch (Throwable t) {
                            res = shizukuStartResult("failed", "", null);
                        } finally {
                            shizukuStarting.set(false);
                        }
                        notifyJs("window.onShizukuStartResult && window.onShizukuStartResult(" + res.toString() + ")");
                    }
                });
            } catch (RejectedExecutionException e) {
                shizukuStarting.set(false);
                return "error";
            }
            return "started_async";
        }

